local Boot = getgenv()
if Boot.CorvusBooting and os.clock() - Boot.CorvusBooting < 25 then
	pcall(function()
		game:GetService("StarterGui")
			:SetCore("SendNotification", { Title = "Percy Hub", Text = "Already starting, give it a few seconds", Duration = 5 })
	end)
	return
end
Boot.CorvusBooting = os.clock()
if not game:IsLoaded() then
	game.Loaded:Wait()
end
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
do
	local waited = 0
	local ok = false
	while not ok and waited < 25 do
		local build = workspace:FindFirstChild("Build")
		ok = ReplicatedStorage:FindFirstChild("EggHitRequest") ~= nil
			and workspace:FindFirstChild("Plots") ~= nil
			and build ~= nil
			and build:FindFirstChild("ZoneBuilds") ~= nil
		if not ok then
			waited += task.wait(0.5) or 0.5
		end
	end
	if not ok then
		Boot.CorvusBooting = nil
		warn("[Percy Hub] This is not Break and Steal an Egg, the hub was not started")
		return
	end
	waited = 0
	while LocalPlayer:GetAttribute("Cash") == nil and waited < 60 do
		waited += task.wait(0.25) or 0.25
	end
	LocalPlayer:WaitForChild("PlayerGui", 20)
	task.wait(0.5)
end
