    local function CreateInstantTween(Object, Properties)
        local Listeners = {}
        local Completed = {}
        function Completed:Connect(Callback)
            table.insert(Listeners, Callback)
            local Connection = { Connected = true }
            function Connection:Disconnect()
                Connection.Connected = false
                local Index = table.find(Listeners, Callback)
                if Index then
                    table.remove(Listeners, Index)
                end
            end
            return Connection
        end
        Completed.Once = Completed.Connect
        function Completed:Wait()
            return Enum.PlaybackState.Completed
        end
        local Tween = { Completed = Completed, PlaybackState = Enum.PlaybackState.Begin, Instance = Object }
        function Tween:Play()
            for Key, Value in Properties do
                pcall(function()
                    Object[Key] = Value
                end)
            end
            Tween.PlaybackState = Enum.PlaybackState.Completed
            local Pending = table.clone(Listeners)
            table.clear(Listeners)
            for _, Callback in Pending do
                task.spawn(Callback, Enum.PlaybackState.Completed)
            end
        end
        function Tween:Cancel()
            Tween.PlaybackState = Enum.PlaybackState.Cancelled
        end
        function Tween:Pause()
            Tween.PlaybackState = Enum.PlaybackState.Paused
        end
        function Tween:Destroy()
            table.clear(Listeners)
        end
        return Tween
    end
    TweenService = setmetatable({
        Create = function(_, Object, Info, Properties)
            local Success, Tween = pcall(RawTweenService.Create, RawTweenService, Object, Info, Properties)
            if Success and Tween then
                return Tween
            end
            return CreateInstantTween(Object, Properties)
        end,
    }, {
        __index = function(_, Key)
            local Value = RawTweenService[Key]
            if type(Value) == "function" then
                return function(_, ...)
                    return Value(RawTweenService, ...)
                end
            end
            return Value
        end,
    })
    local EmbeddedAssets = {}
    
    local Base64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local Base64Lookup = {}
    for Index = 1, #Base64Alphabet do
        Base64Lookup[string.byte(Base64Alphabet, Index)] = Index - 1
    end
    
    local function Base64Decode(Data: string): string
        local Decoder = (crypt and (crypt.base64decode or (crypt.base64 and crypt.base64.decode))) or base64_decode
        if typeof(Decoder) == "function" then
            local Success, Result = pcall(Decoder, Data)
            if Success and typeof(Result) == "string" and #Result > 0 then
                return Result
            end
        end
    
        Data = string.gsub(Data, "[^%w%+/=]", "")
        local Output = table.create(math.floor(#Data / 4) * 3)
        local Count = 0
    
        for Index = 1, #Data, 4 do
            local A, B, C, D = string.byte(Data, Index, Index + 3)
            local V1 = Base64Lookup[A] or 0
            local V2 = Base64Lookup[B] or 0
            local V3 = Base64Lookup[C] or 0
            local V4 = Base64Lookup[D] or 0
            local Triple = V1 * 262144 + V2 * 4096 + V3 * 64 + V4
    
            Count += 1
            Output[Count] = string.char(math.floor(Triple / 65536) % 256)
            if C and C ~= 61 then
                Count += 1
                Output[Count] = string.char(math.floor(Triple / 256) % 256)
            end
            if D and D ~= 61 then
                Count += 1
                Output[Count] = string.char(Triple % 256)
            end
        end
    
        return table.concat(Output)
    end
    
