    local function GetSchemeValue(Index)
        if not Index then
            return nil
        end
    
        local ReplaceAliasIndex = SchemeReplaceAlias[Index]
        if ReplaceAliasIndex and Library.Scheme[ReplaceAliasIndex] ~= nil then
            Library.Scheme[Index] = Library.Scheme[ReplaceAliasIndex]
            Library.Scheme[ReplaceAliasIndex] = nil
    
            return Library.Scheme[Index]
        end
    
        local AliasIndex = SchemeAlias[Index]
        if AliasIndex and Library.Scheme[AliasIndex] ~= nil then
            warn(string.format("Scheme Value %q is deprecated, please use %q instead.", Index, AliasIndex))
            return Library.Scheme[AliasIndex]
        end
    
        return Library.Scheme[Index]
    end
    
    local function WaitForEvent(Event, Timeout, Condition)
        local Bindable = CreateInstance("BindableEvent")
        local Connection = Event:Once(function(...)
            if not Condition or typeof(Condition) == "function" and Condition(...) then
                Bindable:Fire(true)
            else
                Bindable:Fire(false)
            end
        end)
        task.delay(Timeout, function()
            Connection:Disconnect()
            Bindable:Fire(false)
        end)
    
        local Result = Bindable.Event:Wait()
        Bindable:Destroy()
    
        return Result
    end
    
    local function IsMouseInput(Input: InputObject, IncludeM2: boolean?)
        return Input.UserInputType == Enum.UserInputType.MouseButton1
            or (IncludeM2 == true and Input.UserInputType == Enum.UserInputType.MouseButton2)
            or Input.UserInputType == Enum.UserInputType.Touch
    end
    local function IsClickInput(Input: InputObject, IncludeM2: boolean?)
        return IsMouseInput(Input, IncludeM2)
            and Input.UserInputState == Enum.UserInputState.Begin
            and Library.IsRobloxFocused
    end
    local function IsHoverInput(Input: InputObject)
        return (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch)
            and Input.UserInputState == Enum.UserInputState.Change
    end
    local function IsDragInput(Input: InputObject, IncludeM2: boolean?)
        return IsMouseInput(Input, IncludeM2)
            and (Input.UserInputState == Enum.UserInputState.Begin or Input.UserInputState == Enum.UserInputState.Change)
            and Library.IsRobloxFocused
    end
    local function IsMouseClickInput(Input: InputObject)
        return Input.UserInputType == Enum.UserInputType.MouseButton1 or
            Input.UserInputType == Enum.UserInputType.MouseButton2 or
            Input.UserInputType == Enum.UserInputType.MouseButton3
    end
    local function IsMovementInput(Input: InputObject)
        return (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch)
            and Library.IsRobloxFocused
    end
    
    local function GetTableSize(Table: { [any]: any })
        local Size = 0
    
        for _, _ in Table do
            Size += 1
        end
    
        return Size
    end
    local function IsSequentialArray(Table: { [any]: any })
        for Key in Table do
            if typeof(Key) ~= "number" or Key < 1 or Key % 1 ~= 0 then
                return false
            end
        end
    
        return true
    end
    
    local function StopTween(Tween: TweenBase, Destroy: boolean?)
        if not Tween then
            return
        end
    
        if Tween.PlaybackState == Enum.PlaybackState.Playing then
            Tween:Cancel()
        end
    
        if Destroy == true then
            pcall(Tween.Destroy, Tween)
        end
    end
    
    local function Trim(Text: string)
        return Text:match("^%s*(.-)%s*$")
    end
    local function Round(Value, Rounding)
        assert(Rounding >= 0, "Invalid rounding number.")
    
        if Rounding == 0 then
            return math.floor(Value)
        end
    
        return tonumber(string.format("%." .. Rounding .. "f", Value))
    end
    
    local function FuzzyScore(Text: string, Search: string): (boolean, number)
        if Search == "" then
            return true, 0
        end
        if Text == "" then
            return false, 0
        end
    
        local ExactIdx = Text:find(Search, 1, true)
        if ExactIdx then
            local PrevChar = ExactIdx > 1 and Text:sub(ExactIdx - 1, ExactIdx - 1) or ""
            local AtBoundary = ExactIdx == 1 or PrevChar:match("[%s%p_]") ~= nil
    
            return true, 1e5 - ExactIdx + (AtBoundary and 500 or 0) + (Search:len() * 5)
        end
    
        local TextLen, SearchLen = Text:len(), Search:len()
        if SearchLen > TextLen then
            return false, 0
        end
    
        local SearchIdx = 1
        local Score = 0
        local RunLength = 0
        local LastMatchIdx = 0
    
        for TextIdx = 1, TextLen do
            if SearchIdx > SearchLen then
                break
            end
    
            if Text:sub(TextIdx, TextIdx) == Search:sub(SearchIdx, SearchIdx) then
                local PrevChar = TextIdx > 1 and Text:sub(TextIdx - 1, TextIdx - 1) or ""
                local AtBoundary = TextIdx == 1 or PrevChar:match("[%s%p_]") ~= nil
    
                RunLength = (LastMatchIdx == TextIdx - 1) and (RunLength + 1) or 1
                Score += 1 + (AtBoundary and 6 or 0) + math.min(RunLength - 1, 5) * 3
    
                LastMatchIdx = TextIdx
                SearchIdx += 1
            end
        end
    
        if SearchIdx <= SearchLen then
            return false, 0
        end
    
        Score -= (LastMatchIdx - SearchLen) * 0.05
        return true, Score
    end
    
    local function NormalizeSearch(Search: string): string
        return (Search:gsub("%s+", ""))
    end
    
    local SearchRecords = {}
    local SearchRecordCount = 0
    
    local function GetSearchRecord(Text: any)
        if typeof(Text) ~= "string" or Text == "" then
            return nil
        end
    
        local Record = SearchRecords[Text]
        if Record then
            return Record
        end
    
        local Clean = (Text:gsub("<[^<>]->", ""):lower():gsub("%s+", " "))
        Record = {
            Clean = Clean,
            Compact = (Clean:gsub("[%s%p]+", "")),
            Initials = ((Clean:gsub("(%w)%w*", "%1")):gsub("[^%w]", "")),
        }
    
        if SearchRecordCount >= 4000 then
            table.clear(SearchRecords)
            SearchRecordCount = 0
        end
        SearchRecords[Text] = Record
        SearchRecordCount += 1
    
        return Record
    end
    
    local function SearchTokenScore(Record, Token: string, Strict: boolean?): number
        local Clean = Record.Clean
        local Index = Clean:find(Token, 1, true)
        if Index then
            local PrevChar = if Index > 1 then Clean:sub(Index - 1, Index - 1) else ""
            local AtBoundary = Index == 1 or PrevChar:match("[%s%p]") ~= nil
            return 100 + Token:len() * 4 + (if AtBoundary then 60 else 0) + (if Clean == Token then 200 else 0) - math.min(Index, 60) * 0.5
        end
    
        local CompactToken = (Token:gsub("[%s%p]+", ""))
        if CompactToken == "" then
            return 0
        end
        if Record.Compact:find(CompactToken, 1, true) then
            return 80 + CompactToken:len() * 3
        end
        if Strict then
            return 0
        end
        if CompactToken:len() >= 2 and Record.Initials:sub(1, CompactToken:len()) == CompactToken then
            return 70 + CompactToken:len() * 3
        end
        if CompactToken:len() < 3 then
            return 0
        end
    
        local Compact = Record.Compact
        local Position, First, Last = 1, 0, 0
        for Char in CompactToken:gmatch(".") do
            local Found = Compact:find(Char, Position, true)
            if not Found then
                return 0
            end
            if First == 0 then
                First = Found
            end
            Last = Found
            Position = Found + 1
        end
    
        local Span = Last - First + 1
        if Span > CompactToken:len() * 2 then
            return 0
        end
    
        return 30 + CompactToken:len() * 2 - (Span - CompactToken:len())
    end
    
    local function SearchFieldsScore(Fields, Search: string): number
        local Total = 0
        for Token in Search:gmatch("%S+") do
            local Best = 0
            for _, Field in Fields do
                local Record = GetSearchRecord(Field[1])
                if Record then
                    local Score = SearchTokenScore(Record, Token, Field[3]) * Field[2]
                    if Score > Best then
                        Best = Score
                    end
                end
            end
            if Best <= 0 then
                return 0
            end
            Total += Best
        end
    
        return Total
    end
    
    local function TryFuzzyMatch(Text: any, Search: string): (boolean, number)
        local Score = SearchFieldsScore({ { Text, 1, false } }, Search)
        return Score > 0, Score
    end
    
    local function FuzzyMatchScore(Text: any, Search: string): number
        return SearchFieldsScore({ { Text, 1, false } }, Search)
    end
    
    local function MatchesSearch(ElementInfo, Search: string, ForceMatch: boolean?): boolean
        if not ElementInfo then
            return false
        end
        if ForceMatch then
            return true
        end
    
        local Fields = {
            { ElementInfo.Text, 1, false },
            { ElementInfo.Tooltip, 0.5, true },
            { ElementInfo.DisabledTooltip, 0.4, true },
        }
    
        local DescriptionLabel = ElementInfo.DescriptionLabel
        if typeof(DescriptionLabel) == "Instance" and DescriptionLabel:IsA("TextLabel") then
            table.insert(Fields, { DescriptionLabel.Text, 0.7, true })
        end
    
        if typeof(ElementInfo.Values) == "table" then
            local Checked = 0
            for Key, Value in ElementInfo.Values do
                Checked += 1
                if Checked > 200 then
                    break
                end
    
                table.insert(Fields, { if typeof(Value) == "string" then Value else tostring(Value), 0.6, true })
                if typeof(Key) == "string" then
                    table.insert(Fields, { Key, 0.6, true })
                end
            end
        end
    
        return SearchFieldsScore(Fields, Search) > 0
    end
    
    local function GetPlayers(ExcludeLocalPlayer: boolean?)
        local PlayerList = Players:GetPlayers()
    
        if ExcludeLocalPlayer then
            local Idx = table.find(PlayerList, LocalPlayer)
            if Idx then
                table.remove(PlayerList, Idx)
            end
        end
    
        table.sort(PlayerList, function(Player1, Player2)
            return Player1.Name:lower() < Player2.Name:lower()
        end)
    
        return PlayerList
    end
    local function GetTeams()
        local TeamList = Teams:GetTeams()
    
        table.sort(TeamList, function(Team1, Team2)
            return Team1.Name:lower() < Team2.Name:lower()
        end)
    
        return TeamList
    end
    
    function Library:UpdateDependencyBoxes()
        for _, Depbox in Library.DependencyBoxes do
            Depbox:Update(true)
        end
    
        if Library.Searching then
            Library:UpdateSearch(Library.SearchText)
        end
    end
    
    function Library:UpdateAddons(Parent)
        if not Parent or not Parent.Addons then
            return
        end
    
        for _, Addon in Parent.Addons do
            Addon:Update()
        end
    end
    
    local function CheckDepbox(Box, Search, ForceVisible: boolean?)
        local VisibleElements = 0
        local BestScore = 0
    
        for _, ElementInfo in Box.Elements do
            if ElementInfo.Type == "Divider" then
                ElementInfo.Holder.Visible = false
                continue
            elseif ElementInfo.SubButton then
                local Visible = false
    
                if MatchesSearch(ElementInfo, Search, ForceVisible) and ElementInfo.Visible then
                    Visible = true
                    BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.Text, Search))
                else
                    ElementInfo.Base.Visible = false
                end
                if MatchesSearch(ElementInfo.SubButton, Search, ForceVisible) and ElementInfo.SubButton.Visible then
                    Visible = true
                    BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.SubButton.Text, Search))
                else
                    ElementInfo.SubButton.Base.Visible = false
                end
                ElementInfo.Holder.Visible = Visible
                if Visible then
                    VisibleElements += 1
                end
    
                continue
            end
    
            if ElementInfo.Text and MatchesSearch(ElementInfo, Search, ForceVisible) and ElementInfo.Visible then
                ElementInfo.Holder.Visible = true
                VisibleElements += 1
                BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.Text, Search))
            else
                ElementInfo.Holder.Visible = false
            end
        end
    
        for _, Depbox in Box.DependencyBoxes do
            if not Depbox.Visible then
                continue
            end
    
            local DepVisible, DepScore = CheckDepbox(Depbox, Search, ForceVisible)
            VisibleElements += DepVisible
            if DepScore > BestScore then
                BestScore = DepScore
            end
        end
    
        Box.Holder.Visible = VisibleElements > 0
        return VisibleElements, BestScore
    end
    local function RestoreDepbox(Box)
        for _, ElementInfo in Box.Elements do
            ElementInfo.Holder.Visible = ElementInfo.Visible ~= false
    
            if ElementInfo.SubButton then
                ElementInfo.Base.Visible = ElementInfo.Visible
                ElementInfo.SubButton.Base.Visible = ElementInfo.SubButton.Visible
            end
        end
    
        Box:Resize()
        Box.Holder.Visible = true
    
        for _, Depbox in Box.DependencyBoxes do
            if not Depbox.Visible then
                continue
            end
    
            RestoreDepbox(Depbox)
        end
    end
    
    function SyncPopOutVisibility(Box: any)
        if not Box.PopOutFloat then
            return
        end
    
        Box.PopOutFloat.Visible = Box.BoxHolder.Visible ~= false and Box.Visible ~= false
    end
    
    local function DimPopOutClone(Root: GuiObject)
        for _, Descendant in Root:QueryDescendants("TextLabel, TextButton, TextBox") do
            Descendant.TextTransparency = math.max(Descendant.TextTransparency, 0.45)
        end
    
        for _, Descendant in Root:QueryDescendants("ImageLabel, ImageButton") do
            Descendant.ImageTransparency = math.max(Descendant.ImageTransparency, 0.45)
        end
    
        for _, Descendant in Root:QueryDescendants("GuiButton") do
            Descendant.Active = false
            Descendant.AutoButtonColor = false
        end
    end
    
    local function IsScreenPointOutsideMain(Point: Vector2): boolean
        local MainFrame = Library.Window and Library.Window.MainFrame
        if not MainFrame or not Library.Toggled or not MainFrame.Visible then
            return true
        end
    
        return not Library:MouseIsOverFrame(MainFrame, Point)
    end
    
    local function GetTopFloatAt(Point: Vector2): GuiObject?
        local Best: GuiObject? = nil
        local BestOrder = -math.huge
        local Floats = Library.Floats
    
        for _, Surface in Library.DraggableElements do
            if not Surface or not Surface.Parent or not Surface.Visible then
                continue
            end
            if Floats and Surface.Parent ~= Floats then
                continue
            end
            if not Library:MouseIsOverFrame(Surface, Point) then
                continue
            end
    
            local SiblingIndex = tonumber(select(2, pcall(function() return Surface:GetSiblingIndex() end))) or 0
            local Order = Surface.ZIndex * 100000 + SiblingIndex
            if Order >= BestOrder then
                BestOrder = Order
                Best = Surface
            end
        end
    
        return Best
    end
    
    local function GetPopOutBodyMaxHeight(Box: any, Reserved: number): number
        local Float = Box.PopOutFloat
        local ScreenGui = Library.ScreenGui
        if not Float or not ScreenGui then
            return math.huge
        end
    
        local Gap = 12 * Library.DPIScale
        local MaxBottom = ScreenGui.AbsolutePosition.Y + ScreenGui.AbsoluteSize.Y - Gap
        local Available = math.min(MaxBottom - Float.AbsolutePosition.Y, ScreenGui.AbsoluteSize.Y * 0.9)
        local ScreenMax = math.max(0, Available / Library.DPIScale - Reserved)
    
        local CustomMax = Box.PopOutMaxHeight
        if typeof(CustomMax) == "number" then
            return math.min(ScreenMax, math.max(0, CustomMax))
        end
    
        return ScreenMax
    end
    
    local function ApplySearchToTab(Tab, Search)
        if not Tab then
            return false, 0
        end
    
        local HasVisible = false
        local BestScore = 0
    
        local TabMatches = TryFuzzyMatch(Tab.Name, Search) or TryFuzzyMatch(Tab.Description, Search)
        BestScore = math.max(BestScore, FuzzyMatchScore(Tab.Name, Search), FuzzyMatchScore(Tab.Description, Search))
    
        for _, Groupbox in Tab.Groupboxes do
            if Groupbox.Visible == false then
                continue
            end
    
            local GroupboxMatches = TabMatches or (TryFuzzyMatch(Groupbox.Name, Search) or TryFuzzyMatch(Groupbox.Description, Search))
            BestScore = math.max(BestScore, FuzzyMatchScore(Groupbox.Name, Search), FuzzyMatchScore(Groupbox.Description, Search))
    
            local VisibleElements = 0
            for _, ElementInfo in Groupbox.Elements do
                if ElementInfo.Type == "Divider" then
                    ElementInfo.Holder.Visible = false
                    continue
                elseif ElementInfo.SubButton then
                    local Visible = false
                    if MatchesSearch(ElementInfo, Search, GroupboxMatches) and ElementInfo.Visible then
                        Visible = true
                        BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.Text, Search))
                    else
                        ElementInfo.Base.Visible = false
                    end
    
                    if MatchesSearch(ElementInfo.SubButton, Search, GroupboxMatches) and ElementInfo.SubButton.Visible then
                        Visible = true
                        BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.SubButton.Text, Search))
                    else
                        ElementInfo.SubButton.Base.Visible = false
                    end
    
                    ElementInfo.Holder.Visible = Visible
                    if Visible then
                        VisibleElements += 1
                    end
    
                    continue
                end
    
                if ElementInfo.Text and MatchesSearch(ElementInfo, Search, GroupboxMatches) and ElementInfo.Visible then
                    ElementInfo.Holder.Visible = true
                    VisibleElements += 1
                    BestScore = math.max(BestScore, FuzzyMatchScore(ElementInfo.Text, Search))
                else
                    ElementInfo.Holder.Visible = false
                end
            end
    
            for _, Depbox in Groupbox.DependencyBoxes do
                if not Depbox.Visible then
                    continue
                end
    
                local DepVisible, DepScore = CheckDepbox(Depbox, Search, GroupboxMatches)
                VisibleElements += DepVisible
                if DepScore > BestScore then
                    BestScore = DepScore
                end
            end
    
            if VisibleElements > 0 then
                Groupbox:Resize()
                HasVisible = true
            end
            Groupbox.BoxHolder.Visible = VisibleElements > 0
            SyncPopOutVisibility(Groupbox)
        end
    
        for _, Tabbox in Tab.Tabboxes do
            local VisibleTabs = 0
            local VisibleElements = {}
            local SubTabScores = {}
    
            for _, SubTab in Tabbox.Tabs do
                VisibleElements[SubTab] = 0
    
                local SubTabMatches = TabMatches or TryFuzzyMatch(SubTab.Name, Search)
                local SubScore = FuzzyMatchScore(SubTab.Name, Search)
                BestScore = math.max(BestScore, SubScore)
    
                for _, ElementInfo in SubTab.Elements do
                    if ElementInfo.Type == "Divider" then
                        ElementInfo.Holder.Visible = false
                        continue
                    elseif ElementInfo.SubButton then
                        local Visible = false
                        if MatchesSearch(ElementInfo, Search, SubTabMatches) and ElementInfo.Visible then
                            Visible = true
                            local ElementScore = FuzzyMatchScore(ElementInfo.Text, Search)
                            SubScore = math.max(SubScore, ElementScore)
                            BestScore = math.max(BestScore, ElementScore)
                        else
                            ElementInfo.Base.Visible = false
                        end
    
                        if MatchesSearch(ElementInfo.SubButton, Search, SubTabMatches) and ElementInfo.SubButton.Visible then
                            Visible = true
                            local ElementScore = FuzzyMatchScore(ElementInfo.SubButton.Text, Search)
                            SubScore = math.max(SubScore, ElementScore)
                            BestScore = math.max(BestScore, ElementScore)
                        else
                            ElementInfo.SubButton.Base.Visible = false
                        end
    
                        ElementInfo.Holder.Visible = Visible
                        if Visible then
                            VisibleElements[SubTab] += 1
                        end
    
                        continue
                    end
    
                    if ElementInfo.Text and MatchesSearch(ElementInfo, Search, SubTabMatches) and ElementInfo.Visible then
                        ElementInfo.Holder.Visible = true
                        VisibleElements[SubTab] += 1
                        local ElementScore = FuzzyMatchScore(ElementInfo.Text, Search)
                        SubScore = math.max(SubScore, ElementScore)
                        BestScore = math.max(BestScore, ElementScore)
                    else
                        ElementInfo.Holder.Visible = false
                    end
                end
    
                for _, Depbox in SubTab.DependencyBoxes do
                    if not Depbox.Visible then
                        continue
                    end
    
                    local DepVisible, DepScore = CheckDepbox(Depbox, Search, SubTabMatches)
                    VisibleElements[SubTab] += DepVisible
                    SubScore = math.max(SubScore, DepScore)
                    BestScore = math.max(BestScore, DepScore)
                end
    
                SubTabScores[SubTab] = SubScore
            end
    
            local BestSubTab = nil
            local BestSubScore = -1
    
            for SubTab, Visible in VisibleElements do
                SubTab.ButtonHolder.Visible = Visible > 0
                if Visible > 0 then
                    VisibleTabs += 1
                    HasVisible = true
    
                    local SubScore = SubTabScores[SubTab] or 0
                    if SubScore > BestSubScore then
                        BestSubScore = SubScore
                        BestSubTab = SubTab
                    end
                end
            end
    
            local ActiveSubTab = Tabbox.ActiveTab
            local ActiveSubVisible = ActiveSubTab and (VisibleElements[ActiveSubTab] or 0) > 0
            local ActiveSubScore = ActiveSubTab and (SubTabScores[ActiveSubTab] or -1) or -1
    
            if ActiveSubVisible and ActiveSubScore >= BestSubScore then
                ActiveSubTab:Resize()
            elseif BestSubTab then
                BestSubTab:Show()
            end
    
            Tabbox.BoxHolder.Visible = VisibleTabs > 0
            SyncPopOutVisibility(Tabbox)
        end
    
        return HasVisible, BestScore
    end
    local function ResetTab(Tab)
        if not Tab then
            return
        end
    
        for _, Groupbox in Tab.Groupboxes do
            for _, ElementInfo in Groupbox.Elements do
                ElementInfo.Holder.Visible = ElementInfo.Visible ~= false
    
                if ElementInfo.SubButton then
                    ElementInfo.Base.Visible = ElementInfo.Visible
                    ElementInfo.SubButton.Base.Visible = ElementInfo.SubButton.Visible
                end
            end
    
            for _, Depbox in Groupbox.DependencyBoxes do
                if not Depbox.Visible then
                    continue
                end
    
                RestoreDepbox(Depbox)
            end
    
            Groupbox:Resize()
            Groupbox.BoxHolder.Visible = Groupbox.Visible ~= false
            SyncPopOutVisibility(Groupbox)
        end
    
        for _, Tabbox in Tab.Tabboxes do
            for _, SubTab in Tabbox.Tabs do
                for _, ElementInfo in SubTab.Elements do
                    ElementInfo.Holder.Visible = ElementInfo.Visible ~= false
    
                    if ElementInfo.SubButton then
                        ElementInfo.Base.Visible = ElementInfo.Visible
                        ElementInfo.SubButton.Base.Visible = ElementInfo.SubButton.Visible
                    end
                end
    
                for _, Depbox in SubTab.DependencyBoxes do
                    if not Depbox.Visible then
                        continue
                    end
    
                    RestoreDepbox(Depbox)
                end
    
                SubTab.ButtonHolder.Visible = true
            end
    
            if Tabbox.ActiveTab then
                Tabbox.ActiveTab:Resize()
            end
            Tabbox.BoxHolder.Visible = true
            SyncPopOutVisibility(Tabbox)
        end
    end
    
    function Library:QueueSearchRefresh()
        if not Library.Searching or Library.SearchRefreshQueued then
            return
        end
    
        Library.SearchRefreshQueued = true
        task.defer(function()
            Library.SearchRefreshQueued = false
            if Library.Searching and not Library.Unloaded then
                Library:UpdateSearch(Library.SearchText)
            end
        end)
    end
    
    function Library:UpdateSearch(SearchText)
        SearchText = tostring(SearchText or "")
        local QueryChanged = SearchText ~= Library.LastSearchQuery
        Library.LastSearchQuery = SearchText
        Library.SearchText = SearchText
    
        local TabsToSearch = {}
        for _, Tab in Library.Tabs do
            if typeof(Tab) == "table" and not Tab.IsKeyTab then
                table.insert(TabsToSearch, Tab)
            end
        end
    
        for _, Tab in TabsToSearch do
            ResetTab(Tab)
        end
    
        local Search = Trim((SearchText:lower():gsub("%s+", " ")))
        if Search == "" then
            Library.Searching = false
            Library.LastSearchTab = nil
            return
        end
        if not Library.GlobalSearch and Library.ActiveTab and Library.ActiveTab.IsKeyTab then
            Library.Searching = false
            Library.LastSearchTab = nil
            return
        end
    
        Library.Searching = true
    
        local Results = {}
        local BestTab = nil
        local BestScore = -1
    
        for _, Tab in TabsToSearch do
            local HasVisible, Score = ApplySearchToTab(Tab, Search)
            if not HasVisible then
                continue
            end
    
            Results[Tab] = Score
            if Score > BestScore then
                BestScore = Score
                BestTab = Tab
            end
        end
    
        local ActiveTab = Library.ActiveTab
        local ActiveScore = ActiveTab and Results[ActiveTab]
        local Target = ActiveTab
        if QueryChanged and BestTab and not (ActiveScore and ActiveScore >= BestScore) then
            Target = BestTab
        end
    
        if not Library.GlobalSearch then
            for _, Tab in TabsToSearch do
                if Tab ~= Target or not Results[Tab] then
                    ResetTab(Tab)
                end
            end
        end
    
        if Target == ActiveTab then
            if ActiveTab then
                ActiveTab:RefreshSides()
            end
        elseif Target then
            local SearchMarker = SearchText
            task.defer(function()
                if Library.SearchText ~= SearchMarker then
                    return
                end
    
                if Library.ActiveTab ~= Target then
                    Target:Show()
                elseif Library.ActiveTab then
                    Library.ActiveTab:RefreshSides()
                end
            end)
        end
    
        Library.LastSearchTab = nil
    end
    
    function Library:AddToRegistry(Instance, Properties)
        Library.Registry[Instance] = Properties
    end
    
    function Library:RemoveFromRegistry(Instance)
        Library.Registry[Instance] = nil
    end
    
    Library.ThemeListeners = {}
    
    function Library:OnThemeChanged(Callback: () -> ())
        table.insert(Library.ThemeListeners, Callback)
    end
    
    function Library:UpdateColorsUsingRegistry()
        for Instance, Properties in Library.Registry do
            for Property, Index in Properties do
                local SchemeValue = GetSchemeValue(Index)
    
                if SchemeValue or typeof(Index) == "function" then
                    Instance[Property] = SchemeValue or Index()
                end
            end
        end
    
        if Library.ThemeListenersQueued then
            return
        end
        Library.ThemeListenersQueued = true
        task.defer(function()
            Library.ThemeListenersQueued = false
            for _, Group in { Library.Options, Library.Toggles } do
                for _, Option in Group do
                    if typeof(Option) == "table" and typeof(Option.UpdateColors) == "function" then
                        pcall(Option.UpdateColors, Option)
                    end
                end
            end
            for _, Listener in Library.ThemeListeners do
                task.spawn(pcall, Listener)
            end
        end)
    end
    
    function Library:SetDPIScale(DPIScale: number)
        Library.DPIScale = DPIScale / 100
        Library.MinSize = Library.OriginalMinSize * Library.DPIScale
    
        for _, UIScale in Library.Scales do
            UIScale.Scale = Library.DPIScale - (tonumber(Library.ScalesOffset[UIScale]) or 0)
        end
    
        for _, Option in Options do
            if Option.Type == "Dropdown" then
                Option:RecalculateListSize()
                Option:RefreshPool()
            end
        end
    
        for _, Notification in Library.Notifications do
            Notification:Resize()
        end
    end
    
    function Library:GiveSignal(Connection: RBXScriptConnection | RBXScriptSignal)
        local ConnectionType = typeof(Connection)
        if Connection and (ConnectionType == "RBXScriptConnection" or ConnectionType == "RBXScriptSignal") then
            table.insert(Library.Signals, Connection)
        end
    
        return Connection
    end
    
    function IsValidCustomIcon(Icon: string)
        return typeof(Icon) == "string" and (Icon:match("^rbxasset://textures/") or Icon:match("roblox%.com/asset/%?id=") or Icon:match("rbxthumb://type="))
    end
    
    local function IsCustomAssetIcon(Icon: string, IncludeAssetId: boolean)
        return typeof(Icon) == "string" and (Icon:match("^content://") or (Icon:match("^rbxasset://%x+/") or Icon:match("^rbxasset://[^/]+/")) or (IncludeAssetId == true and Icon:match("^rbxassetid://")))
    end
    
    type Icon = {
        Url: string,
        Id: number,
        IconName: string,
        ImageRectOffset: Vector2,
        ImageRectSize: Vector2,
    }
    
    type IconModule = {
        Icons: { string },
        GetAsset: (Name: string) -> Icon?,
    }
    
    local FetchIcons = false
    local Icons: IconModule | nil = nil
    -- First run without the Lucide cache: while the download runs, GetIcon hands out a placeholder (Pending) and
    -- ApplyLucideIcon remembers every image it was applied to (Users: image -> icon name); SetIconModule fills them in
    local IconState = { Pending = false, Users = setmetatable({}, { __mode = "k" }), LoadBase = function() end }

    function Library:IconsReady(): boolean
        return FetchIcons and Icons ~= nil
    end

    function Library:GetIcon(IconName: string)
        if not FetchIcons or not Icons then
            if IconState.Pending and typeof(IconName) == "string" and IconName ~= "" then
                return {
                    Url = "",
                    ImageRectOffset = Vector2.zero,
                    ImageRectSize = Vector2.zero,
                    IconName = IconName,
                    Pending = true,
                }
            end
            return
        end
    
        local Success, Icon = pcall(Icons.GetAsset, IconName)
        if not Success then
            return
        end
    
        return Icon
    end
    
    function Library:GetCustomIcon(IconName: string): any
        if not IconName then
            return nil
        end
    
        if typeof(IconName) == "string" then
            local Key = string.lower(IconName)
            local Embedded = EmbeddedAssets[Key]
            if Embedded then
                local AssetId = Library:GetEmbeddedAsset(Key)
                if AssetId then
                    return {
                        Url = AssetId,
                        ImageRectOffset = Vector2.zero,
                        ImageRectSize = Vector2.zero,
                        Custom = true,
                        Embedded = true,
                    }
                end
    
                return Library:GetIcon(Embedded.Fallback or "bird")
            end
    
            if string.match(IconName, "^https?://") then
                return Library:GetRemoteImage(IconName)
            end
        end
    
        if typeof(IconName) == "number" or (typeof(IconName) == "string" and IconName:match("^%d+$")) then
            IconName = string.format("rbxassetid://%s", tostring(IconName))
        end
    
        if IsCustomAssetIcon(IconName, true) then
            return {
                Url = IconName,
                ImageRectOffset = Vector2.zero,
                ImageRectSize = Vector2.zero,
            }
        elseif IsValidCustomIcon(IconName) then
            return {
                Url = IconName,
                ImageRectOffset = Vector2.zero,
                ImageRectSize = Vector2.zero,
                Custom = true,
            }
        end
    
        local LucideIcon = Library:GetIcon(IconName)
        if LucideIcon then
            return LucideIcon
        end
    
        return nil
    end
    
    function Library:ApplyLucideIcon(ImageGui: any, Icon: any, Rotation: number?)
        if not ImageGui or not Icon then
            return
        end
    
        if not (ImageGui:IsA("ImageLabel") or ImageGui:IsA("ImageButton")) then
            return
        end

        if Icon.Pending then
            local Real = if FetchIcons and Icons then Library:GetIcon(Icon.IconName) else nil
            if Real then
                Icon = Real
            elseif not (FetchIcons and Icons) then
                IconState.Users[ImageGui] = Icon.IconName
            end
        end
        if not Icon.Pending then
            IconState.Users[ImageGui] = nil
        end

        ImageGui.Image = Icon.Url or ImageGui.Image
        ImageGui.ImageRectOffset = Icon.ImageRectOffset or ImageGui.ImageRectOffset
        ImageGui.ImageRectSize = Icon.ImageRectSize or ImageGui.ImageRectSize
        ImageGui.Rotation = Rotation or ImageGui.Rotation
    end
    
    function Library:Validate(Table: { [string]: any }, Template: { [string]: any }): { [string]: any }
        if typeof(Table) ~= "table" then
            return Template
        end
    
        for k, v in Template do
            if typeof(k) == "number" then
                continue
            end
    
            if typeof(v) == "table" then
                Table[k] = Library:Validate(Table[k], v)
            elseif Table[k] == nil then
                Table[k] = v
            end
        end
    
        return Table
    end
    
    local function FillInstance(Table: { [string]: any }, Instance: GuiObject)
        local ThemeProperties = Library.Registry[Instance] or {}
    
        for key, value in Table do
            if key ~= "Text" then
                local SchemeValue = GetSchemeValue(value)
    
                if SchemeValue or typeof(value) == "function" then
                    ThemeProperties[key] = value
                    value = SchemeValue or value()
                else
                    ThemeProperties[key] = nil
                end
            end
    
            Instance[key] = value
        end
    
        if GetTableSize(ThemeProperties) > 0 then
            Library.Registry[Instance] = ThemeProperties
        end
    end
    
    local function New(ClassName: string, Properties: { [string]: any }): any
        local Instance = CreateInstance(ClassName)
    
        if Templates[ClassName] then
            FillInstance(Templates[ClassName], Instance)
        end
        FillInstance(Properties, Instance)
    
        if Properties["Parent"] and not Properties["ZIndex"] then
            pcall(function()
                Instance.ZIndex = Properties.Parent.ZIndex
            end)
        end
    
        return Instance
    end
    
    local function GetBoldFont()
        local Current = Library.Scheme.Font
        local Family = typeof(Current) == "Font" and Current.Family or "rbxasset://fonts/families/BuilderSans.json"
        return Font.new(Family, Enum.FontWeight.Bold)
    end
    
    local function GetMediumFont()
        local Current = Library.Scheme.Font
        local Family = typeof(Current) == "Font" and Current.Family or "rbxasset://fonts/families/BuilderSans.json"
        return Font.new(Family, Enum.FontWeight.Medium)
    end
    
    local function GetLinkColor()
        return Library.Scheme.LinkColor or Library.Scheme.AccentColor
    end
    
    local function GetSecondaryAccent(): Color3
        local Secondary = Library.Scheme.SecondaryAccentColor
        if typeof(Secondary) == "Color3" then
            return Secondary
        end
    
        return Library.Scheme.AccentColor:Lerp(Color3.fromRGB(236, 242, 255), 0.6)
    end
    
    local function GetNebulaSequence()
        return ColorSequence.new(Library.Scheme.AccentColor, GetSecondaryAccent())
    end
    
    local function GetBadgeColor()
        return Library.Scheme.BadgeColor or Color3.fromRGB(255, 92, 122)
    end
    
    function Library:GetSecondaryAccent(): Color3
        return GetSecondaryAccent()
    end
    
    function Library:AddHoverStroke(Target: GuiObject, Stroke: UIStroke, IsLocked: (() -> boolean)?, IsDisabled: (() -> boolean)?)
        if not (Target and Stroke) then
            return nil
        end
    
        local Hovering = false
        local function Refresh()
            if Library.Unloaded or not Stroke.Parent then
                return
            end
    
            local Active = (Hovering or (IsLocked ~= nil and IsLocked() == true)) and not (IsDisabled ~= nil and IsDisabled() == true)
            Library:SetSchemeProperty(Stroke, "Color", if Active then "AccentColor" else "OutlineColor", true)
        end
    
        Target.MouseEnter:Connect(function()
            Hovering = true
            Refresh()
        end)
        Target.MouseLeave:Connect(function()
            Hovering = false
            Refresh()
        end)
    
        return Refresh
    end
    
    function Library:SetSchemeProperty(Inst: Instance, Property: string, Key: any, UseTween: boolean?)
        if not Inst then
            return
        end
    
        local Properties = Library.Registry[Inst]
        if not Properties then
            Properties = {}
            Library.Registry[Inst] = Properties
        end
        Properties[Property] = Key
    
        local Value = GetSchemeValue(Key)
        if Value == nil and typeof(Key) == "function" then
            Value = Key()
        end
        if Value == nil then
            return
        end
    
        if UseTween then
            TweenService:Create(Inst, Library.TweenInfo, { [Property] = Value }):Play()
        else
            Inst[Property] = Value
        end
    end
    
    function Library:AddIconHover(Target: GuiObject, Icon: GuiObject, Options: { [string]: any }?)
        if not (Target and Icon) then
            return nil
        end
    
        Options = Options or {}
    
        local IconScale = Icon:FindFirstChildOfClass("UIScale")
        if not IconScale then
            IconScale = New("UIScale", {
                Parent = Icon,
            })
        end
    
        local Hover = {
            Hovering = false,
            Connections = {},
            Scale = IconScale,
        }
    
        local HoverScale = Options.Scale or 1.15
        local PressScale = Options.PressScale or 0.88
        local BaseRotation = Options.BaseRotation or Icon.Rotation
        local EnterInfo = TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        local LeaveInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local MotionToken = 0
    
        local function IsEnabled()
            return Library.IconAnimations ~= false and not Library.Unloaded
        end
    
        local function RestTransparency()
            local Rest = Options.RestTransparency
            if typeof(Rest) == "function" then
                return Rest()
            end
            return Rest
        end
    
        local function PlayWiggle()
            MotionToken += 1
            local Token = MotionToken
    
            task.spawn(function()
                for _, Angle in { -16, 13, -9, 5, 0 } do
                    if Token ~= MotionToken or not Icon.Parent then
                        return
                    end
    
                    TweenService:Create(Icon, TweenInfo.new(0.07, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                        Rotation = BaseRotation + Angle,
                    }):Play()
                    task.wait(0.07)
                end
            end)
        end
    
        local function PlaySpin()
            MotionToken += 1
            local Token = MotionToken
    
            Icon.Rotation = BaseRotation
            local Tween = TweenService:Create(Icon, TweenInfo.new(0.6, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                Rotation = BaseRotation + (Options.Spin or 360),
            })
            Tween.Completed:Once(function()
                if Token == MotionToken and Icon.Parent then
                    Icon.Rotation = BaseRotation
                end
            end)
            Tween:Play()
        end
    
        table.insert(Hover.Connections, Target.MouseEnter:Connect(function()
            Hover.Hovering = true
            if not IsEnabled() then
                return
            end
    
            TweenService:Create(IconScale, EnterInfo, { Scale = HoverScale }):Play()
    
            if Options.Wiggle then
                PlayWiggle()
            elseif Options.Spin then
                PlaySpin()
            elseif Options.Tilt then
                TweenService:Create(Icon, EnterInfo, { Rotation = BaseRotation + Options.Tilt }):Play()
            end
    
            if Options.Transparency ~= nil then
                TweenService:Create(Icon, Library.TweenInfo, { ImageTransparency = Options.Transparency }):Play()
            end
        end))
    
        table.insert(Hover.Connections, Target.MouseLeave:Connect(function()
            Hover.Hovering = false
            if Library.Unloaded then
                return
            end
    
            TweenService:Create(IconScale, LeaveInfo, { Scale = 1 }):Play()
    
            if Options.Tilt then
                TweenService:Create(Icon, LeaveInfo, { Rotation = BaseRotation }):Play()
            end
    
            local Rest = RestTransparency()
            if Options.Transparency ~= nil and Rest ~= nil then
                TweenService:Create(Icon, Library.TweenInfo, { ImageTransparency = Rest }):Play()
            end
        end))
    
        if Options.Press ~= false and Target:IsA("GuiButton") then
            table.insert(Hover.Connections, Target.MouseButton1Down:Connect(function()
                if not IsEnabled() then
                    return
                end
    
                TweenService:Create(IconScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Scale = PressScale,
                }):Play()
            end))
    
            table.insert(Hover.Connections, Target.MouseButton1Up:Connect(function()
                if not IsEnabled() then
                    return
                end
    
                TweenService:Create(IconScale, EnterInfo, {
                    Scale = Hover.Hovering and HoverScale or 1,
                }):Play()
            end))
        end
    
        function Hover:SetBaseRotation(Rotation: number)
            BaseRotation = Rotation
        end
    
        function Hover:Destroy()
            for _, Connection in Hover.Connections do
                Connection:Disconnect()
            end
            table.clear(Hover.Connections)
        end
    
        return Hover
    end
    
    local function SafeParentUI(Instance: Instance, Parent: Instance | () -> Instance)
        local success, _error = pcall(function()
            if not Parent then
                Parent = CoreGui
            end
    
            local DestinationParent
            if typeof(Parent) == "function" then
                DestinationParent = Parent()
            else
                DestinationParent = Parent
            end
    
            Instance.Parent = DestinationParent
        end)
    
        if not (success and Instance.Parent) then
            Instance.Parent = Library.LocalPlayer:WaitForChild("PlayerGui", math.huge)
        end
    end
    
    local function ParentUI(UI: Instance, SkipHiddenUI: boolean?)
        if SkipHiddenUI then
            SafeParentUI(UI, CoreGui)
            return
        end
    
        pcall(protectgui, UI)
        SafeParentUI(UI, gethui)
    end
    
    local function SetAlwaysOnTop(Gui: ScreenGui, Enabled: boolean)
        if not Gui then
            return
        end
    
        pcall(function()
            if sethiddenproperty then
                sethiddenproperty(Gui, "OnTopOfCoreBlur", Enabled)
            elseif setscriptable then
                setscriptable(Gui, "OnTopOfCoreBlur", true)
                Gui.OnTopOfCoreBlur = Enabled
                setscriptable(Gui, "OnTopOfCoreBlur", false)
            end
        end)
    end
    
    do
        local Env = getgenv()
        local Previous = Env.CorvusLibrary
        if typeof(Previous) == "table" and typeof(Previous.Unload) == "function" and not Previous.Unloaded then
            pcall(Previous.Unload, Previous)
        end
        pcall(function()
            local Containers = { game:GetService("CoreGui") }
            if typeof(gethui) == "function" then
                table.insert(Containers, gethui())
            end
            local PlayerGui = LocalPlayer and LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if PlayerGui then
                table.insert(Containers, PlayerGui)
            end
            for _, Container in Containers do
                for _, Child in Container:GetChildren() do
                    if Child:IsA("ScreenGui") and Child.Name == "Corvus" then
                        Child:Destroy()
                    end
                end
            end
        end)
    end
    
