    local CheckIcon, ArrowIcon, ResizeIcon, KeyIcon, MoveIcon, PopOutIcon, CloseIcon
    local ExpandIcon, CopyIcon, BellIcon, BellOffIcon, MinusIcon, PlusIcon, TrashIcon
    function IconState.LoadBase()
        CheckIcon = Library:GetIcon("check")
        ArrowIcon = Library:GetIcon("chevron-up")
        ResizeIcon = Library:GetIcon("move-diagonal-2")
        KeyIcon = Library:GetIcon("key")
        MoveIcon = Library:GetIcon("move")
        PopOutIcon = Library:GetIcon("square-arrow-down-left")
        CloseIcon = Library:GetIcon("x")
        ExpandIcon = Library:GetIcon("maximize-2")
        CopyIcon = Library:GetIcon("copy")
        BellIcon = Library:GetIcon("bell")
        BellOffIcon = Library:GetIcon("bell-off")
        MinusIcon = Library:GetIcon("minus")
        PlusIcon = Library:GetIcon("plus")
        TrashIcon = Library:GetIcon("trash-2")
    end
    function Library:SetIconModule(module: IconModule)
        FetchIcons = true
        Icons = module
        IconState.Pending = false
        IconState.LoadBase()
        -- images that asked for an icon before the module arrived (tabs, checks, arrows, buttons...) get it now
        local Users = IconState.Users
        IconState.Users = setmetatable({}, { __mode = "k" })
        for ImageGui, Name in Users do
            local Icon = Library:GetIcon(Name)
            if Icon then
                pcall(Library.ApplyLucideIcon, Library, ImageGui, Icon)
            end
        end
    end

    -- Lucide icons: a cached copy loads from disk at once, the download only refreshes the cache in the background
	-- (a synchronous download here held the whole start on slow executors). Without a usable cache (first run on an
	-- executor) the download starts here, Library:CreateWindow waits for it up to 4 s from now, and anything that asks
	-- for an icon earlier or later gets a placeholder that SetIconModule fills in. LOAD shows icons=cache|net|late|none.
	do
		local LucideUrl = "https://raw.githubusercontent.com/mstudio45/lucide-roblox-direct/refs/heads/main/source.lua"
		local LucideFile = "Corvus/lucide.lua"
		local IconsT0 = os.clock()
		local function ApplyIcons(Source)
			if typeof(Source) ~= "string" or #Source < 1000 then
				return false
			end
			local Ok, Module = pcall(function()
				return (loadstring(Source) :: any)()
			end)
			if Ok and Module then
				Library:SetIconModule(Module)
				return true
			end
			return false
		end
		local Cached = nil
		pcall(function()
			if isfile and readfile and isfile(LucideFile) then
				Cached = readfile(LucideFile)
			end
		end)
		local UsedCache = ApplyIcons(Cached)
		local Settled, WaitOver = UsedCache, false
		CorvusLoadTimes.icons = os.clock() - IconsT0
		CorvusLoadTimes.iconsState = if UsedCache then "cache" else "none"
		if not UsedCache then
			IconState.Pending = true
			IconState.LoadBase()
		end
		task.spawn(function()
			local Ok, Source = pcall(game.HttpGet, game, LucideUrl)
			local Fresh = Ok and typeof(Source) == "string" and #Source >= 1000 and Source ~= Cached
			if Fresh then
				pcall(function()
					if isfolder and makefolder and not isfolder("Corvus") then
						makefolder("Corvus")
					end
					if writefile then
						writefile(LucideFile, Source)
					end
				end)
			end
			if not UsedCache then
				if Fresh and not Library.Unloaded and ApplyIcons(Source) then
					CorvusLoadTimes.iconsState = string.format(if WaitOver then "late(%.1fs)" else "net(%.1fs)", os.clock() - IconsT0)
				else
					IconState.Pending = false
					IconState.LoadBase()
					CorvusLoadTimes.iconsState = "none"
				end
			end
			Settled = true
		end)
		-- called by CreateWindow before the UI is built: no cache -> wait for the download, at most Limit s after its start
		function Library:WaitForIcons(Limit: number?)
			if Settled or WaitOver then
				return
			end
			local T0 = os.clock()
			local Deadline = IconsT0 + (Limit or 4)
			while not Settled and not Library.Unloaded and os.clock() < Deadline do
				if not pcall(task.wait, 0.05) then
					break
				end
			end
			CorvusLoadTimes.icons = (CorvusLoadTimes.icons or 0) + (os.clock() - T0)
			if not Settled then
				WaitOver = true
				CorvusLoadTimes.iconsState = "late(pending)"
			end
		end
	end
    
    Library.Cursor = {}
    
    function Library.Cursor:ResetCross()
        for _, Inner in InnerCross do
            Library.Registry[Inner].BackgroundColor3 = "WhiteColor"
            Inner.BackgroundColor3 = Library.Scheme.WhiteColor
        end
    end
    
    function Library.Cursor:ResetIcon()
        CursorCross.Visible = true
        CursorCustomImage.Visible = false
        CursorCustomImage.ImageColor3 = Color3.new(1, 1, 1)
        CursorCustomImage.Size = UDim2.fromOffset(20, 20)
    end
    
    function Library.Cursor:ResetCursor()
        Library.Cursor:ResetCross()
        Library.Cursor:ResetIcon()
    end
    
    function Library.Cursor:ChangeCrossColor(Color: Color3)
        assert(typeof(Color) == "Color3", "Color3 expected.")
        for _, Inner in InnerCross do
            Inner.BackgroundColor3 = Color
            Library.Registry[Inner].BackgroundColor3 = nil
        end
    end
    
    function Library.Cursor:ChangeIcon(ImageId: string)
        if not ImageId or ImageId == "" then
            Library.Cursor:ResetIcon()
            return
        end
    
        local Icon = Library:GetCustomIcon(ImageId)
        assert(Icon, "Image must be a valid Roblox asset or a valid URL or a valid lucide icon.")
    
        CursorCross.Visible = false
        CursorCustomImage.Visible = true
        Library:ApplyLucideIcon(CursorCustomImage, Icon)
    end
    
    function Library.Cursor:ChangeIconColor(Color: Color3)
        assert(typeof(Color) == "Color3", "Color3 expected.")
        CursorCustomImage.ImageColor3 = Color
    end
    
    function Library.Cursor:ChangeIconSize(Size: UDim2)
        assert(typeof(Size) == "UDim2", "UDim2 expected.")
        CursorCustomImage.Size = Size
