    function Library:AddOutline(Frame: GuiObject)
        local OutlineStroke = New("UIStroke", {
            Color = "OutlineColor",
            Thickness = 1,
            ZIndex = 2,
            Parent = Frame,
        })
        local ShadowStroke = New("UIStroke", {
