    local CurrentMenu
    function Library:AddContextMenu(
        Holder: GuiObject,
        Size: UDim2 | () -> (),
        Offset: { [number]: number } | () -> {},
        List: number?,
        ActiveCallback: (Active: boolean) -> ()?,
        IgnoreCornerRadius: boolean?,
        SpecificCornersOnly: ("top" | "bottom" | "no_left" | "no_top_left")?,
        AnimationType: ("Dropdown" | "KeyPicker" | "none")?
    )
        local Menu
        local HolderGui = Holder:FindFirstAncestorOfClass("ScreenGui")
        local ParentGui = Overlay
        if HolderGui and HolderGui ~= ScreenGui and Library.ActiveLoading and HolderGui == Library.ActiveLoading.ScreenGui then
            ParentGui = HolderGui
        end
    
        if List then
            Menu = New("ScrollingFrame", {
                AutomaticCanvasSize = Enum.AutomaticSize.None,
                AutomaticSize = List == 1 and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
                BackgroundColor3 = "BackgroundColor",
                BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
                CanvasSize = UDim2.fromOffset(0, 0),
                ScrollBarImageColor3 = "OutlineColor",
                ScrollBarThickness = List == 2 and 2 or 0,
                Size = typeof(Size) == "function" and Size() or Size,
                TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
                Visible = false,
                ZIndex = 1,
                Parent = ParentGui,
            })
        else
            Menu = New("Frame", {
                BackgroundColor3 = "BackgroundColor",
                Size = typeof(Size) == "function" and Size() or Size,
                Visible = false,
                ZIndex = 1,
                Parent = ParentGui,
            })
        end
        table.insert(
            Library.Scales,
            New("UIScale", {
                Parent = Menu,
            })
        )
    
        New("UIStroke", {
            Color = "OutlineColor",
            Parent = Menu,
        })
    
        local Corner;
        if IgnoreCornerRadius ~= true then
            if SpecificCornersOnly == "top" then
                Corner = New("UICorner", {
                    TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                    TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomRightRadius = UDim.new(0, 0),
                    BottomLeftRadius = UDim.new(0, 0),
                    Parent = Menu,
                }); table.insert(Library.SpecificCorners, Corner)
            elseif SpecificCornersOnly == "bottom" then
                Corner = New("UICorner", {
                    TopLeftRadius = UDim.new(0, 0),
                    TopRightRadius = UDim.new(0, 0),
                    BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Menu,
                }); table.insert(Library.SpecificCorners, Corner)
            elseif SpecificCornersOnly == "no_left" then
                Corner = New("UICorner", {
                    TopLeftRadius = UDim.new(0, 0),
                    TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomLeftRadius = UDim.new(0, 0),
                    Parent = Menu,
                }); table.insert(Library.SpecificCorners, Corner)
            elseif SpecificCornersOnly == "no_top_left" then
                Corner = New("UICorner", {
                    TopLeftRadius = UDim.new(0, 0),
                    TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                    BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Menu,
                }); table.insert(Library.SpecificCorners, Corner)
            else
                Corner = New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Menu,
                }); table.insert(Library.Corners, Corner)
            end
        end
    
        local Table = {
            Connections = {},
            Destroyed = false,
    
            Active = false,
            ActiveCallback = ActiveCallback,
    
            Holder = Holder,
            Menu = Menu,
            Corner = Corner,
    
            List = nil,
            Signal = nil,
    
            Size = Size,
            AutoSizeY = List == 1,
    
            OpenCloseTween = nil,
            Animated = function()
                if not AnimationType or AnimationType == "none" then
                    return false
                end
    
                if not (Library.Animations and Library.Animations[AnimationType] == true) then
                    return false
                end
    
                return true, Library[string.format("%sTransitionInfo", AnimationType)] or TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            end
        }
    
        if List == 1 then
            Table.List = New("UIListLayout", {
                Parent = Menu,
            })
        end
    
        function Table:FitToScreen()
            local Size = typeof(Table.Size) == "function" and Table.Size() or Table.Size
            if typeof(Size) ~= "UDim2" then
                return
            end
            local Height = if Table.AutoSizeY then Menu.AbsoluteSize.Y else Size.Y.Offset * Library.DPIScale
            if Height <= 0 then
                return
            end
            local Area = if Library.GetGuiArea then Library:GetGuiArea() else Vector2.new(1920, 1080)
            local Top = Menu.Position.Y.Offset
            if Top + Height <= Area.Y - 6 then
                return
            end
            local Above = Holder.AbsolutePosition.Y - Height - 4
            local NewY = if Above >= 6 then Above else Area.Y - Height - 6
            NewY = math.clamp(NewY, 6, math.max(6, Area.Y - Height - 6))
            Menu.Position = UDim2.fromOffset(Menu.Position.X.Offset, math.floor(NewY))
        end
    
        function Table:Open()
            if CurrentMenu == Table then
                return
            elseif CurrentMenu then
                CurrentMenu:Close()
            end
    
            CurrentMenu = Table
            Table.Active = true
            Menu.ZIndex = 1
            do
                local MenuScale = Menu:FindFirstChildOfClass("UIScale")
                if MenuScale then
                    MenuScale.Scale = Library.DPIScale - (tonumber(Library.ScalesOffset[MenuScale]) or 0)
                end
            end
    
            local TargetParent = if ParentGui == Overlay then Overlay else ParentGui
            Menu.Parent = nil
            Menu.Parent = TargetParent
    
            if typeof(Offset) == "function" then
                Menu.Position = UDim2.fromOffset(
                    math.floor(Holder.AbsolutePosition.X + Offset()[1]),
                    math.floor(Holder.AbsolutePosition.Y + Offset()[2])
                )
            else
                Menu.Position = UDim2.fromOffset(
                    math.floor(Holder.AbsolutePosition.X + Offset[1]),
                    math.floor(Holder.AbsolutePosition.Y + Offset[2])
                )
            end
    
            pcall(Table.FitToScreen, Table)
    
            local TargetSize = typeof(Table.Size) == "function" and Table.Size() or Table.Size
    
            if typeof(ActiveCallback) == "function" then
                Library:SafeCallback(ActiveCallback, true)
            end
    
            if Table.OpenCloseTween then
                StopTween(Table.OpenCloseTween, true)
                Table.OpenCloseTween = nil
            end
    
            local IsAnimated, TweenInfo = Table.Animated()
            if IsAnimated == true then
                local OpenSize = TargetSize
                if Table.AutoSizeY then
                    local FullHeight = Menu.AbsoluteSize.Y
    
                    Menu.AutomaticSize = Enum.AutomaticSize.None
                    OpenSize = UDim2.new(TargetSize.X.Scale, TargetSize.X.Offset, 0, FullHeight)
                end
    
                Menu.Size = UDim2.new(OpenSize.X.Scale, OpenSize.X.Offset, 0, 0)
                Menu.Visible = true
    
                local Tween = TweenService:Create(Menu, TweenInfo, { Size = OpenSize })
                Table.OpenCloseTween = Tween
    
                local Connection; Connection = Library:GiveSignal(Tween.Completed:Once(function()
                    if Connection then
                        Connection:Disconnect()
                    end
    
                    if Table.OpenCloseTween == Tween then
                        StopTween(Table.OpenCloseTween, true)
                        Table.OpenCloseTween = nil
    
                        if Table.AutoSizeY then
                            Menu.AutomaticSize = Enum.AutomaticSize.Y
                        end
                    end
                end))
    
                Tween:Play()
            else
                Menu.Size = TargetSize
                Menu.Visible = true
            end
    
            Table.Signal = Holder:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
                if typeof(Offset) == "function" then
                    Menu.Position = UDim2.fromOffset(
                        math.floor(Holder.AbsolutePosition.X + Offset()[1]),
                        math.floor(Holder.AbsolutePosition.Y + Offset()[2])
                    )
                else
                    Menu.Position = UDim2.fromOffset(
                        math.floor(Holder.AbsolutePosition.X + Offset[1]),
                        math.floor(Holder.AbsolutePosition.Y + Offset[2])
                    )
                end
    
                pcall(Table.FitToScreen, Table)
    
                local HolderAllowed = Library:IsInsideFrame(Library.WindowContainer, Holder)
                if not HolderAllowed then
                    for _, Surface in Library.DraggableElements do
                        if not (Surface and Library:IsInsideFrame(Surface, Holder)) then
                            continue
                        end
    
                        HolderAllowed = true
                        break
                    end
                end
    
                if not HolderAllowed and Table.Active then
                    Table:Close()
                end
            end)
        end
    
        function Table:Close()
            if CurrentMenu ~= Table then
                return
            end
    
            if Table.Signal then
                Table.Signal:Disconnect()
                Table.Signal = nil
            end
    
            Table.Active = false
            CurrentMenu = nil
    
            if typeof(ActiveCallback) == "function" then
                Library:SafeCallback(ActiveCallback, false)
            end
    
            if Table.OpenCloseTween then
                StopTween(Table.OpenCloseTween, true)
                Table.OpenCloseTween = nil
            end
    
            local IsAnimated, TweenInfo = Table.Animated()
            if IsAnimated == true then
                if Table.AutoSizeY then
                    Menu.AutomaticSize = Enum.AutomaticSize.None
                end
    
                local CurrentSize = Menu.Size
                local CollapsedSize = UDim2.new(CurrentSize.X.Scale, CurrentSize.X.Offset, 0, 0)
    
                local Tween = TweenService:Create(Menu, TweenInfo, { Size = CollapsedSize })
                Table.OpenCloseTween = Tween
    
                local Connection; Connection = Library:GiveSignal(Tween.Completed:Once(function(PlaybackState)
                    if Connection then
                        Connection:Disconnect()
                    end
    
                    if Table.OpenCloseTween == Tween then
                        StopTween(Table.OpenCloseTween, true)
                        Table.OpenCloseTween = nil
    
                        Menu.Visible = false
                        if Table.AutoSizeY then
                            Menu.AutomaticSize = Enum.AutomaticSize.Y
                        end
                    end
                end))
    
                Tween:Play()
            else
                Menu.Visible = false
            end
        end
    
        function Table:Toggle()
            if Table.Active then
                Table:Close()
            else
                Table:Open()
            end
        end
    
        function Table:SetSize(Size)
            Table.Size = Size
            Menu.Size = typeof(Size) == "function" and Size() or Size
        end
    
        function Table:Destroy()
            Table.Destroyed = true
    
            if Table.Connections then
                for _, Connection in Table.Connections do
                    Connection:Disconnect()
                end
            end
    
            if CurrentMenu == Table then
                Table:Close()
            end
    
            if Table.OpenCloseTween then
                StopTween(Table.OpenCloseTween, true)
                Table.OpenCloseTween = nil
            end
    
            local MenuIndex = table.find(Library.ContextMenus, Table)
            if MenuIndex then
                table.remove(Library.ContextMenus, MenuIndex)
            end
    
            if Menu then
                Menu:Destroy()
            end
        end
    
        table.insert(Library.ContextMenus, Table)
        return Table
    end
    
    Library:GiveSignal(UserInputService.InputBegan:Connect(function(Input: InputObject)
        if Library.Unloaded then
            return
        end
    
        if IsClickInput(Input, true) then
            local Location = Input.Position
    
            if
                CurrentMenu
                and not (
                    Library:MouseIsOverFrame(CurrentMenu.Menu, Location)
                    or Library:MouseIsOverFrame(CurrentMenu.Holder, Location)
                )
            then
                CurrentMenu:Close()
            end
        end
    end))
    
    local TooltipLabel = New("TextLabel", {
        BackgroundColor3 = "MainColor",
        TextSize = 13,
        TextWrapped = true,
        Visible = false,
        ZIndex = 30,
        Parent = ScreenGui,
    })
    New("UIPadding", {
        PaddingBottom = UDim.new(0, 4),
        PaddingLeft = UDim.new(0, 7),
        PaddingRight = UDim.new(0, 7),
        PaddingTop = UDim.new(0, 4),
        Parent = TooltipLabel,
    })
    table.insert(
        Library.Scales,
        New("UIScale", {
            Parent = TooltipLabel,
        })
    )
    New("UIStroke", {
        Color = "OutlineColor",
        Parent = TooltipLabel,
    })
    table.insert(
        Library.Corners,
        New("UICorner", {
            CornerRadius = UDim.new(0, Library.CornerRadius / 2),
            Parent = TooltipLabel,
        })
    )
    
    local TooltipMeasureId = 0
    local LastTooltipText = ""
    local LastTooltipMaxWidth = 0
    
    local function UpdateTooltipSize(Force: boolean?)
        if Library.Unloaded or not TooltipLabel.Visible then
            return
        end
    
        local MaxWidth = math.clamp(
            (workspace.CurrentCamera.ViewportSize.X - TooltipLabel.AbsolutePosition.X - 8) / Library.DPIScale - 16,
            40,
            280
        )
    
        if
            not Force
            and TooltipLabel.Text == LastTooltipText
            and math.abs(MaxWidth - LastTooltipMaxWidth) < 1
            and TooltipLabel.Size.X.Offset > 0
        then
            return
        end
    
        TooltipMeasureId += 1
        local MeasureId = TooltipMeasureId
        local Text = TooltipLabel.Text
    
        local X, Y = Library:GetTextBounds(Text, TooltipLabel.FontFace, TooltipLabel.TextSize, MaxWidth)
        if MeasureId ~= TooltipMeasureId or TooltipLabel.Text ~= Text then
            return
        end
    
        LastTooltipText = Text
        LastTooltipMaxWidth = MaxWidth
        TooltipLabel.Size = UDim2.fromOffset(X + 16, Y + 8)
    end
    
    TooltipLabel:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
        UpdateTooltipSize(false)
    end)
    
    local CurrentHoverInstance
    function Library:AddTooltip(InfoStr: string, DisabledInfoStr: string, HoverInstance: GuiObject)
        local TooltipTable = {
            Disabled = false,
            Hovering = false,
            Signals = {},
        }
    
        local function DoHover()
            if
                CurrentHoverInstance == HoverInstance
                or Library.ActiveDialog
                or (CurrentMenu and Library:MouseIsOverFrame(CurrentMenu.Menu, Mouse))
                or (TooltipTable.Disabled and typeof(DisabledInfoStr) ~= "string")
                or (not TooltipTable.Disabled and typeof(InfoStr) ~= "string")
            then
                return
            end
            CurrentHoverInstance = HoverInstance
    
            local HolderGui = HoverInstance:FindFirstAncestorOfClass("ScreenGui")
            if HolderGui and HolderGui ~= ScreenGui and Library.ActiveLoading and HolderGui == Library.ActiveLoading.ScreenGui then
                TooltipLabel.Parent = HolderGui
            else
                TooltipLabel.Parent = ScreenGui
            end
    
            TooltipLabel.Text = TooltipTable.Disabled and DisabledInfoStr or InfoStr
            TooltipLabel.Position = UDim2.fromOffset(
                Mouse.X + (Library.ShowCustomCursor and 8 or 14),
                Mouse.Y + (Library.ShowCustomCursor and 8 or 12)
            )
            TooltipLabel.Visible = true
            UpdateTooltipSize(true)
    
            while
                (Library.Toggled or Library.ActiveLoading)
                and not Library.ActiveDialog
                and Library:MouseIsOverFrame(HoverInstance, Mouse)
                and not (CurrentMenu and Library:MouseIsOverFrame(CurrentMenu.Menu, Mouse))
            do
                TooltipLabel.Position = UDim2.fromOffset(
                    Mouse.X + (Library.ShowCustomCursor and 8 or 14),
                    Mouse.Y + (Library.ShowCustomCursor and 8 or 12)
                )
    
                RunService.RenderStepped:Wait()
            end
    
            TooltipLabel.Visible = false
            CurrentHoverInstance = nil
        end
    
        local function GiveSignal(Connection: RBXScriptConnection | RBXScriptSignal)
            local ConnectionType = typeof(Connection)
            if Connection and (ConnectionType == "RBXScriptConnection" or ConnectionType == "RBXScriptSignal") then
                table.insert(TooltipTable.Signals, Connection)
            end
    
            return Connection
        end
    
        GiveSignal(HoverInstance.MouseEnter:Connect(DoHover))
        GiveSignal(HoverInstance.MouseMoved:Connect(DoHover))
        GiveSignal(HoverInstance.MouseLeave:Connect(function()
            if CurrentHoverInstance ~= HoverInstance then
                return
            end
    
            TooltipLabel.Visible = false
            CurrentHoverInstance = nil
        end))
    
        function TooltipTable:Destroy()
            for Index = #TooltipTable.Signals, 1, -1 do
                local Connection = table.remove(TooltipTable.Signals, Index)
                if Connection and Connection.Connected then
                    Connection:Disconnect()
                end
            end
    
            if CurrentHoverInstance == HoverInstance then
                if TooltipLabel then
                    TooltipLabel.Visible = false
                end
    
                CurrentHoverInstance = nil
            end
        end
    
        table.insert(Tooltips, TooltipLabel)
        return TooltipTable
    end
    
    function Library:OnUnload(Callback)
        table.insert(Library.UnloadSignals, Callback)
    end
    
    local function ShadeColor(Color: Color3, Factor: number): Color3
        return Color3.new(
            math.clamp(Color.R * Factor, 0, 1),
            math.clamp(Color.G * Factor, 0, 1),
            math.clamp(Color.B * Factor, 0, 1)
        )
    end
    
    local function GetSwitchOnSequence()
        return ColorSequence.new(Library.Scheme.AccentColor, GetSecondaryAccent())
    end
    
    local function GetSwitchOffSequence()
        local Main = Library.Scheme.MainColor
        return ColorSequence.new(Library:GetBetterColor(Main, 27), Library:GetBetterColor(Main, 55))
    end
    
    local DiscordStatusColors = {
        online = Color3.fromRGB(35, 165, 90),
        idle = Color3.fromRGB(240, 178, 50),
        dnd = Color3.fromRGB(242, 63, 67),
        offline = Color3.fromRGB(128, 132, 142),
    }
    
    local function GetStatusColor(Status: string?): Color3
        return DiscordStatusColors[string.lower(tostring(Status or "online"))] or DiscordStatusColors.online
    end
    
    local function FormatThousands(Value: number): string
        local Formatted = tostring(math.floor(tonumber(Value) or 0))
        local Result = Formatted:reverse():gsub("(%d%d%d)", "%1,"):reverse()
        if Result:sub(1, 1) == "," then
            Result = Result:sub(2)
        end
        return Result
    end
    
    local function ParseDiscordInvite(Invite: any): (string?, string?)
        if typeof(Invite) ~= "string" then
            return nil, nil
        end
    
        Invite = Trim(Invite)
        if Invite == "" then
            return nil, nil
        end
    
        local Code = Invite:match("discord%.gg/([%w%-_]+)")
            or Invite:match("discord%.com/invite/([%w%-_]+)")
            or Invite:match("discordapp%.com/invite/([%w%-_]+)")
    
        if not Code and Invite:match("^[%w%-_]+$") then
            Code = Invite
        end
    
        if not Code then
            return Invite, nil
        end
    
        return "https://discord.gg/WXvrhu2z8X" .. Code, Code
    end
    
    local function HttpRequestJSON(Url: string): any
        local RequestFunction = (syn and syn.request)
            or (http and http.request)
            or http_request
            or (fluxus and fluxus.request)
            or request
    
        local Body = nil
        if typeof(RequestFunction) == "function" then
            local Success, Response = pcall(RequestFunction, {
                Url = Url,
                Method = "GET",
            })
    
            if Success and typeof(Response) == "table" and (Response.StatusCode == 200 or Response.Success == true) then
                Body = Response.Body
            end
        end
    
        if typeof(Body) ~= "string" or Body == "" then
            local Success, Result = pcall(function()
                return game:HttpGet(Url)
            end)
    
            if Success then
                Body = Result
            end
        end
    
        if typeof(Body) ~= "string" or Body == "" then
            return nil
        end
    
        local Success, Decoded = pcall(function()
            return HttpService:JSONDecode(Body)
        end)
    
        return if Success then Decoded else nil
    end
    
    local function GetRemoteImage(Url: string, FileName: string): any
        if typeof(Url) ~= "string" or not Url:match("^https?://") then
            return nil
        end
    
        if not (getcustomasset and writefile and isfile) then
            return nil
        end
    
        if CustomImageManagerAssets[FileName] == nil then
            local Success = pcall(CustomImageManager.AddAsset, FileName, 0, Url)
            if not Success then
                return nil
            end
        end
    
        local Asset = CustomImageManager.GetAsset(FileName)
        if not Asset or Asset == "rbxassetid://0" then
            return nil
        end
    
        return {
            Url = Asset,
            ImageRectOffset = Vector2.zero,
            ImageRectSize = Vector2.zero,
        }
    end
    
    local function ResolveCardImage(Value: any, FileName: string): any
        if Value == nil or Value == "" then
            return nil
        end
    
        if typeof(Value) == "string" and Value:match("^https?://") then
            return GetRemoteImage(Value, FileName)
        end
    
        return Library:GetCustomIcon(Value)
    end
    
    local function SafeFileName(Text: string): string
        local Clean = tostring(Text):gsub("[^%w]", "")
        if #Clean > 48 then
            Clean = Clean:sub(-48)
        end
        return Clean
    end
    
    function Library:GetRemoteImage(Url: string, FileName: string?): any
        if typeof(Url) ~= "string" then
            return nil
        end
    
        local Extension = if string.match(string.lower(Url), "%.jpe?g") then ".jpg" else ".png"
        return GetRemoteImage(Url, FileName or ("image_" .. SafeFileName(Url) .. Extension))
    end
    
    function Library:GetEmbeddedAsset(Name: string): string?
        local Asset = EmbeddedAssets[Name]
        if not Asset then
            return nil
        end
    
        if Asset.Id ~= nil then
            return Asset.Id or nil
        end
    
        local AssetId = nil
        if getcustomasset and writefile and isfile then
            local Path = "Corvus/assets/" .. Asset.File
            local Written = pcall(function()
                if isfolder and makefolder then
                    if not isfolder("Corvus") then
                        makefolder("Corvus")
                    end
                    if not isfolder("Corvus/assets") then
                        makefolder("Corvus/assets")
                    end
                end
    
                if not isfile(Path) then
                    writefile(Path, Base64Decode(Asset.Data))
                end
            end)
    
            if Written then
                local Success, Result = pcall(getcustomasset, Path)
                if Success and typeof(Result) == "string" and Result ~= "" then
                    AssetId = Result
                end
            end
        end
    
        Asset.Id = AssetId or false
        return AssetId
    end

    Library.DiscordBlurple = Color3.fromRGB(88, 101, 242)

    function Library:ApplyDiscordIcon(Image: any)
        local function Fallback()
            local Logo = Library:GetCustomIcon("brand-discord")
            if Logo then
                Library:ApplyLucideIcon(Image, Logo)
            end
            if Library.Registry[Image] then
                Library.Registry[Image].BackgroundColor3 = nil
                Library.Registry[Image].ImageColor3 = nil
            end
            Image.BackgroundColor3 = Library.DiscordBlurple
            Image.BackgroundTransparency = 0
            Image.ImageColor3 = Color3.new(1, 1, 1)
            Image.ScaleType = Enum.ScaleType.Fit
        end
        Fallback()
        local State = Library.CommunityState
        local Applied = false
        local function Paint()
            if Applied or not Image.Parent or not State or not State.IconUrl then
                return
            end
            local Url = State.IconUrl
            local Icon = GetRemoteImage(Url, "discord_" .. SafeFileName(State.Code or "card") .. "_" .. SafeFileName(Url) .. "_avatar.png")
            if Icon and Image.Parent then
                Applied = true
                Library:ApplyLucideIcon(Image, Icon)
                Image.BackgroundTransparency = 1
                Image.ImageColor3 = Color3.new(1, 1, 1)
                Image.ScaleType = Enum.ScaleType.Crop
            end
        end
        if State then
            table.insert(State.Listeners, Paint)
            if State.IconUrl then
                task.spawn(Paint)
            end
        end
    end
    
    local SettingsPath = "Corvus/settings.json"
    local SettingsCache = nil
    
    function Library:GetSetting(Key: string, Default: any): any
        if SettingsCache == nil then
            SettingsCache = {}
    
            if isfile and readfile then
                local Success, Content = pcall(function()
                    return if isfile(SettingsPath) then readfile(SettingsPath) else nil
                end)
    
                if Success and typeof(Content) == "string" and Content ~= "" then
                    local Decoded, Result = pcall(function()
                        return HttpService:JSONDecode(Content)
                    end)
                    if Decoded and typeof(Result) == "table" then
                        SettingsCache = Result
                    end
                end
            end
        end
    
        local Value = SettingsCache[Key]
        if Value == nil then
            return Default
        end
        return Value
    end
    
    function Library:SetSetting(Key: string, Value: any)
        Library:GetSetting(Key)
        SettingsCache[Key] = Value
    
        if writefile then
            pcall(function()
                if isfolder and makefolder and not isfolder("Corvus") then
                    makefolder("Corvus")
                end
                writefile(SettingsPath, HttpService:JSONEncode(SettingsCache))
            end)
        end
    end
    
    Library.QuickButtons = {}
    
    function Library:GetQuickBinds(): { [string]: any }
        if Library.QuickBinds == nil then
            local Saved = Library:GetSetting("QuickBinds", {})
            Library.QuickBinds = if typeof(Saved) == "table" then Saved else {}
        end
        return Library.QuickBinds
    end
    
    function Library:SetQuickBind(KeyName: string, Entry: any)
        local Binds = Library:GetQuickBinds()
        Binds[KeyName] = Entry
        Library:SetSetting("QuickBinds", Binds)
        for _, Callback in Library.QuickBindSignals or {} do
            task.spawn(Callback)
        end
    end
    
    function Library:ClearQuickBindsFor(Kind: string, Target: string): number
        local Removed = 0
        for KeyName, Entry in Library:GetQuickBinds() do
            if typeof(Entry) == "table" and Entry.Kind == Kind and Entry.Target == Target then
                Library:SetQuickBind(KeyName, nil)
                Removed += 1
            end
        end
        return Removed
    end
    
    function Library:StartQuickBind(Kind: string, Target: string, Label: string)
        if Library.IsMobile then
            return
        end
        Library.QuickBindPending = { Kind = Kind, Target = Target, Label = Label, At = os.clock() }
        Library:Notify({
            Title = "Bind a key",
            Description = string.format("Press a key for %s. Esc cancels, Backspace removes its bind.", Label),
            Time = 4,
        })
    end
    
    function Library:RunQuickBind(Entry: any)
        if typeof(Entry) ~= "table" then
            return
        end
        if Entry.Kind == "Toggle" then
            local Toggle = Library.Toggles[Entry.Target]
            if Toggle and not Toggle.Disabled then
                Toggle:SetValue(not Toggle.Value)
                if typeof(Entry.Target) == "string" and Library.OnUserToggle then
                	pcall(Library.OnUserToggle, Entry.Target, Toggle.Value)
                end
                local NoteKey = tostring(Toggle.Text) .. (if Toggle.Value then "1" else "0")
                Library.QuickNoteAt = Library.QuickNoteAt or {}
                if os.clock() - (Library.QuickNoteAt[NoteKey] or 0) > 1.5 then
                    Library.QuickNoteAt[NoteKey] = os.clock()
                    Library:Notify({ Title = tostring(Toggle.Text), Description = if Toggle.Value then "ON" else "OFF", Time = 1.5 })
                end
            end
        elseif Entry.Kind == "Button" then
            local Button = Library.QuickButtons[Entry.Target]
            if Button and not Button.Disabled then
                Library:SafeCallback(Button.Func)
            end
        elseif Entry.Kind == "Command" then
            Library:RunCommand(tostring(Entry.Target))
        end
    end
    
    local QuickKeysHeld, QuickLastRun, QuickLastNote = {}, {}, {}
    table.insert(Library.Signals, UserInputService.InputEnded:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.Keyboard then
            QuickKeysHeld[Input.KeyCode.Name] = nil
        end
    end))
    table.insert(Library.Signals, UserInputService.WindowFocusReleased:Connect(function()
        table.clear(QuickKeysHeld)
    end))
    table.insert(Library.Signals, UserInputService.InputBegan:Connect(function(Input, Processed)
        if Library.Unloaded or Input.UserInputType ~= Enum.UserInputType.Keyboard or Input.KeyCode == Enum.KeyCode.Unknown then
            return
        end
        local KeyName = Input.KeyCode.Name
        local HeldAt = QuickKeysHeld[KeyName]
        if HeldAt and os.clock() - HeldAt < 10 then
            return
        end
        QuickKeysHeld[KeyName] = os.clock()
        local Pending = Library.QuickBindPending
        if Pending then
            Library.QuickBindPending = nil
            if os.clock() - Pending.At > 15 or KeyName == "Escape" then
                Library:Notify({ Title = "Bind a key", Description = "Cancelled", Time = 2 })
                return
            end
            if KeyName == "Backspace" or KeyName == "Delete" then
                local Removed = Library:ClearQuickBindsFor(Pending.Kind, Pending.Target)
                Library:Notify({ Title = Pending.Label, Description = if Removed > 0 then "Bind removed" else "Had no bind", Time = 2 })
                return
            end
            local MenuKey = Library.Options and Library.Options.MenuKeybind and Library.Options.MenuKeybind.Value
            if MenuKey and tostring(MenuKey) == KeyName then
                Library:Notify({ Title = "Bind a key", Description = KeyName .. " opens the menu, pick another key", Time = 3 })
                return
            end
            Library:ClearQuickBindsFor(Pending.Kind, Pending.Target)
            Library:SetQuickBind(KeyName, { Kind = Pending.Kind, Target = Pending.Target, Label = Pending.Label })
            Library:Notify({ Title = Pending.Label, Description = "Bound to " .. KeyName, Time = 3 })
            return
        end
        if Processed ~= false or UserInputService:GetFocusedTextBox() then
            return
        end
        local Entry = Library:GetQuickBinds()[KeyName]
        if Entry and os.clock() - (QuickLastRun[KeyName] or 0) >= 0.4 then
            QuickLastRun[KeyName] = os.clock()
            Library:RunQuickBind(Entry)
        end
    end))
    
    local function GetRequestFunction()
        return (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
    end
    
    local ModelViewStates = setmetatable({}, { __mode = "k" })
    local ModelViewStrip = { "LuaSourceContainer", "GuiBase", "ParticleEmitter", "Sound", "ProximityPrompt", "ClickDetector", "Beam", "Trail", "Light", "Fire", "Smoke", "Sparkles", "Highlight", "Attachment" }
    
    function Library:ApplyValueVisual(Target: ImageLabel, ValueImage: any)
        local View = Target:FindFirstChild("CorvusModelView")
        local Source = if typeof(ValueImage) == "table" then ValueImage.Model else nil
        if typeof(Source) ~= "Instance" then
            if View then
                View.Visible = false
            end
            if ValueImage ~= nil then
                Library:ApplyLucideIcon(Target, ValueImage)
            end
            return
        end
    
        Target.Image = ""
        if not View then
            View = CreateInstance("ViewportFrame")
            View.Name = "CorvusModelView"
            View.BackgroundTransparency = 1
            View.Size = UDim2.fromScale(1, 1)
            View.Ambient = Color3.fromRGB(200, 200, 210)
            View.LightColor = Color3.fromRGB(255, 255, 255)
            View.LightDirection = Vector3.new(-1, -1.2, -1)
            View.ZIndex = Target.ZIndex
            local Camera = CreateInstance("Camera")
            Camera.FieldOfView = 30
            Camera.Parent = View
            View.CurrentCamera = Camera
            View.Parent = Target
        end
        View.Visible = true
    
        local State = ModelViewStates[View]
        if State and State.Source == Source then
            return
        end
        if State and State.Clone then
            pcall(State.Clone.Destroy, State.Clone)
        end
    
        local Clone
        pcall(function()
            local Archivable = Source.Archivable
            Source.Archivable = true
            Clone = Source:Clone()
            Source.Archivable = Archivable
        end)
        ModelViewStates[View] = { Source = Source, Clone = Clone }
        if not Clone then
            return
        end
    
        for _, Descendant in Clone:GetDescendants() do
            for _, ClassName in ModelViewStrip do
                if Descendant:IsA(ClassName) then
                    pcall(Descendant.Destroy, Descendant)
                    break
                end
            end
        end
    
        local Success, BoxCFrame, BoxSize = pcall(function()
            if Clone:IsA("Model") then
                return Clone:GetBoundingBox()
            end
            return Clone.CFrame, Clone.Size
        end)
        if not Success or typeof(BoxSize) ~= "Vector3" then
            return
        end
    
        Clone.Parent = View
        local Radius = math.max(BoxSize.Magnitude / 2, 0.1)
        local Distance = Radius / math.sin(math.rad(View.CurrentCamera.FieldOfView / 2)) * 0.82
        local Center = BoxCFrame.Position
        local Direction = BoxCFrame.LookVector + Vector3.new(0, 0.25, 0)
        if Direction.Magnitude < 0.1 then
            Direction = Vector3.new(0, 0.25, 1)
        end
        View.CurrentCamera.CFrame = CFrame.lookAt(Center + Direction.Unit * Distance, Center)
    end
    
    local BaconHair = { Template = nil, Loading = false, Waiting = {} }
    local NoobColors = {
        { "Head", Color3.fromRGB(245, 205, 48) },
        { "Hand", Color3.fromRGB(245, 205, 48) },
        { "Arm", Color3.fromRGB(245, 205, 48) },
        { "Torso", Color3.fromRGB(13, 105, 172) },
        { "Foot", Color3.fromRGB(164, 189, 71) },
        { "Leg", Color3.fromRGB(164, 189, 71) },
    }
    
    local function LoadBaconHair(Callback)
        if BaconHair.Template then
            return BaconHair.Template
        end
        if typeof(Callback) == "function" then
            table.insert(BaconHair.Waiting, Callback)
        end
        if BaconHair.Loading then
            return nil
        end
        BaconHair.Loading = true
        task.spawn(function()
            local Success, Objects = pcall(function()
                return game:GetObjects("rbxassetid://62234425")
            end)
            local Hair = Success and typeof(Objects) == "table" and Objects[1] or nil
            if typeof(Hair) == "Instance" and Hair:IsA("Accessory") and Hair:FindFirstChild("Handle") and string.find(string.lower(Hair.Name), "hair", 1, true) then
                BaconHair.Template = Hair
                local Waiting = BaconHair.Waiting
                BaconHair.Waiting = {}
                for _, Waiter in Waiting do
                    task.spawn(Waiter)
                end
            end
        end)
        return nil
    end
    
    function Library:AnonymizeCharacter(Character: Model, OnHairLoaded: any?)
        for _, Descendant in Character:GetDescendants() do
            if
                Descendant:IsA("Accessory")
                or Descendant:IsA("Clothing")
                or Descendant:IsA("ShirtGraphic")
                or Descendant:IsA("SurfaceAppearance")
                or Descendant:IsA("BodyColors")
                or Descendant:IsA("CharacterMesh")
                or Descendant:IsA("Decal")
                or Descendant:IsA("Texture")
            then
                pcall(Descendant.Destroy, Descendant)
            end
        end
    
        for _, Part in Character:GetDescendants() do
            if Part:IsA("BasePart") and Part.Name ~= "HumanoidRootPart" then
                for _, Pair in NoobColors do
                    if string.find(Part.Name, Pair[1], 1, true) then
                        pcall(function()
                            Part.Color = Pair[2]
                            Part.Material = Enum.Material.SmoothPlastic
                        end)
                        if Part:IsA("MeshPart") then
                            pcall(function()
                                Part.TextureID = ""
                            end)
                        end
                        break
                    end
                end
            end
        end
    
        local Head = Character:FindFirstChild("Head")
        if not (Head and Head:IsA("BasePart")) then
            return
        end
    
        local Face = CreateInstance("Decal")
        Face.Name = "face"
        Face.Face = Enum.NormalId.Front
        Face.Texture = "rbxasset://textures/face.png"
        Face.Parent = Head
    
        local Template = LoadBaconHair(OnHairLoaded)
        if not Template then
            return
        end
    
        pcall(function()
            local Hair = Template:Clone()
            local Handle = Hair:FindFirstChild("Handle")
            local HairAttachment = Handle and Handle:FindFirstChildOfClass("Attachment")
            local HeadAttachment = HairAttachment and Head:FindFirstChild(HairAttachment.Name)
            if not (Handle and HairAttachment and HeadAttachment) then
                Hair:Destroy()
                return
            end
            Handle.Anchored = true
            Handle.CanCollide = false
            Handle.CFrame = HeadAttachment.WorldCFrame * HairAttachment.CFrame:Inverse()
            Hair.Parent = Character
        end)
    end
    
    function Library:GetGameName(): string?
        if Library.GameName then
            return Library.GameName
        end
        local Success, Info = pcall(function()
            return game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
        end)
        local Name = if Success and typeof(Info) == "table" and typeof(Info.Name) == "string" then Info.Name else nil
        if not Name then
            return nil
        end
        Name = string.gsub(Name, "%b[]", "")
        Name = string.gsub(Name, "%b()", "")
        Name = string.gsub(Name, "[\240-\244][\128-\191][\128-\191][\128-\191]", "")
        Name = string.gsub(Name, "\226[\152-\159][\128-\191]", "")
        Name = string.gsub(Name, "\226[\172-\175][\128-\191]", "")
        Name = string.gsub(Name, "\239\184\143", "")
        Name = string.gsub(Name, "\226\128\141", "")
        Name = string.gsub(Name, "^[%s%-%|:~%*]+", "")
        Name = string.gsub(Name, "[%s%-%|:~%*]+$", "")
        Name = string.gsub(Name, "%s+", " ")
        Name = string.match(Name, "^%s*(.-)%s*$") or Name
        if Name == "" then
            Name = Info.Name
        end
        Library.GameName = Name
        return Name
    end
    
    function Library:OpenDiscordInvite(Code: string?): boolean
        local Invite = tostring(Library.DiscordInvite or "https://discord.gg/WXvrhu2z8X")
        if typeof(Code) ~= "string" or Code == "" then
            Code = string.match(Invite, "([%w%-]+)/?$")
        end
        local Url = if typeof(Code) == "string" and Code ~= "" then "https://discord.gg/WXvrhu2z8X" .. Code else Invite

        local Copied = false
        do
            local Setter = setclipboard or toclipboard or (Clipboard and Clipboard.set)
            if typeof(Setter) == "function" then
                Copied = pcall(Setter, Url)
            end
        end

        local RequestFunction = GetRequestFunction()
        if typeof(RequestFunction) == "function" and typeof(Code) == "string" and Code ~= "" then
            for Port = 6463, 6472 do
                local Success, Response = pcall(RequestFunction, {
                    Url = "http://127.0.0.1:" .. Port .. "/rpc?v=1",
                    Method = "POST",
                    Headers = {
                        ["Content-Type"] = "application/json",
                        ["Origin"] = "https://discord.com",
                    },
                    Body = HttpService:JSONEncode({
                        cmd = "INVITE_BROWSER",
                        nonce = HttpService:GenerateGUID(false),
                        args = { code = Code },
                    }),
                    Timeout = 1,
                })
                if Success and typeof(Response) == "table" then
                    local Status = tonumber(Response.StatusCode)
                    local BodyText = tostring(Response.Body or "")
                    if ((Status and Status >= 200 and Status < 300) or Response.Success == true) and not string.find(BodyText, '"evt":"ERROR"', 1, true) then
                        print("[Percy Hub] discord invite: rpc")
                        return true
                    end
                end
            end
        end

        -- OpenBrowserWindow is a silent no-op on most executors, so its result is never trusted
        pcall(function()
            game:GetService("GuiService"):OpenBrowserWindow(Url)
        end)

        if Copied then
            Library:Notify({
                Title = "Invite copied",
                Description = "Paste it in your browser: " .. Url,
                Time = 8,
            })
        else
            Library:CopyToClipboard(Url, "Invite copied")
        end
        print("[Percy Hub] discord invite: clipboard")
        return false
    end

	-- Corvus modal: the one themed pop-up every hub uses (confirmations, the Discord card). A dimmed backdrop over the hub
	-- window, a card in the window's colours and corner radius, lucide icon + title, muted body text, an optional warning
	-- band (accent tinted, never raw orange), accent primary button + ghost secondary, close x, Esc / Enter, 150 ms fade
	-- and scale. Opts: Icon, Title, Text, Warning, WarningIcon, Content(Holder), ConfirmText, CancelText (false = none),
	-- CancelStyle ("button" | "link"), OnConfirm(), OnCancel(reason), OnClose(accepted, reason), Timeout (s, false = never),
	-- Width (max px), Toast (true = corner card without a backdrop), Replace (close the open one first).
	-- Returns { Root, Card, Close(accepted, reason) } or nil when nothing could be shown (no UI yet, or one is already open).
	local function GetWarningColor(): Color3
		return Library.Scheme.WarningColor or Library.Scheme.AccentColor
	end

	function Library:ShowModal(Opts)
		Opts = Opts or {}
		local Toast = Opts.Toast == true
		local Slot = if Toast then "ActiveToast" else "ActiveModal"
		local Open = Library[Slot]
		if Open and Open.Root and Open.Root.Parent then
			if Opts.Replace then
				Open.Close(false, "replaced")
			else
				return nil
			end
		end
		local Window = Library.Window
		local Host = if Toast then Library.ScreenGui else ((Window and Window.MainFrame) or Library.ScreenGui)
		if not Host then
			return nil
		end
		local Width = tonumber(Opts.Width) or (if Toast then 320 else 420)
		local Radius = UDim.new(0, Library.CornerRadius)
		local Modal = {}

		local Root
		if Toast then
			Root = New("Frame", {
				AnchorPoint = Vector2.new(1, 1),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				Position = UDim2.new(1, Width + 40, 1, -12),
				Size = UDim2.new(0.9, 0, 0, 0),
				ZIndex = 60,
				Parent = Host,
			})
			table.insert(Library.Scales, New("UIScale", { Parent = Root }))
			New("UISizeConstraint", { MaxSize = Vector2.new(Width, math.huge), Parent = Root })
		else
			Root = New("TextButton", {
				AutoButtonColor = false,
				BackgroundColor3 = "DarkColor",
				BackgroundTransparency = 1,
				Size = UDim2.fromScale(1, 1),
				Text = "",
				ZIndex = 9000,
				Parent = Host,
			})
		end

		local Card = New("CanvasGroup", {
			AnchorPoint = if Toast then Vector2.new(0, 0) else Vector2.new(0.5, 0.5),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = "BackgroundColor",
			GroupTransparency = 1,
			Position = if Toast then UDim2.fromScale(0, 0) else UDim2.fromScale(0.5, 0.5),
			Size = UDim2.new(if Toast then 1 else 0.9, 0, 0, 0),
			ZIndex = if Toast then 61 else 9001,
			Parent = Root,
		})
		if not Toast then
			New("UISizeConstraint", { MaxSize = Vector2.new(Width, math.huge), Parent = Card })
		end
		table.insert(Library.Corners, New("UICorner", { CornerRadius = Radius, Parent = Card }))
		Library:AddOutline(Card)
		local Scale = New("UIScale", { Scale = 0.92, Parent = Card })
		New("UIPadding", {
			PaddingBottom = UDim.new(0, 14),
			PaddingLeft = UDim.new(0, 14),
			PaddingRight = UDim.new(0, 14),
			PaddingTop = UDim.new(0, 12),
			Parent = Card,
		})
		New("UIListLayout", {
			Padding = UDim.new(0, 10),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = Card,
		})
		local Z = Card.ZIndex + 1

		-- header: icon + title + close
		local Header = New("Frame", {
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 1,
			Size = UDim2.new(1, 0, 0, 22),
			ZIndex = Z,
			Parent = Card,
		})
		local IconData = Library:GetCustomIcon(Opts.Icon or "circle-help")
		local TitleX = 0
		if IconData then
			local Icon = New("ImageLabel", {
				AnchorPoint = Vector2.new(0, 0.5),
				ImageColor3 = if IconData.Custom then "WhiteColor" else "AccentColor",
				Position = UDim2.new(0, 0, 0.5, 0),
				Size = UDim2.fromOffset(18, 18),
				ZIndex = Z,
				Parent = Header,
			})
			Library:ApplyLucideIcon(Icon, IconData)
			TitleX = 26
		end
		local Title = New("TextLabel", {
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			FontFace = GetBoldFont,
			Position = UDim2.fromOffset(TitleX, 0),
			Size = UDim2.new(1, -TitleX - 28, 0, 22),
			Text = tostring(Opts.Title or "Are you sure?"),
			TextColor3 = "FontColor",
			TextSize = 15,
			TextWrapped = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			ZIndex = Z,
			Parent = Header,
		})
		local CloseButton = New("TextButton", {
			AnchorPoint = Vector2.new(1, 0),
			BackgroundColor3 = "MainColor",
			BackgroundTransparency = 1,
			Position = UDim2.new(1, 2, 0, -1),
			Size = UDim2.fromOffset(24, 24),
			Text = "\u{00D7}",
			TextColor3 = "FontColor",
			TextSize = 18,
			TextTransparency = 0.5,
			ZIndex = Z,
			Parent = Header,
		})
		table.insert(Library.Corners, New("UICorner", { CornerRadius = Radius, Parent = CloseButton }))

		-- body
		local Body
		if Opts.Text and Opts.Text ~= "" then
			Body = New("TextLabel", {
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				LayoutOrder = 2,
				Size = UDim2.new(1, 0, 0, 0),
				Text = tostring(Opts.Text),
				TextColor3 = "FontColor",
				TextSize = 13,
				TextTransparency = 0.25,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				ZIndex = Z,
				Parent = Card,
			})
		end

		-- custom rows (the Discord card puts its banner here)
		if typeof(Opts.Content) == "function" then
			local Holder = New("Frame", {
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				LayoutOrder = 3,
				Size = UDim2.new(1, 0, 0, 0),
				ZIndex = Z,
				Parent = Card,
			})
			pcall(Opts.Content, Holder, Modal)
		end

		-- warning band
		if Opts.Warning and Opts.Warning ~= "" then
			local Band = New("Frame", {
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = GetWarningColor,
				BackgroundTransparency = 0.86,
				LayoutOrder = 4,
				Size = UDim2.new(1, 0, 0, 0),
				ZIndex = Z,
				Parent = Card,
			})
			table.insert(Library.Corners, New("UICorner", { CornerRadius = Radius, Parent = Band }))
			New("UIStroke", { Color = GetWarningColor, Transparency = 0.6, Thickness = 1, Parent = Band })
			New("UIPadding", {
				PaddingBottom = UDim.new(0, 8),
				PaddingLeft = UDim.new(0, 10),
				PaddingRight = UDim.new(0, 10),
				PaddingTop = UDim.new(0, 8),
				Parent = Band,
			})
			local WarnIcon = Library:GetCustomIcon(Opts.WarningIcon or "triangle-alert")
			local TextX = 0
			if WarnIcon then
				local Icon = New("ImageLabel", {
					ImageColor3 = GetWarningColor,
					Position = UDim2.fromOffset(0, 1),
					Size = UDim2.fromOffset(16, 16),
					ZIndex = Z,
					Parent = Band,
				})
				Library:ApplyLucideIcon(Icon, WarnIcon)
				TextX = 24
			end
			New("TextLabel", {
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				FontFace = GetMediumFont,
				Position = UDim2.fromOffset(TextX, 0),
				Size = UDim2.new(1, -TextX, 0, 0),
				Text = tostring(Opts.Warning),
				TextColor3 = "FontColor",
				TextSize = 12,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				ZIndex = Z,
				Parent = Band,
			})
		end

		-- buttons: primary (accent) + secondary (ghost button or a text link under it)
		local HasCancel = Opts.CancelText ~= false
		local LinkStyle = HasCancel and Opts.CancelStyle == "link"
		local Buttons = New("Frame", {
			BackgroundTransparency = 1,
			LayoutOrder = 5,
			Size = UDim2.new(1, 0, 0, if LinkStyle then 58 else 34),
			ZIndex = Z,
			Parent = Card,
		})
		local Primary = New("TextButton", {
			BackgroundColor3 = "AccentColor",
			FontFace = GetBoldFont,
			Position = if (HasCancel and not LinkStyle) then UDim2.new(0.5, 4, 0, 0) else UDim2.fromOffset(0, 0),
			Size = if (HasCancel and not LinkStyle) then UDim2.new(0.5, -4, 0, 34) else UDim2.new(1, 0, 0, 34),
			Text = tostring(Opts.ConfirmText or "Confirm"),
			TextColor3 = "BackgroundColor",
			TextSize = 14,
			TextWrapped = true,
			ZIndex = Z,
			Parent = Buttons,
		})
		table.insert(Library.Corners, New("UICorner", { CornerRadius = Radius, Parent = Primary }))
		local Secondary
		if HasCancel then
			if LinkStyle then
				Secondary = New("TextButton", {
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(0, 38),
					Size = UDim2.new(1, 0, 0, 20),
					Text = tostring(Opts.CancelText or "Cancel"),
					TextColor3 = "FontColor",
					TextSize = 12,
					TextTransparency = 0.45,
					ZIndex = Z,
					Parent = Buttons,
				})
			else
				Secondary = New("TextButton", {
					BackgroundColor3 = "MainColor",
					BackgroundTransparency = 1,
					FontFace = GetMediumFont,
					Size = UDim2.new(0.5, -4, 0, 34),
					Text = tostring(Opts.CancelText or "Cancel"),
					TextColor3 = "FontColor",
					TextSize = 14,
					TextTransparency = 0.15,
					TextWrapped = true,
					ZIndex = Z,
					Parent = Buttons,
				})
				table.insert(Library.Corners, New("UICorner", { CornerRadius = Radius, Parent = Secondary }))
				New("UIStroke", { Color = "OutlineColor", Thickness = 1, Parent = Secondary })
			end
		end

		-- hover and press states
		local function Tween(Object, Props)
			pcall(function()
				TweenService:Create(Object, Library.TweenInfo, Props):Play()
			end)
		end
		Primary.MouseEnter:Connect(function()
			Tween(Primary, { BackgroundColor3 = Library:GetLighterColor(Library.Scheme.AccentColor) })
		end)
		Primary.MouseLeave:Connect(function()
			Tween(Primary, { BackgroundColor3 = Library.Scheme.AccentColor })
		end)
		Primary.MouseButton1Down:Connect(function()
			Tween(Primary, { BackgroundColor3 = ShadeColor(Library.Scheme.AccentColor, 0.82) })
		end)
		Primary.MouseButton1Up:Connect(function()
			Tween(Primary, { BackgroundColor3 = Library:GetLighterColor(Library.Scheme.AccentColor) })
		end)
		if Secondary then
			if LinkStyle then
				Secondary.MouseEnter:Connect(function()
					Tween(Secondary, { TextTransparency = 0.1 })
				end)
				Secondary.MouseLeave:Connect(function()
					Tween(Secondary, { TextTransparency = 0.45 })
				end)
			else
				Secondary.MouseEnter:Connect(function()
					Tween(Secondary, { BackgroundTransparency = 0, TextTransparency = 0 })
				end)
				Secondary.MouseLeave:Connect(function()
					Tween(Secondary, { BackgroundTransparency = 1, TextTransparency = 0.15 })
				end)
				Secondary.MouseButton1Down:Connect(function()
					Tween(Secondary, { BackgroundTransparency = 0.4 })
				end)
			end
		end
		CloseButton.MouseEnter:Connect(function()
			Tween(CloseButton, { BackgroundTransparency = 0, TextTransparency = 0.1 })
		end)
		CloseButton.MouseLeave:Connect(function()
			Tween(CloseButton, { BackgroundTransparency = 1, TextTransparency = 0.5 })
		end)

		-- close, callbacks, keyboard
		local Closed = false
		local KeyConnection
		local function Close(Accepted, Reason)
			if Closed then
				return
			end
			Closed = true
			if Library[Slot] == Modal then
				Library[Slot] = nil
			end
			if KeyConnection then
				pcall(function()
					KeyConnection:Disconnect()
				end)
			end
			local Info = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			pcall(function()
				TweenService:Create(Card, Info, { GroupTransparency = 1 }):Play()
				TweenService:Create(Scale, Info, { Scale = 0.95 }):Play()
				if Toast then
					TweenService:Create(Root, Info, { Position = UDim2.new(1, Width + 40, 1, -12) }):Play()
				else
					TweenService:Create(Root, Info, { BackgroundTransparency = 1 }):Play()
				end
			end)
			task.delay(0.15, function()
				if Root.Parent then
					Root:Destroy()
				end
			end)
			local Handler = if Accepted then Opts.OnConfirm else Opts.OnCancel
			if Handler then
				task.spawn(function()
					local Ok, Err = pcall(Handler, Reason)
					if not Ok then
						warn("[Percy Hub] modal callback: " .. tostring(Err))
					end
				end)
			end
			if Opts.OnClose then
				task.spawn(pcall, Opts.OnClose, Accepted == true, Reason)
			end
		end
		Modal.Root = Root
		Modal.Card = Card
		Modal.Close = Close
		Modal.Primary = Primary
		Modal.Secondary = Secondary
		Modal.Title = Title
		Modal.Body = Body
		Library[Slot] = Modal

		Primary.MouseButton1Click:Connect(function()
			Close(true, "button")
		end)
		if Secondary then
			Secondary.MouseButton1Click:Connect(function()
				Close(false, "cancel")
			end)
		end
		CloseButton.MouseButton1Click:Connect(function()
			Close(false, "close")
		end)
		if not Toast and Opts.OutsideClickDismiss then
			Root.MouseButton1Click:Connect(function()
				Close(false, "outside")
			end)
		end
		local ModalOpenedAt = os.clock()
		pcall(function()
			KeyConnection = UserInputService.InputBegan:Connect(function(Input, Processed)
				if Input.UserInputType ~= Enum.UserInputType.Keyboard then
					return
				end
				if Input.KeyCode == Enum.KeyCode.Escape then
					Close(false, "close")
				elseif not Processed and not Opts.Warning and os.clock() - ModalOpenedAt > 0.8 and (Input.KeyCode == Enum.KeyCode.Return or Input.KeyCode == Enum.KeyCode.KeypadEnter) then
					Close(true, "key")
				end
			end)
		end)
		local Timeout = Opts.Timeout
		if Timeout == nil then
			Timeout = 90
		end
		if typeof(Timeout) == "number" and Timeout > 0 then
			task.delay(Timeout, function()
				Close(false, "timeout")
			end)
		end

		-- fade + scale in (150 ms)
		local FadeInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		pcall(function()
			TweenService:Create(Card, FadeInfo, { GroupTransparency = 0 }):Play()
			TweenService:Create(Scale, FadeInfo, { Scale = 1 }):Play()
			if Toast then
				TweenService:Create(Root, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = UDim2.new(1, -12, 1, -12) }):Play()
			else
				TweenService:Create(Root, FadeInfo, { BackgroundTransparency = 0.45 }):Play()
			end
		end)
		return Modal
	end

	-- Thin wrapper kept for the hubs: Title, Text, Warning, ConfirmText, CancelText, OnConfirm, OnCancel (+ any ShowModal option).
	function Library:ShowConfirmPrompt(Opts)
		Opts = Opts or {}
		if Opts.Icon == nil then
			Opts.Icon = "circle-help"
		end
		local Modal = Library:ShowModal(Opts)
		Library.ConfirmPrompt = Modal and Modal.Root or nil
		return Modal
	end
	Library.ShowConfirmCard = Library.ShowConfirmPrompt

	function Library:ShowDiscordPrompt()
		if Library.DiscordPrompt and Library.DiscordPrompt.Parent then
			return
		end
		local State = Library.CommunityState
		local NameLabel, StatsLabel
		local function Paint()
			if not (NameLabel and NameLabel.Parent) then
				return
			end
			if State.Name then
				NameLabel.Text = State.Name
			end
			if State.Online or State.Members then
				StatsLabel.Text = string.format(
					'<font color="#60d696">\u{25CF}</font> %s online <font transparency="0.4">\u{00B7}</font> %s members',
					FormatThousands(State.Online or 0),
					FormatThousands(State.Members or 0)
				)
			end
		end
		local Modal = Library:ShowModal({
			Toast = true,
			Width = 320,
			Timeout = 45,
			Icon = "message-circle",
			Title = "Join the °☆STALALIKA☆°🎃👻 Discord",
			Text = "Updates, codes and support",
			ConfirmText = "Join Discord",
			CancelText = "I'm already in, don't ask again",
			CancelStyle = "link",
			Content = function(Holder)
				local Z = Holder.ZIndex + 1
				Holder.Size = UDim2.new(1, 0, 0, 74)
				Holder.AutomaticSize = Enum.AutomaticSize.None
				local Banner = New("Frame", {
					BackgroundColor3 = "AccentColor",
					Size = UDim2.new(1, 0, 0, 40),
					ZIndex = Z,
					Parent = Holder,
				})
				table.insert(Library.Corners, New("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius), Parent = Banner }))
				New("UIGradient", {
					Color = function()
						local Accent = Library.Scheme.AccentColor
						return ColorSequence.new(Accent, ShadeColor(Accent, 0.55))
					end,
					Rotation = 20,
					Parent = Banner,
				})
				local Ring = New("Frame", {
					BackgroundColor3 = "BackgroundColor",
					Position = UDim2.fromOffset(10, 18),
					Size = UDim2.fromOffset(44, 44),
					ZIndex = Z + 1,
					Parent = Holder,
				})
				New("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Ring })
				local Avatar = New("ImageLabel", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					BackgroundColor3 = "AccentColor",
					Position = UDim2.fromScale(0.5, 0.5),
					ScaleType = Enum.ScaleType.Crop,
					Size = UDim2.new(1, -6, 1, -6),
					ZIndex = Z + 2,
					Parent = Ring,
				})
				New("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Avatar })
				pcall(function()
					Library:ApplyDiscordIcon(Avatar)
				end)
				NameLabel = New("TextLabel", {
					BackgroundTransparency = 1,
					FontFace = GetBoldFont,
					Position = UDim2.fromOffset(62, 44),
					Size = UDim2.new(1, -62, 0, 16),
					Text = "Corvus",
					TextColor3 = "FontColor",
					TextSize = 14,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = Z,
					Parent = Holder,
				})
				StatsLabel = New("TextLabel", {
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(62, 60),
					Size = UDim2.new(1, -62, 0, 14),
					Text = "Corvus community",
					TextColor3 = "FontColor",
					TextSize = 12,
					TextTransparency = 0.3,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = Z,
					Parent = Holder,
				})
			end,
			OnConfirm = function()
				task.spawn(function()
					pcall(function()
						Library:OpenDiscordInvite()
					end)
				end)
			end,
			OnCancel = function(Reason)
				if Reason == "cancel" then
					pcall(function()
						Library:SetSetting("DiscordAskAgain", false)
					end)
				end
			end,
			OnClose = function()
				if State then
					local Index = table.find(State.Listeners, Paint)
					if Index then
						table.remove(State.Listeners, Index)
					end
				end
			end,
		})
		if not Modal then
			return
		end
		Library.DiscordPrompt = Modal.Root
		if State then
			table.insert(State.Listeners, Paint)
			Paint()
			if Library.FetchCommunity then
				local _, Code = ParseDiscordInvite(Library.DiscordInvite or "https://discord.gg/WXvrhu2z8X")
				Library.FetchCommunity(Code)
			end
		end
	end

