        ["Corvus Aurora"] = { 0.3, { FontColor = "e6f7f4", MainColor = "121d21", AccentColor = "5ee6c9", BackgroundColor = "0b1215", OutlineColor = "1c2d32", BackgroundImage = "" } },
        ["Corvus Ember"] = { 0.4, { FontColor = "fbe9ee", MainColor = "20131a", AccentColor = "ff6e8a", BackgroundColor = "140c10", OutlineColor = "35202b", BackgroundImage = "" } },
