    function Library:GetThemeNames(): { string }
        local Names = {}
        for Name in Library.CorvusThemes do
            table.insert(Names, Name)
        end
        table.sort(Names, function(A, B)
            return Library.CorvusThemes[A][1] < Library.CorvusThemes[B][1]
        end)
        return Names
    end
    
    function Library:SetTheme(Theme: any): boolean
        local Data = Theme
        if typeof(Theme) == "string" then
            local Entry = Library.CorvusThemes[Theme]
            Data = Entry and Entry[2]
        end
        if typeof(Data) ~= "table" then
            return false
        end
    
        for _, Key in { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" } do
            local Value = Data[Key]
            if typeof(Value) == "string" then
                local Success, Color = pcall(Color3.fromHex, Value)
                Value = if Success then Color else nil
            end
    
            if typeof(Value) == "Color3" then
                Library.Scheme[Key] = Value
    
                local Option = Library.Options[Key]
                if Option and Option.Type == "ColorPicker" and Option.SetValueRGB then
                    pcall(Option.SetValueRGB, Option, Value)
                end
            end
        end
    
        Library:UpdateColorsUsingRegistry()
        return true
    end
    
    local Performance = {
        FPS = 60,
        Ping = 0,
        Frames = 0,
        Elapsed = 0,
        Connection = nil,
        Listeners = {},
    }
    
    local function ReadPing(): number
        local Success, Value = pcall(function()
            local StatsService = game:GetService("Stats")
            return StatsService.Network.ServerStatsItem["Data Ping"]:GetValue()
        end)
        if Success and typeof(Value) == "number" and Value > 0 then
            return Value
        end
    
        local PingSuccess, NetworkPing = pcall(function()
            return LocalPlayer:GetNetworkPing()
        end)
        if PingSuccess and typeof(NetworkPing) == "number" then
            return NetworkPing * 2000
        end
    
        return 0
    end
    
    function Library:GetPerformance(): (number, number)
        if not Performance.Connection then
            Performance.Connection = RunService.RenderStepped:Connect(function(Delta)
                Performance.Frames += 1
                Performance.Elapsed += Delta
                if Performance.Elapsed < 0.5 then
                    return
                end
    
                Performance.FPS = math.floor(Performance.Frames / Performance.Elapsed + 0.5)
                Performance.Ping = math.floor(ReadPing() + 0.5)
                Performance.Frames = 0
                Performance.Elapsed = 0
    
                for _, Listener in Performance.Listeners do
                    task.spawn(Listener, Performance.FPS, Performance.Ping)
                end
            end)
            Library:GiveSignal(Performance.Connection)
        end
    
        return Performance.FPS, Performance.Ping
    end
    
    function Library:OnPerformance(Callback: (number, number) -> ())
        Library:GetPerformance()
        table.insert(Performance.Listeners, Callback)
        return function()
            local Index = table.find(Performance.Listeners, Callback)
            if Index then
                table.remove(Performance.Listeners, Index)
            end
        end
    end
    
    function Library:FormatDuration(Seconds: number): string
        Seconds = math.max(0, math.floor(tonumber(Seconds) or 0))
        local Hours = math.floor(Seconds / 3600)
        local Minutes = math.floor(Seconds / 60) % 60
        local Secs = Seconds % 60
        if Hours > 0 then
            return string.format("%dh %02dm %02ds", Hours, Minutes, Secs)
        end
        return string.format("%dm %02ds", Minutes, Secs)
    end
    
    function Library:CreateStarfield(Parent: GuiObject, Options: { [string]: any }?)
        local Config = Options or {}
        local Rng = Random.new(Config.Seed or 7)
        local BaseZ = Config.ZIndex or 0
    
        local Field = {
            Enabled = true,
            Active = true,
            Destroyed = false,
            Tweens = {},
            Connections = {},
        }
    
        local Frame = New("Frame", {
            BackgroundTransparency = 1,
            ClipsDescendants = true,
            Name = "Starfield",
            Size = UDim2.fromScale(1, 1),
            ZIndex = BaseZ,
            Parent = Parent,
        })
        if Config.CornerRadius then
            New("UICorner", {
                CornerRadius = UDim.new(0, Config.CornerRadius),
                Parent = Frame,
            })
        end
        Field.Frame = Frame
    
        local function Band(Rotation: number, Offset: Vector2, Peak: number, Width: number)
            local BandFrame = New("Frame", {
                BackgroundColor3 = "WhiteColor",
                Size = UDim2.fromScale(1, 1),
                ZIndex = BaseZ,
                Parent = Frame,
            })
            New("UIGradient", {
                Color = GetNebulaSequence,
                Offset = Offset,
                Rotation = Rotation,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.5 - Width, 1),
                    NumberSequenceKeypoint.new(0.5, Peak),
                    NumberSequenceKeypoint.new(0.5 + Width, 1),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = BandFrame,
            })
        end
        Band(28, Vector2.new(0.1, -0.05), Config.NebulaPeak or 0.9, 0.3)
        Band(-22, Vector2.new(-0.25, 0.15), math.min(1, (Config.NebulaPeak or 0.9) + 0.04), 0.2)
    
        local Layers = {}
        for Index, Depth in { 10, 24, 17 } do
            Layers[Index] = {
                Depth = Depth,
                Frame = New("Frame", {
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 1),
                    ZIndex = BaseZ,
                    Parent = Frame,
                }),
            }
        end
    
        local Stars = {}
        for _ = 1, Config.Count or 64 do
            local Near = Rng:NextNumber() < 0.28
            local Size = if Near then Rng:NextInteger(2, 3) else Rng:NextInteger(1, 2)
            local Base = if Near then Rng:NextNumber(0.05, 0.35) else Rng:NextNumber(0.35, 0.7)
            local Tinted = Rng:NextNumber() < 0.3
    
            local Star = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = if Tinted
                    then function()
                        return Color3.new(1, 1, 1):Lerp(Library.Scheme.AccentColor, 0.45)
                    end
                    else Color3.new(1, 1, 1),
                BackgroundTransparency = Base,
                Position = UDim2.fromScale(Rng:NextNumber(0.015, 0.985), Rng:NextNumber(0.02, 0.98)),
                Size = UDim2.fromOffset(Size, Size),
                ZIndex = BaseZ,
                Parent = Layers[if Near then 2 else 1].Frame,
            })
            if Size > 1 then
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Star,
                })
            end
    
            table.insert(Stars, {
                Star = Star,
                Base = Base,
                Twinkle = Rng:NextNumber() < 0.55,
                Duration = Rng:NextNumber(1.1, 3.4),
                Delay = Rng:NextNumber(0, 2.5),
            })
        end
    
        local Sparkles = {}
        for _ = 1, Config.Sparkles or 3 do
            local Holder = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(Rng:NextNumber(0.08, 0.92), Rng:NextNumber(0.1, 0.9)),
                Size = UDim2.fromOffset(11, 11),
                ZIndex = BaseZ,
                Parent = Layers[2].Frame,
            })
            for _, Horizontal in { true, false } do
                local Ray = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = "WhiteColor",
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = if Horizontal then UDim2.new(1, 0, 0, 1) else UDim2.new(0, 1, 1, 0),
                    ZIndex = BaseZ,
                    Parent = Holder,
                })
                New("UIGradient", {
                    Rotation = if Horizontal then 0 else 90,
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.5, 0),
                        NumberSequenceKeypoint.new(1, 1),
                    }),
                    Parent = Ray,
                })
            end
            local Core = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(3, 3),
                ZIndex = BaseZ,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Core,
            })
    
            table.insert(Sparkles, {
                Scale = New("UIScale", {
                    Parent = Holder,
                }),
                Duration = Rng:NextNumber(1.6, 2.8),
                Delay = Rng:NextNumber(0, 1.5),
            })
        end
    
        local BrightStars = {}
        local function CreateBrightStar(Parent: GuiObject, Position: UDim2, CoreSize: number, GlowSize: number)
            local Holder = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Position = Position,
                Size = UDim2.fromOffset(GlowSize, GlowSize),
                ZIndex = BaseZ,
                Parent = Parent,
            })
            local Halo = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = function()
                    return Color3.new(1, 1, 1):Lerp(Library.Scheme.AccentColor, 0.55)
                end,
                BackgroundTransparency = 0.88,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(1, 1),
                ZIndex = BaseZ,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Halo,
            })
            local Inner = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = function()
                    return Color3.new(1, 1, 1):Lerp(Library.Scheme.AccentColor, 0.3)
                end,
                BackgroundTransparency = 0.72,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.45, 0.45),
                ZIndex = BaseZ,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Inner,
            })
            local Rays = {}
            for _, Horizontal in { true, false } do
                local Ray = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = "WhiteColor",
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = if Horizontal then UDim2.new(1.9, 0, 0, 1) else UDim2.new(0, 1, 1.9, 0),
                    ZIndex = BaseZ,
                    Parent = Holder,
                })
                New("UIGradient", {
                    Rotation = if Horizontal then 0 else 90,
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.5, 0),
                        NumberSequenceKeypoint.new(1, 1),
                    }),
                    Parent = Ray,
                })
                table.insert(Rays, Ray)
            end
            local Core = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(CoreSize, CoreSize),
                ZIndex = BaseZ,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Core,
            })
            local Data = {
                Holder = Holder,
                Halo = Halo,
                Inner = Inner,
                Rays = Rays,
                Scale = New("UIScale", {
                    Parent = Holder,
                }),
                Phase = Rng:NextNumber(0, math.pi * 2),
                Speed = Rng:NextNumber(1.2, 2.6),
                Flare = 0,
                NextFlare = Rng:NextNumber(0.5, 6),
            }
            table.insert(BrightStars, Data)
            return Data
        end
    
        for _ = 1, Config.BrightStars or 0 do
            local X, Y
            for _ = 1, 12 do
                X, Y = Rng:NextNumber(0.04, 0.96), Rng:NextNumber(0.05, 0.95)
                if not (Config.Constellation and X > 0.66 and Y > 0.38) then
                    break
                end
            end
            CreateBrightStar(Layers[2].Frame, UDim2.fromScale(X, Y), Rng:NextInteger(2, 3), Rng:NextInteger(10, 15))
        end
    
        if Config.Constellation then
            local BoxSize = Vector2.new(132, 184)
            local Box = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Name = "Corvus",
                Position = Config.ConstellationPosition or UDim2.fromScale(0.84, 0.66),
                Size = UDim2.fromOffset(BoxSize.X, BoxSize.Y),
                ZIndex = BaseZ,
                Parent = Layers[3].Frame,
            })
            local Points = {
                Alchiba = { 1.0, 1.0, 3, 13 },
                Minkar = { 0.935, 0.753, 3, 15 },
                Gienah = { 0.717, 0.157, 4, 19 },
                Algorab = { 0.175, 0.037, 4, 17 },
                Kraz = { 0.0, 0.844, 4, 18 },
                Eta = { 0.09, 0.0, 2, 10 },
            }
            local function PointOffset(Name: string): Vector2
                local Point = Points[Name]
                return Vector2.new(Point[1] * BoxSize.X, Point[2] * BoxSize.Y)
            end
            for _, Pair in { { "Alchiba", "Minkar" }, { "Minkar", "Gienah" }, { "Gienah", "Algorab" }, { "Algorab", "Kraz" }, { "Kraz", "Minkar" } } do
                local From, To = PointOffset(Pair[1]), PointOffset(Pair[2])
                local Middle = (From + To) / 2
                local Direction = To - From
                local Line = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = function()
                        return Color3.new(1, 1, 1):Lerp(Library.Scheme.AccentColor, 0.6)
                    end,
                    BackgroundTransparency = 0.7,
                    Position = UDim2.fromOffset(Middle.X, Middle.Y),
                    Rotation = math.deg(math.atan2(Direction.Y, Direction.X)),
                    Size = UDim2.fromOffset(Direction.Magnitude - 14, 1),
                    ZIndex = BaseZ,
                    Parent = Box,
                })
                New("UIGradient", {
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 0.7),
                        NumberSequenceKeypoint.new(0.5, 0),
                        NumberSequenceKeypoint.new(1, 0.7),
                    }),
                    Parent = Line,
                })
            end
            for Name, Point in Points do
                local Offset = PointOffset(Name)
                local Data = CreateBrightStar(Box, UDim2.fromOffset(Offset.X, Offset.Y), Point[3], Point[4])
                Data.Constellation = true
            end
            New("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 1, 16),
                Size = UDim2.fromOffset(BoxSize.X, 12),
                Text = "C  O  R  V  U  S",
                TextColor3 = "AccentColor",
                TextSize = 9,
                TextTransparency = 0.55,
                ZIndex = BaseZ,
                Parent = Box,
            })
            local NameShine = New("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 1, 16),
                Size = UDim2.fromOffset(BoxSize.X, 12),
                Text = "C  O  R  V  U  S",
                TextColor3 = "WhiteColor",
                TextSize = 9,
                ZIndex = BaseZ,
                Parent = Box,
            })
            local NameGradient = New("UIGradient", {
                Offset = Vector2.new(-1.3, 0),
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.35, 1),
                    NumberSequenceKeypoint.new(0.5, 0),
                    NumberSequenceKeypoint.new(0.65, 1),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = NameShine,
            })
            task.spawn(function()
                while not Field.Destroyed and not Library.Unloaded do
                    task.wait(4.5)
                    if Field.Enabled and Field.Active and Library.IconAnimations ~= false then
                        NameGradient.Offset = Vector2.new(-1.3, 0)
                        TweenService:Create(NameGradient, TweenInfo.new(1.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                            Offset = Vector2.new(1.3, 0),
                        }):Play()
                    end
                end
            end)
        end
    
        if #BrightStars > 0 then
            local Clock = 0
            table.insert(Field.Connections, RunService.RenderStepped:Connect(function(Delta)
                if Field.Destroyed or not (Field.Enabled and Field.Active) or Library.IconAnimations == false then
                    return
                end
                Clock += Delta
                for _, Data in BrightStars do
                    if Clock >= Data.NextFlare then
                        Data.Flare = 1
                        Data.NextFlare = Clock + (if Data.Constellation then Rng:NextNumber(2.5, 7) else Rng:NextNumber(3, 9))
                    end
                    Data.Flare = math.max(0, Data.Flare - Delta * 1.4)
                    local Flare = Data.Flare * Data.Flare
                    local Shimmer = math.sin(Clock * Data.Speed + Data.Phase)
                    Data.Scale.Scale = 1 + Shimmer * 0.08 + Flare * 0.55
                    Data.Halo.BackgroundTransparency = 0.88 - Shimmer * 0.03 - Flare * 0.3
                    Data.Inner.BackgroundTransparency = 0.72 - Flare * 0.35
                    for _, Ray in Data.Rays do
                        Ray.BackgroundTransparency = 1 - Flare * 0.85
                    end
                end
            end))
        end
    
        local function StopTweens()
            for _, Tween in Field.Tweens do
                Tween:Cancel()
            end
            table.clear(Field.Tweens)
    
            for _, Data in Stars do
                Data.Star.BackgroundTransparency = Data.Base
            end
            for _, Data in Sparkles do
                Data.Scale.Scale = 1
            end
        end
    
        local function StartTweens()
            if #Field.Tweens > 0 then
                return
            end
    
            for _, Data in Stars do
                if Data.Twinkle then
                    local Tween = TweenService:Create(Data.Star, TweenInfo.new(Data.Duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true, Data.Delay), {
                        BackgroundTransparency = math.min(1, Data.Base + 0.55),
                    })
                    Tween:Play()
                    table.insert(Field.Tweens, Tween)
                end
            end
    
            for _, Data in Sparkles do
                local Tween = TweenService:Create(Data.Scale, TweenInfo.new(Data.Duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true, Data.Delay), {
                    Scale = 0.35,
                })
                Tween:Play()
                table.insert(Field.Tweens, Tween)
            end
        end
    
        function Field:Refresh()
            if Field.Destroyed then
                return
            end
    
            local Running = Field.Enabled and Field.Active
            Frame.Visible = Running
    
            if Running and Library.IconAnimations ~= false then
                StartTweens()
            else
                StopTweens()
            end
        end
    
        function Field:SetEnabled(Enabled: boolean)
            Field.Enabled = Enabled ~= false
            Field:Refresh()
        end
    
        function Field:SetActive(Active: boolean)
            Field.Active = Active ~= false
            Field:Refresh()
        end
    
        function Field:Shoot()
            if Field.Destroyed then
                return
            end
    
            local Angle = math.rad(Rng:NextNumber(16, 34))
            local Travel = Rng:NextInteger(260, 420)
            local Length = Rng:NextInteger(150, 250)
            local Duration = Rng:NextNumber(0.8, 1.2)
            local StartX, StartY = Rng:NextNumber(0.02, 0.7), Rng:NextNumber(0.0, 0.4)
    
            local Streak = New("Frame", {
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = "WhiteColor",
                BackgroundTransparency = 0,
                Position = UDim2.fromScale(StartX, StartY),
                Rotation = math.deg(Angle),
                Size = UDim2.fromOffset(Length, 3),
                ZIndex = BaseZ,
                Parent = Frame,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Streak,
            })
            New("UIGradient", {
                Color = function()
                    return ColorSequence.new({
                        ColorSequenceKeypoint.new(0, GetSecondaryAccent()),
                        ColorSequenceKeypoint.new(0.7, Library.Scheme.AccentColor),
                        ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)),
                    })
                end,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.6, 0.6),
                    NumberSequenceKeypoint.new(0.92, 0.15),
                    NumberSequenceKeypoint.new(1, 0),
                }),
                Parent = Streak,
            })
    
            local Head = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.fromScale(1, 0.5),
                Size = UDim2.fromOffset(6, 6),
                ZIndex = BaseZ,
                Parent = Streak,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Head,
            })
            local Glow = New("UIStroke", {
                Color = "AccentColor",
                Thickness = 4,
                Transparency = 0.45,
                Parent = Head,
            })
    
            local Info = TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            local Tween = TweenService:Create(Streak, Info, {
                Position = UDim2.new(StartX, math.cos(Angle) * Travel, StartY, math.sin(Angle) * Travel),
                BackgroundTransparency = 1,
            })
            TweenService:Create(Head, Info, { BackgroundTransparency = 1 }):Play()
            TweenService:Create(Glow, Info, { Transparency = 1 }):Play()
            Tween.Completed:Once(function()
                Streak:Destroy()
            end)
            Tween:Play()
        end
    
        if Config.Parallax ~= false then
            local Offset = Vector2.zero
            table.insert(Field.Connections, RunService.RenderStepped:Connect(function(Delta)
                if Field.Destroyed or not (Field.Enabled and Field.Active) then
                    return
                end
    
                local Size = Frame.AbsoluteSize
                if Size.X < 1 or Size.Y < 1 then
                    return
                end
    
                local Center = Frame.AbsolutePosition + Size / 2
                local Target = Vector2.new(
                    math.clamp((Mouse.X - Center.X) / Size.X, -0.75, 0.75),
                    math.clamp((Mouse.Y - Center.Y) / Size.Y, -0.75, 0.75)
                )
                Offset = Offset:Lerp(Target, math.clamp(Delta * 5, 0, 1))
    
                for _, Layer in Layers do
                    Layer.Frame.Position = UDim2.fromOffset(-Offset.X * Layer.Depth, -Offset.Y * Layer.Depth)
                end
            end))
        end
    
        if Config.ShootingStars ~= false then
            task.spawn(function()
                while not Field.Destroyed and not Library.Unloaded do
                    task.wait(Rng:NextNumber(Config.ShootingMin or 0.7, Config.ShootingMax or 2))
                    if Field.Destroyed or Library.Unloaded then
                        break
                    end
    
                    if Field.Enabled and Field.Active and Library.IconAnimations ~= false and Frame.AbsoluteSize.X > 80 then
                        Field:Shoot()
                        if Rng:NextNumber() < (Config.BurstChance or 0.35) then
                            for _ = 1, Rng:NextInteger(1, 3) do
                                task.wait(Rng:NextNumber(0.12, 0.3))
                                if Field.Destroyed or not (Field.Enabled and Field.Active) then
                                    break
                                end
                                Field:Shoot()
                            end
                        end
                    end
                end
            end)
        end
    
        function Field:Destroy()
            if Field.Destroyed then
                return
            end
    
            StopTweens()
            Field.Destroyed = true
            for _, Connection in Field.Connections do
                Connection:Disconnect()
            end
            table.clear(Field.Connections)
            Frame:Destroy()
        end
    
        Field:Refresh()
        return Field
    end
    
    local StatsHUD = nil
    function Library:SetStatsHUD(Enabled: boolean)
        Enabled = Enabled == true
        Library.StatsHUDEnabled = Enabled
    
        if not Enabled then
            if StatsHUD then
                StatsHUD.Frame.Visible = false
            end
            return
        end
    
        if not StatsHUD then
            local Frame = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = function()
                    return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
                end,
                BackgroundTransparency = 0.06,
                Name = "CorvusStats",
                Position = UDim2.new(0.5, 0, 0, 10),
                Size = UDim2.fromOffset(0, 30),
                ZIndex = 500,
                Parent = ScreenGui,
            })
            table.insert(Library.Scales, New("UIScale", {
                Scale = Library.DPIScale,
                Parent = Frame,
            }))
            New("UICorner", {
                CornerRadius = UDim.new(0, 8),
                Parent = Frame,
            })
            local Stroke = New("UIStroke", {
                Color = "OutlineColor",
                Parent = Frame,
            })
            Library:AddHoverStroke(Frame, Stroke)
            New("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 12),
                Parent = Frame,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 9),
                Parent = Frame,
            })
    
            local Icon = New("ImageLabel", {
                LayoutOrder = 1,
                Size = UDim2.fromOffset(18, 18),
                Parent = Frame,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 5),
                Parent = Icon,
            })
            local IconData = Library:GetCustomIcon("corvus")
            if IconData then
                Library:ApplyLucideIcon(Icon, IconData)
            end
    
            local function Text(Order: number, Value: string, Bold: boolean?)
                return New("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    FontFace = if Bold then GetBoldFont else nil,
                    LayoutOrder = Order,
                    Size = UDim2.fromOffset(0, 30),
                    Text = Value,
                    TextSize = 13,
                    Parent = Frame,
                })
            end
    
            local function Divider(Order: number)
                New("Frame", {
                    BackgroundColor3 = "OutlineColor",
                    LayoutOrder = Order,
                    Size = UDim2.fromOffset(1, 14),
                    Parent = Frame,
                })
            end
    
            Text(2, Library.Name, true)
            Divider(3)
            local FpsLabel = Text(4, "-- fps")
            Divider(5)
            local PingLabel = Text(6, "-- ms")
            Divider(7)
            local ClockLabel = Text(8, os.date("%H:%M"))
    
            Library:MakeDraggable(Frame, Frame, true)
    
            local function Paint(Fps: number, Ping: number)
                if not Frame.Visible then
                    return
                end
    
                local FpsColor = if Fps >= 50 then Library.Scheme.AccentColor elseif Fps >= 30 then Color3.fromRGB(240, 190, 90) else Library.Scheme.RedColor
                local PingColor = if Ping <= 120 then Library.Scheme.AccentColor elseif Ping <= 250 then Color3.fromRGB(240, 190, 90) else Library.Scheme.RedColor
    
                FpsLabel.Text = string.format('<font color="#%s"><b>%d</b></font> <font transparency="0.45">fps</font>', FpsColor:ToHex(), Fps)
                PingLabel.Text = string.format('<font color="#%s"><b>%d</b></font> <font transparency="0.45">ms</font>', PingColor:ToHex(), Ping)
                ClockLabel.Text = os.date("%H:%M")
            end
    
            StatsHUD = {
                Frame = Frame,
                Paint = Paint,
            }
            Library:OnPerformance(Paint)
            Paint(Library:GetPerformance())
        end
    
        StatsHUD.Frame.Visible = true
        StatsHUD.Paint(Library:GetPerformance())
    end
    
    local CommandRegistry = {
        List = {},
        Lookup = {},
        Listeners = {},
    }
    local ConsoleLines = {}
    local ConsoleSinks = {}
    
    local InfiniteYield = {
        Loaded = false,
        Loading = false,
        Env = nil,
        Commands = {},
        Lookup = {},
        Executable = {},
    }
    
    Library.InfiniteYield = InfiniteYield
    Library.InfiniteYieldSource = "https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source"
    
    local function SplitWords(Text: string): { string }
        local Words = {}
        for Word in string.gmatch(tostring(Text), "%S+") do
            table.insert(Words, Word)
        end
        return Words
    end
    
    local function FireCommandListeners()
        for _, Listener in CommandRegistry.Listeners do
            task.spawn(Listener)
        end
    end
    
    function Library:OnCommandsChanged(Callback: () -> ())
        table.insert(CommandRegistry.Listeners, Callback)
    end
    
    function Library:ConsoleLog(Text: any, Kind: string?)
        local Entry = {
            Text = tostring(Text),
            Kind = Kind or "info",
            Time = os.date("%H:%M:%S"),
        }
        table.insert(ConsoleLines, Entry)
        if #ConsoleLines > 150 then
            table.remove(ConsoleLines, 1)
        end
    
        for _, Sink in ConsoleSinks do
            task.spawn(Sink, Entry)
        end
        return Entry
    end
    
    function Library:GetConsoleLines(): { any }
        return ConsoleLines
    end
    
    function Library:OnConsoleLog(Callback: (any) -> ())
        table.insert(ConsoleSinks, Callback)
    end
    
    function Library:ClearConsole()
        table.clear(ConsoleLines)
        for _, Sink in ConsoleSinks do
            task.spawn(Sink, nil)
        end
    end
    
    function Library:AddCommand(Info: { [string]: any })
        assert(typeof(Info) == "table" and typeof(Info.Name) == "string", "AddCommand expects a table with a Name")
    
        local Command = {
            Name = string.lower(Info.Name),
            Aliases = {},
            Args = tostring(Info.Args or ""),
            Description = tostring(Info.Description or ""),
            Callback = Info.Callback,
            Source = Info.Source or "Corvus",
        }
        for _, Alias in Info.Aliases or {} do
            table.insert(Command.Aliases, string.lower(tostring(Alias)))
        end
    
        local Existing = CommandRegistry.Lookup[Command.Name]
        if Existing and Existing.Name == Command.Name then
            local Index = table.find(CommandRegistry.List, Existing)
            if Index then
                table.remove(CommandRegistry.List, Index)
            end
        end
    
        table.insert(CommandRegistry.List, Command)
        CommandRegistry.Lookup[Command.Name] = Command
        for _, Alias in Command.Aliases do
            local Current = CommandRegistry.Lookup[Alias]
            if not Current or Current.Name ~= Alias then
                CommandRegistry.Lookup[Alias] = Command
            end
        end
    
        FireCommandListeners()
        return Command
    end
    
    function Library:RemoveCommand(Name: string)
        local Command = CommandRegistry.Lookup[string.lower(tostring(Name))]
        if not Command then
            return
        end
    
        local Index = table.find(CommandRegistry.List, Command)
        if Index then
            table.remove(CommandRegistry.List, Index)
        end
        for Key, Value in CommandRegistry.Lookup do
            if Value == Command then
                CommandRegistry.Lookup[Key] = nil
            end
        end
        FireCommandListeners()
    end
    
    function Library:GetCommands(): { any }
        local List = table.clone(CommandRegistry.List)
        for _, Command in InfiniteYield.Commands do
            table.insert(List, Command)
        end
        return List
    end
    
    function Library:FindCommand(Name: string)
        Name = string.lower(tostring(Name))
        return CommandRegistry.Lookup[Name] or InfiniteYield.Lookup[Name]
    end
    
    local function ParseInfiniteYield(Env)
        local Executable = {}
        if typeof(Env.cmds) == "table" then
            for _, Cmd in Env.cmds do
                if typeof(Cmd) == "table" and typeof(Cmd.NAME) == "string" then
                    Executable[string.lower(Cmd.NAME)] = true
                    if typeof(Cmd.ALIAS) == "table" then
                        for _, Alias in Cmd.ALIAS do
                            Executable[string.lower(tostring(Alias))] = true
                        end
                    end
                end
            end
        end
    
        local Commands, Lookup = {}, {}
        local function Register(Names: { string }, Args: string, Description: string)
            local Primary = Names[1]
            if not Primary or Lookup[Primary] then
                return
            end
    
            local Command = {
                Name = Primary,
                Aliases = {},
                Args = Args,
                Description = Description,
                Source = "Pack",
            }
            for Index = 2, #Names do
                table.insert(Command.Aliases, Names[Index])
            end
    
            table.insert(Commands, Command)
            for _, Name in Names do
                if not Lookup[Name] then
                    Lookup[Name] = Command
                end
            end
        end
    
        if typeof(Env.CMDs) == "table" then
            for _, Data in Env.CMDs do
                if typeof(Data) == "table" and typeof(Data.NAME) == "string" then
                    local Raw = Data.NAME
                    local ArgsStart = string.find(Raw, "[%[%(<{]")
                    local NamesPart = if ArgsStart then string.sub(Raw, 1, ArgsStart - 1) else Raw
                    local Args = if ArgsStart then Trim(string.sub(Raw, ArgsStart)) else ""
    
                    local Names = {}
                    local Runnable = next(Executable) == nil
                    for Name in string.gmatch(NamesPart, "[^/]+") do
                        Name = string.lower(Trim(Name))
                        if Name ~= "" and not string.find(Name, " ", 1, true) then
                            table.insert(Names, Name)
                            if Executable[Name] then
                                Runnable = true
                            end
                        end
                    end
    
                    if #Names > 0 and Runnable then
                        Register(Names, Args, tostring(Data.DESC or ""))
                    end
                end
            end
        end
    
        if typeof(Env.cmds) == "table" then
            for _, Cmd in Env.cmds do
                if typeof(Cmd) == "table" and typeof(Cmd.NAME) == "string" and not Lookup[string.lower(Cmd.NAME)] then
                    local Names = { string.lower(Cmd.NAME) }
                    if typeof(Cmd.ALIAS) == "table" then
                        for _, Alias in Cmd.ALIAS do
                            table.insert(Names, string.lower(tostring(Alias)))
                        end
                    end
                    Register(Names, "", if Cmd.PLUGIN then "Plugin command" else "")
                end
            end
        end
    
        return Commands, Lookup, Executable
    end
    
    function Library:LoadInfiniteYield(): boolean
        if InfiniteYield.Loaded then
            return true
        end
    
        if InfiniteYield.Loading then
            repeat
                task.wait(0.1)
            until not InfiniteYield.Loading
            return InfiniteYield.Loaded
        end
    
        InfiniteYield.Loading = true
        FireCommandListeners()
        Library:ConsoleLog("Loading commands...", "system")
    
        local Success, Error = pcall(function()
            local Source = game:HttpGet(Library.InfiniteYieldSource)
            local Chunk, CompileError = loadstring(Source, "=InfiniteYield")
            if not Chunk then
                error(CompileError or "could not compile the command pack", 0)
            end
    
            local Base = getgenv()
            local Env = setmetatable({ IY_LOADED = false }, {
                __index = Base,
            })
            setfenv(Chunk, Env)
            InfiniteYield.Env = Env
            Chunk()
    
            if typeof(Env.execCmd) ~= "function" then
                error("command runner missing", 0)
            end
        end)
    
        InfiniteYield.Loading = false
    
        if not Success then
            Library:ConsoleLog("Commands failed to load: " .. tostring(Error), "error")
            FireCommandListeners()
            return false
        end
    
        local Env = InfiniteYield.Env
        InfiniteYield.Commands, InfiniteYield.Lookup, InfiniteYield.Executable = ParseInfiniteYield(Env)
        InfiniteYield.Loaded = true
    
        pcall(function()
            local function OpenCommunity()
                local Invite = tostring(Library.DiscordInvite or "https://discord.gg/WXvrhu2z8X")
                Library:CopyToClipboard(Invite, "Discord invite copied")
                local Code = string.match(Invite, "([%w%-]+)/?$")
                if Code then
                    task.spawn(Library.OpenDiscordInvite, Library, Code)
                end
            end
            if typeof(Env.cmds) == "table" then
                for _, Cmd in Env.cmds do
                    if typeof(Cmd) == "table" and string.lower(tostring(Cmd.NAME)) == "discord" then
                        Cmd.FUNC = function()
                            OpenCommunity()
                        end
                    end
                end
            end
            for _, Command in InfiniteYield.Commands do
                if Command.Name == "discord" then
                    Command.Description = "Copies the Discord invite and opens it in Discord"
                else
                    Command.Description = string.gsub(string.gsub(tostring(Command.Description), "In%a+ Y%a+ld", "Corvus"), "C%a+balt", "Corvus")
                end
            end
        end)
    
        pcall(function()
            if Env.ScaledHolder then
                InfiniteYield.HolderWasVisible = Env.ScaledHolder.Visible
                Env.ScaledHolder.Visible = false
            end
        end)
    
        InfiniteYield.OriginalNotify = Env.notify
        Env.notify = function(Title, Text, Length)
            local HasText = Text ~= nil and Text ~= ""
            local Heading = if HasText then tostring(Title) else tostring(Library.Title or Library.Name)
            local Body = if HasText then tostring(Text) else tostring(Title)
            Library:ConsoleLog(Heading .. ": " .. Body, "iy")
            Library:Notify({
                Title = Heading,
                Description = Body,
                Time = tonumber(Length) or 4,
            })
        end
    
        InfiniteYield.OriginalMaximize = Env.maximizeHolder
        Env.maximizeHolder = function()
            task.defer(function()
                pcall(function()
                    Env.Cmdbar:ReleaseFocus()
                end)
                if Library.OpenConsole then
                    Library:OpenConsole()
                end
            end)
        end
    
        Library:ConsoleLog(string.format("%d commands ready.", #InfiniteYield.Commands), "success")
        FireCommandListeners()
        return true
    end
    
    function Library:RunCommand(Text: string): boolean
        Text = Trim(tostring(Text or ""))
        if Text == "" then
            return false
        end
    
        Library:ConsoleLog(Text, "input")
    
        local Words = SplitWords(Text)
        local Name = string.lower(table.remove(Words, 1))
        local Command = CommandRegistry.Lookup[Name]
    
        if Command and typeof(Command.Callback) == "function" then
            local Success, Result = pcall(Command.Callback, Words, Text)
            if not Success then
                Library:ConsoleLog(tostring(Result), "error")
                return false
            end
            if Result ~= nil then
                Library:ConsoleLog(tostring(Result), "success")
            end
            return true
        end
    
        if InfiniteYield.Loaded then
            local Known = InfiniteYield.Lookup[Name] or InfiniteYield.Executable[Name]
            if Known or string.find(Text, "^%d+%^") or string.find(Text, "^inf%^") or string.find(Text, "\\", 1, true) then
                local Success, Error = pcall(InfiniteYield.Env.execCmd, Text, LocalPlayer, true)
                if not Success then
                    Library:ConsoleLog(tostring(Error), "error")
                    return false
                end
                return true
            end
    
            Library:ConsoleLog(string.format('Unknown command "%s".', Name), "error")
            return false
        end
    
        Library:ConsoleLog(string.format('Unknown command "%s". Commands are still loading.', Name), "error")
        return false
    end
    
    Library:OnUnload(function()
        local Env = InfiniteYield.Env
        if not (InfiniteYield.Loaded and Env) then
            return
        end
    
        pcall(function()
            if Env.ScaledHolder then
                Env.ScaledHolder.Visible = true
            end
            if InfiniteYield.OriginalNotify then
                Env.notify = InfiniteYield.OriginalNotify
            end
            if InfiniteYield.OriginalMaximize then
                Env.maximizeHolder = InfiniteYield.OriginalMaximize
            end
        end)
    end)
    
    local RemoteSpy = {
        Hooked = false,
        Enabled = false,
        Paused = false,
        LogOutgoing = true,
        LogIncoming = false,
        LogExecutor = false,
        Remotes = {},
        Order = {},
        Queue = {},
        Listeners = {},
        IncomingConnections = {},
        Connections = {},
        TotalCalls = 0,
        MaxCalls = 80,
        MaxRemotes = 400,
        Original = nil,
    }
    Library.RemoteSpy = RemoteSpy
    
    local SpyMethods = {
        FireServer = "Outgoing",
        fireServer = "Outgoing",
        InvokeServer = "Outgoing",
        invokeServer = "Outgoing",
    }
    local SpyClasses = {
        RemoteEvent = true,
        RemoteFunction = true,
        UnreliableRemoteEvent = true,
    }
    
    local function SpyChanged()
        if RemoteSpy.PendingNotify then
            return
        end
        RemoteSpy.PendingNotify = true
    
        task.delay(0.12, function()
            RemoteSpy.PendingNotify = false
            for _, Listener in RemoteSpy.Listeners do
                task.spawn(Listener)
            end
        end)
    end
    
    function RemoteSpy:OnChanged(Callback: () -> ())
        table.insert(RemoteSpy.Listeners, Callback)
    end
    
    local function SpyIndexName(Name: string): string
        if string.match(Name, "^[%a_][%w_]*$") then
            return "." .. Name
        end
        return "[" .. string.format("%q", Name) .. "]"
    end
    
    local function SpyEscape(Text: string): string
        local Escaped = string.gsub(Text, '[%c"\\]', function(Char)
            if Char == '"' then
                return '\\"'
            elseif Char == "\\" then
                return "\\\\"
            elseif Char == "\n" then
                return "\\n"
            elseif Char == "\r" then
                return "\\r"
            elseif Char == "\t" then
                return "\\t"
            end
            return string.format("\\%03d", string.byte(Char))
        end)
        return '"' .. Escaped .. '"'
    end
    
    function RemoteSpy.GetPath(Target: Instance): (string, boolean)
        if Target == game then
            return "game", false
        end
        if Target == workspace then
            return "workspace", false
        end
    
        local Segments = {}
        local Current = Target
        while Current do
            if Current == LocalPlayer then
                table.insert(Segments, 1, 'game:GetService("Players").LocalPlayer')
                return table.concat(Segments), false
            end
    
            local Parent = Current.Parent
            if Parent == game then
                local Success, Service = pcall(function()
                    return game:FindService(Current.ClassName)
                end)
                if Success and Service == Current then
                    table.insert(Segments, 1, string.format('game:GetService("%s")', Current.ClassName))
                else
                    table.insert(Segments, 1, "game" .. SpyIndexName(Current.Name))
                end
                return table.concat(Segments), false
            end
    
            if Parent == nil then
                return table.concat(Segments), true
            end
    
            table.insert(Segments, 1, SpyIndexName(Current.Name))
            Current = Parent
        end
    
        return table.concat(Segments), true
    end
    
    local function SpyNumber(Value: number): string
        if Value ~= Value then
            return "0 / 0"
        elseif Value == math.huge then
            return "math.huge"
        elseif Value == -math.huge then
            return "-math.huge"
        elseif Value == math.floor(Value) and math.abs(Value) < 1e15 then
            return string.format("%d", Value)
        end
        return string.format("%.14g", Value)
    end
    
    function RemoteSpy.Serialize(Value: any, Depth: number?, Seen: { [any]: boolean }?): string
        Depth = Depth or 0
        Seen = Seen or {}
    
        local Kind = typeof(Value)
        if Kind == "nil" then
            return "nil"
        elseif Kind == "boolean" then
            return tostring(Value)
        elseif Kind == "number" then
            return SpyNumber(Value)
        elseif Kind == "string" then
            return SpyEscape(Value)
        elseif Kind == "Instance" then
            local Path, IsNil = RemoteSpy.GetPath(Value)
            if IsNil then
                return "nil"
            end
            return Path
        elseif Kind == "Vector3" then
            return string.format("Vector3.new(%s, %s, %s)", SpyNumber(Value.X), SpyNumber(Value.Y), SpyNumber(Value.Z))
        elseif Kind == "Vector2" then
            return string.format("Vector2.new(%s, %s)", SpyNumber(Value.X), SpyNumber(Value.Y))
        elseif Kind == "CFrame" then
            local Parts = {}
            for _, Component in { Value:GetComponents() } do
                table.insert(Parts, SpyNumber(Component))
            end
            return "CFrame.new(" .. table.concat(Parts, ", ") .. ")"
        elseif Kind == "Color3" then
            return string.format("Color3.fromRGB(%d, %d, %d)", math.floor(Value.R * 255 + 0.5), math.floor(Value.G * 255 + 0.5), math.floor(Value.B * 255 + 0.5))
        elseif Kind == "UDim2" then
            return string.format("UDim2.new(%s, %s, %s, %s)", SpyNumber(Value.X.Scale), SpyNumber(Value.X.Offset), SpyNumber(Value.Y.Scale), SpyNumber(Value.Y.Offset))
        elseif Kind == "UDim" then
            return string.format("UDim.new(%s, %s)", SpyNumber(Value.Scale), SpyNumber(Value.Offset))
        elseif Kind == "EnumItem" then
            return tostring(Value)
        elseif Kind == "BrickColor" then
            return string.format("BrickColor.new(%s)", SpyEscape(tostring(Value)))
        elseif Kind == "table" then
            if Seen[Value] or Depth > 8 then
                return "{}"
            end
            Seen[Value] = true
    
            local Count = 0
            local MaxIndex = 0
            for Key in Value do
                Count += 1
                if typeof(Key) == "number" and Key >= 1 and Key == math.floor(Key) then
                    MaxIndex = math.max(MaxIndex, Key)
                end
            end
            if Count == 0 then
                Seen[Value] = nil
                return "{}"
            end
    
            local Indent = string.rep("    ", Depth + 1)
            local Lines = {}
            if MaxIndex == Count then
                for Index = 1, MaxIndex do
                    table.insert(Lines, Indent .. RemoteSpy.Serialize(Value[Index], Depth + 1, Seen))
                end
            else
                local Keys = {}
                for Key in Value do
                    table.insert(Keys, Key)
                end
                table.sort(Keys, function(A, B)
                    return tostring(A) < tostring(B)
                end)
                for _, Key in Keys do
                    local KeyText
                    if typeof(Key) == "string" and string.match(Key, "^[%a_][%w_]*$") then
                        KeyText = Key
                    else
                        KeyText = "[" .. RemoteSpy.Serialize(Key, Depth + 1, Seen) .. "]"
                    end
                    table.insert(Lines, Indent .. KeyText .. " = " .. RemoteSpy.Serialize(Value[Key], Depth + 1, Seen))
                end
            end
    
            Seen[Value] = nil
            return "{\n" .. table.concat(Lines, ",\n") .. "\n" .. string.rep("    ", Depth) .. "}"
        end
    
        return "nil"
    end
    
    function RemoteSpy.Preview(Args): string
        local Parts = {}
        for Index = 1, math.min(Args.n or #Args, 6) do
            local Value = Args[Index]
            local Kind = typeof(Value)
            local Text
            if Kind == "string" then
                Text = if #Value > 22 then SpyEscape(string.sub(Value, 1, 20)) .. "\u{2026}" else SpyEscape(Value)
            elseif Kind == "table" then
                local Count = 0
                for _ in Value do
                    Count += 1
                end
                Text = string.format("{%d}", Count)
            elseif Kind == "Instance" then
                Text = Value.Name
            elseif Kind == "number" then
                Text = SpyNumber(Value)
            elseif Kind == "nil" or Kind == "boolean" then
                Text = tostring(Value)
            else
                Text = Kind
            end
            table.insert(Parts, Text)
        end
        if (Args.n or #Args) > 6 then
            table.insert(Parts, "\u{2026}")
        end
        return if #Parts == 0 then "no arguments" else table.concat(Parts, ", ")
    end
    
    function RemoteSpy.GetCode(Record, Call): string
        if not (Record and Call) then
            return ""
        end
    
        local Lines = {}
        local Target = Record.Path
        if Record.IsNil then
            table.insert(Lines, "local Remote")
            table.insert(Lines, "for _, Instance in getnilinstances() do")
            table.insert(Lines, string.format("    if Instance.Name == %s and Instance.ClassName == %s then", SpyEscape(Record.Name), SpyEscape(Record.ClassName)))
            table.insert(Lines, "        Remote = Instance")
            table.insert(Lines, "        break")
            table.insert(Lines, "    end")
            table.insert(Lines, "end")
            Target = "Remote"
        end
    
        if Call.Direction == "Incoming" then
            table.insert(Lines, Target .. ".OnClientEvent:Connect(function(...)")
            table.insert(Lines, "    print(...)")
            table.insert(Lines, "end)")
            return table.concat(Lines, "\n")
        end
    
        local Method = if Record.ClassName == "RemoteFunction" then "InvokeServer" else "FireServer"
        local Count = Call.Args.n or #Call.Args
        if Call.ScriptPath then
            table.insert(Lines, 1, "local CalledFrom = " .. SpyEscape(Call.ScriptPath))
        end
        if Count == 0 then
            table.insert(Lines, string.format("%s:%s()", Target, Method))
        else
            table.insert(Lines, "local Args = {")
            for Index = 1, Count do
                table.insert(Lines, string.format("    [%d] = %s,", Index, RemoteSpy.Serialize(Call.Args[Index], 1)))
            end
            table.insert(Lines, "}")
            table.insert(Lines, string.format("%s:%s(table.unpack(Args, 1, %d))", Target, Method, Count))
        end
        if Call.Returns and (Call.Returns.n or #Call.Returns) > 0 then
            table.insert(Lines, "")
            table.insert(Lines, "local Returned = " .. RemoteSpy.Serialize({ table.unpack(Call.Returns, 1, Call.Returns.n) }, 0))
        end
        return table.concat(Lines, "\n")
    end
    
    local function SpyScriptPath(Script: any): string?
        if typeof(Script) ~= "Instance" then
            return nil
        end
        local Success, Path = pcall(RemoteSpy.GetPath, Script)
        return if Success then Path else Script.Name
    end
    
    function RemoteSpy.Record(Remote: Instance, Method: string, Args, Direction: string, FromExecutor: boolean?, Script: any?, Returns: any?)
        local Record = RemoteSpy.Remotes[Remote]
        if not Record then
            if #RemoteSpy.Order >= RemoteSpy.MaxRemotes then
                return
            end
    
            local Path, IsNil = RemoteSpy.GetPath(Remote)
            Record = {
                Remote = Remote,
                Name = Remote.Name,
                ClassName = Remote.ClassName,
                Path = Path,
                IsNil = IsNil,
                Calls = {},
                Count = 0,
                Outgoing = 0,
                Incoming = 0,
                Blocked = false,
                Ignored = false,
                Order = #RemoteSpy.Order + 1,
            }
            RemoteSpy.Remotes[Remote] = Record
            table.insert(RemoteSpy.Order, Record)
        end
    
        Record.Count += 1
        Record[Direction] += 1
        Record.LastSeen = os.clock()
    
        if not Record.Ignored then
            table.insert(Record.Calls, 1, {
                Method = Method,
                Args = Args,
                Direction = Direction,
                FromExecutor = FromExecutor == true,
                Script = Script,
                ScriptPath = SpyScriptPath(Script),
                Returns = Returns,
                Time = os.date("%H:%M:%S"),
                Preview = RemoteSpy.Preview(Args),
            })
            if #Record.Calls > RemoteSpy.MaxCalls then
                table.remove(Record.Calls)
            end
        end
    
        RemoteSpy.TotalCalls += 1
        SpyChanged()
    end
    
    local function SpyProcessQueue()
        local Queue = RemoteSpy.Queue
        if #Queue == 0 then
            return
        end
    
        RemoteSpy.Queue = {}
        for _, Item in Queue do
            local Success = pcall(RemoteSpy.Record, Item[1], Item[2], Item[3], Item[4], Item[5], Item[6], Item[7])
            if not Success then
                continue
            end
        end
    end
    
    function RemoteSpy:WatchIncoming()
        if RemoteSpy.WatchingIncoming then
            return
        end
        RemoteSpy.WatchingIncoming = true
    
        local function Watch(Target: Instance)
            if RemoteSpy.IncomingConnections[Target] then
                return
            end
    
            local Success, IsRemote = pcall(function()
                return Target:IsA("RemoteEvent") or Target:IsA("UnreliableRemoteEvent")
            end)
            if not (Success and IsRemote) then
                return
            end
    
            RemoteSpy.IncomingConnections[Target] = Target.OnClientEvent:Connect(function(...)
                if RemoteSpy.Enabled and RemoteSpy.LogIncoming and not RemoteSpy.Paused then
                    local Record = RemoteSpy.Remotes[Target]
                    if Record and Record.Ignored then
                        return
                    end
                    table.insert(RemoteSpy.Queue, { Target, "OnClientEvent", table.pack(...), "Incoming", false })
                end
            end)
        end
    
        task.spawn(function()
            for Index, Target in game:GetDescendants() do
                Watch(Target)
                if Index % 2500 == 0 then
                    task.wait()
                end
            end
        end)
        table.insert(RemoteSpy.Connections, game.DescendantAdded:Connect(Watch))
    end
    
    function RemoteSpy:Supported(): boolean
        return typeof(hookmetamethod) == "function" and typeof(getnamecallmethod) == "function"
    end
    
    function RemoteSpy:Start(): (boolean, string?)
        if not RemoteSpy.Hooked then
            if not RemoteSpy:Supported() then
                return false, "Your executor does not support hookmetamethod"
            end
    
            local Wrap = if typeof(newcclosure) == "function" then newcclosure else function(Callback)
                return Callback
            end
            local IsExecutor = if typeof(checkcaller) == "function" then checkcaller else function()
                return false
            end
    
            local Original
            local Success, Error = pcall(function()
                Original = hookmetamethod(game, "__namecall", Wrap(function(Self, ...)
                    local Method = getnamecallmethod()
                    if RemoteSpy.Enabled and SpyMethods[Method] and typeof(Self) == "Instance" and SpyClasses[Self.ClassName] then
                        local FromExecutor = IsExecutor()
                        local Record = RemoteSpy.Remotes[Self]
    
                        if Record and Record.Blocked and not FromExecutor then
                            return nil
                        end
    
                        if RemoteSpy.LogOutgoing and not RemoteSpy.Paused and (RemoteSpy.LogExecutor or not FromExecutor) and not (Record and Record.Ignored) then
                            local Queue = RemoteSpy.Queue
                            if #Queue < 600 then
                                local Script = nil
                                if typeof(getcallingscript) == "function" then
                                    local Ok, Result = pcall(getcallingscript)
                                    Script = if Ok then Result else nil
                                end
    
                                if Method == "InvokeServer" or Method == "invokeServer" then
                                    local Results = table.pack(Original(Self, ...))
                                    Queue[#Queue + 1] = { Self, Method, table.pack(...), "Outgoing", FromExecutor, Script, Results }
                                    return table.unpack(Results, 1, Results.n)
                                end
    
                                Queue[#Queue + 1] = { Self, Method, table.pack(...), "Outgoing", FromExecutor, Script }
                            end
                        end
                    end
    
                    return Original(Self, ...)
                end))
            end)
    
            if not Success or not Original then
                return false, tostring(Error or "hook failed")
            end
    
            RemoteSpy.Original = Original
            RemoteSpy.Hooked = true
            table.insert(RemoteSpy.Connections, RunService.Heartbeat:Connect(SpyProcessQueue))
        end
    
        RemoteSpy.Enabled = true
        if RemoteSpy.LogIncoming then
            RemoteSpy:WatchIncoming()
        end
        SpyChanged()
        return true
    end
    
    function RemoteSpy:Stop()
        RemoteSpy.Enabled = false
        SpyChanged()
    end
    
    function RemoteSpy:SetPaused(Paused: boolean)
        RemoteSpy.Paused = Paused == true
        SpyChanged()
    end
    
    function RemoteSpy:SetIncoming(Enabled: boolean)
        RemoteSpy.LogIncoming = Enabled == true
        if RemoteSpy.LogIncoming and RemoteSpy.Enabled then
            RemoteSpy:WatchIncoming()
        end
        SpyChanged()
    end
    
    function RemoteSpy:Clear()
        table.clear(RemoteSpy.Remotes)
        table.clear(RemoteSpy.Order)
        RemoteSpy.Queue = {}
        RemoteSpy.TotalCalls = 0
        SpyChanged()
    end
    
    function RemoteSpy:Decompile(Call): (boolean, string)
        local Script = Call and Call.Script
        if typeof(Script) ~= "Instance" then
            return false, "No calling script was captured for this call."
        end
        if typeof(decompile) ~= "function" then
            return false, "Your executor has no decompiler."
        end
    
        local Success, Result = pcall(decompile, Script)
        if not Success or typeof(Result) ~= "string" or Result == "" then
            return false, "Decompile failed: " .. tostring(Result)
        end
        return true, Result
    end
    
    function RemoteSpy:Repeat(Record, Call): (boolean, string?)
        if not (Record and Call) or Call.Direction ~= "Outgoing" then
            return false, "Only outgoing calls can be repeated"
        end
    
        local Remote = Record.Remote
        local Args = Call.Args
        return pcall(function()
            if Record.ClassName == "RemoteFunction" then
                return Remote:InvokeServer(table.unpack(Args, 1, Args.n or #Args))
            end
            Remote:FireServer(table.unpack(Args, 1, Args.n or #Args))
        end)
    end
    
    Library:OnUnload(function()
        RemoteSpy.Enabled = false
        for _, Connection in RemoteSpy.Connections do
            pcall(function()
                Connection:Disconnect()
            end)
        end
        for _, Connection in RemoteSpy.IncomingConnections do
            pcall(function()
                Connection:Disconnect()
            end)
        end
        table.clear(RemoteSpy.IncomingConnections)
    
        if RemoteSpy.Hooked and RemoteSpy.Original and typeof(hookmetamethod) == "function" then
            pcall(hookmetamethod, game, "__namecall", RemoteSpy.Original)
        end
    end)
    
    local BaseAddons = {}
    do
        local Funcs = {}
    
        function Funcs:AddKeyPicker(Idx, Info)
            if self.Destroyed then return nil end
    
            Info = Library:Validate(Info, Templates.KeyPicker)
    
            local ParentObj = self
            local ToggleLabel = ParentObj.TextLabel
    
            if ParentObj.Type == "Button" or ParentObj.Type == "SubButton" then
                assert(Info.Mode == "Press", "KeyPicker on Buttons can only be applied with the 'Press' mode.")
    
                ToggleLabel = ParentObj.Base
            end
    
            local KeyPicker = {
                Connections = {},
    
                Text = Info.Text,
                Value = Info.Default,
                Modifiers = Info.DefaultModifiers,
                DisplayValue = Info.Default,
    
                Blacklisted = Info.Blacklisted,
                BlacklistedModifiers = Info.BlacklistedModifiers,
                Whitelisted = Info.Whitelisted,
                WhitelistedModifiers = Info.WhitelistedModifiers,
    
                Toggled = false,
                Mode = Info.Mode,
                SyncToggleState = Info.SyncToggleState,
    
                MenuVisible = Info.NoUI ~= true,
    
                Callback = Info.Callback,
                ChangedCallback = Info.ChangedCallback,
                Changed = Info.Changed,
                Clicked = Info.Clicked,
    
                Type = "KeyPicker",
            }
    
            if KeyPicker.Mode == "Press" then
                assert(ParentObj.Type == "Label" or ParentObj.Type == "Button" or ParentObj.Type == "SubButton", "KeyPicker with the mode 'Press' can be only applied on Labels and Buttons.")
    
                KeyPicker.SyncToggleState = false
                Info.Modes = { "Press" }
                Info.Mode = "Press"
            end
    
            if KeyPicker.SyncToggleState then
                Info.Modes = { "Toggle", "Hold" }
    
                if not table.find(Info.Modes, Info.Mode) then
                    Info.Mode = "Toggle"
                end
            end
    
            local Picking = false
            local IsForButton = ParentObj.Type == "Button" or ParentObj.Type == "SubButton"
    
            local SpecialKeys = {
                ["MB1"] = Enum.UserInputType.MouseButton1,
                ["MB2"] = Enum.UserInputType.MouseButton2,
                ["MB3"] = Enum.UserInputType.MouseButton3,
            }
    
            local SpecialKeysInput = {
                [Enum.UserInputType.MouseButton1] = "MB1",
                [Enum.UserInputType.MouseButton2] = "MB2",
                [Enum.UserInputType.MouseButton3] = "MB3",
            }
    
            local Modifiers = {
                ["LAlt"] = Enum.KeyCode.LeftAlt,
                ["RAlt"] = Enum.KeyCode.RightAlt,
    
                ["LCtrl"] = Enum.KeyCode.LeftControl,
                ["RCtrl"] = Enum.KeyCode.RightControl,
    
                ["LShift"] = Enum.KeyCode.LeftShift,
                ["RShift"] = Enum.KeyCode.RightShift,
    
                ["Tab"] = Enum.KeyCode.Tab,
                ["CapsLock"] = Enum.KeyCode.CapsLock,
            }
    
            local ModifiersInput = {
                [Enum.KeyCode.LeftAlt] = "LAlt",
                [Enum.KeyCode.RightAlt] = "RAlt",
    
                [Enum.KeyCode.LeftControl] = "LCtrl",
                [Enum.KeyCode.RightControl] = "RCtrl",
    
                [Enum.KeyCode.LeftShift] = "LShift",
                [Enum.KeyCode.RightShift] = "RShift",
    
                [Enum.KeyCode.Tab] = "Tab",
                [Enum.KeyCode.CapsLock] = "CapsLock",
            }
    
            local IsModifierInput = function(Input)
                return Input.UserInputType == Enum.UserInputType.Keyboard and ModifiersInput[Input.KeyCode] ~= nil
            end
    
            local GetActiveModifiers = function()
                local ActiveModifiers = {}
    
                for Name, Input in Modifiers do
                    if table.find(ActiveModifiers, Name) then
                        continue
                    end
                    if not UserInputService:IsKeyDown(Input) then
                        continue
                    end
    
                    table.insert(ActiveModifiers, Name)
                end
    
                return ActiveModifiers
            end
    
            local AreModifiersHeld = function(Required)
                if not (typeof(Required) == "table" and GetTableSize(Required) > 0) then
                    return true
                end
    
                local ActiveModifiers = GetActiveModifiers()
                local Holding = true
    
                for _, Name in Required do
                    if table.find(ActiveModifiers, Name) then
                        continue
                    end
    
                    Holding = false
                    break
                end
    
                return Holding
            end
    
            local IsInputDown = function(Input)
                if not Input then
                    return false
                end
    
                if SpecialKeysInput[Input.UserInputType] ~= nil then
                    return UserInputService:IsMouseButtonPressed(Input.UserInputType)
                        and not UserInputService:GetFocusedTextBox()
                elseif Input.UserInputType == Enum.UserInputType.Keyboard then
                    return UserInputService:IsKeyDown(Input.KeyCode) and not UserInputService:GetFocusedTextBox()
                else
                    return false
                end
            end
    
            local ConvertToInputModifiers = function(CurrentModifiers)
                local InputModifiers = {}
    
                for _, name in CurrentModifiers do
                    table.insert(InputModifiers, Modifiers[name])
                end
    
                return InputModifiers
            end
    
            local VerifyModifiers = function(CurrentModifiers)
                if typeof(CurrentModifiers) ~= "table" then
                    return {}
                end
    
                local ValidModifiers = {}
    
                for _, name in CurrentModifiers do
                    if not Modifiers[name] then
                        continue
                    end
    
                    table.insert(ValidModifiers, name)
                end
    
                return ValidModifiers
            end
    
            KeyPicker.Modifiers = VerifyModifiers(KeyPicker.Modifiers)
    
            local SlideOverflow = true
            local LastDisplayText = nil
            local MaxPickerWidth = 85
            local SlidingLabel
    
            local SlideForwardTween
            local SlideBackTween
            local HandleForwardTween = function(State)
                if State ~= Enum.PlaybackState.Completed then
                    return
                end
    
                task.wait(1.5)
                if SlideBackTween then
                    SlideBackTween:Play()
                end
            end
    
            local HandleBackTween = function(State)
                if State ~= Enum.PlaybackState.Completed then
                    return
                end
    
                task.wait(1.5)
                if SlideForwardTween then
                    SlideForwardTween:Play()
                end
            end
    
            local SlideForwardConn, SlideBackConn
            local CancelSlidingTweens = function()
                if SlideForwardConn then
                    SlideForwardConn:Disconnect()
                    SlideForwardConn = nil
                end
    
                if SlideBackConn then
                    SlideBackConn:Disconnect()
                    SlideBackConn = nil
                end
    
                if SlideForwardTween then
                    StopTween(SlideForwardTween, true)
                    SlideForwardTween = nil
                end
    
                if SlideBackTween then
                    StopTween(SlideBackTween, true)
                    SlideBackTween = nil
                end
    
                RunService.RenderStepped:Wait()
            end
    
            local Picker = New("TextButton", {
                BackgroundColor3 = "MainColor",
                Size = UDim2.fromOffset(18, 18),
                Text = (IsForButton and SlideOverflow) and "" or KeyPicker.Value,
                TextSize = 14,
                TextTransparency = 0.4,
                Parent = ToggleLabel,
            })
    
            if IsForButton and SlideOverflow then
                Picker.ClipsDescendants = true
    
                SlidingLabel = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 1, 0),
                    Position = UDim2.new(0, 0, 0, 0),
                    Text = KeyPicker.Value,
                    TextSize = 14,
                    FontFace = Picker.FontFace,
                    TextXAlignment = Enum.TextXAlignment.Center,
                    Parent = Picker,
                })
    
                Library:AddToRegistry(SlidingLabel, {
                    TextColor3 = "FontColor",
                })
            end
    
            New("UIStroke", {
                Color = "OutlineColor",
                Parent = Picker,
            })
    
            local PickerCorner = New("UICorner", {
                TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Picker,
            }); table.insert(Library.SpecificCorners, PickerCorner)
    
            local PickerHoverTween = nil
    
            local function ApplyPickerTextTransparency(Transparency: number)
                StopTween(PickerHoverTween)
                PickerHoverTween = nil
    
                Picker.TextTransparency = Transparency
                if SlidingLabel then
                    SlidingLabel.TextTransparency = Transparency
                end
            end
    
            local function TweenPickerTextTransparency(Transparency: number)
                StopTween(PickerHoverTween)
    
                PickerHoverTween = TweenService:Create(Picker, Library.TweenInfo, {
                    TextTransparency = Transparency,
                })
                PickerHoverTween:Play()
    
                if SlidingLabel then
                    TweenService:Create(SlidingLabel, Library.TweenInfo, {
                        TextTransparency = Transparency,
                    }):Play()
                end
            end
    
            table.insert(KeyPicker.Connections, Picker.MouseEnter:Connect(function()
                if ParentObj.Disabled then
                    return
                end
    
                TweenPickerTextTransparency(0)
            end))
    
            table.insert(KeyPicker.Connections, Picker.MouseLeave:Connect(function()
                if ParentObj.Disabled then
                    return
                end
    
                TweenPickerTextTransparency(0.4)
            end))
    
            if IsForButton then
                local Holder = New("Frame", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, 21),
                    Parent = ToggleLabel.Parent,
                })
    
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    Padding = UDim.new(0, 9),
                    Parent = Holder,
                })
    
                New("UIFlexItem", {
                    FlexMode = Enum.UIFlexMode.Fill,
                    Parent = ToggleLabel,
                })
    
                ToggleLabel.Parent = Holder
                Picker.Parent = Holder
    
                Picker.Size = UDim2.new(0, 18, 1, 0)
            end
    
            local KeybindsToggle = { Normal = KeyPicker.Mode ~= "Toggle" }
            do
                local Holder = New("TextButton", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, 16),
                    Text = "",
                    Visible = not Info.NoUI,
                    Parent = Library.KeybindContainer,
                })
    
                local Label = New("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(0, 1),
                    Text = "",
                    TextSize = 14,
                    TextTransparency = 0.5,
                    Parent = Holder,
                })
    
                local Checkbox = New("Frame", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundColor3 = "MainColor",
                    Position = UDim2.fromScale(0, 0.5),
                    Size = UDim2.fromOffset(14, 14),
                    SizeConstraint = Enum.SizeConstraint.RelativeYY,
                    Parent = Holder,
                })
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Checkbox,
                    })
                )
                New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = Checkbox,
                })
    
                local CheckImage = New("ImageLabel", {
                    ImageColor3 = "FontColor",
                    ImageTransparency = 1,
                    Position = UDim2.fromOffset(2, 2),
                    Size = UDim2.new(1, -4, 1, -4),
                    Parent = Checkbox,
                })
                if CheckIcon then
                    Library:ApplyLucideIcon(CheckImage, CheckIcon)
                end
    
                function KeybindsToggle:Display(State)
                    Label.TextTransparency = State and 0 or 0.5
                    CheckImage.ImageTransparency = State and 0 or 1
                end
    
                function KeybindsToggle:SetText(Text)
                    Label.Text = Text
                end
    
                function KeybindsToggle:SetVisibility(Visibility)
                    Holder.Visible = Visibility
                end
    
                function KeybindsToggle:SetNormal(Normal)
                    KeybindsToggle.Normal = Normal
    
                    Holder.Active = not Normal
                    Label.Position = Normal and UDim2.fromOffset(0, 0) or UDim2.fromOffset(22, 0)
                    Checkbox.Visible = not Normal
                end
    
                KeyPicker.DoClick = function(...) end
                table.insert(KeyPicker.Connections, Holder.MouseButton1Click:Connect(function()
                    if KeybindsToggle.Normal then
                        return
                    end
    
                    KeyPicker.Toggled = not KeyPicker.Toggled
                    KeyPicker:DoClick()
                    KeyPicker:Update()
                end))
    
                KeybindsToggle.Holder = Holder
                KeybindsToggle.Label = Label
                KeybindsToggle.Checkbox = Checkbox
                KeybindsToggle.Loaded = true
                table.insert(Library.KeybindToggles, KeybindsToggle)
            end
    
            local ModeButtons = {}
            local ModeCorners = {}
            local TotalModeButtons = GetTableSize(Info.Modes)
            local MenuCornersOnly = if TotalModeButtons == 1 then "no_left" else "no_top_left"
    
            local MenuTable
            MenuTable = Library:AddContextMenu(Picker, UDim2.fromOffset(62, 0), function()
                return { Picker.AbsoluteSize.X + 1.5, 0.5 }
            end, 1, function(Active: boolean)
                local Half = UDim.new(0, Library.CornerRadius / 2)
                local Zero = UDim.new(0, 0)
    
                PickerCorner.TopLeftRadius = Half
                PickerCorner.BottomLeftRadius = Half
                PickerCorner.TopRightRadius = Active and Zero or Half
                PickerCorner.BottomRightRadius = Active and Zero or Half
    
                local MenuCorner = MenuTable and MenuTable.Corner
                if MenuCorner then
                    if MenuCornersOnly == "no_left" then
                        MenuCorner.TopLeftRadius = Zero
                        MenuCorner.BottomLeftRadius = Zero
                        MenuCorner.TopRightRadius = Half
                        MenuCorner.BottomRightRadius = Half
                    else
                        MenuCorner.TopLeftRadius = Zero
                        MenuCorner.TopRightRadius = Half
                        MenuCorner.BottomRightRadius = Half
                        MenuCorner.BottomLeftRadius = Half
                    end
                end
    
                for _, Entry in ModeCorners do
                    local Corner = Entry.Corner
                    if Entry.Style == "single" then
                        Corner.TopLeftRadius = Zero
                        Corner.BottomLeftRadius = Zero
                        Corner.TopRightRadius = Half
                        Corner.BottomRightRadius = Half
                    elseif Entry.Style == "first" then
                        Corner.TopLeftRadius = Zero
                        Corner.TopRightRadius = Half
                        Corner.BottomLeftRadius = Zero
                        Corner.BottomRightRadius = Zero
                    elseif Entry.Style == "last" then
                        Corner.TopLeftRadius = Zero
                        Corner.TopRightRadius = Zero
                        Corner.BottomLeftRadius = Half
                        Corner.BottomRightRadius = Half
                    end
                end
            end, false, MenuCornersOnly, "KeyPicker")
            KeyPicker.Menu = MenuTable
    
            for Index, Mode in Info.Modes do
                local ModeButton = {}
    
                local Button = New("TextButton", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, IsForButton and 21 or (TotalModeButtons == 1 and 18 or 19)),
                    Text = Mode,
                    TextSize = 14,
                    TextTransparency = 0.5,
                    Parent = MenuTable.Menu,
                })
    
                if Index == 1 and TotalModeButtons == 1 then
                    local Corner = New("UICorner", {
                        TopLeftRadius = UDim.new(0, 0),
                        TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                        BottomLeftRadius = UDim.new(0, 0),
                        BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Button,
                    })
                    table.insert(Library.SpecificCorners, Corner)
                    table.insert(ModeCorners, { Corner = Corner, Style = "single" })
                elseif Index == 1 then
                    local Corner = New("UICorner", {
                        TopLeftRadius = UDim.new(0, 0),
                        TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                        BottomLeftRadius = UDim.new(0, 0),
                        BottomRightRadius = UDim.new(0, 0),
                        Parent = Button,
                    })
                    table.insert(Library.SpecificCorners, Corner)
                    table.insert(ModeCorners, { Corner = Corner, Style = "first" })
                elseif Index == TotalModeButtons then
                    local Corner = New("UICorner", {
                        TopLeftRadius = UDim.new(0, 0),
                        TopRightRadius = UDim.new(0, 0),
                        BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                        BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Button,
                    })
                    table.insert(Library.SpecificCorners, Corner)
                    table.insert(ModeCorners, { Corner = Corner, Style = "last" })
                end
    
                function ModeButton:Select()
                    for _, Button in ModeButtons do
                        Button:Deselect()
                    end
    
                    KeyPicker.Mode = Mode
    
                    Button.BackgroundTransparency = 0
                    Button.TextTransparency = 0
    
                    MenuTable:Close()
                    if KeyPicker.Update then
                        KeyPicker:Update()
                    end
                end
    
                function ModeButton:Deselect()
                    KeyPicker.Mode = nil
    
                    Button.BackgroundTransparency = 1
                    Button.TextTransparency = 0.5
                end
    
                table.insert(KeyPicker.Connections, Button.MouseButton1Click:Connect(function()
                    ModeButton:Select()
                end))
    
                table.insert(KeyPicker.Connections, Button.MouseEnter:Connect(function()
                    if KeyPicker.Mode == Mode then
                        return
                    end
    
                    TweenService:Create(Button, Library.TweenInfo, {
                        BackgroundTransparency = 0.7,
                        TextTransparency = 0.1,
                    }):Play()
                end))
    
                table.insert(KeyPicker.Connections, Button.MouseLeave:Connect(function()
                    if KeyPicker.Mode == Mode then
                        return
                    end
    
                    TweenService:Create(Button, Library.TweenInfo, {
                        BackgroundTransparency = 1,
                        TextTransparency = 0.5,
                    }):Play()
                end))
    
                if KeyPicker.Mode == Mode then
                    ModeButton:Select()
                end
    
                ModeButtons[Mode] = ModeButton
            end
    
            local SetPickingState = function(State, SkipUpdate: boolean?)
                Picking = State
                Library.IsPicking = State
    
                if ParentObj then
                    ParentObj.AnyKeyPickerPicking = Picking
                end
    
                if IsForButton then
                    ToggleLabel.Visible = not Picking
                    LastDisplayText = nil
                    RunService.RenderStepped:Wait()
                end
    
                if SkipUpdate ~= true then
                    (KeyPicker :: any):Update()
                end
            end
    
            function KeyPicker:Display(PickerText)
                if Library.Unloaded then
                    return
                end
    
                local DisplayText = PickerText or KeyPicker.DisplayValue
                if IsForButton and SlideOverflow then
                    local X, _Y = Library:GetTextBounds(
                        DisplayText,
                        Picker.FontFace,
                        Picker.TextSize,
                        10000
                    )
    
                    local OffsetScale = X + 9
                    local TextChanged = LastDisplayText ~= DisplayText
                    local LabelWidth
    
                    SlidingLabel.Text = DisplayText
                    LastDisplayText = DisplayText
    
                    if Picking then
                        Picker.Size = UDim2.new(1, 0, 1, 0)
                        RunService.RenderStepped:Wait()
                        LabelWidth = Picker.AbsoluteSize.X
    
                        if LabelWidth <= 0 then
                            LabelWidth = MaxPickerWidth
                        end
                    else
                        LabelWidth = math.min(OffsetScale, MaxPickerWidth)
                        Picker.Size = UDim2.new(0, LabelWidth, 1, 0)
                    end
    
                    if OffsetScale > LabelWidth then
                        SlidingLabel.TextXAlignment = Enum.TextXAlignment.Left
                        SlidingLabel.Size = UDim2.new(0, OffsetScale, 1, 0)
    
                        local OverflowDistance = OffsetScale - LabelWidth - 4.5
                        if OverflowDistance > 0 then
                            if TextChanged or not SlideForwardTween then
                                SlidingLabel.Position = UDim2.fromOffset(4.5, 0)
                                CancelSlidingTweens()
    
                                local Duration = math.max(OverflowDistance / 25, 0.35)
                                local TweenInfo = TweenInfo.new(
                                    Duration,
                                    Enum.EasingStyle.Linear,
                                    Enum.EasingDirection.InOut
                                )
    
                                SlideForwardTween = TweenService:Create(SlidingLabel, TweenInfo, {
                                    Position = UDim2.fromOffset(-OverflowDistance, 0),
                                })
    
                                SlideBackTween = TweenService:Create(SlidingLabel, TweenInfo, {
                                    Position = UDim2.fromOffset(4.5, 0),
                                })
    
                                SlideForwardTween:Play()
    
                                if SlideForwardConn then
                                    SlideForwardConn:Disconnect()
                                end
    
                                if SlideBackConn then
                                    SlideBackConn:Disconnect()
                                end
    
                                SlideForwardConn = SlideForwardTween.Completed:Connect(HandleForwardTween)
                                SlideBackConn = SlideBackTween.Completed:Connect(HandleBackTween)
                            end
                        else
                            CancelSlidingTweens()
    
                            SlidingLabel.TextXAlignment = Enum.TextXAlignment.Center
                            SlidingLabel.Size = UDim2.new(1, 0, 1, 0)
                            SlidingLabel.Position = UDim2.new(0, 0, 0, 0)
                        end
                    else
                        CancelSlidingTweens()
    
                        SlidingLabel.TextXAlignment = Enum.TextXAlignment.Center
                        SlidingLabel.Size = UDim2.new(1, 0, 1, 0)
                        SlidingLabel.Position = UDim2.new(0, 0, 0, 0)
                    end
                else
                    local X, Y = Library:GetTextBounds(
                        DisplayText,
                        Picker.FontFace,
                        Picker.TextSize,
                        ToggleLabel.AbsoluteSize.X / Library.DPIScale
                    )
                    Picker.Text = DisplayText
                    Picker.Size = IsForButton and UDim2.new(0, X + 9, 1, 0) or UDim2.fromOffset((X + 9), (Y + 4))
                end
            end
    
            function KeyPicker:Update()
                local Disabled = ParentObj.Disabled == true
    
                if Disabled and Picking then
                    SetPickingState(false, true)
                end
    
                KeyPicker:Display()
    
                Picker.Active = not Disabled
                ApplyPickerTextTransparency(Disabled and 0.8 or 0.4)
    
                if Disabled then
                    if MenuTable.Active then
                        MenuTable:Close()
                    end
                end
    
                if KeyPicker.Mode == "Toggle" and ParentObj.Type == "Toggle" and ParentObj.Disabled then
                    KeybindsToggle:SetVisibility(false)
                    return
                end
    
                local State = KeyPicker:GetState()
                local ShowToggle = Library.ShowToggleFrameInKeybinds and KeyPicker.Mode == "Toggle"
    
                if KeyPicker.SyncToggleState and ParentObj.Value ~= State then
                    ParentObj:SetValue(State)
                end
    
                if Info.NoUI then
                    return
                end
    
                if KeybindsToggle.Loaded then
                    if ShowToggle then
                        KeybindsToggle:SetNormal(false)
                    else
                        KeybindsToggle:SetNormal(true)
                    end
    
                    KeybindsToggle:SetText(("[%s] %s (%s)"):format(KeyPicker.DisplayValue, KeyPicker.Text, KeyPicker.Mode))
                    KeybindsToggle:SetVisibility(KeyPicker.MenuVisible ~= false)
                    KeybindsToggle:Display(State)
                end
            end
    
            function KeyPicker:GetState()
                if KeyPicker.Mode == "Always" then
                    return true
                elseif KeyPicker.Mode == "Hold" then
                    local Key = KeyPicker.Value
                    if Key == "None" then
                        return false
                    end
    
                    if not AreModifiersHeld(KeyPicker.Modifiers) then
                        return false
                    end
    
                    if Picking then
                        return false
                    end
    
                    if SpecialKeys[Key] ~= nil then
                        if Library.Toggled then
                            return false
                        end
    
                        return UserInputService:IsMouseButtonPressed(SpecialKeys[Key])
                            and not UserInputService:GetFocusedTextBox()
                    else
                        return UserInputService:IsKeyDown(Enum.KeyCode[Key] :: any) and not UserInputService:GetFocusedTextBox()
                    end
                else
                    return KeyPicker.Toggled
                end
            end
    
            function KeyPicker:OnChanged(Func)
                KeyPicker.Changed = Func
            end
    
            function KeyPicker:OnClick(Func)
                KeyPicker.Clicked = Func
            end
    
            function KeyPicker:DoClick()
                if Picking or ParentObj.Disabled then
                    return
                end
    
                if KeyPicker.Mode == "Press" then
                    if KeyPicker.Toggled and Info.WaitForCallback == true then
                        return
                    end
    
                    KeyPicker.Toggled = true
                end
    
                Library:SafeCallback(KeyPicker.Callback, KeyPicker.Toggled)
                Library:SafeCallback(KeyPicker.Clicked, KeyPicker.Toggled)
    
                if IsForButton then
                    Library:SafeCallback(ParentObj.Func, KeyPicker.Toggled)
                end
    
                if Library.ToggleKeybind == KeyPicker and Library.Toggle then
                    Library:Toggle()
                end
    
                if KeyPicker.Mode == "Press" then
                    KeyPicker.Toggled = false
                end
            end
    
            function KeyPicker:RunChanged(IsKeyValid, KeyCode)
                if ParentObj.Disabled then
                    return
                end
    
                if IsKeyValid == nil or KeyCode == nil then
                    IsKeyValid, KeyCode = pcall(function()
                        if KeyPicker.Value == "None" then
                            return nil
                        end
    
                        if SpecialKeys[KeyPicker.Value] == nil then
                            return Enum.KeyCode[KeyPicker.Value]
                        end
    
                        return SpecialKeys[KeyPicker.Value]
                    end)
                end
    
                local NewModifiers = ConvertToInputModifiers(KeyPicker.Modifiers)
                Library:SafeCallback(KeyPicker.ChangedCallback, KeyCode, NewModifiers)
                Library:SafeCallback(KeyPicker.Changed, KeyCode, NewModifiers)
            end
    
            function KeyPicker:SetValue(Data)
                local Key, Mode, Modifiers = Data[1], Data[2], Data[3]
    
                local IsKeyValid, KeyCode = pcall(function()
                    if Key == "None" then
                        Key = nil
                        return nil
                    end
    
                    if SpecialKeys[Key] == nil then
                        return Enum.KeyCode[Key]
                    end
    
                    return SpecialKeys[Key]
                end)
    
                if Key == nil then
                    KeyPicker.Value = "None"
                elseif IsKeyValid then
                    KeyPicker.Value = Key
                else
                    KeyPicker.Value = "Unknown"
                end
    
                KeyPicker.Modifiers =
                    VerifyModifiers(if typeof(Modifiers) == "table" then Modifiers else KeyPicker.Modifiers)
                KeyPicker.DisplayValue = if GetTableSize(KeyPicker.Modifiers) > 0
                    then (table.concat(KeyPicker.Modifiers, " + ") .. " + " .. KeyPicker.Value)
                    else KeyPicker.Value
    
                if ModeButtons[Mode] then
                    ModeButtons[Mode]:Select()
                end
    
                KeyPicker:Update()
                KeyPicker:RunChanged(IsKeyValid, KeyCode)
            end
    
            function KeyPicker:SetText(Text)
                KeybindsToggle:SetText(Text)
                KeyPicker:Update()
            end
    
            function KeyPicker:SetMenuVisibility(Visible: boolean)
                assert(typeof(Visible) == "boolean", "Visible must be a boolean")
    
                KeyPicker.MenuVisible = Visible
                KeyPicker:Update()
            end
    
            table.insert(KeyPicker.Connections, Picker.MouseButton1Click:Connect(function()
                if Picking or Library.IsPicking or ParentObj.Disabled then
                    return
                end
    
                SetPickingState(true)
    
                if IsForButton and SlideOverflow then
                    KeyPicker:Display("...")
                else
                    Picker.Text = "..."
                    Picker.Size = IsForButton and UDim2.new(0, 29, 1, 0) or UDim2.fromOffset(29, 18)
                end
    
                local ActiveModifiers = {}
                local CurrentInput = nil
    
                local IsValidInput = function(InputObj)
                    if InputObj.KeyCode == Enum.KeyCode.Escape then
                        return true
                    end
    
                    local IsMod = IsModifierInput(InputObj)
                    local KeyName
                    if SpecialKeysInput[InputObj.UserInputType] ~= nil then
                        KeyName = SpecialKeysInput[InputObj.UserInputType]
                    elseif InputObj.UserInputType == Enum.UserInputType.Keyboard then
                        if IsMod then
                            KeyName = ModifiersInput[InputObj.KeyCode]
                        else
                            KeyName = InputObj.KeyCode.Name
                        end
                    end
    
                    if KeyName then
                        if IsMod then
                            if KeyPicker.WhitelistedModifiers and #KeyPicker.WhitelistedModifiers > 0 and not table.find(KeyPicker.WhitelistedModifiers, KeyName) then
                                return false
                            end
    
                            if KeyPicker.BlacklistedModifiers and table.find(KeyPicker.BlacklistedModifiers, KeyName) then
                                return false
                            end
                        else
                            if KeyPicker.Whitelisted and #KeyPicker.Whitelisted > 0 and not table.find(KeyPicker.Whitelisted, KeyName) then
                                return false
                            end
    
                            if KeyPicker.Blacklisted and table.find(KeyPicker.Blacklisted, KeyName) then
                                return false
                            end
                        end
                    end
    
                    return true
                end
    
                while true do
                    local InputObj = UserInputService.InputBegan:Wait()
                    if UserInputService:GetFocusedTextBox() ~= nil then
                        SetPickingState(false)
                        return
                    end
    
                    if IsValidInput(InputObj) then
                        CurrentInput = InputObj
                        break
                    end
                end
    
                while IsModifierInput(CurrentInput) do
                    if CurrentInput.KeyCode == Enum.KeyCode.Escape then
                        break
                    end
    
                    local ModName = ModifiersInput[CurrentInput.KeyCode]
                    if ModName then
                        local text = if #ActiveModifiers > 0 then table.concat(ActiveModifiers, " + ") .. " + " .. ModName .. " + ..." else ModName .. " + ..."
                        KeyPicker:Display(text)
                    end
    
                    local NextInput = nil
                    local Released = false
    
                    local BeganConn
                    local EndedConn
    
                    BeganConn = UserInputService.InputBegan:Connect(function(InputObj)
                        if UserInputService:GetFocusedTextBox() ~= nil then
                            return
                        end
                        if IsValidInput(InputObj) then
                            NextInput = InputObj
                        end
                    end)
    
                    EndedConn = UserInputService.InputEnded:Connect(function(InputObj)
                        if InputObj.KeyCode == CurrentInput.KeyCode then
                            Released = true
                        end
                    end)
    
                    repeat
                        task.wait()
                    until Released or NextInput or UserInputService:GetFocusedTextBox() ~= nil or Library.Unloaded
    
                    if BeganConn then BeganConn:Disconnect() end
                    if EndedConn then EndedConn:Disconnect() end
    
                    if UserInputService:GetFocusedTextBox() ~= nil or Library.Unloaded then
                        SetPickingState(false)
                        return
                    end
    
                    if Released then
                        break
                    elseif NextInput then
                        local OldModName = ModifiersInput[CurrentInput.KeyCode]
                        if OldModName and not table.find(ActiveModifiers, OldModName) then
                            ActiveModifiers[#ActiveModifiers + 1] = OldModName
                        end
    
                        CurrentInput = NextInput
                        if CurrentInput.KeyCode == Enum.KeyCode.Escape then
                            break
                        end
                    end
                end
    
                local Key = "Unknown"
                if SpecialKeysInput[CurrentInput.UserInputType] ~= nil then
                    Key = SpecialKeysInput[CurrentInput.UserInputType]
                elseif CurrentInput.UserInputType == Enum.UserInputType.Keyboard then
                    Key = CurrentInput.KeyCode == Enum.KeyCode.Escape and "None" or CurrentInput.KeyCode.Name
                end
    
                ActiveModifiers = if CurrentInput.KeyCode == Enum.KeyCode.Escape or Key == "Unknown" then {} else ActiveModifiers
    
                KeyPicker.Toggled = if ParentObj.Type == "Toggle" then ParentObj.Value else false
                KeyPicker:SetValue({ Key, KeyPicker.Mode, ActiveModifiers })
    
                repeat
                    task.wait()
                until not IsInputDown(CurrentInput) or UserInputService:GetFocusedTextBox()
    
                SetPickingState(false)
            end))
    
            table.insert(KeyPicker.Connections, Picker.MouseButton2Click:Connect(function()
                if ParentObj.Disabled then
                    return
                end
    
                MenuTable:Toggle()
            end))
    
            table.insert(KeyPicker.Connections, UserInputService.InputBegan:Connect(function(Input: InputObject)
                if Library.Unloaded then
                    return
                end
    
                local IsMouse = IsMouseClickInput(Input)
                if
                    ParentObj.Disabled
                    or KeyPicker.Mode == "Always"
                    or KeyPicker.Value == "Unknown"
                    or KeyPicker.Value == "None"
                    or Picking
                    or Library.IsPicking
                    or UserInputService:GetFocusedTextBox()
                    or (IsMouse and Library.Toggled)
                then
                    return
                end
    
                local Key = KeyPicker.Value
                local HoldingModifiers = AreModifiersHeld(KeyPicker.Modifiers)
                local HoldingKey = false
    
                if
                    Key
                    and HoldingModifiers == true
                    and (
                        SpecialKeysInput[Input.UserInputType] == Key
                        or (Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Key)
                    )
                then
                    HoldingKey = true
                end
    
                if HoldingKey then
                    if KeyPicker.Mode == "Toggle" then
                        KeyPicker.Toggled = not KeyPicker.Toggled
                        KeyPicker:DoClick()
                    elseif KeyPicker.Mode == "Press" then
                        KeyPicker:DoClick()
                    elseif KeyPicker.Mode == "Hold" then
                        InputChanged = Input.Changed:Connect(function()
                            if KeyPicker:GetState() then
                                return
                            end
    
                            KeyPicker:Update()
                            if InputChanged and InputChanged.Connected then
                                InputChanged:Disconnect()
                                InputChanged = nil
                            end
                        end)
                    end
    
                    KeyPicker:Update()
                end
            end))
    
            KeyPicker:Update()
    
            if not ParentObj.Addons then
                ParentObj.Addons = {}
            end
    
            table.insert(ParentObj.Addons, KeyPicker)
    
            KeyPicker.Default = KeyPicker.Value
            KeyPicker.DefaultModifiers = table.clone(KeyPicker.Modifiers or {})
    
            function KeyPicker:Destroy()
                KeyPicker.Destroyed = true
    
                if SlideForwardConn then
                    SlideForwardConn:Disconnect()
                    SlideForwardConn = nil
                end
    
                if SlideBackConn then
                    SlideBackConn:Disconnect()
                    SlideBackConn = nil
                end
    
                if KeyPicker.Connections then
                    for _, Connection in KeyPicker.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if KeybindsToggle and KeybindsToggle.Loaded then
                    if KeybindsToggle.Holder then
                        KeybindsToggle.Holder:Destroy()
                    end
                    local KTIdx = table.find(Library.KeybindToggles, KeybindsToggle)
                    if KTIdx then
                        table.remove(Library.KeybindToggles, KTIdx)
                    end
                end
    
                if MenuTable then
                    MenuTable:Destroy()
                end
    
                if IsForButton and SlideOverflow then
                    if SlideForwardTween then
                        SlideForwardTween:Destroy()
                    end
    
                    if SlideBackTween then
                        SlideBackTween:Destroy()
                    end
                end
    
                if Picker then
                    Picker:Destroy()
                end
    
                if ParentObj and ParentObj.Addons then
                    local AddonIdx = table.find(ParentObj.Addons, KeyPicker)
    
                    if AddonIdx then
                        table.remove(ParentObj.Addons, AddonIdx)
                    end
                end
    
                Options[Idx] = nil
            end
    
            Options[Idx] = KeyPicker
    
            return self
        end
    
        local HueSequenceTable = {}
        for Hue = 0, 1, 0.1 do
            table.insert(HueSequenceTable, ColorSequenceKeypoint.new(Hue, Color3.fromHSV(Hue, 1, 1)))
        end
        function Funcs:AddColorPicker(Idx, Info)
            if self.Destroyed then return nil end
    
            Info = Library:Validate(Info, Templates.ColorPicker)
    
            local ParentObj = self
            local ToggleLabel = ParentObj.TextLabel
    
            local ColorPicker = {
                Connections = {},
                Destroyed = false,
    
                Value = Info.Default,
    
                Transparency = Info.Transparency or 0,
                Title = Info.Title,
    
                Callback = Info.Callback,
                Changed = Info.Changed,
    
                Type = "ColorPicker",
            }
            ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = ColorPicker.Value:ToHSV()
    
            local Holder = New("TextButton", {
                BackgroundColor3 = ColorPicker.Value,
                Size = UDim2.fromOffset(18, 18),
                Text = "",
                Parent = ToggleLabel,
            })
    
            local HolderStroke = New("UIStroke", {
                Color = Library:GetDarkerColor(ColorPicker.Value),
                Parent = Holder,
            })
    
            local ColorPickerCorner = New("UICorner", {
                TopLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                TopRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = Holder,
            }); table.insert(Library.SpecificCorners, ColorPickerCorner)
    
            local HolderTransparency = New("ImageLabel", {
                Image = CustomImageManager.GetAsset("TransparencyTexture"),
                ImageTransparency = (1 - ColorPicker.Transparency),
                ScaleType = Enum.ScaleType.Tile,
                Position = UDim2.new(0, -1, 0, -1),
                Size = UDim2.new(1, 2, 1, 2),
                TileSize = UDim2.fromOffset(9, 9),
                Parent = Holder,
            })
    
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = HolderTransparency,
                })
            )
    
            local MapSize = Library.IsMobile and 140 or 200
            local BarWidth = 16
            local MenuWidth = MapSize + BarWidth + 6 + 12
            if Info.Transparency then
                MenuWidth += BarWidth + 6
            end
    
            local ColorMenu
            local FooterCorner
            ColorMenu = Library:AddContextMenu(
                Holder,
                UDim2.fromOffset(MenuWidth, 0),
                function()
                    return { 0.5, Holder.AbsoluteSize.Y + 1.5 }
                end,
                1, function(Active: boolean)
                    local Half = UDim.new(0, Library.CornerRadius / 2)
                    local Zero = UDim.new(0, 0)
    
                    ColorPickerCorner.TopLeftRadius = Half
                    ColorPickerCorner.TopRightRadius = Half
                    ColorPickerCorner.BottomRightRadius = Active and Zero or Half
                    ColorPickerCorner.BottomLeftRadius = Active and Zero or Half
    
                    local MenuCorner = ColorMenu and ColorMenu.Corner
                    if MenuCorner then
                        MenuCorner.TopLeftRadius = Zero
                        MenuCorner.TopRightRadius = Half
                        MenuCorner.BottomRightRadius = Half
                        MenuCorner.BottomLeftRadius = Half
                    end
    
                    if FooterCorner then
                        FooterCorner.TopLeftRadius = Zero
                        FooterCorner.TopRightRadius = Zero
                        FooterCorner.BottomLeftRadius = Half
                        FooterCorner.BottomRightRadius = Half
                    end
                end, false, "no_top_left")
            ColorMenu.List.Padding = UDim.new(0, 0)
            ColorPicker.ColorMenu = ColorMenu
    
            local ContentHolder = New("Frame", {
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 0),
                Parent = ColorMenu.Menu,
            })
            New("UIListLayout", {
                Padding = UDim.new(0, 8),
                Parent = ContentHolder,
            })
            New("UIPadding", {
                PaddingBottom = UDim.new(0, 6),
                PaddingLeft = UDim.new(0, 6),
                PaddingRight = UDim.new(0, 6),
                PaddingTop = UDim.new(0, 6),
                Parent = ContentHolder,
            })
    
            local FooterHeight = Library.IsMobile and 30 or 22
    
            local FooterBackground = New("Frame", {
                BackgroundColor3 = function()
                    return Library:GetBetterColor(Library.Scheme.BackgroundColor, 4)
                end,
                Size = UDim2.new(1, 0, 0, FooterHeight),
                Parent = ColorMenu.Menu,
            })
            FooterCorner = New("UICorner", {
                TopLeftRadius = UDim.new(0, 0),
                TopRightRadius = UDim.new(0, 0),
                BottomLeftRadius = UDim.new(0, Library.CornerRadius / 2),
                BottomRightRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = FooterBackground,
            })
            table.insert(Library.SpecificCorners, FooterCorner)
            Library:MakeLine(FooterBackground, {
                Position = UDim2.fromScale(0, 0),
                Size = UDim2.new(1, 0, 0, 1),
            })
    
            local FooterBar = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Parent = FooterBackground,
            })
            New("UIPadding", {
                PaddingLeft = UDim.new(0, 6),
                PaddingRight = UDim.new(0, Info.Resizable and (FooterHeight + 4) or 6),
                Parent = FooterBar,
            })
    
            local FooterInfoLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextSize = 14,
                TextTransparency = 0.5,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Center,
                Parent = FooterBar,
            })
    
            local function RefreshFooterInfo()
                FooterInfoLabel.Text = string.format(
                    "#%s • %d, %d, %d",
                    ColorPicker.Value:ToHex(),
                    math.floor(ColorPicker.Value.R * 255),
                    math.floor(ColorPicker.Value.G * 255),
                    math.floor(ColorPicker.Value.B * 255)
                )
            end
            RefreshFooterInfo()
    
            if typeof(ColorPicker.Title) == "string" then
                New("TextLabel", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, 8),
                    Text = ColorPicker.Title,
                    TextSize = 14,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Parent = ContentHolder,
                })
            end
    
            local ColorHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, MapSize),
                Parent = ContentHolder,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                Padding = UDim.new(0, 6),
                Parent = ColorHolder,
            })
    
            local SatVipMap = New("ImageButton", {
                BackgroundColor3 = ColorPicker.Value,
                Image = CustomImageManager.GetAsset("SaturationMap"),
                Size = UDim2.fromOffset(MapSize, MapSize),
                Parent = ColorHolder,
            })
    
            local SatVibCursor = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Size = UDim2.fromOffset(6, 6),
                Parent = SatVipMap,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = SatVibCursor,
            })
            New("UIStroke", {
                Color = "DarkColor",
                Parent = SatVibCursor,
            })
    
            local HueSelector = New("TextButton", {
                Size = UDim2.fromOffset(BarWidth, MapSize),
                Text = "",
                Parent = ColorHolder,
            })
            New("UIGradient", {
                Color = ColorSequence.new(HueSequenceTable),
                Rotation = 90,
                Parent = HueSelector,
            })
    
            local HueCursor = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                BorderColor3 = "DarkColor",
                BorderSizePixel = 1,
                Position = UDim2.fromScale(0.5, ColorPicker.Hue),
                Size = UDim2.new(1, 2, 0, 1),
                Parent = HueSelector,
            })
    
            local TransparencySelector, TransparencyColor, TransparencyCursor
            if Info.Transparency then
                TransparencySelector = New("ImageButton", {
                    Image = CustomImageManager.GetAsset("TransparencyTexture"),
                    ScaleType = Enum.ScaleType.Tile,
                    Size = UDim2.fromOffset(BarWidth, MapSize),
                    TileSize = UDim2.fromOffset(8, 8),
                    Parent = ColorHolder,
                })
    
                TransparencyColor = New("Frame", {
                    BackgroundColor3 = ColorPicker.Value,
                    Size = UDim2.fromScale(1, 1),
                    Parent = TransparencySelector,
                })
                New("UIGradient", {
                    Rotation = 90,
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 0),
                        NumberSequenceKeypoint.new(1, 1),
                    }),
                    Parent = TransparencyColor,
                })
    
                TransparencyCursor = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = "WhiteColor",
                    BorderColor3 = "DarkColor",
                    BorderSizePixel = 1,
                    Position = UDim2.fromScale(0.5, ColorPicker.Transparency),
                    Size = UDim2.new(1, 2, 0, 1),
                    Parent = TransparencySelector,
                })
            end
    
            local ResizeGrabber
            if Info.Resizable then
                local BaseMapSize = 200
                local BaseBarWidth = BarWidth
                local BasePadding = 6
                local MinMapSize = 140
    
                ColorPicker.MapWidth = MapSize
                ColorPicker.MapHeight = MapSize
    
                local function GetBarWidth(MapWidth)
                    return math.clamp(math.floor((MapWidth / BaseMapSize) * BaseBarWidth + 0.5), 12, 24)
                end
    
                local function GetContentWidth(MapWidth)
                    local CurrentBarWidth = GetBarWidth(MapWidth)
                    local Width = MapWidth + CurrentBarWidth + BasePadding
                    if Info.Transparency then
                        Width += (CurrentBarWidth + BasePadding)
                    end
    
                    return Width + 12
                end
    
                local FixedVerticalOverhead = 6 + 6 + 8 + 20 + 8 + 20 + FooterHeight
                if typeof(ColorPicker.Title) == "string" then
                    FixedVerticalOverhead += 8 + 8
                end
    
                local function ClampToViewport(NewWidth, NewHeight)
                    local Camera = workspace.CurrentCamera
                    if not Camera then
                        return NewWidth, NewHeight
                    end
    
                    local ViewportSize = Camera.ViewportSize
                    local ScreenMargin = 12
    
                    local MaxWidth = ViewportSize.X - ColorMenu.Menu.AbsolutePosition.X - ScreenMargin
                    local MaxHeight = ViewportSize.Y - ColorMenu.Menu.AbsolutePosition.Y - ScreenMargin - FixedVerticalOverhead
    
                    while NewWidth > MinMapSize and GetContentWidth(NewWidth) > MaxWidth do
                        NewWidth -= 4
                    end
    
                    if NewHeight > MaxHeight then
                        NewHeight = math.max(MinMapSize, math.floor(MaxHeight))
                    end
    
                    return NewWidth, NewHeight
                end
    
                local function UpdateColorMenuSize(NewWidth, NewHeight)
                    NewWidth = math.max(MinMapSize, math.floor(NewWidth + 0.5))
                    NewHeight = math.max(MinMapSize, math.floor(NewHeight + 0.5))
                    NewWidth, NewHeight = ClampToViewport(NewWidth, NewHeight)
    
                    if NewWidth == ColorPicker.MapWidth and NewHeight == ColorPicker.MapHeight then
                        return
                    end
    
                    local CurrentBarWidth = GetBarWidth(NewWidth)
                    local CursorSize = math.clamp(math.floor((math.min(NewWidth, NewHeight) / BaseMapSize) * 6 + 0.5), 4, 10)
    
                    ColorHolder.Size = UDim2.new(1, 0, 0, NewHeight)
                    SatVipMap.Size = UDim2.fromOffset(NewWidth, NewHeight)
                    SatVibCursor.Size = UDim2.fromOffset(CursorSize, CursorSize)
                    HueSelector.Size = UDim2.new(0, CurrentBarWidth, 0, NewHeight)
    
                    if TransparencySelector then
                        TransparencySelector.Size = UDim2.new(0, CurrentBarWidth, 0, NewHeight)
                    end
    
                    ColorPicker.MapWidth = NewWidth
                    ColorPicker.MapHeight = NewHeight
                    ColorMenu:SetSize(UDim2.new(0, GetContentWidth(NewWidth), 0, 0))
                end
    
                ResizeGrabber = New("TextButton", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(1, -Library.CornerRadius / 4, 0, 0),
                    Size = UDim2.fromScale(1, 1),
                    SizeConstraint = Enum.SizeConstraint.RelativeYY,
                    Text = "",
                    Parent = FooterBackground,
                })
                local ResizeGrabberIcon = New("ImageLabel", {
                    ImageColor3 = "FontColor",
                    ImageTransparency = 0.5,
                    Position = UDim2.fromOffset(2, 2),
                    Size = UDim2.new(1, -4, 1, -4),
                    Parent = ResizeGrabber,
                })
                if ResizeIcon then
                    Library:ApplyLucideIcon(ResizeGrabberIcon, ResizeIcon)
                end
    
                table.insert(ColorPicker.Connections, ResizeGrabber.InputBegan:Connect(function(Input: InputObject)
                    Library.CantDragForced = true
                    local StartMouse = Vector2.new(Mouse.X, Mouse.Y)
                    local StartWidth = ColorPicker.MapWidth
                    local StartHeight = ColorPicker.MapHeight
    
                    while IsDragInput(Input) and not ColorPicker.Destroyed do
                        local Delta = Vector2.new(Mouse.X, Mouse.Y) - StartMouse
                        UpdateColorMenuSize(StartWidth + Delta.X, StartHeight + Delta.Y)
    
                        RunService.RenderStepped:Wait()
                    end
    
                    Library.CantDragForced = false
                end))
            end
    
            local InfoHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 20),
                Parent = ContentHolder,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalFlex = Enum.UIFlexAlignment.Fill,
                Padding = UDim.new(0, 8),
                Parent = InfoHolder,
            })
    
            local HueBox = New("TextBox", {
                BackgroundColor3 = "MainColor",
                ClearTextOnFocus = false,
                Size = UDim2.fromScale(1, 1),
                Text = "#??????",
                TextSize = 14,
                Parent = InfoHolder,
            })
    
            local HueBoxStroke = New("UIStroke", {
                Color = "OutlineColor",
                Parent = HueBox,
            })
    
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = HueBox,
                })
            )
    
            local RgbBox = New("TextBox", {
                BackgroundColor3 = "MainColor",
                ClearTextOnFocus = false,
                Size = UDim2.fromScale(1, 1),
                Text = "?, ?, ?",
                TextSize = 14,
                Parent = InfoHolder,
            })
    
            local RgbBoxStroke = New("UIStroke", {
                Color = "OutlineColor",
                Parent = RgbBox,
            })
    
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = RgbBox,
                })
            )
    
            local ContextMenu
            ContextMenu = Library:AddContextMenu(Holder, UDim2.fromOffset(93, 0), function()
                return { Holder.AbsoluteSize.X + 1.5, 0.5 }
            end, 1, function(Active: boolean)
                local Half = UDim.new(0, Library.CornerRadius / 2)
                local Zero = UDim.new(0, 0)
    
                ColorPickerCorner.TopLeftRadius = Half
                ColorPickerCorner.BottomLeftRadius = Half
                ColorPickerCorner.TopRightRadius = Active and Zero or Half
                ColorPickerCorner.BottomRightRadius = Active and Zero or Half
    
                local MenuCorner = ContextMenu and ContextMenu.Corner
                if MenuCorner then
                    MenuCorner.TopLeftRadius = Zero
                    MenuCorner.TopRightRadius = Half
                    MenuCorner.BottomRightRadius = Half
                    MenuCorner.BottomLeftRadius = Half
                end
            end, false, "no_top_left")
            ColorPicker.ContextMenu = ContextMenu
            ContextMenu.List.Padding = UDim.new(0, 6)
            do
                local function CreateButton(Text, Func)
                    local Button = New("TextButton", {
                        BackgroundColor3 = "MainColor",
                        BackgroundTransparency = 1,
                        Size = UDim2.new(1, 0, 0, 21),
                        Text = Text,
                        TextSize = 14,
                        Parent = ContextMenu.Menu,
                    })
    
                    table.insert(ColorPicker.Connections, Button.MouseButton1Click:Connect(function()
                        Library:SafeCallback(Func)
                        ContextMenu:Close()
                    end))
    
                    table.insert(ColorPicker.Connections, Button.MouseEnter:Connect(function()
                        TweenService:Create(Button, Library.TweenInfo, {
                            BackgroundTransparency = 0.7,
                        }):Play()
                    end))
    
                    table.insert(ColorPicker.Connections, Button.MouseLeave:Connect(function()
                        TweenService:Create(Button, Library.TweenInfo, {
                            BackgroundTransparency = 1,
                        }):Play()
                    end))
                end
    
                CreateButton("Copy color", function()
                    Library.CopiedColor = { ColorPicker.Value, ColorPicker.Transparency }
                end)
    
                ColorPicker.SetValueRGB = function(...) end
                CreateButton("Paste color", function()
                    if not Library.CopiedColor then
                        return
                    end
    
                    ColorPicker:SetValueRGB(Library.CopiedColor[1], Library.CopiedColor[2])
                end)
    
                if setclipboard then
                    CreateButton("Copy Hex", function()
                        setclipboard(tostring(ColorPicker.Value:ToHex()))
                    end)
    
                    CreateButton("Copy RGB", function()
                        setclipboard(table.concat({
                            math.floor(ColorPicker.Value.R * 255),
                            math.floor(ColorPicker.Value.G * 255),
                            math.floor(ColorPicker.Value.B * 255),
                        }, ", "))
                    end)
                end
            end
    
            local ActionHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 20),
                Parent = ContentHolder,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalFlex = Enum.UIFlexAlignment.Fill,
                Padding = UDim.new(0, 8),
                Parent = ActionHolder,
            })
    
            local CopyColorButton = New("TextButton", {
                BackgroundColor3 = "MainColor",
                Size = UDim2.fromScale(1, 1),
                Text = "Copy color",
                TextSize = 14,
                Parent = ActionHolder,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Parent = CopyColorButton,
            })
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = CopyColorButton,
                })
            )
    
            local PasteColorButton = New("TextButton", {
                BackgroundColor3 = "MainColor",
                Size = UDim2.fromScale(1, 1),
                Text = "Paste color",
                TextSize = 14,
                Parent = ActionHolder,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Parent = PasteColorButton,
            })
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = PasteColorButton,
                })
            )
    
            local CopyColorOriginalText = CopyColorButton.Text
            local PasteColorOriginalText = PasteColorButton.Text
            local CopyColorResetId = 0
            local PasteColorResetId = 0
    
            table.insert(ColorPicker.Connections, CopyColorButton.MouseEnter:Connect(function()
                TweenService:Create(CopyColorButton, Library.TweenInfo, {
                    BackgroundColor3 = Library:GetBetterColor(Library.Scheme.MainColor, 10),
                }):Play()
            end))
    
            table.insert(ColorPicker.Connections, CopyColorButton.MouseLeave:Connect(function()
                TweenService:Create(CopyColorButton, Library.TweenInfo, {
                    BackgroundColor3 = Library.Scheme.MainColor,
                }):Play()
            end))
    
            table.insert(ColorPicker.Connections, PasteColorButton.MouseEnter:Connect(function()
                TweenService:Create(PasteColorButton, Library.TweenInfo, {
                    BackgroundColor3 = Library:GetBetterColor(Library.Scheme.MainColor, 10),
                }):Play()
            end))
    
            table.insert(ColorPicker.Connections, PasteColorButton.MouseLeave:Connect(function()
                TweenService:Create(PasteColorButton, Library.TweenInfo, {
                    BackgroundColor3 = Library.Scheme.MainColor,
                }):Play()
            end))
    
            table.insert(ColorPicker.Connections, CopyColorButton.MouseButton1Click:Connect(function()
                Library.CopiedColor = { ColorPicker.Value, ColorPicker.Transparency }
    
                CopyColorResetId += 1
                local ThisResetId = CopyColorResetId
                CopyColorButton.Text = "Copied color"
    
                task.delay(1, function()
                    if ColorPicker.Destroyed or ThisResetId ~= CopyColorResetId then
                        return
                    end
    
                    CopyColorButton.Text = CopyColorOriginalText
                end)
            end))
    
            table.insert(ColorPicker.Connections, PasteColorButton.MouseButton1Click:Connect(function()
                PasteColorResetId += 1
                local ThisResetId = PasteColorResetId
    
                if not Library.CopiedColor then
                    PasteColorButton.Text = "Nothing to paste"
                else
                    ColorPicker:SetValueRGB(Library.CopiedColor[1], Library.CopiedColor[2])
                    PasteColorButton.Text = "Pasted color"
                end
    
                task.delay(1, function()
                    if ColorPicker.Destroyed or ThisResetId ~= PasteColorResetId then
                        return
                    end
    
                    PasteColorButton.Text = PasteColorOriginalText
                end)
            end))
    
            function ColorPicker:SetHSVFromRGB(Color)
                ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color:ToHSV()
            end
    
            function ColorPicker:Display()
                if Library.Unloaded then
                    return
                end
    
                ColorPicker.Value = Color3.fromHSV(ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib)
    
                SatVipMap.BackgroundColor3 = Color3.fromHSV(ColorPicker.Hue, 1, 1)
                if TransparencyColor then
                    TransparencyColor.BackgroundColor3 = ColorPicker.Value
                end
    
                SatVibCursor.Position = UDim2.fromScale(ColorPicker.Sat, 1 - ColorPicker.Vib)
                HueCursor.Position = UDim2.fromScale(0.5, ColorPicker.Hue)
                if TransparencyCursor then
                    TransparencyCursor.Position = UDim2.fromScale(0.5, ColorPicker.Transparency)
                end
    
                HueBox.Text = "#" .. ColorPicker.Value:ToHex()
                RgbBox.Text = table.concat({
                    math.floor(ColorPicker.Value.R * 255),
                    math.floor(ColorPicker.Value.G * 255),
                    math.floor(ColorPicker.Value.B * 255),
                }, ", ")
    
                RefreshFooterInfo()
            end
    
            local function ApplyHolderVisual(Disabled: boolean)
                Holder.Active = not Disabled
                HolderStroke.Transparency = Disabled and 0.5 or 0
                Holder.BackgroundTransparency = Disabled and 0.5 or 0
    
                if Disabled then
                    Holder.BackgroundColor3 = ColorPicker.Value:Lerp(Library.Scheme.BackgroundColor, 0.5)
                    HolderTransparency.ImageTransparency = math.clamp((1 - ColorPicker.Transparency) + 0.5, 0, 1)
                else
                    Holder.BackgroundColor3 = ColorPicker.Value
                    HolderStroke.Color = Library:GetDarkerColor(ColorPicker.Value)
                    HolderTransparency.ImageTransparency = (1 - ColorPicker.Transparency)
                end
            end
    
            function ColorPicker:RunChanged()
                if ParentObj.Disabled then
                    return
                end
    
                Library:SafeCallback(ColorPicker.Callback, ColorPicker.Value)
                Library:SafeCallback(ColorPicker.Changed, ColorPicker.Value)
            end
    
            function ColorPicker:Update()
                ColorPicker:Display()
    
                local Disabled = ParentObj.Disabled == true
                ApplyHolderVisual(Disabled)
    
                if Disabled then
                    if ColorMenu.Active then
                        ColorMenu:Close()
                    end
    
                    if ContextMenu.Active then
                        ContextMenu:Close()
                    end
                end
    
                ColorPicker:RunChanged()
            end
    
            function ColorPicker:OnChanged(Func)
                ColorPicker.Changed = Func
            end
    
            function ColorPicker:SetValue(HSV, Transparency)
                if typeof(HSV) == "Color3" then
                    ColorPicker:SetValueRGB(HSV, Transparency)
                    return
                end
    
                local Color = Color3.fromHSV(HSV[1], HSV[2], HSV[3])
                ColorPicker.Transparency = Info.Transparency and Transparency or 0
                ColorPicker:SetHSVFromRGB(Color)
                ColorPicker:Update()
            end
    
            function ColorPicker:SetValueRGB(Color, Transparency)
                ColorPicker.Transparency = Info.Transparency and Transparency or 0
                ColorPicker:SetHSVFromRGB(Color)
                ColorPicker:Update()
            end
    
            table.insert(ColorPicker.Connections, Holder.MouseButton1Click:Connect(function()
                if ParentObj.Disabled then
                    return
                end
    
                ColorMenu:Toggle()
            end))
    
            table.insert(ColorPicker.Connections, Holder.MouseButton2Click:Connect(function()
                if ParentObj.Disabled then
                    return
                end
    
                ContextMenu:Toggle()
            end))
    
            table.insert(ColorPicker.Connections, SatVipMap.InputBegan:Connect(function(Input: InputObject)
                while IsDragInput(Input) and not ColorPicker.Destroyed do
                    local MinX = SatVipMap.AbsolutePosition.X
                    local MaxX = MinX + SatVipMap.AbsoluteSize.X
                    local LocationX = math.clamp(Mouse.X, MinX, MaxX)
    
                    local MinY = SatVipMap.AbsolutePosition.Y
                    local MaxY = MinY + SatVipMap.AbsoluteSize.Y
                    local LocationY = math.clamp(Mouse.Y, MinY, MaxY)
    
                    local OldSat = ColorPicker.Sat
                    local OldVib = ColorPicker.Vib
                    ColorPicker.Sat = (LocationX - MinX) / (MaxX - MinX)
                    ColorPicker.Vib = 1 - ((LocationY - MinY) / (MaxY - MinY))
    
                    if ColorPicker.Sat ~= OldSat or ColorPicker.Vib ~= OldVib then
                        ColorPicker:Update()
                    end
    
                    RunService.RenderStepped:Wait()
                end
            end))
    
            table.insert(ColorPicker.Connections, HueSelector.InputBegan:Connect(function(Input: InputObject)
                while IsDragInput(Input) and not ColorPicker.Destroyed do
                    local Min = HueSelector.AbsolutePosition.Y
                    local Max = Min + HueSelector.AbsoluteSize.Y
                    local Location = math.clamp(Mouse.Y, Min, Max)
    
                    local OldHue = ColorPicker.Hue
                    ColorPicker.Hue = (Location - Min) / (Max - Min)
    
                    if ColorPicker.Hue ~= OldHue then
                        ColorPicker:Update()
                    end
    
                    RunService.RenderStepped:Wait()
                end
            end))
    
            if TransparencySelector then
                table.insert(ColorPicker.Connections, TransparencySelector.InputBegan:Connect(function(Input: InputObject)
                    while IsDragInput(Input) and not ColorPicker.Destroyed do
                        local Min = TransparencySelector.AbsolutePosition.Y
                        local Max = TransparencySelector.AbsolutePosition.Y + TransparencySelector.AbsoluteSize.Y
                        local Location = math.clamp(Mouse.Y, Min, Max)
    
                        local OldTransparency = ColorPicker.Transparency
                        ColorPicker.Transparency = (Location - Min) / (Max - Min)
    
                        if ColorPicker.Transparency ~= OldTransparency then
                            ColorPicker:Update()
                        end
    
                        RunService.RenderStepped:Wait()
                    end
                end))
            end
    
            table.insert(ColorPicker.Connections, HueBox.FocusLost:Connect(function(Enter)
                if not Enter then
                    return
                end
    
                local Success, Color = pcall(Color3.fromHex, HueBox.Text)
                if Success and typeof(Color) == "Color3" then
                    ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color:ToHSV()
                end
    
                ColorPicker:Update()
            end))
    
            table.insert(ColorPicker.Connections, RgbBox.FocusLost:Connect(function(Enter)
                if not Enter then
                    return
                end
    
                local R, G, B = RgbBox.Text:match("(%d+),%s*(%d+),%s*(%d+)")
                if R and G and B then
                    ColorPicker:SetHSVFromRGB(Color3.fromRGB(R, G, B))
                end
    
                ColorPicker:Update()
            end))
    
            for _, BoxPair in {
                { HueBox, HueBoxStroke },
                { RgbBox, RgbBoxStroke }
            } do
                local TextBoxInstance, Stroke = BoxPair[1], BoxPair[2]
    
                table.insert(ColorPicker.Connections, TextBoxInstance.Focused:Connect(function()
                    Library.Registry[Stroke].Color = "AccentColor"
                    TweenService:Create(Stroke, Library.TweenInfo, {
                        Color = Library.Scheme.AccentColor,
                    }):Play()
                end))
    
                table.insert(ColorPicker.Connections, TextBoxInstance.FocusLost:Connect(function()
                    Library.Registry[Stroke].Color = "OutlineColor"
                    TweenService:Create(Stroke, Library.TweenInfo, {
                        Color = Library.Scheme.OutlineColor,
                    }):Play()
                end))
            end
    
            ColorPicker:Update()
    
            if not ParentObj.Addons then
                ParentObj.Addons = {}
            end
    
            table.insert(ParentObj.Addons, ColorPicker)
    
            ColorPicker.Default = ColorPicker.Value
    
            function ColorPicker:Destroy()
                ColorPicker.Destroyed = true
    
                if ColorPicker.Connections then
                    for _, Connection in ColorPicker.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if ColorMenu then
                    ColorMenu:Destroy()
                end
    
                if ResizeGrabber then
                    ResizeGrabber:Destroy()
                end
    
                if ContextMenu then
                    ContextMenu:Destroy()
                end
    
                if Holder then
                    Holder:Destroy()
                end
    
                if ParentObj and ParentObj.Addons then
                    local AddonIdx = table.find(ParentObj.Addons, ColorPicker)
    
                    if AddonIdx then
                        table.remove(ParentObj.Addons, AddonIdx)
                    end
                end
    
                Options[Idx] = nil
            end
    
            Options[Idx] = ColorPicker
    
            return self
        end
    
        BaseAddons.__index = Funcs
        BaseAddons.__namecall = function(_, Key, ...)
            return Funcs[Key](...)
        end
    end
    
    local BaseGroupbox = {}
    do
        local Funcs = {}
    
        function Funcs:AddDivider(...)
            if self.Destroyed then return nil end
    
            local Params = select(1, ...)
            local Text
            local MarginTop = 0
            local MarginBottom = 0
    
            if typeof(Params) == "table" then
                Text = Params.Text
                MarginTop = Params.MarginTop or Params.Margin or 0
                MarginBottom = Params.MarginBottom or Params.Margin or 0
            elseif typeof(Params) == "string" then
                Text = Params
            end
    
            local Groupbox = self
            local Container = Groupbox.Container
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, (if Text then 16 else 9) + MarginTop + MarginBottom),
                Parent = Container,
            })
    
            local InnerHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 1, 0),
                Parent = Holder,
            })
    
            New("UIPadding", {
                PaddingTop = UDim.new(0, MarginTop),
                PaddingBottom = UDim.new(0, MarginBottom),
                Parent = Holder,
            })
    
            if Text then
                local TextLabel = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = GetMediumFont,
                    Size = UDim2.fromScale(1, 1),
                    Text = string.upper(Text),
                    TextColor3 = "AccentColor",
                    TextSize = 11,
                    TextTransparency = 0.15,
                    TextXAlignment = Enum.TextXAlignment.Center,
                    Parent = InnerHolder,
                })
    
                local X, _ = Library:GetTextBounds(TextLabel.Text, GetMediumFont(), 11, 1000)
                local SizeX = X // 2 + 10
    
                for Side = 0, 1 do
                    local Line = New("Frame", {
                        AnchorPoint = Vector2.new(Side, 0.5),
                        BackgroundColor3 = "OutlineColor",
                        BorderSizePixel = 0,
                        Position = UDim2.fromScale(Side, 0.5),
                        Size = UDim2.new(0.5, -SizeX, 0, 1),
                        Parent = InnerHolder,
                    })
                    New("UIGradient", {
                        Transparency = NumberSequence.new(if Side == 0 then 1 else 0, if Side == 0 then 0 else 1),
                        Parent = Line,
                    })
                end
            else
                local Line = New("Frame", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundColor3 = "OutlineColor",
                    BorderSizePixel = 0,
                    Position = UDim2.fromScale(0, 0.5),
                    Size = UDim2.new(1, 0, 0, 1),
                    Parent = InnerHolder,
                })
                New("UIGradient", {
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.2, 0.1),
                        NumberSequenceKeypoint.new(0.8, 0.1),
                        NumberSequenceKeypoint.new(1, 1),
                    }),
                    Parent = Line,
                })
            end
    
            Groupbox:Resize()
    
            local Divider = {
                Connections = {},
                Destroyed = false,
    
                Holder = Holder,
                Text = Text,
                MarginTop = MarginTop,
                MarginBottom = MarginBottom,
                Type = "Divider",
    
                Parent = Groupbox,
            }
    
            function Divider:SetVisible(Value)
                Holder.Visible = Value == true
                Groupbox:Resize()
            end
    
            function Divider:Destroy()
                Divider.Destroyed = true
    
                if Divider.Connections then
                    for _, Connection in Divider.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if Holder then
                    Holder:Destroy()
                end
    
                local ElemIdx = table.find(Groupbox.Elements, Divider)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
    
                Groupbox:Resize()
            end
    
            table.insert(Groupbox.Elements, Divider)
            return Divider
        end
    
        function Funcs:AddLabel(...)
            if self.Destroyed then return nil end
    
            local Data = {}
            local Addons = {}
    
            local First = select(1, ...)
            local Second = select(2, ...)
    
            if typeof(First) == "table" or typeof(Second) == "table" then
                local Params = typeof(First) == "table" and First or Second
    
                Data.Text = Params.Text or ""
                Data.DoesWrap = Params.DoesWrap or false
                Data.Size = Params.Size or 14
                Data.Visible = if typeof(Params.Visible) == "boolean" then Params.Visible else true
                Data.Idx = typeof(Second) == "table" and First or nil
            else
                Data.Text = First or ""
                Data.DoesWrap = Second or false
                Data.Size = 14
                Data.Visible = true
                Data.Idx = select(3, ...) or nil
            end
    
            local Groupbox = self
            local Container = Groupbox.Container
    
            local Label = {
                Connections = {},
                Destroyed = false,
    
                Text = Data.Text,
                DoesWrap = Data.DoesWrap,
    
                Addons = Addons,
    
                Visible = Data.Visible,
                Type = "Label",
    
                Parent = Groupbox,
            }
    
            local TextLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 18),
                Text = Label.Text,
                TextSize = Data.Size,
                TextWrapped = Label.DoesWrap,
                TextXAlignment = Groupbox.IsKeyTab and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
                Visible = Label.Visible,
                Parent = Container,
            })
    
            function Label:Display()
                if not Label.DoesWrap then
                    return
                end
    
                local Width = TextLabel.AbsoluteSize.X / Library.DPIScale
                if Width <= 0 then return end
    
                local _, Y = Library:GetTextBounds(Label.Text, TextLabel.FontFace, TextLabel.TextSize, Width)
                TextLabel.Size = UDim2.new(1, 0, 0, Y + 4)
            end
    
            function Label:SetVisible(Visible: boolean)
                Label.Visible = Visible
    
                TextLabel.Visible = Label.Visible
                Groupbox:Resize()
                Library:QueueSearchRefresh()
            end
    
            function Label:SetText(Text: string)
                if Label.Text == Text and TextLabel.Text == Text then
                    return
                end
                Label.Text = Text
                TextLabel.Text = Text
    
                pcall(Label.Display, Label)
                pcall(Groupbox.Resize, Groupbox)
            end
    
            if Label.DoesWrap then
                Label:Display()
    
                local Last = TextLabel.AbsoluteSize
                table.insert(Label.Connections, TextLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                    if TextLabel.AbsoluteSize == Last then
                        return
                    end
    
                    Label:Display()
                    Last = TextLabel.AbsoluteSize
    
                    Groupbox:Resize()
                end))
            else
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalAlignment = Enum.HorizontalAlignment.Right,
                    Padding = UDim.new(0, 6),
                    Parent = TextLabel,
                })
            end
    
            Groupbox:Resize()
    
            Label.TextLabel = TextLabel
            Label.Container = Container
            if not Data.DoesWrap then
                setmetatable(Label, BaseAddons)
            end
    
            Label.Holder = TextLabel
            table.insert(Groupbox.Elements, Label)
    
            if Data.Idx then
                Labels[Data.Idx] = Label
            else
                table.insert(Labels, Label)
            end
    
            function Label:Destroy()
                Label.Destroyed = true
    
                if Label.Connections then
                    for _, Connection in Label.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if Label.Addons then
                    for Index = #Label.Addons, 1, -1 do
                        local Addon = table.remove(Label.Addons, Index)
                        if Addon and Addon.Destroy then
                            Addon:Destroy()
                        end
                    end
                end
    
                if TextLabel then
                    TextLabel:Destroy()
                end
    
                local ElemIdx = table.find(Groupbox.Elements, Label)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
    
                Groupbox:Resize()
    
                if Data.Idx then
                    Labels[Data.Idx] = nil
                else
                    local LblIdx = table.find(Labels, Label)
    
                    if LblIdx then
                        table.remove(Labels, LblIdx)
                    end
                end
            end
    
            return Label
        end
    
        function Funcs:AddButton(...)
            if self.Destroyed then return nil end
    
            local function GetInfo(...)
                local Info = {}
    
                local First = select(1, ...)
                local Second = select(2, ...)
    
                if typeof(First) == "table" or typeof(Second) == "table" then
                    local Params = typeof(First) == "table" and First or Second
    
                    Info.Text = Params.Text or ""
                    Info.Func = Params.Func or Params.Callback or function() end
                    Info.DoubleClick = Params.DoubleClick
    
                    Info.Tooltip = Params.Tooltip
                    Info.DisabledTooltip = Params.DisabledTooltip
    
                    Info.Risky = Params.Risky or false
                    Info.Disabled = Params.Disabled or false
                    Info.Visible = if typeof(Params.Visible) == "boolean" then Params.Visible else true
                    Info.Idx = typeof(Second) == "table" and First or nil
                else
                    Info.Text = First or ""
                    Info.Func = Second or function() end
                    Info.DoubleClick = false
    
                    Info.Tooltip = nil
                    Info.DisabledTooltip = nil
    
                    Info.Risky = false
                    Info.Disabled = false
                    Info.Visible = true
                    Info.Idx = select(3, ...) or nil
                end
    
                return Info
            end
            local Info = GetInfo(...)
    
            local Groupbox = self
            local Container = Groupbox.Container
    
            local Button = {
                Connections = {},
                Destroyed = false,
    
                Text = Info.Text,
                Func = Info.Func,
                DoubleClick = Info.DoubleClick,
    
                Tooltip = Info.Tooltip,
                DisabledTooltip = Info.DisabledTooltip,
                TooltipTable = nil,
    
                Risky = Info.Risky,
                Disabled = Info.Disabled,
                Visible = Info.Visible,
    
                Tween = nil,
                Type = "Button",
    
                Parent = Groupbox,
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 23),
                Parent = Container,
            })
    
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalFlex = Enum.UIFlexAlignment.Fill,
                Padding = UDim.new(0, 9),
                Parent = Holder,
            })
    
            local function CreateButton(Button)
                local Base = New("TextButton", {
                    Active = not Button.Disabled,
                    BackgroundColor3 = Button.Disabled and "BackgroundColor" or "MainColor",
                    Size = UDim2.fromScale(1, 1),
                    Text = Button.Text,
                    TextSize = 14,
                    TextTransparency = 0.4,
                    Visible = Button.Visible,
                    Parent = Holder,
                })
    
                local Stroke = New("UIStroke", {
                    Color = "OutlineColor",
                    Transparency = Button.Disabled and 0.5 or 0,
                    Parent = Base,
                })
    
                New("UIScale", {
                    Parent = Base,
                })
    
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Base,
                    })
                )
    
                return Base, Stroke
            end
    
            local function InitEvents(Button)
                Library:AddHoverStroke(Button.Base, Button.Stroke, nil, function()
                    return Button.Disabled
                end)
    
                Button.Base.ClipsDescendants = true
                table.insert(Button.Connections, Button.Base.MouseButton1Down:Connect(function()
                    if Button.Disabled or Library.IconAnimations == false then
                        return
                    end
    
                    local Base = Button.Base
                    local Width = math.max(Base.AbsoluteSize.X, 1)
                    local RelativeX = math.clamp((Mouse.X - Base.AbsolutePosition.X) / Width, 0, 1)
    
                    local Ripple = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        BackgroundColor3 = "AccentColor",
                        BackgroundTransparency = 0.7,
                        Position = UDim2.fromScale(RelativeX, 0.5),
                        Size = UDim2.fromScale(0, 0),
                        SizeConstraint = Enum.SizeConstraint.RelativeXX,
                        ZIndex = Base.ZIndex + 1,
                        Parent = Base,
                    })
                    New("UICorner", {
                        CornerRadius = UDim.new(1, 0),
                        Parent = Ripple,
                    })
    
                    local Grow = TweenService:Create(Ripple, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Size = UDim2.fromScale(2.2, 2.2),
                        BackgroundTransparency = 1,
                    })
                    Grow.Completed:Once(function()
                        Ripple:Destroy()
                    end)
                    Grow:Play()
                end))
                local BaseScale = Button.Base:FindFirstChildOfClass("UIScale")
                if BaseScale then
                    local function Release()
                        TweenService:Create(BaseScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                            Scale = 1,
                        }):Play()
                    end
    
                    table.insert(Button.Connections, Button.Base.MouseButton1Down:Connect(function()
                        if Button.Disabled or Library.IconAnimations == false then
                            return
                        end
    
                        TweenService:Create(BaseScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                            Scale = 0.96,
                        }):Play()
                    end))
                    table.insert(Button.Connections, Button.Base.MouseButton1Up:Connect(Release))
                    table.insert(Button.Connections, Button.Base.MouseLeave:Connect(Release))
                end
    
                table.insert(Button.Connections, Button.Base.MouseEnter:Connect(function()
                    if Button.Disabled then
                        return
                    end
    
                    Button.Tween = TweenService:Create(Button.Base, Library.TweenInfo, {
                        TextTransparency = 0,
                    })
                    Button.Tween:Play()
                end))
                table.insert(Button.Connections, Button.Base.MouseLeave:Connect(function()
                    if Button.Disabled then
                        return
                    end
    
                    Button.Tween = TweenService:Create(Button.Base, Library.TweenInfo, {
                        TextTransparency = 0.4,
                    })
                    Button.Tween:Play()
                end))
    
                local QuickKey = tostring(Button.Text)
                if not Button.DoubleClick and QuickKey ~= "" then
                    Library.QuickButtons[QuickKey] = if Library.QuickButtons[QuickKey] == nil then Button else false
                end
                table.insert(Button.Connections, Button.Base.MouseButton2Click:Connect(function()
                    if Button.DoubleClick or Button.Risky then
                        Library:Notify({ Title = QuickKey, Description = "This button needs a double click, so it can't get a key", Time = 3 })
                    elseif Library.QuickButtons[QuickKey] == false then
                        Library:Notify({ Title = QuickKey, Description = "Two buttons share this name, so it can't get a key", Time = 3 })
                    else
                        Library:StartQuickBind("Button", QuickKey, QuickKey)
                    end
                end))
    
                table.insert(Button.Connections, Button.Base.MouseButton1Click:Connect(function()
                    if Button.Disabled or Button.Locked then
                        return
                    end
    
                    if Button.DoubleClick then
                        Button.Locked = true
    
                        Button.Base.Text = "Are you sure?"
                        Button.Base.TextColor3 = Library.Scheme.AccentColor
                        Library.Registry[Button.Base].TextColor3 = "AccentColor"
    
                        local Clicked = WaitForEvent(Button.Base.MouseButton1Click, 0.5)
    
                        Button.Base.Text = Button.Text
                        Button.Base.TextColor3 = Button.Risky and Library.Scheme.RedColor or Library.Scheme.FontColor
                        Library.Registry[Button.Base].TextColor3 = Button.Risky and "RedColor" or "FontColor"
    
                        if Clicked then
                            Library:SafeCallback(Button.Func)
                        end
    
                        RunService.RenderStepped:Wait()
                        Button.Locked = false
                        return
                    end
    
                    Library:SafeCallback(Button.Func)
                end))
            end
    
            Button.Base, Button.Stroke = CreateButton(Button)
            InitEvents(Button)
    
            function Button:AddButton(...)
                local Info = GetInfo(...)
    
                local SubButton = {
                    Connections = {},
                    Destroyed = false,
    
                    Text = Info.Text,
                    Func = Info.Func,
                    DoubleClick = Info.DoubleClick,
    
                    Tooltip = Info.Tooltip,
                    DisabledTooltip = Info.DisabledTooltip,
                    TooltipTable = nil,
    
                    Risky = Info.Risky,
                    Disabled = Info.Disabled,
                    Visible = Info.Visible,
    
                    Tween = nil,
                    Type = "SubButton",
                }
    
                Button.SubButton = SubButton
                SubButton.Base, SubButton.Stroke = CreateButton(SubButton)
                InitEvents(SubButton)
    
                function SubButton:UpdateColors()
                    if Library.Unloaded then
                        return
                    end
    
                    StopTween(SubButton.Tween)
    
                    SubButton.Base.BackgroundColor3 = SubButton.Disabled and Library.Scheme.BackgroundColor
                        or Library.Scheme.MainColor
                    SubButton.Base.TextTransparency = SubButton.Disabled and 0.8 or 0.4
                    SubButton.Stroke.Transparency = SubButton.Disabled and 0.5 or 0
    
                    Library.Registry[SubButton.Base].BackgroundColor3 = SubButton.Disabled and "BackgroundColor"
                        or "MainColor"
                end
    
                function SubButton:SetDisabled(Disabled: boolean)
                    SubButton.Disabled = Disabled
    
                    if SubButton.TooltipTable then
                        SubButton.TooltipTable.Disabled = SubButton.Disabled
                    end
    
                    SubButton.Base.Active = not SubButton.Disabled
                    SubButton:UpdateColors()
                    Library:UpdateAddons(SubButton)
                end
    
                function SubButton:SetVisible(Visible: boolean)
                    SubButton.Visible = Visible
    
                    SubButton.Base.Visible = SubButton.Visible
                    Groupbox:Resize()
                end
    
                function SubButton:SetText(Text: string)
                    SubButton.Text = Text
                    SubButton.Base.Text = Text
                end
    
                if typeof(SubButton.Tooltip) == "string" or typeof(SubButton.DisabledTooltip) == "string" then
                    SubButton.TooltipTable =
                        Library:AddTooltip(SubButton.Tooltip, SubButton.DisabledTooltip, SubButton.Base)
                    SubButton.TooltipTable.Disabled = SubButton.Disabled
                end
    
                if SubButton.Risky then
                    SubButton.Base.TextColor3 = Library.Scheme.RedColor
                    Library.Registry[SubButton.Base].TextColor3 = "RedColor"
                end
    
                SubButton:UpdateColors()
    
                if Info.Idx then
                    Buttons[Info.Idx] = SubButton
                else
                    table.insert(Buttons, SubButton)
                end
    
                SubButton.AddKeyPicker = BaseAddons.__index.AddKeyPicker
    
                function SubButton:Destroy()
                    SubButton.Destroyed = true
    
                    if SubButton.Connections then
                        for _, Connection in SubButton.Connections do
                            Connection:Disconnect()
                        end
                    end
    
                    if SubButton.TooltipTable then
                        SubButton.TooltipTable:Destroy()
                    end
    
                    if SubButton.Tween then
                        SubButton.Tween:Destroy()
                    end
    
                    if SubButton.Base then
                        SubButton.Base:Destroy()
                    end
    
                    if Info.Idx then
                        Buttons[Info.Idx] = nil
                    else
                        local BIdx = table.find(Buttons, SubButton)
    
                        if BIdx then
                            table.remove(Buttons, BIdx)
                        end
                    end
                end
    
                return SubButton
            end
    
            function Button:UpdateColors()
                if Library.Unloaded then
                    return
                end
    
                StopTween(Button.Tween)
    
                Button.Base.BackgroundColor3 = Button.Disabled and Library.Scheme.BackgroundColor
                    or Library.Scheme.MainColor
                Button.Base.TextTransparency = Button.Disabled and 0.8 or 0.4
                Button.Stroke.Transparency = Button.Disabled and 0.5 or 0
    
                Library.Registry[Button.Base].BackgroundColor3 = Button.Disabled and "BackgroundColor" or "MainColor"
            end
    
            function Button:SetDisabled(Disabled: boolean)
                Button.Disabled = Disabled
    
                if Button.TooltipTable then
                    Button.TooltipTable.Disabled = Button.Disabled
                end
    
                Button.Base.Active = not Button.Disabled
                Button:UpdateColors()
                Library:UpdateAddons(Button)
            end
    
            function Button:SetVisible(Visible: boolean)
                Button.Visible = Visible
    
                Holder.Visible = Button.Visible
                Groupbox:Resize()
            end
    
            function Button:SetText(Text: string)
                Button.Text = Text
                Button.Base.Text = Text
            end
    
            if typeof(Button.Tooltip) == "string" or typeof(Button.DisabledTooltip) == "string" then
                Button.TooltipTable = Library:AddTooltip(Button.Tooltip, Button.DisabledTooltip, Button.Base)
                Button.TooltipTable.Disabled = Button.Disabled
            end
    
            if Button.Risky then
                Button.Base.TextColor3 = Library.Scheme.RedColor
                Library.Registry[Button.Base].TextColor3 = "RedColor"
            end
    
            Button:UpdateColors()
            Groupbox:Resize()
    
            Button.Holder = Holder
            table.insert(Groupbox.Elements, Button)
    
            if Info.Idx then
                Buttons[Info.Idx] = Button
            else
                table.insert(Buttons, Button)
            end
    
            Button.AddKeyPicker = BaseAddons.__index.AddKeyPicker
    
            function Button:Destroy()
                Button.Destroyed = true
    
                if Button.Connections then
                    for _, Connection in Button.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if Button.TooltipTable then
                    Button.TooltipTable:Destroy()
                end
    
                if Button.Tween then
                    Button.Tween:Destroy()
                end
    
                if Button.SubButton then
                    Button.SubButton:Destroy()
                end
    
                if Holder then
                    Holder:Destroy()
                end
    
                local ElemIdx = table.find(Groupbox.Elements, Button)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
    
                Groupbox:Resize()
    
                if Info.Idx then
                    Buttons[Info.Idx] = nil
                else
                    local BIdx = table.find(Buttons, Button)
    
                    if BIdx then
                        table.remove(Buttons, BIdx)
                    end
                end
            end
    
            return Button
        end
    
