        function Funcs:AddAvatarCard(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local Target = Info.Player or LocalPlayer
            local Height = Info.Height or 190
    
            local Card = {
                Connections = {},
                Destroyed = false,
    
                Player = Target,
                Model = nil,
                Rotate = Info.Rotate ~= false,
                Dragging = false,
    
                Visible = if typeof(Info.Visible) == "boolean" then Info.Visible else true,
                Type = "AvatarCard",
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, Height),
                Visible = Card.Visible,
                Parent = Container,
            })
    
            local Box = New("TextButton", {
                BackgroundColor3 = function()
                    return Library.Scheme.MainColor:Lerp(Library.Scheme.AccentColor, 0.08)
                end,
                BackgroundTransparency = 0.3,
                ClipsDescendants = true,
