                }),
                Parent = Stage,
            })
            local Spotlight = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.55,
                Position = UDim2.new(0.5, 0, 1, -50),
                Size = UDim2.new(0.62, 0, 0, 30),
                Parent = Box,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Spotlight,
            })
            New("UIGradient", {
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.5, 0.35),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = Spotlight,
            })
    
            local CardField = Library:CreateStarfield(Box, {
                Count = 26,
                Sparkles = 1,
                Seed = 41,
                Parallax = false,
                ShootingStars = false,
                ZIndex = Box.ZIndex,
            })
    
            local Camera = CreateInstance("Camera")
            Camera.FieldOfView = 30
    
            local Viewport = New("ViewportFrame", {
                Ambient = Color3.fromRGB(160, 160, 180),
                BackgroundTransparency = 1,
                CurrentCamera = Camera,
                LightColor = Color3.fromRGB(240, 240, 255),
                LightDirection = Vector3.new(-0.6, -1, -0.8),
                Size = UDim2.new(1, 0, 1, -10),
                ZIndex = Box.ZIndex + 1,
                Parent = Box,
            })
            Camera.Parent = Viewport
    
            local Thumbnail = New("ImageLabel", {
                BackgroundTransparency = 1,
                Image = if Library.Anonymous then "" else string.format("rbxthumb://type=Avatar&id=%d&w=420&h=420", tonumber(Target.UserId) or 1),
                ScaleType = Enum.ScaleType.Fit,
                Size = UDim2.new(1, 0, 1, -30),
                Visible = false,
                ZIndex = Box.ZIndex + 1,
                Parent = Box,
            })
    
            local Shade = New("Frame", {
                AnchorPoint = Vector2.new(0, 1),
                BackgroundColor3 = "DarkColor",
                Position = UDim2.fromScale(0, 1),
                Size = UDim2.new(1, 0, 0, 52),
                ZIndex = Box.ZIndex + 2,
                Parent = Box,
            })
            New("UIGradient", {
                Rotation = 90,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(1, 0.35),
                }),
                Parent = Shade,
            })
    
            local NameLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.new(0, 11, 1, -38),
                Size = UDim2.new(1, -90, 0, 17),
                Text = if Library.Anonymous then "Anonymous" else tostring(Target.DisplayName),
                TextSize = 15,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Box.ZIndex + 3,
                Parent = Box,
            })
            local HandleLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.new(0, 11, 1, -20),
                Size = UDim2.new(1, -90, 0, 14),
                Text = if Library.Anonymous then "@hidden" else "@" .. tostring(Target.Name),
                TextSize = 12,
                TextTransparency = 0.45,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Box.ZIndex + 3,
                Parent = Box,
            })
    
            local IsPremium = false
            pcall(function()
                IsPremium = Target.MembershipType == Enum.MembershipType.Premium
            end)
    
            local Chip = New("TextLabel", {
                AnchorPoint = Vector2.new(1, 1),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.82,
                FontFace = GetMediumFont,
                Position = UDim2.new(1, -10, 1, -12),
                Size = UDim2.fromOffset(0, 20),
                Text = if Library.Anonymous then "Hidden" elseif IsPremium then "Premium" else "Member",
                TextColor3 = "AccentColor",
                TextSize = 12,
                ZIndex = Box.ZIndex + 3,
                Parent = Box,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 5),
                Parent = Chip,
            })
            New("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
                Parent = Chip,
            })
    
            local RotateHint = New("ImageLabel", {
                AnchorPoint = Vector2.new(1, 0),
                ImageColor3 = "FontColor",
                ImageTransparency = 0.6,
                Position = UDim2.new(1, -9, 0, 9),
                Size = UDim2.fromOffset(15, 15),
                ZIndex = Box.ZIndex + 3,
                Parent = Box,
            })
            local RotateIcon = Library:GetIcon("rotate-3d")
            if RotateIcon then
                Library:ApplyLucideIcon(RotateHint, RotateIcon)
            end
            Library:AddIconHover(Box, RotateHint, { Scale = 1.15, Transparency = 0.1, RestTransparency = 0.6, Press = false })
    
            local Focus = Vector3.zero
            local Distance = 8
            local Angle = math.rad(Info.Angle or 18)
            local Pitch = math.rad(Info.Pitch or 6)
    
            local function UpdateCamera()
                local Flat = math.cos(Pitch) * Distance
                Camera.CFrame = CFrame.lookAt(
                    Focus + Vector3.new(math.sin(Angle) * Flat, math.sin(Pitch) * Distance, -math.cos(Angle) * Flat),
                    Focus
                )
            end
    
            local function FitCamera()
                if not Card.Model then
                    return
                end
    
                local Success, BoxCFrame, BoxSize = pcall(function()
                    return Card.Model:GetBoundingBox()
                end)
                if not Success then
                    return
                end
    
                Focus = BoxCFrame.Position - Vector3.new(0, BoxSize.Y * 0.04, 0)
                local Aspect = math.max(Viewport.AbsoluteSize.X, 1) / math.max(Viewport.AbsoluteSize.Y, 1)
                local Tangent = math.tan(math.rad(Camera.FieldOfView / 2))
                local FitHeight = (BoxSize.Y * 0.5 + 0.45) / Tangent
                local FitWidth = (math.max(BoxSize.X, BoxSize.Z) * 0.5 + 0.45) / (Tangent * Aspect)
                Distance = math.max(FitHeight, FitWidth, 4)
                UpdateCamera()
            end
    
            local function BuildModel()
                local Character = Target.Character
                if not Character then
                    return nil
                end
    
                local OldArchivable = Character.Archivable
                local Success, Clone = pcall(function()
                    Character.Archivable = true
                    return Character:Clone()
                end)
                pcall(function()
                    Character.Archivable = OldArchivable
                end)
    
                if not Success or typeof(Clone) ~= "Instance" then
                    return nil
                end
    
                for _, Descendant in Clone:GetDescendants() do
                    if
                        Descendant:IsA("LuaSourceContainer")
                        or Descendant:IsA("Sound")
                        or Descendant:IsA("ParticleEmitter")
                        or Descendant:IsA("Trail")
                        or Descendant:IsA("Beam")
                        or Descendant:IsA("ForceField")
                        or Descendant:IsA("BillboardGui")
                        or Descendant:IsA("Highlight")
                        or Descendant:IsA("Tool")
                    then
                        Descendant:Destroy()
                    elseif Descendant:IsA("BasePart") then
                        Descendant.Anchored = true
                        Descendant.CanCollide = false
                    end
                end
    
                local Humanoid = Clone:FindFirstChildOfClass("Humanoid")
                if Humanoid then
                    pcall(function()
                        Humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                        Humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
                    end)
                end
    
                local Root = Clone:FindFirstChild("HumanoidRootPart")
                if Root and Root:IsA("BasePart") then
                    Root.Transparency = 1
                end
    
                if Card.Anonymous then
                    Library:AnonymizeCharacter(Clone, function()
                        if not Card.Destroyed and Card.Anonymous then
                            Card:Refresh()
                        end
                    end)
                end
    
                pcall(function()
                    Clone:PivotTo(CFrame.new())
                end)
    
                return Clone
            end
    
            Card.Anonymous = Library.Anonymous == true
            function Card:SetAnonymous(State: boolean)
                Card.Anonymous = State == true
                NameLabel.Text = if Card.Anonymous then "Anonymous" else tostring(Target.DisplayName)
                HandleLabel.Text = if Card.Anonymous then "@hidden" else "@" .. tostring(Target.Name)
                Chip.Text = if Card.Anonymous then "Hidden" elseif IsPremium then "Premium" else "Member"
                Thumbnail.Image = if Card.Anonymous then "" else string.format("rbxthumb://type=Avatar&id=%d&w=420&h=420", tonumber(Target.UserId) or 1)
                Card:Refresh()
            end
            if Target == LocalPlayer then
                Library.AvatarCards = Library.AvatarCards or {}
                table.insert(Library.AvatarCards, Card)
            end
    
            function Card:Refresh()
                if Card.Destroyed then
                    return
                end
    
                if Card.Model then
                    Card.Model:Destroy()
                    Card.Model = nil
                end
    
                local Model = if Info.Mode ~= "2D" then BuildModel() else nil
                if Model then
                    Model.Parent = Viewport
                    Card.Model = Model
                    Viewport.Visible = true
                    Thumbnail.Visible = false
                    FitCamera()
                else
                    Viewport.Visible = false
                    Thumbnail.Visible = true
                end
            end
    
            function Card:SetVisible(Visible: boolean)
                Card.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            table.insert(Card.Connections, Viewport:GetPropertyChangedSignal("AbsoluteSize"):Connect(FitCamera))
    
            table.insert(Card.Connections, Box.InputBegan:Connect(function(Input: InputObject)
                if not IsClickInput(Input) then
                    return
                end
    
                Card.Dragging = true
                local LastX = Input.Position.X
                local LastY = Input.Position.Y
    
                if Groupbox.Tab and Groupbox.Tab.Sides then
                    for _, Side in Groupbox.Tab.Sides do
                        Side.ScrollingEnabled = false
                    end
                end
    
                local Moved, Ended
                Moved = UserInputService.InputChanged:Connect(function(Changed: InputObject)
                    if Changed.UserInputType == Enum.UserInputType.MouseMovement or Changed.UserInputType == Enum.UserInputType.Touch then
                        local X, Y = Changed.Position.X, Changed.Position.Y
                        Angle += (X - LastX) * 0.012
                        Pitch = math.clamp(Pitch + (Y - LastY) * 0.01, -1.3, 1.3)
                        LastX, LastY = X, Y
                        UpdateCamera()
                    end
                end)
                Ended = UserInputService.InputEnded:Connect(function(Finished: InputObject)
                    if Finished.UserInputType ~= Input.UserInputType then
                        return
                    end
    
                    Card.Dragging = false
                    Moved:Disconnect()
                    Ended:Disconnect()
    
                    if Groupbox.Tab and Groupbox.Tab.Sides then
                        for _, Side in Groupbox.Tab.Sides do
                            Side.ScrollingEnabled = true
                        end
                    end
                end)
            end))
    
            table.insert(Card.Connections, RunService.RenderStepped:Connect(function(Delta)
                if not Card.Rotate or Card.Dragging or not Card.Model or not Holder.Visible or not Library.Toggled then
                    return
                end
                if Groupbox.Tab and Library.ActiveTab ~= Groupbox.Tab then
                    return
                end
    
                Angle += Delta * 0.55
                UpdateCamera()
            end))
    
            table.insert(Card.Connections, Target.CharacterAdded:Connect(function()
                task.delay(1.5, function()
                    Card:Refresh()
                end)
            end))
    
            function Card:Destroy()
                Card.Destroyed = true
    
                for _, Connection in Card.Connections do
                    Connection:Disconnect()
                end
                table.clear(Card.Connections)
    
                CardField:Destroy()
                if Card.Model then
                    Card.Model:Destroy()
                end
                Holder:Destroy()
    
                local ElemIdx = table.find(Groupbox.Elements, Card)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
    
                Groupbox:Resize()
                if Idx then
                    Options[Idx] = nil
                end
            end
    
            Card.Holder = Holder
            Card:Refresh()
            Groupbox:Resize()
            table.insert(Groupbox.Elements, Card)
    
            if Idx then
                Options[Idx] = Card
            end
    
            return Card
        end
    
        function Funcs:AddStat(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local Size = Info.Size or 26
    
            local Stat = {
                Connections = {},
                Destroyed = false,
                Text = Info.Text or "",
                Value = Info.Value or "",
                Visible = if typeof(Info.Visible) == "boolean" then Info.Visible else true,
                Type = "Stat",
            }
    
            local HasBar = typeof(Info.Progress) == "number"
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, Size + 6 + (if HasBar then 8 else 0)),
                Visible = Stat.Visible,
                Parent = Container,
            })
    
            local Row = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, Size + 6),
                Parent = Holder,
            })
    
            local Track = New("Frame", {
                BackgroundColor3 = "OutlineColor",
                BorderSizePixel = 0,
                Position = UDim2.new(0, 0, 0, Size + 7),
                Size = UDim2.new(1, 0, 0, 4),
                Visible = HasBar,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Track,
            })
            local Fill = New("Frame", {
                BackgroundColor3 = "AccentColor",
                BorderSizePixel = 0,
                Size = UDim2.fromScale(math.clamp(if HasBar then Info.Progress else 0, 0, 1), 1),
                Parent = Track,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Fill,
            })
            New("UIGradient", {
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.45),
                    NumberSequenceKeypoint.new(1, 0),
                }),
                Parent = Fill,
            })
            Stat.Progress = if HasBar then Info.Progress else nil
    
            local Icon = New("ImageLabel", {
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 0, 0.5, 0),
                ScaleType = Enum.ScaleType.Fit,
                Size = UDim2.fromOffset(Size, Size),
                Visible = false,
                Parent = Row,
            })
    
            local Label = New("TextLabel", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundTransparency = 1,
                Position = UDim2.new(0, Size + 8, 0.5, 0),
                Size = UDim2.new(0.55, -Size - 8, 1, 0),
                Text = Stat.Text,
                TextSize = 14,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Row,
            })
    
            local ValueLabel = New("TextLabel", {
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.new(1, 0, 0.5, 0),
                Size = UDim2.new(0.45, 0, 1, 0),
                Text = tostring(Stat.Value),
                TextColor3 = Info.ValueColor or "AccentColor",
                TextSize = 14,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Right,
                Parent = Row,
            })
    
            function Stat:SetIcon(Image: any)
                if typeof(Image) == "Instance" then
                    Library:ApplyValueVisual(Icon, { Model = Image })
                    Icon.Visible = true
                    Library:SetSchemeProperty(Icon, "ImageColor3", "WhiteColor")
                    Label.Position = UDim2.new(0, Size + 8, 0.5, 0)
                    Label.Size = UDim2.new(0.55, -Size - 8, 1, 0)
                    Track.Position = UDim2.new(0, Size + 8, 0, Size + 7)
                    Track.Size = UDim2.new(1, -Size - 8, 0, 4)
                    return
                end
                Library:ApplyValueVisual(Icon, nil)
                local Data = if Image ~= nil and Image ~= "" then Library:GetCustomIcon(Image) else nil
                if Data then
                    Library:ApplyLucideIcon(Icon, Data)
                    Icon.Visible = true
                    Library:SetSchemeProperty(Icon, "ImageColor3", if Data.IconName then "AccentColor" else "WhiteColor")
                else
                    Icon.Visible = false
                end
                local Inset = if Icon.Visible then Size + 8 else 0
                Label.Position = UDim2.new(0, Inset, 0.5, 0)
                Label.Size = UDim2.new(0.55, -Inset, 1, 0)
                Track.Position = UDim2.new(0, Inset, 0, Size + 7)
                Track.Size = UDim2.new(1, -Inset, 0, 4)
            end
    
            function Stat:SetProgress(Progress: number?)
                if typeof(Progress) ~= "number" or Progress ~= Progress then
                    if Stat.Progress ~= nil then
                        Stat.Progress = nil
                        Track.Visible = false
                        Holder.Size = UDim2.new(1, 0, 0, Size + 6)
                        Groupbox:Resize()
                    end
                    return
                end
                Progress = math.clamp(Progress, 0, 1)
                local WasHidden = Stat.Progress == nil
                local Jump = WasHidden or (Stat.Progress ~= nil and Progress < Stat.Progress - 0.2)
                Stat.Progress = Progress
                if WasHidden then
                    Track.Visible = true
                    Holder.Size = UDim2.new(1, 0, 0, Size + 14)
                    Groupbox:Resize()
                end
                if Jump then
                    Fill.Size = UDim2.fromScale(Progress, 1)
                else
                    TweenService:Create(Fill, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Size = UDim2.fromScale(Progress, 1),
                    }):Play()
                end
            end
    
            function Stat:SetText(Text: string)
                Stat.Text = tostring(Text)
                Label.Text = Stat.Text
            end
    
            function Stat:SetValue(Value: any)
                Stat.Value = Value
                ValueLabel.Text = tostring(Value)
            end
    
            function Stat:SetValueColor(Key: any)
                Library:SetSchemeProperty(ValueLabel, "TextColor3", Key)
            end
    
            function Stat:SetVisible(Visible: boolean)
                Stat.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
                Library:QueueSearchRefresh()
            end
    
            function Stat:Destroy()
                Stat.Destroyed = true
                Holder:Destroy()
                local ElemIdx = table.find(Groupbox.Elements, Stat)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
                Groupbox:Resize()
                if Idx then
                    Options[Idx] = nil
                end
            end
    
            Stat:SetIcon(Info.Icon)
            Stat.Holder = Holder
            table.insert(Groupbox.Elements, Stat)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Stat
            end
            return Stat
        end
    
        local function ChartNiceMax(Value: number): number
            if not Value or Value <= 0 or Value ~= Value then
                return 1
            end
            local Exponent = math.floor(math.log10(Value))
            local Base = 10 ^ Exponent
            for _, Step in { 1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10 } do
                if Value <= Step * Base then
                    return Step * Base
                end
            end
            return 10 * Base
        end
    
        local function ChartCompact(Value: number): string
            if typeof(Value) ~= "number" or Value ~= Value then
                return "-"
            end
            local Abs = math.abs(Value)
            local Units = { { 1e15, "Qd" }, { 1e12, "t" }, { 1e9, "b" }, { 1e6, "m" }, { 1e3, "k" } }
            for _, Unit in Units do
                if Abs >= Unit[1] then
                    local Scaled = Value / Unit[1]
                    local Text = if math.abs(Scaled) >= 100 then string.format("%.0f", Scaled) elseif math.abs(Scaled) >= 10 then string.format("%.1f", Scaled) else string.format("%.2f", Scaled)
                    if string.find(Text, ".", 1, true) then
                        Text = string.gsub(Text, "0+$", "")
                        Text = string.gsub(Text, "%.$", "")
                    end
                    return Text .. Unit[2]
                end
            end
            if Abs >= 100 or Value == math.floor(Value) then
                return tostring(math.floor(Value + 0.5))
            end
            return (string.gsub(string.format("%.1f", Value), "%.0$", ""))
        end
        Library.ChartCompact = ChartCompact
    
        function Library:CreateSegmented(Parent: GuiObject, Values: { string }, Selected: string?, Callback: (string) -> ()?, Options: any?)
            Options = Options or {}
            local Count = math.max(#Values, 1)
            local Frame = New("Frame", {
                AnchorPoint = Options.AnchorPoint or Vector2.zero,
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 0.15,
                Position = Options.Position or UDim2.new(),
                Size = Options.Size or UDim2.new(1, 0, 0, Options.Height or 24),
                Parent = Parent,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 6),
                Parent = Frame,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Transparency = 0.25,
                Parent = Frame,
            })
            local Indicator = New("Frame", {
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.8,
                Position = UDim2.new(0, 2, 0, 2),
                Size = UDim2.new(1 / Count, -4, 1, -4),
                ZIndex = Frame.ZIndex + 1,
                Parent = Frame,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 5),
                Parent = Indicator,
            })
            New("UIStroke", {
                Color = "AccentColor",
                Transparency = 0.5,
                Parent = Indicator,
            })
    
            local Segmented = { Value = Selected or Values[1], Frame = Frame, Buttons = {} }
    
            local function Paint(Animate: boolean?)
                local Index = table.find(Values, Segmented.Value) or 1
                local Target = UDim2.new((Index - 1) / Count, 2, 0, 2)
                if Animate and Library.Animations ~= false then
                    TweenService:Create(Indicator, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = Target }):Play()
                else
                    Indicator.Position = Target
                end
                for Value, Button in Segmented.Buttons do
                    Button.TextTransparency = if Value == Segmented.Value then 0 else 0.5
                end
            end
    
            for Index, Value in Values do
                local Button = New("TextButton", {
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.new((Index - 1) / Count, 0, 0, 0),
                    Size = UDim2.new(1 / Count, 0, 1, 0),
                    Text = tostring(Value),
                    TextSize = Options.TextSize or 12,
                    ZIndex = Frame.ZIndex + 2,
                    Parent = Frame,
                })
                Segmented.Buttons[Value] = Button
                Button.MouseButton1Click:Connect(function()
                    if Segmented.Value == Value then
                        return
                    end
                    Segmented.Value = Value
                    Paint(true)
                    if Callback then
                        Library:SafeCallback(Callback, Value)
                    end
                end)
            end
    
            function Segmented:Set(Value: string)
                Segmented.Value = Value
                Paint(false)
            end
    
            Paint(false)
            return Segmented
        end
    
        local function ChartLine(Parent: GuiObject, ZIndex: number)
            local Line = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BorderSizePixel = 0,
                Size = UDim2.fromOffset(0, 2),
                Visible = false,
                ZIndex = ZIndex,
                Parent = Parent,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Line,
            })
            return Line
        end
    
        local function ChartDot(Parent: GuiObject, Size: number, ZIndex: number, Ring: boolean?)
            local Dot = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BorderSizePixel = 0,
                Size = UDim2.fromOffset(Size, Size),
                Visible = false,
                ZIndex = ZIndex,
                Parent = Parent,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Dot,
            })
            if Ring then
                New("UIStroke", {
                    Color = "BackgroundColor",
                    Thickness = 2,
                    Parent = Dot,
                })
            end
            return Dot
        end
    
        local function ChartPixels(Frame: GuiObject, Fallback: Vector2): Vector2
            local Scale = math.max(Library.DPIScale, 0.01)
            local Size = Frame.AbsoluteSize / Scale
            if Size.X < 20 or Size.Y < 10 then
                return Fallback
            end
            return Size
        end
    
        local function ChartPaintSeries(Plot: GuiObject, Pools: any, Values: { number? }, Max: number, Size: Vector2, Color: Color3, Options: any?)
            Options = Options or {}
            local Count = #Values
            local Width, Height = Size.X, Size.Y
            local Head = Options.Headroom or 0.08
            local Limit = Options.Limit or Count
            local Points = {}
            for Index = 1, Count do
                local Value = Values[Index]
                if typeof(Value) == "number" and Value == Value then
                    local X = if Count > 1 then (Index - 1) / (Count - 1) * Width else Width / 2
                    local Y = Height - math.clamp(Value / Max, 0, 1) * Height * (1 - Head)
                    Points[Index] = Vector2.new(X, Y)
                end
            end
            local Thickness = Options.Thickness or 2
            for Index = 1, math.max(Count - 1, #Pools.Lines) do
                local Line = Pools.Lines[Index]
                local A, B = Points[Index], Points[Index + 1]
                local Show = A ~= nil and B ~= nil and Index < Limit
                if Show and not Line then
                    Line = ChartLine(Plot, Plot.ZIndex + 3)
                    Pools.Lines[Index] = Line
                end
                if Line then
                    if Show then
                        local Delta = B - A
                        Line.BackgroundColor3 = Color
                        Line.Position = UDim2.fromOffset((A.X + B.X) / 2, (A.Y + B.Y) / 2)
                        Line.Size = UDim2.fromOffset(Delta.Magnitude + Thickness * 0.5, Thickness)
                        Line.Rotation = math.deg(math.atan2(Delta.Y, Delta.X))
                        Line.Visible = true
                    else
                        Line.Visible = false
                    end
                end
                if Options.Area ~= false then
                    local Column = Pools.Columns[Index]
                    if Show and not Column then
                        Column = New("Frame", {
                            BorderSizePixel = 0,
                            ZIndex = Plot.ZIndex + 1,
                            Parent = Plot,
                        })
                        Pools.Columns[Index] = Column
                    end
                    if Column then
                        if Show then
                            local Top = (A.Y + B.Y) / 2
                            local Surface = Options.Surface or Library.Scheme.BackgroundColor
                            Column.BackgroundColor3 = Surface:Lerp(Color, Options.AreaMix or 0.16)
                            Column.BackgroundTransparency = 0
                            Column.Position = UDim2.fromOffset(A.X, Top)
                            Column.Size = UDim2.fromOffset(math.max(B.X - A.X, 0) + 0.75, math.max(Height - Top, 0))
                            Column.Visible = true
                        else
                            Column.Visible = false
                        end
                    end
                end
            end
            return Points
        end
    
        function Funcs:AddChart(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local PlotHeight = Info.Height or 132
            local AxisWidth = Info.AxisWidth or 40
    
            local Chart = {
                Type = "Chart",
                Connections = {},
                Destroyed = false,
                Visible = true,
                Metric = Info.Metric or (Info.Metrics and Info.Metrics[1]) or nil,
                Range = Info.Range or (Info.Ranges and Info.Ranges[1]) or nil,
                Data = nil,
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                Parent = Container,
            })
            local Base = Holder.ZIndex
    
            local Top = 0
            local function Changed()
                if Info.Changed then
                    Library:SafeCallback(Info.Changed, Chart.Metric, Chart.Range)
                end
            end
    
            if Info.Metrics and #Info.Metrics > 1 then
                Chart.MetricPicker = Library:CreateSegmented(Holder, Info.Metrics, Chart.Metric, function(Value)
                    Chart.Metric = Value
                    Chart.Reveal = true
                    Changed()
                end, { Height = 24, TextSize = 12 })
                Top += 32
            end
    
            local Headline = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.fromOffset(0, Top),
                Size = UDim2.new(1, if Info.Ranges then -128 else 0, 0, 26),
                Text = "",
                TextSize = 22,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Holder,
            })
            local DeltaLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, Top + 26),
                Size = UDim2.new(1, if Info.Ranges then -128 else 0, 0, 14),
                Text = "",
                TextSize = 12,
                TextTransparency = 0.35,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Holder,
            })
            if Info.Ranges and #Info.Ranges > 0 then
                Chart.RangePicker = Library:CreateSegmented(Holder, Info.Ranges, Chart.Range, function(Value)
                    Chart.Range = Value
                    Chart.Reveal = true
                    Changed()
                end, {
                    AnchorPoint = Vector2.new(1, 0),
                    Position = UDim2.new(1, 0, 0, Top + 6),
                    Size = UDim2.fromOffset(124, 22),
                    TextSize = 11,
                })
            end
            Top += 50
    
            local Plot = New("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(AxisWidth, Top),
                Size = UDim2.new(1, -AxisWidth, 0, PlotHeight),
                ZIndex = Base + 1,
                Parent = Holder,
            })
    
            local Grid, Ticks = {}, {}
            for Index = 1, 3 do
                local Fraction = (Index - 1) / 2
                Grid[Index] = New("Frame", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundColor3 = "OutlineColor",
                    BackgroundTransparency = if Index == 1 then 0.15 else 0.55,
                    Position = UDim2.new(0, 0, 1 - Fraction * 0.92, 0),
                    Size = UDim2.new(1, 0, 0, 1),
                    ZIndex = Base + 3,
                    Parent = Plot,
                })
                Ticks[Index] = New("TextLabel", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, AxisWidth - 6, 0, Top + PlotHeight * (1 - Fraction * 0.92)),
                    Size = UDim2.fromOffset(AxisWidth - 6, 14),
                    Text = "",
                    TextSize = 11,
                    TextTransparency = 0.5,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    Parent = Holder,
                })
            end
    
            local XLabels = {}
            for Index, Anchor in { 0, 0.5, 1 } do
                XLabels[Index] = New("TextLabel", {
                    AnchorPoint = Vector2.new(Anchor, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(Anchor, 0, 1, 4),
                    Size = UDim2.fromOffset(60, 12),
                    Text = "",
                    TextSize = 11,
                    TextTransparency = 0.5,
                    TextXAlignment = if Anchor == 0 then Enum.TextXAlignment.Left elseif Anchor == 1 then Enum.TextXAlignment.Right else Enum.TextXAlignment.Center,
                    Parent = Plot,
                })
            end
    
            local AverageLine = New("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = "FontColor",
                BackgroundTransparency = 0.6,
                Size = UDim2.new(1, 0, 0, 1),
                Visible = false,
                ZIndex = Base + 3,
                Parent = Plot,
            })
            local AverageLabel = New("TextLabel", {
                AnchorPoint = Vector2.new(1, 1),
                BackgroundTransparency = 1,
                Position = UDim2.new(1, 0, 0, -1),
                Size = UDim2.fromOffset(60, 12),
                Text = "avg",
                TextSize = 10,
                TextTransparency = 0.45,
                TextXAlignment = Enum.TextXAlignment.Right,
                ZIndex = Base + 3,
                Parent = AverageLine,
            })
    
            local EmptyLabel = New("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.new(1, -20, 0, 36),
                Text = "Collecting data...",
                TextSize = 13,
                TextTransparency = 0.45,
                TextWrapped = true,
                Visible = true,
                ZIndex = Base + 4,
                Parent = Plot,
            })
    
            local Pools = { Lines = {}, Columns = {} }
            local Markers = {}
            local EndDot = ChartDot(Plot, 8, Base + 6, true)
            local Crosshair = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundColor3 = "FontColor",
                BackgroundTransparency = 0.55,
                Size = UDim2.new(0, 1, 1, 0),
                Visible = false,
                ZIndex = Base + 5,
                Parent = Plot,
            })
            local HoverDot = ChartDot(Plot, 9, Base + 7, true)
            local Tooltip = New("Frame", {
                AnchorPoint = Vector2.new(0, 0),
                BackgroundColor3 = "MainColor",
                Size = UDim2.fromOffset(0, 0),
                Visible = false,
                ZIndex = Base + 20,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 6),
                Parent = Tooltip,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Parent = Tooltip,
            })
            New("UIPadding", {
                PaddingBottom = UDim.new(0, 5),
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
                PaddingTop = UDim.new(0, 5),
                Parent = Tooltip,
            })
            local TooltipText = New("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Base + 21,
                Parent = Tooltip,
            })
    
            Holder.Size = UDim2.new(1, 0, 0, Top + PlotHeight + 20)
    
            local Points = {}
            local RevealToken = 0
    
            local function Format(Value)
                local Data = Chart.Data
                if Data and Data.Format then
                    local Ok, Text = pcall(Data.Format, Value)
                    if Ok and Text then
                        return tostring(Text)
                    end
                end
                return ChartCompact(Value)
            end
    
            local function Draw(Limit)
                local Data = Chart.Data
                if not Data then
                    return
                end
                local Values = Data.Values or {}
                local Count = #Values
                local Known, Max = 0, 0
                for Index = 1, Count do
                    local Value = Values[Index]
                    if typeof(Value) == "number" and Value == Value then
                        Known += 1
                        Max = math.max(Max, Value)
                    end
                end
                if Data.Average then
                    Max = math.max(Max, Data.Average)
                end
                local Nice = ChartNiceMax(Max)
                Chart.Max = Nice
                for Index = 1, 3 do
                    Ticks[Index].Text = if Known >= 2 then Format(Nice * (Index - 1) / 2) else ""
                end
                local Labels = Data.XLabels or {}
                for Index = 1, 3 do
                    XLabels[Index].Text = tostring(Labels[Index] or "")
                end
                local Color = Data.Color or Library.Scheme.AccentColor
                local Size = ChartPixels(Plot, Vector2.new(240, PlotHeight))
                EmptyLabel.Visible = Known < 2
                EmptyLabel.Text = Data.EmptyText or "Collecting data, check back in a minute"
                if Known < 2 then
                    for _, Line in Pools.Lines do
                        Line.Visible = false
                    end
                    for _, Column in Pools.Columns do
                        Column.Visible = false
                    end
                    EndDot.Visible = false
                    AverageLine.Visible = false
                    for _, Marker in Markers do
                        Marker.Dot.Visible = false
                        Marker.Line.Visible = false
                    end
                    Points = {}
                    return
                end
                Points = ChartPaintSeries(Plot, Pools, Values, Nice, Size, Color, { Limit = Limit or Count })
                local LastIndex = nil
                for Index = math.min(Limit or Count, Count), 1, -1 do
                    if Points[Index] then
                        LastIndex = Index
                        break
                    end
                end
                if LastIndex then
                    EndDot.BackgroundColor3 = Color
                    EndDot.Position = UDim2.fromOffset(Points[LastIndex].X, Points[LastIndex].Y)
                    EndDot.Visible = true
                else
                    EndDot.Visible = false
                end
                if typeof(Data.Average) == "number" and Data.Average > 0 then
                    AverageLine.Position = UDim2.new(0, 0, 0, Size.Y - math.clamp(Data.Average / Nice, 0, 1) * Size.Y * 0.92)
                    AverageLine.Visible = true
                else
                    AverageLine.Visible = false
                end
                local Events = Data.Events or {}
                for Index = 1, math.max(#Events, #Markers) do
                    local Event = Events[Index]
                    local Marker = Markers[Index]
                    if Event and not Marker then
                        Marker = {
                            Line = New("Frame", {
                                AnchorPoint = Vector2.new(0.5, 0),
                                BackgroundColor3 = "FontColor",
                                BackgroundTransparency = 0.86,
                                Size = UDim2.new(0, 1, 1, -6),
                                Position = UDim2.fromOffset(0, 6),
                                ZIndex = Base + 3,
                                Parent = Plot,
                            }),
                            Dot = ChartDot(Plot, 7, Base + 6, true),
                        }
                        Markers[Index] = Marker
                    end
                    if Marker then
                        local Show = Event ~= nil and typeof(Event.Index) == "number" and Event.Index >= 1 and Event.Index <= Count and Event.Index <= (Limit or Count)
                        if Show then
                            local X = if Count > 1 then (Event.Index - 1) / (Count - 1) * Size.X else Size.X / 2
                            Marker.Line.Position = UDim2.fromOffset(X, 6)
                            Marker.Dot.Position = UDim2.fromOffset(X, 4)
                            Marker.Dot.BackgroundColor3 = Event.Color or Library.Scheme.AccentColor
                        end
                        Marker.Line.Visible = Show
                        Marker.Dot.Visible = Show
                    end
                end
            end
    
            local function HideHover()
                Chart.HoverX = nil
                Crosshair.Visible = false
                HoverDot.Visible = false
                Tooltip.Visible = false
            end
    
            local HideToken = 0
            local function ShowAt(ScreenX: number)
                local Data = Chart.Data
                if not Data or not Data.Values then
                    return
                end
                local Count = #Data.Values
                if Count < 2 then
                    return
                end
                local Width = math.max(Plot.AbsoluteSize.X, 1)
                local Relative = math.clamp((ScreenX - Plot.AbsolutePosition.X) / Width, 0, 1)
                local Index = math.clamp(math.floor(Relative * (Count - 1) + 0.5) + 1, 1, Count)
                local Found = nil
                for Offset = 0, 4 do
                    for _, Candidate in { Index - Offset, Index + Offset } do
                        if not Found and Points[Candidate] then
                            Found = Candidate
                        end
                    end
                end
                if not Found then
                    HideHover()
                    return
                end
                local Point = Points[Found]
                local Size = ChartPixels(Plot, Vector2.new(240, PlotHeight))
                Crosshair.Position = UDim2.fromOffset(Point.X, 0)
                Crosshair.Visible = true
                HoverDot.BackgroundColor3 = Data.Color or Library.Scheme.AccentColor
                HoverDot.Position = UDim2.fromOffset(Point.X, Point.Y)
                HoverDot.Visible = true
                local Lines = { string.format("<b>%s</b>%s", Format(Data.Values[Found]), if Data.Suffix then '<font transparency="0.4"> ' .. Data.Suffix .. "</font>" else "") }
                local Label = Data.Labels and Data.Labels[Found]
                if Label then
                    table.insert(Lines, string.format('<font transparency="0.45">%s</font>', tostring(Label)))
                end
                for _, Event in Data.Events or {} do
                    if typeof(Event.Index) == "number" and math.abs(Event.Index - Found) <= 1 and Event.Text then
                        table.insert(Lines, string.format('<font transparency="0.2">%s</font>', tostring(Event.Text)))
                    end
                end
                TooltipText.Text = table.concat(Lines, "\n")
                Chart.HoverX = ScreenX
                local Widest = 0
                for Number, Line in Lines do
                    local Plain = string.gsub(Line, "<[^>]+>", "")
                    Widest = math.max(Widest, #Plain * (if Number == 1 then 7.2 else 6.4))
                end
                Tooltip.Size = UDim2.fromOffset(math.ceil(Widest) + 18, #Lines * 15 + 10)
                local TipWidth = Tooltip.Size.X.Offset
                local HolderWidth = ChartPixels(Holder, Vector2.new(AxisWidth + Size.X, 0)).X
                local Anchor = AxisWidth + Point.X
                if Anchor + 10 + TipWidth <= HolderWidth then
                    Tooltip.AnchorPoint = Vector2.new(0, 0)
                    Tooltip.Position = UDim2.fromOffset(Anchor + 10, Top + 4)
                else
                    Tooltip.AnchorPoint = Vector2.new(1, 0)
                    Tooltip.Position = UDim2.fromOffset(math.max(TipWidth, Anchor - 10), Top + 4)
                end
                Tooltip.Visible = true
                HideToken += 1
            end
    
            local function IsPointer(Input: InputObject)
                return Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch or Input.UserInputType == Enum.UserInputType.MouseButton1
            end
    
            table.insert(Chart.Connections, Plot.InputBegan:Connect(function(Input: InputObject)
                if IsPointer(Input) then
                    ShowAt(Input.Position.X)
                end
            end))
            table.insert(Chart.Connections, Plot.InputChanged:Connect(function(Input: InputObject)
                if IsPointer(Input) then
                    ShowAt(Input.Position.X)
                end
            end))
            table.insert(Chart.Connections, Plot.InputEnded:Connect(function(Input: InputObject)
                if Input.UserInputType == Enum.UserInputType.MouseMovement then
                    HideHover()
                elseif Input.UserInputType == Enum.UserInputType.Touch then
                    local Token = HideToken
                    task.delay(1.8, function()
                        if HideToken == Token then
                            HideHover()
                        end
                    end)
                end
            end))
            table.insert(Chart.Connections, Plot.MouseLeave:Connect(HideHover))
            table.insert(Chart.Connections, Plot:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                if Chart.Data then
                    Draw()
                end
            end))
    
            function Chart:SetData(Data)
                Chart.Data = Data or {}
                local Suffix = if Chart.Data.Suffix then '<font size="13" transparency="0.45"> ' .. Chart.Data.Suffix .. "</font>" else ""
                Headline.Text = tostring(Chart.Data.Headline or "") .. Suffix
                local Delta = Chart.Data.Delta
                if typeof(Delta) == "number" and Delta == Delta and math.abs(Delta) < 100 then
                    local Up = Delta >= 0
                    local Arrow = if Up then "\u{25B2}" else "\u{25BC}"
                    local Color = if Up then "#60d696" else "#ff6e8a"
                    DeltaLabel.Text = string.format('<font color="%s">%s %d%%</font>  %s', Color, Arrow, math.floor(math.abs(Delta) * 100 + 0.5), tostring(Chart.Data.DeltaLabel or ""))
                else
                    DeltaLabel.Text = tostring(Chart.Data.Subtitle or "")
                end
                local HoverX = Chart.HoverX
                local Reveal = Chart.Reveal and Library.Animations ~= false
                Chart.Reveal = false
                if Reveal then
                    RevealToken += 1
                    local Token = RevealToken
                    local Count = #(Chart.Data.Values or {})
                    task.spawn(function()
                        local Started = os.clock()
                        while RevealToken == Token and not Chart.Destroyed do
                            local Progress = math.clamp((os.clock() - Started) / 0.42, 0, 1)
                            local Eased = 1 - (1 - Progress) ^ 3
                            Draw(math.max(2, math.floor(Eased * Count + 0.5)))
                            if Progress >= 1 then
                                break
                            end
                            task.wait()
                        end
                    end)
                else
                    Draw()
                end
                if HoverX and not Reveal then
                    ShowAt(HoverX)
                else
                    HideHover()
                end
            end
    
            function Chart:SetMetric(Metric: string)
                Chart.Metric = Metric
                if Chart.MetricPicker then
                    Chart.MetricPicker:Set(Metric)
                end
            end
    
            function Chart:SetRange(Range: string)
                Chart.Range = Range
                if Chart.RangePicker then
                    Chart.RangePicker:Set(Range)
                end
            end
    
            function Chart:SetVisible(Visible: boolean)
                Chart.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            function Chart:Destroy()
                Chart.Destroyed = true
                for _, Connection in Chart.Connections do
                    Connection:Disconnect()
                end
                Holder:Destroy()
                local ElemIdx = table.find(Groupbox.Elements, Chart)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
                Groupbox:Resize()
                if Idx then
                    Options[Idx] = nil
                end
            end
    
            Chart.Holder = Holder
            Chart.Plot = Plot
            Chart.Tooltip = Tooltip
            Chart.ShowAt = ShowAt
            table.insert(Groupbox.Elements, Chart)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Chart
            end
            return Chart
        end
    
        function Funcs:AddStatTiles(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local Columns = Info.Columns or 2
            local TileHeight = Info.TileHeight or 82
            local Gap = 8
            local Defs = Info.Tiles or {}
            local Rows = math.max(1, math.ceil(#Defs / Columns))
    
            local Tiles = {
                Type = "StatTiles",
                Destroyed = false,
                Visible = true,
                Tiles = {},
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, Rows * TileHeight + (Rows - 1) * Gap),
                Parent = Container,
            })
            local Base = Holder.ZIndex
    
            for Index, Def in Defs do
                local Column = (Index - 1) % Columns
                local Row = math.floor((Index - 1) / Columns)
                local Card = New("Frame", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 0.12,
                    Position = UDim2.new(Column / Columns, if Column == 0 then 0 else Gap / 2, 0, Row * (TileHeight + Gap)),
                    Size = UDim2.new(1 / Columns, -Gap / 2, 0, TileHeight),
                    Parent = Holder,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 8),
                    Parent = Card,
                })
                New("UIStroke", {
                    Color = "OutlineColor",
                    Transparency = 0.3,
                    Parent = Card,
                })
                local Key = New("Frame", {
                    BackgroundColor3 = Def.Color or Library.Scheme.AccentColor,
                    Position = UDim2.fromOffset(10, 12),
                    Size = UDim2.fromOffset(8, 8),
                    ZIndex = Base + 1,
                    Parent = Card,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Key,
                })
                New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(24, 7),
                    Size = UDim2.new(1, -30, 0, 16),
                    Text = tostring(Def.Label or Def.Id),
                    TextSize = 12,
                    TextTransparency = 0.35,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 1,
                    Parent = Card,
                })
                local Value = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.fromOffset(10, 25),
                    Size = UDim2.new(1, -16, 0, 22),
                    Text = "-",
                    TextSize = 19,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 1,
                    Parent = Card,
                })
                local Delta = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(10, 50),
                    Size = UDim2.new(0.5, -10, 0, 14),
                    Text = "",
                    TextSize = 11,
                    TextTransparency = 0.2,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 1,
                    Parent = Card,
                })
                local Spark = New("Frame", {
                    AnchorPoint = Vector2.new(1, 1),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(1, -8, 1, -8),
                    Size = UDim2.new(0.52, -8, 0, 28),
                    ZIndex = Base + 1,
                    Parent = Card,
                })
                local Tile = {
                    Card = Card,
                    Value = Value,
                    Delta = Delta,
                    Spark = Spark,
                    Pools = { Lines = {}, Columns = {} },
                    Dot = ChartDot(Spark, 5, Base + 5, true),
                    Color = Def.Color,
                }
                Tiles.Tiles[Def.Id or Index] = Tile
            end
    
            local function DrawSpark(Tile)
                local Points = Tile.Points or {}
                local Max = 0
                local Known = 0
                for _, Value in Points do
                    if typeof(Value) == "number" then
                        Max = math.max(Max, Value)
                        Known += 1
                    end
                end
                if Known < 2 then
                    for _, Line in Tile.Pools.Lines do
                        Line.Visible = false
                    end
                    for _, Column in Tile.Pools.Columns do
                        Column.Visible = false
                    end
                    Tile.Dot.Visible = false
                    return
                end
                local Size = ChartPixels(Tile.Spark, Vector2.new(60, 28))
                local Painted = ChartPaintSeries(Tile.Spark, Tile.Pools, Points, ChartNiceMax(Max), Size, Tile.Color or Library.Scheme.AccentColor, { Thickness = 1.5, AreaMix = 0.14, Surface = Library.Scheme.MainColor, Headroom = 0.12 })
                local Last = nil
                for Index = #Points, 1, -1 do
                    if Painted[Index] then
                        Last = Painted[Index]
                        break
                    end
                end
                if Last then
                    Tile.Dot.BackgroundColor3 = Tile.Color or Library.Scheme.AccentColor
                    Tile.Dot.Position = UDim2.fromOffset(Last.X, Last.Y)
                    Tile.Dot.Visible = true
                end
            end
    
            function Tiles:SetTile(Id, Data)
                local Tile = Tiles.Tiles[Id]
                if not Tile then
                    return
                end
                Data = Data or {}
                local Suffix = if Data.Suffix then '<font size="12" transparency="0.45"> ' .. Data.Suffix .. "</font>" else ""
                Tile.Value.Text = tostring(Data.Value or "-") .. Suffix
                local Delta = Data.Delta
                if typeof(Delta) == "number" and Delta == Delta and math.abs(Delta) < 100 then
                    local Up = Delta >= 0
                    Tile.Delta.Text = string.format('<font color="%s">%s %d%%</font>', if Up then "#60d696" else "#ff6e8a", if Up then "\u{25B2}" else "\u{25BC}", math.floor(math.abs(Delta) * 100 + 0.5))
                else
                    Tile.Delta.Text = tostring(Data.Note or "")
                end
                Tile.Points = Data.Points
                DrawSpark(Tile)
            end
    
            Tiles.SizeConnection = Holder:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                for _, Tile in Tiles.Tiles do
                    if Tile.Points then
                        DrawSpark(Tile)
                    end
                end
            end)
    
            function Tiles:SetVisible(Visible: boolean)
                Tiles.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Tiles.Holder = Holder
            table.insert(Groupbox.Elements, Tiles)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Tiles
            end
            return Tiles
        end
    
        function Funcs:AddBarChart(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local RowHeight = Info.RowHeight or 24
            local LabelWidth = Info.LabelWidth or 74
            local ValueWidth = Info.ValueWidth or 76
    
            local Bars = {
                Type = "BarChart",
                Destroyed = false,
                Visible = true,
                Scope = Info.Scope or (Info.Scopes and Info.Scopes[1]) or nil,
                Rows = {},
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                Parent = Container,
            })
            local Base = Holder.ZIndex
            local Top = 0
            if Info.Scopes and #Info.Scopes > 1 then
                Bars.ScopePicker = Library:CreateSegmented(Holder, Info.Scopes, Bars.Scope, function(Value)
                    Bars.Scope = Value
                    if Info.Changed then
                        Library:SafeCallback(Info.Changed, Value)
                    end
                end, { Height = 24, TextSize = 12 })
                Top += 32
            end
            local List = New("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, Top),
                Size = UDim2.new(1, 0, 0, 0),
                Parent = Holder,
            })
            local EmptyLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, Top),
                Size = UDim2.new(1, 0, 0, 24),
                Text = Info.EmptyText or "Nothing yet",
                TextSize = 13,
                TextTransparency = 0.45,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Holder,
            })
    
            local function Resize(Count: number)
                List.Size = UDim2.new(1, 0, 0, Count * RowHeight)
                Holder.Size = UDim2.new(1, 0, 0, Top + math.max(Count * RowHeight, 24))
                Groupbox:Resize()
            end
    
            function Bars:SetData(Data)
                Data = Data or {}
                local Max = 0
                for _, Entry in Data do
                    Max = math.max(Max, tonumber(Entry.Value) or 0)
                end
                local Total = 0
                for _, Entry in Data do
                    Total += tonumber(Entry.Value) or 0
                end
                for Index = 1, math.max(#Data, #Bars.Rows) do
                    local Entry = Data[Index]
                    local Row = Bars.Rows[Index]
                    if Entry and not Row then
                        local Frame = New("Frame", {
                            BackgroundTransparency = 1,
                            Position = UDim2.fromOffset(0, (Index - 1) * RowHeight),
                            Size = UDim2.new(1, 0, 0, RowHeight),
                            Parent = List,
                        })
                        local Label = New("TextLabel", {
                            AnchorPoint = Vector2.new(0, 0.5),
                            BackgroundTransparency = 1,
                            Position = UDim2.new(0, 0, 0.5, 0),
                            Size = UDim2.new(0, LabelWidth - 6, 1, 0),
                            Text = "",
                            TextSize = 13,
                            TextTruncate = Enum.TextTruncate.AtEnd,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            Parent = Frame,
                        })
                        local Track = New("Frame", {
                            AnchorPoint = Vector2.new(0, 0.5),
                            BackgroundTransparency = 1,
                            Position = UDim2.new(0, LabelWidth, 0.5, 0),
                            Size = UDim2.new(1, -LabelWidth - ValueWidth, 0, 12),
                            Parent = Frame,
                        })
                        local Bar = New("Frame", {
                            BorderSizePixel = 0,
                            Size = UDim2.fromScale(0, 1),
                            Parent = Track,
                        })
                        New("UICorner", {
                            CornerRadius = UDim.new(0, 4),
                            Parent = Bar,
                        })
                        local Value = New("TextLabel", {
                            AnchorPoint = Vector2.new(0, 0.5),
                            BackgroundTransparency = 1,
                            FontFace = GetBoldFont,
                            Position = UDim2.new(0, 6, 0.5, 0),
                            Size = UDim2.fromOffset(ValueWidth, RowHeight),
                            Text = "",
                            TextSize = 12,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            Parent = Frame,
                        })
                        Row = { Frame = Frame, Label = Label, Track = Track, Bar = Bar, Value = Value }
                        Bars.Rows[Index] = Row
                    end
                    if Row then
                        if Entry then
                            local Amount = tonumber(Entry.Value) or 0
                            local Fraction = if Max > 0 then Amount / Max else 0
                            Row.Label.Text = tostring(Entry.Label or "")
                            Row.Bar.BackgroundColor3 = Entry.Color or Library.Scheme.AccentColor
                            TweenService:Create(Row.Bar, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Size = UDim2.new(Fraction, if Amount > 0 then 4 else 0, 1, 0) }):Play()
                            local Share = if Total > 0 then string.format('  <font transparency="0.5">%d%%</font>', math.floor(Amount / Total * 100 + 0.5)) else ""
                            Row.Value.Text = tostring(Entry.Text or ChartCompact(Amount)) .. Share
                            Row.Value.Position = UDim2.new(0, LabelWidth + 6, 0.5, 0)
                            Row.Value.AnchorPoint = Vector2.new(0, 0.5)
                            Row.Frame.Visible = true
                            task.defer(function()
                                local Scale = math.max(Library.DPIScale, 0.01)
                                local TrackWidth = Row.Track.AbsoluteSize.X / Scale
                                Row.Value.Position = UDim2.new(0, LabelWidth + TrackWidth * Fraction + 10, 0.5, 0)
                            end)
                        else
                            Row.Frame.Visible = false
                        end
                    end
                end
                EmptyLabel.Visible = #Data == 0
                Resize(#Data)
            end
    
            function Bars:SetVisible(Visible: boolean)
                Bars.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Resize(0)
            Bars.Holder = Holder
            table.insert(Groupbox.Elements, Bars)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Bars
            end
            return Bars
        end
    
        local function WidgetColor(Value: any, Fallback: Color3?): Color3
            if typeof(Value) == "Color3" then
                return Value
            end
            if typeof(Value) == "string" and Value ~= "" then
                local Ok, Parsed = pcall(Color3.fromHex, Value)
                if Ok and typeof(Parsed) == "Color3" then
                    return Parsed
                end
            end
            return Fallback or Library.Scheme.AccentColor
        end
        Library.WidgetColor = WidgetColor
    
        local function WidgetIcon(Target: ImageLabel, Image: any, Tint: Color3?)
            if typeof(Image) == "Instance" then
                Library:ApplyValueVisual(Target, { Model = Image })
                Target.ImageColor3 = Color3.new(1, 1, 1)
                Target.Visible = true
                return
            end
            Library:ApplyValueVisual(Target, nil)
            local Data = if typeof(Image) == "string" and Image ~= "" then Library:GetCustomIcon(Image) else nil
            if Data then
                Library:ApplyLucideIcon(Target, Data)
                Target.ImageColor3 = if Data.IconName then (Tint or Library.Scheme.AccentColor) else Color3.new(1, 1, 1)
                Target.Visible = true
            else
                Target.Visible = false
            end
        end
        Library.WidgetIcon = WidgetIcon
    
        Library.CorvusTint = function()
            return Library.Scheme.AccentColor:Lerp(Color3.new(1, 1, 1), 0.3)
        end
    
        local function WidgetAge(At: number?): string
            if typeof(At) ~= "number" then
                return ""
            end
            local Age = math.max(0, os.clock() - At)
            if Age < 5 then
                return "now"
            elseif Age < 60 then
                return string.format("%ds ago", math.floor(Age))
            elseif Age < 3600 then
                return string.format("%dm ago", math.floor(Age / 60))
            end
            return string.format("%dh ago", math.floor(Age / 3600))
        end
        Library.WidgetAge = WidgetAge
    
        local function WidgetEscape(Text: any): string
            return (string.gsub(tostring(Text or ""), "[<>&]", { ["<"] = "&lt;", [">"] = "&gt;", ["&"] = "&amp;" }))
        end
    
        local function WidgetWidth(Frame: GuiObject, Fallback: number): number
            local Scale = math.max(Library.DPIScale, 0.01)
            local Width = Frame.AbsoluteSize.X / Scale
            if Width < 40 then
                return Fallback
            end
            return Width
        end
    
        local function WidgetTween(Object: Instance, Time: number, Goal: any, Style: Enum.EasingStyle?, Direction: Enum.EasingDirection?)
            if Library.Animations == false then
                for Key, Value in Goal do
                    Object[Key] = Value
                end
                return
            end
            TweenService:Create(Object, TweenInfo.new(Time, Style or Enum.EasingStyle.Quint, Direction or Enum.EasingDirection.Out), Goal):Play()
        end
    
        function Funcs:AddFeed(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local RowHeight = Info.RowHeight or 40
            local MaxRows = Info.MaxRows or 6
            local Gap = 5
    
            local Feed = {
                Type = "Feed",
                Destroyed = false,
                Visible = true,
                Rows = {},
                Seen = {},
                Primed = false,
                Count = 0,
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, RowHeight),
                Parent = Container,
            })
            local Base = Holder.ZIndex
    
            local EmptyLabel = New("TextLabel", {
                BackgroundTransparency = 1,
