                })
                Row.IconStroke = New("UIStroke", {
                    Color = Color3.new(1, 1, 1),
                    Thickness = 1.5,
                    Transparency = 0.2,
                    Parent = Row.IconBack,
                })
                Row.IconScale = New("UIScale", {
                    Scale = 1,
                    Parent = Row.IconBack,
                })
                Row.Icon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromOffset(24, 24),
                    ZIndex = Base + 3,
                    Parent = Row.IconBack,
                })
                Row.Title = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.fromOffset(48, 5),
                    Size = UDim2.new(1, -164, 0, 17),
                    Text = "",
                    TextSize = 14,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 3,
                    Parent = Row.Frame,
                })
                Row.Badge = New("TextLabel", {
                    BackgroundColor3 = Color3.new(1, 1, 1),
                    FontFace = GetBoldFont,
                    Position = UDim2.fromOffset(48, 6),
                    Size = UDim2.fromOffset(34, 15),
                    Text = "",
                    TextColor3 = Color3.fromRGB(12, 12, 18),
                    TextSize = 10,
                    Visible = false,
                    ZIndex = Base + 4,
                    Parent = Row.Frame,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Row.Badge,
                })
                Row.Sub = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(48, 22),
                    Size = UDim2.new(1, -164, 0, 14),
                    Text = "",
                    TextSize = 12,
                    TextTransparency = 0.4,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 3,
                    Parent = Row.Frame,
                })
                Row.Right = New("TextLabel", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.new(1, -10, 0, 5),
                    Size = UDim2.fromOffset(108, 17),
                    Text = "",
                    TextSize = 13,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    ZIndex = Base + 3,
                    Parent = Row.Frame,
                })
                Row.Time = New("TextLabel", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(1, -10, 0, 22),
                    Size = UDim2.fromOffset(108, 14),
                    Text = "",
                    TextSize = 11,
                    TextTransparency = 0.5,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    ZIndex = Base + 3,
                    Parent = Row.Frame,
                })
                return Row
            end
    
            local function Resize()
                local Count = math.max(Feed.Count, 1)
                Holder.Size = UDim2.new(1, 0, 0, Count * RowHeight + (Count - 1) * Gap)
                Groupbox:Resize()
            end
    
            function Feed:SetData(List)
                List = List or {}
                local Count = math.min(#List, MaxRows)
                local Seen = {}
                for Index = 1, Count do
                    local Entry = List[Index]
                    local Row = Feed.Rows[Index]
                    if not Row then
                        Row = MakeRow(Index)
                        Feed.Rows[Index] = Row
                    end
                    local Color = WidgetColor(Entry.Color, Library.Scheme.AccentColor)
                    Row.Bar.BackgroundColor3 = Color
                    Row.Tint.BackgroundColor3 = Color
                    Row.IconStroke.Color = Color
                    WidgetIcon(Row.Icon, Entry.Image, Color)
                    local Title = WidgetEscape(Entry.Title or "")
                    if typeof(Entry.Count) == "number" and Entry.Count > 1 then
                        Title ..= string.format('  <font transparency="0.35">x%d</font>', Entry.Count)
                    end
                    Row.Title.Text = Title
                    Row.Sub.Text = tostring(Entry.Sub or "")
                    Row.Right.Text = string.format('<font color="#%s">%s</font>', Color:ToHex(), WidgetEscape(Entry.Right or ""))
                    Row.Time.Text = WidgetAge(Entry.At)
                    if Entry.Badge and Entry.Badge ~= "" then
                        local BadgeColor = WidgetColor(Entry.BadgeColor, Library.Scheme.AccentColor)
                        local TitleWidth = Library:GetTextBounds(Title, GetBoldFont(), 14)
                        local Room = WidgetWidth(Row.Frame, 260) - 164
                        local BadgeWidth = Library:GetTextBounds(tostring(Entry.Badge), GetBoldFont(), 10) + 12
                        Row.Badge.Text = tostring(Entry.Badge)
                        Row.Badge.BackgroundColor3 = BadgeColor
                        Row.Badge.Size = UDim2.fromOffset(BadgeWidth, 15)
                        Row.Badge.Position = UDim2.fromOffset(48 + math.min(TitleWidth, math.max(Room - BadgeWidth - 8, 0)) + 8, 6)
                        Row.Title.Size = UDim2.new(1, -164 - BadgeWidth - 6, 0, 17)
                        Row.Badge.Visible = true
                    else
                        Row.Badge.Visible = false
                        Row.Title.Size = UDim2.new(1, -164, 0, 17)
                    end
                    local Key = Entry.Id
                    if Key ~= nil then
                        Seen[Key] = true
                    end
                    if Key ~= nil and Feed.Primed and not Feed.Seen[Key] then
                        Row.Flash.BackgroundColor3 = Color
                        Row.Flash.BackgroundTransparency = 0.45
                        WidgetTween(Row.Flash, 1.1, { BackgroundTransparency = 1 })
                        Row.IconScale.Scale = 0.55
                        WidgetTween(Row.IconScale, 0.5, { Scale = 1 }, Enum.EasingStyle.Back)
                    end
                    Row.Frame.Visible = true
                end
                for Index = Count + 1, #Feed.Rows do
                    Feed.Rows[Index].Frame.Visible = false
                end
                Feed.Seen = Seen
                Feed.Primed = true
                Feed.Count = Count
                EmptyLabel.Visible = Count == 0
                Resize()
            end
    
            function Feed:SetVisible(Visible: boolean)
                Feed.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Feed.Holder = Holder
            Resize()
            table.insert(Groupbox.Elements, Feed)
            if Idx then
                Options[Idx] = Feed
            end
            return Feed
        end
    
