                Visible = Info.Detail ~= false,
                Parent = Holder,
            })
    
            local function MakeTile()
                local Tile = {}
                Tile.Button = New("TextButton", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 0.1,
                    Text = "",
                    Size = UDim2.fromOffset(TileSize, TileHeight),
                    ZIndex = Base + 2,
                    Parent = TilesFrame,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 9),
                    Parent = Tile.Button,
                })
                Tile.Stroke = New("UIStroke", {
                    Color = Color3.new(1, 1, 1),
                    Thickness = 1,
                    Transparency = 0.5,
                    Parent = Tile.Button,
                })
                Tile.Glow = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = Library.Scheme.AccentColor,
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.new(1, 6, 1, 6),
                    ZIndex = Base + 1,
                    Parent = Tile.Button,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 12),
                    Parent = Tile.Glow,
                })
                Tile.Tint = New("Frame", {
                    BackgroundColor3 = Color3.new(1, 1, 1),
                    BackgroundTransparency = 0.88,
                    Size = UDim2.new(1, 0, 0.62, 0),
                    ZIndex = Base + 2,
                    Parent = Tile.Button,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 9),
                    Parent = Tile.Tint,
                })
                New("UIGradient", {
                    Rotation = 90,
                    Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 0),
                        NumberSequenceKeypoint.new(1, 1),
                    }),
                    Parent = Tile.Tint,
                })
                Tile.Icon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0, 6),
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromOffset(TileSize - 18, TileSize - 18),
                    ZIndex = Base + 3,
                    Parent = Tile.Button,
                })
                Tile.Caption = New("TextLabel", {
                    AnchorPoint = Vector2.new(0, 1),
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.new(0, 2, 1, -4),
                    Size = UDim2.new(1, -4, 0, 13),
                    Text = "",
                    TextSize = 11,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = Base + 3,
                    Parent = Tile.Button,
                })
                Tile.Mark = New("Frame", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundColor3 = Library.Scheme.AccentColor,
                    Position = UDim2.new(1, 4, 0, -4),
                    Size = UDim2.fromOffset(16, 16),
                    Visible = false,
                    ZIndex = Base + 5,
                    Parent = Tile.Button,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Tile.Mark,
                })
                Tile.MarkIcon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(10, 10),
                    ZIndex = Base + 6,
                    Parent = Tile.Mark,
                })
                Tile.Button.MouseButton1Click:Connect(function()
                    local Item = Tile.Item
                    if not Item then
                        return
                    end
                    Grid.Selected = Item.Id
                    if Item.Detail then
                        Detail.Text = tostring(Item.Detail)
                    end
                    if Info.Clicked then
                        Library:SafeCallback(Info.Clicked, Item)
                    end
                    Grid:Render()
                end)
                return Tile
            end
    
            local function Layout()
                local Width = WidgetWidth(Holder, 260)
                Grid.Columns = math.max(3, math.floor((Width + Gap) / (TileSize + Gap)))
            end
    
            function Grid:Render()
                Layout()
                local Columns = Grid.Columns
                local PerPage = Columns * RowsPerPage
                local Total = #Grid.Items
                Grid.Pages = math.max(1, math.ceil(Total / PerPage))
                Grid.Page = math.clamp(Grid.Page, 1, Grid.Pages)
                local First = (Grid.Page - 1) * PerPage
                local Shown = math.min(PerPage, math.max(Total - First, 0))
                local Pulse = false
                for Slot = 1, math.max(Shown, #Grid.Tiles) do
                    local Item = if Slot <= Shown then Grid.Items[First + Slot] else nil
                    local Tile = Grid.Tiles[Slot]
                    if Item and not Tile then
                        Tile = MakeTile()
                        Grid.Tiles[Slot] = Tile
                    end
                    if Tile then
                        Tile.Item = Item
                        if Item then
                            local Column = (Slot - 1) % Columns
                            local Row = math.floor((Slot - 1) / Columns)
                            Tile.Button.Position = UDim2.new(Column / Columns, Column * Gap / Columns, 0, Row * (TileHeight + Gap))
                            Tile.Button.Size = UDim2.new(1 / Columns, -(Columns - 1) * Gap / Columns, 0, TileHeight)
                            local Color = WidgetColor(Item.Color, Library.Scheme.OutlineColor)
                            WidgetIcon(Tile.Icon, Item.Image, Color)
                            Tile.Icon.ImageTransparency = if Item.Dim then 0.55 else 0
                            Tile.Tint.BackgroundColor3 = Color
                            Tile.Caption.Text = tostring(Item.Caption or "")
                            Tile.Caption.TextTransparency = if Item.Dim then 0.6 else 0.15
                            local Selected = Grid.Selected ~= nil and Grid.Selected == Item.Id
                            if Item.Highlight then
                                Pulse = true
                                Tile.Stroke.Color = Library.Scheme.AccentColor
                                Tile.Stroke.Thickness = 2
                                Tile.Stroke.Transparency = 0
                                Tile.Glow.BackgroundColor3 = Library.Scheme.AccentColor
                                if not Tile.Pulsing then
                                    Tile.Pulsing = true
                                    Tile.Glow.BackgroundTransparency = 0.6
                                    if Library.Animations ~= false then
                                        Tile.PulseTween = TweenService:Create(Tile.Glow, TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { BackgroundTransparency = 0.9 })
                                        Tile.PulseTween:Play()
                                    end
                                end
                            else
                                Tile.Stroke.Color = if Selected then Library.Scheme.FontColor else Color
                                Tile.Stroke.Thickness = if Selected then 1.5 else 1
                                Tile.Stroke.Transparency = if Selected then 0.2 elseif Item.Dim then 0.75 else 0.45
                                if Tile.Pulsing then
                                    Tile.Pulsing = false
                                    if Tile.PulseTween then
                                        pcall(Tile.PulseTween.Cancel, Tile.PulseTween)
                                        Tile.PulseTween = nil
                                    end
                                end
                                Tile.Glow.BackgroundTransparency = 1
                            end
                            local Mark = Item.Mark
                            if Mark then
                                Tile.Mark.BackgroundColor3 = WidgetColor(Item.MarkColor, Library.Scheme.AccentColor)
                                WidgetIcon(Tile.MarkIcon, Mark, Color3.fromRGB(12, 12, 18))
                                Tile.Mark.Visible = true
                            else
                                Tile.Mark.Visible = false
                            end
                            Tile.Button.Visible = true
                        else
                            Tile.Button.Visible = false
                            if Tile.PulseTween then
                                pcall(Tile.PulseTween.Cancel, Tile.PulseTween)
                                Tile.PulseTween = nil
                            end
                            Tile.Pulsing = false
                        end
                    end
                end
                Grid.Pulsing = Pulse
                local RowsShown = math.max(1, math.ceil(Shown / Columns))
                local TilesHeight = if Shown > 0 then RowsShown * TileHeight + (RowsShown - 1) * Gap else 34
                TilesFrame.Size = UDim2.new(1, 0, 0, TilesHeight)
                EmptyLabel.Visible = Shown == 0
                Pager.Visible = Grid.Pages > 1
                PageLabel.Text = string.format("%d/%d", Grid.Page, Grid.Pages)
                PrevButton.TextTransparency = if Grid.Page > 1 then 0 else 0.7
                NextButton.TextTransparency = if Grid.Page < Grid.Pages then 0 else 0.7
                local DetailHeight = if Detail.Visible and Detail.Text ~= "" then 34 else 0
                Detail.Position = UDim2.fromOffset(0, Top + TilesHeight + 8)
                Holder.Size = UDim2.new(1, 0, 0, Top + TilesHeight + (if DetailHeight > 0 then 8 + DetailHeight else 0))
                Groupbox:Resize()
            end
    
            PrevButton.MouseButton1Click:Connect(function()
                if Grid.Page > 1 then
                    Grid.Page -= 1
                    Grid:Render()
                end
            end)
            NextButton.MouseButton1Click:Connect(function()
                if Grid.Page < Grid.Pages then
                    Grid.Page += 1
                    Grid:Render()
                end
            end)
    
            function Grid:SetItems(Items)
                Grid.Items = Items or {}
                Grid:Render()
            end
    
            function Grid:SetSummary(Text: string)
                Summary.Text = tostring(Text or "")
            end
    
            function Grid:SetDetail(Text: string)
                Detail.Text = tostring(Text or "")
                Grid:Render()
            end
    
            function Grid:SetFilter(Value: string)
                Grid.Filter = Value
                if Grid.FilterPicker then
                    Grid.FilterPicker:Set(Value)
                end
            end
    
            function Grid:ShowItem(Id: any)
                local Columns = Grid.Columns
                local PerPage = Columns * RowsPerPage
                for Index, Item in Grid.Items do
                    if Item.Id == Id then
                        Grid.Page = math.floor((Index - 1) / PerPage) + 1
                        Grid:Render()
                        return true
                    end
                end
                return false
            end
    
            function Grid:SetVisible(Visible: boolean)
                Grid.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            local LastColumns = 0
            Grid.SizeConnection = Holder:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                Layout()
                if Grid.Columns ~= LastColumns then
                    LastColumns = Grid.Columns
                    Grid:Render()
                end
            end)
    
            Grid.Holder = Holder
            Grid.Detail = Detail
            Grid.TilesFrame = TilesFrame
            Grid:Render()
            table.insert(Groupbox.Elements, Grid)
            if Idx then
                Options[Idx] = Grid
            end
            return Grid
        end
    
        function Funcs:AddGoals(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
                Info = Idx
                Idx = nil
            end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local CardHeight = Info.CardHeight or 72
            local RingSize = Info.RingSize or 56
            local TickCount = Info.Ticks or 40
            local Gap = 6
    
            local Goals = {
                Type = "Goals",
                Destroyed = false,
                Visible = true,
                Cards = {},
                Count = 0,
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 40),
                Parent = Container,
            })
            local Base = Holder.ZIndex
    
            local EmptyLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 40),
                Text = Info.EmptyText or "No goals yet",
                TextSize = 13,
                TextTransparency = 0.45,
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Holder,
            })
    
            local function PaintRing(Card, Progress: number)
                local Filled = math.clamp(math.floor(Progress * TickCount + 0.5), 0, TickCount)
                if Progress > 0 and Filled == 0 then
                    Filled = 1
                end
                local Color = Card.Color or Library.Scheme.AccentColor
                local Empty = Library.Scheme.OutlineColor
                local Bright = Color:Lerp(Color3.new(1, 1, 1), 0.45)
                for Index, Tick in Card.Ticks do
                    if Index <= Filled then
                        Tick.BackgroundColor3 = if Index == Filled and Filled < TickCount then Bright else Color:Lerp(Color3.new(0, 0, 0), 0.22 * (1 - Index / TickCount))
                        Tick.BackgroundTransparency = 0
                    else
                        Tick.BackgroundColor3 = Empty
                        Tick.BackgroundTransparency = 0.25
                    end
                end
                Card.Shown = Progress
            end
    
            local function AnimateRing(Card, Target: number)
                Card.Target = Target
                local From = Card.Shown or 0
                if Library.Animations == false or math.abs(Target - From) < 0.004 then
                    PaintRing(Card, Target)
                    return
                end
                Card.Token = (Card.Token or 0) + 1
                local Token = Card.Token
                task.spawn(function()
                    local Steps = 18
                    for Step = 1, Steps do
                        if Card.Token ~= Token or Goals.Destroyed then
                            return
                        end
                        local Alpha = 1 - (1 - Step / Steps) ^ 3
                        PaintRing(Card, From + (Target - From) * Alpha)
                        task.wait(0.025)
                    end
                end)
            end
    
            local function MakeCard(Index: number)
                local Card = { Ticks = {} }
                Card.Frame = New("Frame", {
                    BackgroundColor3 = "MainColor",
                    BackgroundTransparency = 0.12,
                    Position = UDim2.fromOffset(0, (Index - 1) * (CardHeight + Gap)),
                    Size = UDim2.new(1, 0, 0, CardHeight),
                    Parent = Holder,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 10),
                    Parent = Card.Frame,
                })
                Card.Stroke = New("UIStroke", {
                    Color = Library.Scheme.OutlineColor,
                    Transparency = 0.3,
                    Parent = Card.Frame,
                })
                Card.Ring = New("Frame", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 9, 0.5, 0),
                    Size = UDim2.fromOffset(RingSize, RingSize),
                    ZIndex = Base + 1,
                    Parent = Card.Frame,
                })
                local Radius = RingSize / 2 - 4
                for Tick = 1, TickCount do
                    local Angle = (Tick - 0.5) / TickCount * math.pi * 2
                    local Frame = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        BackgroundColor3 = Library.Scheme.OutlineColor,
                        Position = UDim2.new(0.5, math.sin(Angle) * Radius, 0.5, -math.cos(Angle) * Radius),
                        Rotation = math.deg(Angle),
                        Size = UDim2.fromOffset(3, 8),
                        ZIndex = Base + 2,
                        Parent = Card.Ring,
                    })
                    New("UICorner", {
                        CornerRadius = UDim.new(1, 0),
                        Parent = Frame,
                    })
                    Card.Ticks[Tick] = Frame
                end
                Card.Disc = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = Color3.new(1, 1, 1),
                    BackgroundTransparency = 0.86,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(RingSize - 24, RingSize - 24),
                    ZIndex = Base + 2,
                    Parent = Card.Ring,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Card.Disc,
                })
                Card.Icon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromOffset(20, 20),
                    ZIndex = Base + 3,
                    Parent = Card.Ring,
                })
                local TextLeft = RingSize + 20
                Card.Title = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.fromOffset(TextLeft, 10),
                    Size = UDim2.new(1, -TextLeft - 78, 0, 17),
                    Text = "",
                    TextSize = 14,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 2,
                    Parent = Card.Frame,
                })
                Card.Value = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(TextLeft, 29),
                    Size = UDim2.new(1, -TextLeft - 12, 0, 15),
                    Text = "",
                    TextSize = 13,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 2,
                    Parent = Card.Frame,
                })
                Card.Note = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(TextLeft, 46),
                    Size = UDim2.new(1, -TextLeft - 12, 0, 14),
                    Text = "",
                    TextSize = 12,
                    TextTransparency = 0.45,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Base + 2,
                    Parent = Card.Frame,
                })
                Card.Percent = New("TextLabel", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.new(1, -32, 0, 8),
                    Size = UDim2.fromOffset(52, 20),
                    Text = "",
                    TextSize = 17,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    ZIndex = Base + 2,
                    Parent = Card.Frame,
                })
                Card.Remove = New("ImageButton", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(1, -9, 0, 11),
                    Size = UDim2.fromOffset(14, 14),
                    ImageTransparency = 0.5,
                    ZIndex = Base + 3,
                    Parent = Card.Frame,
                })
                WidgetIcon(Card.Remove, "x", Library.Scheme.FontColor)
                Card.Remove.MouseEnter:Connect(function()
                    Card.Remove.ImageTransparency = 0
                end)
                Card.Remove.MouseLeave:Connect(function()
                    Card.Remove.ImageTransparency = 0.5
                end)
                Card.Remove.MouseButton1Click:Connect(function()
                    if Card.Id ~= nil and Info.Removed then
                        Library:SafeCallback(Info.Removed, Card.Id)
                    end
                end)
                return Card
            end
    
            local function Resize()
                local Count = Goals.Count
                if Count == 0 then
                    Holder.Size = UDim2.new(1, 0, 0, 40)
                else
                    Holder.Size = UDim2.new(1, 0, 0, Count * CardHeight + (Count - 1) * Gap)
                end
                Groupbox:Resize()
            end
    
            function Goals:SetData(List)
                List = List or {}
                local Count = #List
                for Index = 1, Count do
                    local Entry = List[Index]
                    local Card = Goals.Cards[Index]
                    if not Card then
                        Card = MakeCard(Index)
                        Goals.Cards[Index] = Card
                    end
                    local Color = WidgetColor(Entry.Color, Library.Scheme.AccentColor)
                    local Changed = Card.Id ~= Entry.Id
                    Card.Id = Entry.Id
                    Card.Color = Color
                    Card.Disc.BackgroundColor3 = Color
                    WidgetIcon(Card.Icon, Entry.Icon, Color)
                    Card.Title.Text = WidgetEscape(Entry.Title or "")
                    Card.Value.Text = tostring(Entry.Value or "")
                    Card.Note.Text = tostring(Entry.Note or "")
                    local Progress = math.clamp(tonumber(Entry.Progress) or 0, 0, 1)
                    if Entry.Done then
                        Progress = 1
                        Card.Percent.Text = '<font color="#60d696">\u{2713}</font>'
                        Card.Stroke.Color = Color
                        Card.Stroke.Transparency = 0.25
                        if not Card.WasDone and not Changed and Library.Animations ~= false then
                            Card.Stroke.Transparency = 0
                            Card.Stroke.Thickness = 2
                            TweenService:Create(Card.Stroke, TweenInfo.new(1.2, Enum.EasingStyle.Quint), { Thickness = 1, Transparency = 0.25 }):Play()
                        end
                    else
                        Card.Percent.Text = string.format("%d%%", math.floor(Progress * 100))
                        Card.Stroke.Color = Library.Scheme.OutlineColor
                        Card.Stroke.Transparency = 0.3
                    end
                    Card.WasDone = Entry.Done == true
                    if Changed then
                        Card.Shown = 0
                        Card.Token = (Card.Token or 0) + 1
                        PaintRing(Card, 0)
                    end
                    AnimateRing(Card, Progress)
                    Card.Frame.Visible = true
                end
                for Index = Count + 1, #Goals.Cards do
                    local Card = Goals.Cards[Index]
                    Card.Frame.Visible = false
                    Card.Id = nil
                end
                Goals.Count = Count
                EmptyLabel.Visible = Count == 0
                Resize()
            end
    
            function Goals:SetVisible(Visible: boolean)
                Goals.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Library:OnThemeChanged(function()
                for _, Card in Goals.Cards do
                    if Card.Frame.Visible then
                        PaintRing(Card, Card.Target or Card.Shown or 0)
                    end
                end
            end)
    
            Goals.Holder = Holder
            Resize()
            table.insert(Groupbox.Elements, Goals)
            if Idx then
                Options[Idx] = Goals
            end
            return Goals
        end
    
        function Library:ShowWizard(Info)
            Info = Info or {}
            local Host = Library.Window and Library.Window.MainFrame
            if not Host then
                return nil
            end
            if Library.ActiveWizard then
                pcall(Library.ActiveWizard.Close, Library.ActiveWizard, true)
            end
    
            local Steps = Info.Steps or {}
            local Wizard = {
                Step = 1,
                Values = {},
                Closed = false,
                Cards = {},
            }
    
            for Index, Step in Steps do
                local Key = Step.Id or Index
                if Step.Multi then
                    local Set = {}
                    for _, Id in Step.Default or {} do
                        Set[Id] = true
                    end
                    Wizard.Values[Key] = Set
                else
                    Wizard.Values[Key] = if Step.Default ~= nil then Step.Default elseif Step.Choices and Step.Choices[1] then Step.Choices[1].Id else nil
                end
            end
    
            local Scale = math.max(Library.DPIScale, 0.01)
            local HostWidth = Host.AbsoluteSize.X / Scale
            local HostHeight = Host.AbsoluteSize.Y / Scale
            if HostWidth < 100 then
                HostWidth = 720
            end
            if HostHeight < 100 then
                HostHeight = 520
            end
            local Width = math.clamp(HostWidth - 36, 280, 580)
            local Height = math.clamp(HostHeight - 36, 250, 430)
            local Wide = Width >= 440
    
            local Overlay = New("TextButton", {
                AutoButtonColor = false,
                BackgroundColor3 = "DarkColor",
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                ZIndex = 9100,
                Parent = Host,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius or 8),
                Parent = Overlay,
            })
            WidgetTween(Overlay, 0.25, { BackgroundTransparency = 0.3 })
    
            local Card = New("TextButton", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                AutoButtonColor = false,
                BackgroundColor3 = "BackgroundColor",
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(Width, Height),
                Text = "",
                ZIndex = 1,
                Parent = Overlay,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 12),
                Parent = Card,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Parent = Card,
            })
            local CardScale = New("UIScale", {
                Scale = 0.94,
                Parent = Card,
            })
            WidgetTween(CardScale, 0.3, { Scale = 1 }, Enum.EasingStyle.Back)
    
            local Glow = New("Frame", {
                BackgroundColor3 = "AccentColor",
                BackgroundTransparency = 0.82,
                Size = UDim2.new(1, 0, 0, 90),
                ZIndex = 1,
                Parent = Card,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 12),
                Parent = Glow,
            })
            New("UIGradient", {
                Rotation = 90,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = Glow,
            })
    
            local Visible = {}
            local function VisibleSteps()
                table.clear(Visible)
                for Index, Step in Steps do
                    local Show = true
                    if typeof(Step.Visible) == "function" then
                        local Ok, Result = pcall(Step.Visible, Wizard.Values)
                        Show = not Ok or Result ~= false
                    end
                    if Show then
                        table.insert(Visible, Index)
                    end
                end
                return Visible
            end
    
            local Segments = New("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(20, 16),
                Size = UDim2.new(1, -40, 0, 4),
                ZIndex = 2,
                Parent = Card,
            })
            local StepLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.fromOffset(20, 28),
                Size = UDim2.new(1, -40, 0, 14),
                Text = "",
                TextColor3 = "AccentColor",
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 2,
                Parent = Card,
            })
            local TitleLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.fromOffset(20, 44),
                Size = UDim2.new(1, -40, 0, 22),
                Text = "",
                TextSize = 19,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 2,
                Parent = Card,
