        local Base64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local Base64Lookup = {}
        for Index = 1, 64 do
            Base64Lookup[string.byte(Base64Alphabet, Index)] = Index - 1
        end
    
        function Library.Base64Encode(Data: string): string
            local Out = {}
            for Index = 1, #Data, 3 do
                local A, B, C = string.byte(Data, Index, Index + 2)
                local Number = A * 65536 + (B or 0) * 256 + (C or 0)
                local D1 = Number // 262144 % 64
                local D2 = Number // 4096 % 64
                local D3 = Number // 64 % 64
                local D4 = Number % 64
                Out[#Out + 1] = string.sub(Base64Alphabet, D1 + 1, D1 + 1)
                    .. string.sub(Base64Alphabet, D2 + 1, D2 + 1)
                    .. (if B then string.sub(Base64Alphabet, D3 + 1, D3 + 1) else "=")
                    .. (if C then string.sub(Base64Alphabet, D4 + 1, D4 + 1) else "=")
            end
            return table.concat(Out)
        end
    
        function Library.Base64Decode(Data: string): string?
            Data = string.gsub(tostring(Data or ""), "[^%w%+/=]", "")
            if #Data % 4 ~= 0 then
                return nil
            end
            local Out = {}
            for Index = 1, #Data, 4 do
                local C1, C2, C3, C4 = string.byte(Data, Index, Index + 3)
                local V1, V2 = Base64Lookup[C1], Base64Lookup[C2]
                local V3 = if C3 == 61 then nil else Base64Lookup[C3]
                local V4 = if C4 == 61 then nil else Base64Lookup[C4]
                if V1 == nil or V2 == nil or (C3 ~= 61 and V3 == nil) or (C4 ~= 61 and V4 == nil) then
                    return nil
                end
                local Number = V1 * 262144 + V2 * 4096 + (V3 or 0) * 64 + (V4 or 0)
                Out[#Out + 1] = string.char(Number // 65536 % 256)
                if V3 ~= nil then
                    Out[#Out + 1] = string.char(Number // 256 % 256)
                end
                if V4 ~= nil then
                    Out[#Out + 1] = string.char(Number % 256)
                end
            end
            return table.concat(Out)
        end
    
        local ShareTypes = { Toggle = true, Slider = true, Dropdown = true, Input = true }
    
        local function ShareEligible(Index: any, Element: any, Ignore: any): boolean
            if typeof(Index) ~= "string" or typeof(Element) ~= "table" then
                return false
            end
            if not ShareTypes[Element.Type] then
                return false
            end
            if Ignore and Ignore[Index] then
                return false
            end
            if Library.ShareIgnore and Library.ShareIgnore[Index] then
                return false
            end
            if string.sub(Index, 1, 6) == "Corvus" or string.sub(Index, 1, 12) == "SaveManager_" then
                return false
            end
            return true
        end
    
        local function ShareDropdownKeys(Element: any): { string }
            local Keys = {}
            if typeof(Element.Value) == "table" then
                for Key, On in Element.Value do
                    if On then
                        table.insert(Keys, tostring(Key))
                    end
                end
            end
            table.sort(Keys)
            return Keys
        end
    
        local function ShareDefaultKeys(Element: any): { string }
            local Keys = {}
            for _, Key in Element.Default or {} do
                table.insert(Keys, tostring(Key))
            end
            table.sort(Keys)
            return Keys
        end
    
        local function ShareSnapshot(Element: any): (any, boolean)
            local Kind = Element.Type
            if Kind == "Toggle" then
                return Element.Value == true, (Element.Value == true) ~= (Element.Default == true)
            elseif Kind == "Slider" then
                return Element.Value, tostring(Element.Value) ~= tostring(Element.Default)
            elseif Kind == "Input" then
                local Value = tostring(Element.Value or "")
                if string.find(Value, "://", 1, true) then
                    return nil, false
                end
                return Value, Value ~= tostring(Element.Default or "")
            elseif Kind == "Dropdown" then
                if Element.Multi then
                    local Keys = ShareDropdownKeys(Element)
                    return Keys, table.concat(Keys, "\0") ~= table.concat(ShareDefaultKeys(Element), "\0")
                end
                local Value = if Element.Value == nil then false else Element.Value
                local Default = if Element.Default and Element.Default[1] ~= nil then Element.Default[1] else false
                return Value, Value ~= Default
            end
            return nil, false
        end
    
        function Library:ResetHubOptions(Ignore: any): (boolean, any)
        	local Ok, Json = pcall(HttpService.JSONEncode, HttpService, { v = 1, g = game.GameId, d = {} })
        	if not Ok then
        		return false, "Could not reset"
        	end
        	return Library:ImportShareCode("CORVUS-" .. Library.Base64Encode(Json), Ignore)
        end

        function Library:AskResetHubOptions(Ignore: any)
        	return Library:ShowModal({
        		Icon = "rotate-ccw",
        		Title = "Reset all options to defaults?",
        		Text = "Every toggle, dropdown, slider and input of this hub goes back to its default value. Saved configs are not deleted.",
        		ConfirmText = "Reset",
        		CancelText = "Cancel",
        		OnConfirm = function()
        			local Ok, Result = Library:ResetHubOptions(Ignore)
        			Library:Notify({ Title = "Reset Hub Options", Description = if Ok then string.format("%d options reset", Result) else tostring(Result), Time = 4 })
        		end,
        	})
        end

        function Library:ExportShareCode(Ignore: any): (string?, any)
            local Changed = {}
            local Count = 0
            local function Visit(List)
                for Index, Element in List do
                    if ShareEligible(Index, Element, Ignore) then
                        local Ok, Value, Differs = pcall(ShareSnapshot, Element)
                        if Ok and Differs and Value ~= nil then
                            Changed[Index] = Value
                            Count += 1
                        end
                    end
                end
            end
            Visit(Library.Toggles)
            Visit(Library.Options)
            local Ok, Json = pcall(HttpService.JSONEncode, HttpService, { v = 1, g = game.GameId, d = Changed })
            if not Ok then
                return nil, "Could not encode your settings"
            end
            return "CORVUS-" .. Library.Base64Encode(Json), Count
        end
    
        function Library:ImportShareCode(Code: string, Ignore: any): (boolean, any)
            Code = tostring(Code or "")
            Code = string.gsub(Code, "%s", "")
            local Body = string.match(Code, "^CORVUS%-(.+)$")
            if not Body then
                return false, "That is not a Corvus share code"
            end
            local Json = Library.Base64Decode(Body)
            if not Json then
                return false, "The code is damaged, copy it again"
            end
            local Ok, Data = pcall(HttpService.JSONDecode, HttpService, Json)
            if not Ok or typeof(Data) ~= "table" or typeof(Data.d) ~= "table" then
                return false, "The code is damaged, copy it again"
            end
            if Data.g and tonumber(Data.g) and tonumber(Data.g) ~= game.GameId then
                return false, "This code is for a different game"
            end
            local Applied = 0
            local function Apply(Element: any, Value: any)
                local Kind = Element.Type
                if Kind == "Toggle" then
                    Element:SetValue(Value == true)
                elseif Kind == "Slider" then
                    local Number = tonumber(Value)
                    if Number then
                        Element:SetValue(Number)
                    end
                elseif Kind == "Input" then
                    Element:SetValue(tostring(Value or ""))
                elseif Kind == "Dropdown" then
                    if Element.Multi then
                        local Set = {}
                        if typeof(Value) == "table" then
                            for _, Key in Value do
                                Set[Key] = true
                            end
                        end
                        Element:SetValue(Set)
                    else
                        Element:SetValue(if Value == false then nil else Value)
                    end
                end
            end
            local function Visit(List)
                for Index, Element in List do
                    if ShareEligible(Index, Element, Ignore) then
                        local Value = Data.d[Index]
                        if Value ~= nil then
                            if pcall(Apply, Element, Value) then
                                Applied += 1
                            end
                        else
                            local Kind = Element.Type
                            local Default
                            if Kind == "Toggle" then
                                Default = Element.Default == true
                            elseif Kind == "Slider" then
                                Default = Element.Default
                            elseif Kind == "Input" then
                                Default = tostring(Element.Default or "")
                                if string.find(tostring(Element.Value or ""), "://", 1, true) then
                                    Default = nil
                                end
                            elseif Kind == "Dropdown" then
                                Default = if Element.Multi then ShareDefaultKeys(Element) elseif Element.Default and Element.Default[1] ~= nil then Element.Default[1] else false
                            end
                            if Default ~= nil then
                                local _, Current, Differs = pcall(ShareSnapshot, Element)
                                if Differs and Current ~= nil then
                                    pcall(Apply, Element, Default)
                                end
                            end
                        end
                    end
                end
            end
            Visit(Library.Toggles)
            Visit(Library.Options)
            if typeof(Library.SyncMirrors) == "function" then
                pcall(Library.SyncMirrors, Library)
            end
            return true, Applied
        end
    
        local function GroupDigits(Value: number?): string
            if typeof(Value) ~= "number" then
                return "?"
            end
            local Text = tostring(math.floor(Value))
            local Out = string.reverse(Text)
            Out = string.gsub(Out, "(%d%d%d)", "%1,")
            Out = string.reverse(Out)
            if string.sub(Out, 1, 1) == "," then
                Out = string.sub(Out, 2)
            end
            return Out
        end
    
        local CommunityState = { Fetching = false, Fetched = false, Listeners = {} }
        Library.CommunityState = CommunityState
    
        local function FetchCommunity(Code: string?)
            if not Code or CommunityState.Fetching or CommunityState.Fetched then
                return
            end
            CommunityState.Fetching = true
            task.spawn(function()
                local CommunityT0 = os.clock()
local Data = HttpRequestJSON(string.format("https://discord.com/api/v10/invites/%s?with_counts=true", Code))
CorvusLoadTimes.community = CorvusLoadTimes.community or (os.clock() - CommunityT0)
                CommunityState.Fetching = false
                if typeof(Data) ~= "table" or Library.Unloaded then
                    return
                end
                CommunityState.Fetched = true
                CommunityState.Online = tonumber(Data.approximate_presence_count)
                CommunityState.Members = tonumber(Data.approximate_member_count)
                if typeof(Data.guild) == "table" and typeof(Data.guild.name) == "string" then
                    CommunityState.Name = Data.guild.name
                end
                CommunityState.Code = Code
                if typeof(Data.guild) == "table" and Data.guild.id and Data.guild.icon then
                    CommunityState.IconUrl = string.format("https://cdn.discordapp.com/icons/%s/%s.png?size=128", tostring(Data.guild.id), tostring(Data.guild.icon))
                end
                for _, Listener in CommunityState.Listeners do
                    task.spawn(Listener)
                end
            end)
        end
    
        Library.FetchCommunity = FetchCommunity

