                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Base + 3,
                Parent = Card,
            })
            local Stats = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(60, 29),
                Size = UDim2.new(1, -130, 0, 16),
                Text = tostring(Info.Description or "Join the community"),
                TextSize = 12,
                TextTransparency = 0.3,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Base + 3,
                Parent = Card,
            })
            local Join = New("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Blurple,
                FontFace = GetBoldFont,
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(62, 30),
                Text = "Join",
                TextColor3 = Color3.new(1, 1, 1),
                TextSize = 13,
                ZIndex = Base + 3,
                Parent = Card,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 8),
                Parent = Join,
            })
            Strip.JoinButton = Join
            Strip.StatsLabel = Stats
    
            local function Paint()
                if Strip.Destroyed then
                    return
                end
                if CommunityState.Name and not Info.Title then
                    Title.Text = CommunityState.Name
                end
                if CommunityState.Online or CommunityState.Members then
                    Stats.Text = string.format('<font color="#60d696">\u{25CF}</font> %s online <font transparency="0.4">\u{00B7}</font> %s members', GroupDigits(CommunityState.Online), GroupDigits(CommunityState.Members))
                end
            end
            table.insert(CommunityState.Listeners, Paint)
            Paint()
    
            Join.MouseButton1Click:Connect(function()
                if Strip.Invite then
                    Library:CopyToClipboard(Strip.Invite, "Discord invite copied")
                end
                if Strip.Code then
                    task.spawn(Library.OpenDiscordInvite, Library, Strip.Code)
                end
                Join.Text = "Copied"
                task.delay(1.6, function()
                    if not Strip.Destroyed then
                        Join.Text = "Join"
                    end
                end)
            end)
    
            function Strip:SetVisible(Visible: boolean)
                Strip.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            FetchCommunity(Code)
            Strip.Holder = Holder
            table.insert(Groupbox.Elements, Strip)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Strip
            end
            return Strip
        end
    
        function Funcs:AddDonateBoard(Idx, Info)
            if self.Destroyed then return nil end
    
            if typeof(Idx) == "table" and Info == nil then
