                Position = UDim2.fromOffset(0, 32),
                Size = UDim2.new(1, 0, 0, 62),
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 10),
                Parent = Card,
            })
            local Stroke = New("UIStroke", {
                Color = "AccentColor",
                Transparency = 0.55,
                Parent = Card,
            })
            local Tint = New("Frame", {
                BackgroundColor3 = "AccentColor",
