                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = Tint,
            })
            local Coin = New("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = Color3.new(1, 1, 1),
                Position = UDim2.new(0, 10, 0.5, 0),
                Size = UDim2.fromOffset(36, 36),
                ZIndex = Base + 2,
                Parent = Card,
            })
            local CoinImage = New("ImageLabel", {
                BackgroundTransparency = 1,
                ImageColor3 = Color3.new(1, 1, 1),
                ScaleType = Enum.ScaleType.Fit,
                Size = UDim2.fromScale(1, 1),
                Visible = false,
                ZIndex = Base + 4,
                Parent = Coin,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Coin,
            })
            local CoinText = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextColor3 = Color3.new(1, 1, 1),
                TextSize = 11,
                ZIndex = Base + 3,
                Parent = Coin,
            })
            local Name = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.fromOffset(54, 10),
                Size = UDim2.new(1, -140, 0, 17),
                Text = "",
                TextSize = 14,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Base + 3,
                Parent = Card,
            })
            local Address = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = Font.fromEnum(Enum.Font.RobotoMono),
                Position = UDim2.fromOffset(54, 30),
                Size = UDim2.new(1, -140, 0, 16),
                Text = "",
                TextSize = 12,
                TextTransparency = 0.2,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Base + 3,
                Parent = Card,
            })
            local Copy = New("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = "AccentColor",
                FontFace = GetBoldFont,
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(70, 30),
                Text = "Copy",
                TextColor3 = "BackgroundColor",
                TextSize = 13,
                ZIndex = Base + 3,
                Parent = Card,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 8),
                Parent = Copy,
            })
            local Note = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(2, 98),
                Size = UDim2.new(1, -4, 0, 16),
                Text = "",
                TextSize = 12,
                TextTransparency = 0.45,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Holder,
            })
            Board.CopyButton = Copy
            Board.AddressLabel = Address
            Board.CoinImage = CoinImage
            Board.Tint = Tint
    
            local function Shorten(Text: string): string
                if #Text <= 26 or string.find(Text, "paypal", 1, true) then
                    return Text
                end
                return string.sub(Text, 1, 12) .. "\u{2026}" .. string.sub(Text, -10)
            end
    
            local function Paint()
                local Method = ById[Board.Selected]
                if not Method then
                    return
                end
                local Color = WidgetColor(Method.Color, Library.Scheme.AccentColor)
                local IconData = if Method.Icon then Library:GetCustomIcon(Method.Icon) else nil
                if IconData then
                    Library:ApplyLucideIcon(CoinImage, IconData)
                    CoinImage.ImageColor3 = Color3.new(1, 1, 1)
                    CoinImage.Visible = true
                    Coin.BackgroundTransparency = 1
                    CoinText.Text = ""
                else
                    CoinImage.Visible = false
                    Coin.BackgroundTransparency = 0
                    Coin.BackgroundColor3 = Color
                    CoinText.Text = tostring(Method.Symbol or string.sub(tostring(Method.Id), 1, 3))
                end
                Name.Text = string.format('%s  <font transparency="0.45">%s</font>', WidgetEscape(Method.Name or Method.Id), WidgetEscape(Method.Network or ""))
                Address.Text = WidgetEscape(Shorten(tostring(Method.Display or Method.Address or "")))
                Note.Text = tostring(Method.Note or "")
            end
    
            Board.Picker = Library:CreateSegmented(Holder, Labels, Board.Selected, function(Value)
                Board.Selected = Value
                Library.DonateSelected = Value
                Copy.Text = "Copy"
                Paint()
            end, { Height = 24, TextSize = 12 })
    
            Copy.MouseButton1Click:Connect(function()
                local Method = ById[Board.Selected]
                if not Method or not Method.Address then
                    return
                end
                Library:CopyToClipboard(Method.Address, string.format("%s %s copied", tostring(Method.Name or Method.Id), if Method.Link then "link" else "address"))
                Copy.Text = "Copied"
                task.delay(1.6, function()
                    if not Board.Destroyed then
                        Copy.Text = "Copy"
                    end
                end)
            end)
    
            function Board:Select(Id: string)
                if ById[Id] then
                    Board.Selected = Id
                    Board.Picker:Set(Id)
                    Paint()
                end
            end
    
            function Board:SetVisible(Visible: boolean)
                Board.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Paint()
            Board.Holder = Holder
            table.insert(Groupbox.Elements, Board)
            Groupbox:Resize()
            if Idx then
                Options[Idx] = Board
            end
            return Board
        end
    
        function Funcs:AddThemeGallery(Info)
            if self.Destroyed then return nil end
            Info = Info or {}
    
            local Groupbox = self
            local Container = Groupbox.Container
            local Themes = Info.Themes or Library:GetThemeNames()
            local Columns = Info.Columns or 2
            local CardHeight = Info.CardHeight or 56
            local Gap = 6
            local Rows = math.ceil(#Themes / Columns)
    
            local Gallery = {
                Cards = {},
                Callback = Info.Callback,
                Destroyed = false,
                Value = Info.Default,
                Visible = true,
                Type = "ThemeGallery",
            }
    
            local Holder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, Rows * CardHeight + math.max(Rows - 1, 0) * Gap + 2),
                Parent = Container,
            })
    
            local CheckIcon = Library:GetIcon("check")
    
            for Index, Name in Themes do
                local Entry = Library.CorvusThemes[Name]
                local Data = Entry and Entry[2]
                if typeof(Data) ~= "table" then
                    continue
                end
                local function Hex(Key: string): Color3
                    local Success, Color = pcall(Color3.fromHex, Data[Key])
                    return if Success then Color else Color3.new(1, 1, 1)
                end
    
                local Column = (Index - 1) % Columns
                local Row = (Index - 1) // Columns
                local Card = New("TextButton", {
                    AutoButtonColor = false,
                    BackgroundColor3 = Hex("BackgroundColor"),
                    LayoutOrder = Index,
                    Position = UDim2.new(Column / Columns, Column * Gap / Columns, 0, Row * (CardHeight + Gap) + 1),
                    Size = UDim2.new(1 / Columns, -Gap * (Columns - 1) / Columns, 0, CardHeight),
                    Text = "",
                    Parent = Holder,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 8),
                    Parent = Card,
                })
                local Stroke = New("UIStroke", {
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                    Color = Hex("OutlineColor"),
                    Thickness = 1,
                    Parent = Card,
                })
                local Scale = New("UIScale", {
                    Parent = Card,
                })
    
                local Strip = New("Frame", {
                    BackgroundColor3 = Hex("MainColor"),
                    Position = UDim2.fromOffset(7, 7),
                    Size = UDim2.new(1, -14, 0, 16),
                    Parent = Card,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 5),
                    Parent = Strip,
                })
                for DotIndex, Key in { "AccentColor", "FontColor", "OutlineColor" } do
                    local Dot = New("Frame", {
                        AnchorPoint = Vector2.new(0, 0.5),
                        BackgroundColor3 = Hex(Key),
                        Position = UDim2.new(0, 6 + (DotIndex - 1) * 9, 0.5, 0),
                        Size = UDim2.fromOffset(6, 6),
                        Parent = Strip,
                    })
                    New("UICorner", {
                        CornerRadius = UDim.new(1, 0),
                        Parent = Dot,
                    })
                end
                local Bar = New("Frame", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundColor3 = Hex("AccentColor"),
                    Position = UDim2.new(1, -6, 0.5, 0),
                    Size = UDim2.fromOffset(22, 5),
                    Parent = Strip,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = Bar,
                })
    
                local Label = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = GetMediumFont,
                    Position = UDim2.new(0, 9, 1, -24),
                    Size = UDim2.new(1, -34, 0, 16),
                    Text = (string.gsub(Name, "^Corvus%s+", "")),
                    TextColor3 = Hex("FontColor"),
                    TextSize = 13,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Parent = Card,
                })
                local Check = New("ImageLabel", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundTransparency = 1,
                    ImageColor3 = Hex("AccentColor"),
                    Position = UDim2.new(1, -9, 1, -16),
                    Size = UDim2.fromOffset(13, 13),
                    Visible = false,
                    Parent = Card,
                })
                if CheckIcon then
                    Library:ApplyLucideIcon(Check, CheckIcon)
                end
    
                Card.MouseEnter:Connect(function()
                    TweenService:Create(Scale, Library.TweenInfo, { Scale = 1.03 }):Play()
                end)
                Card.MouseLeave:Connect(function()
                    TweenService:Create(Scale, Library.TweenInfo, { Scale = 1 }):Play()
                end)
                Card.MouseButton1Click:Connect(function()
                    Gallery:SetValue(Name, true)
                end)
    
                Gallery.Cards[Name] = {
                    Card = Card,
                    Stroke = Stroke,
                    Check = Check,
                    Label = Label,
                    Accent = Hex("AccentColor"),
                    Outline = Hex("OutlineColor"),
                }
            end
    
            function Gallery:SetValue(Name: string?, Fire: boolean?)
                Gallery.Value = Name
                for CardName, Card in Gallery.Cards do
                    local Selected = CardName == Name
                    Card.Stroke.Color = if Selected then Card.Accent else Card.Outline
                    Card.Stroke.Thickness = if Selected then 1.8 else 1
                    Card.Check.Visible = Selected
                end
                if Fire and Name and Gallery.Callback then
                    Library:SafeCallback(Gallery.Callback, Name)
                end
            end
    
            function Gallery:SetVisible(Visible: boolean)
                Gallery.Visible = Visible
                Holder.Visible = Visible
                Groupbox:Resize()
            end
    
            Gallery:SetValue(Gallery.Value, false)
            Gallery.Holder = Holder
            Groupbox:Resize()
            return Gallery
        end
    
