                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                LayoutOrder = 2,
                Size = UDim2.fromScale(0, 1),
                Text = Info.ButtonText,
                TextColor3 = "WhiteColor",
                TextSize = 14,
                Parent = ActionContent,
            })
    
            local PulseTween = nil
            local function UpdatePulse()
                if PulseTween then
                    PulseTween:Cancel()
                    PulseTween = nil
                end
    
                local Online = string.lower(tostring(Card.Status)) == "online"
                StatusPulse.Visible = Online
                StatusPulse.Size = UDim2.fromOffset(12, 12)
                StatusPulse.BackgroundTransparency = 0.4
    
                if Online and Library.IconAnimations ~= false then
                    PulseTween = TweenService:Create(StatusPulse, TweenInfo.new(1.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, -1), {
                        Size = UDim2.fromOffset(24, 24),
                        BackgroundTransparency = 1,
                    })
                    PulseTween:Play()
                end
            end
    
            function Card:Layout()
                local Height = if StatsLabel.Visible then 195 else 179
                Holder.Size = UDim2.new(1, 0, 0, Height)
                Groupbox:Resize()
            end
    
            function Card:SetTitle(Text: string)
                Card.Title = tostring(Text)
                Card.Text = Card.Title
                TitleLabel.Text = Card.Title
    
                if AvatarInitial.Text ~= "" then
                    AvatarInitial.Text = string.upper(string.sub(Card.Title, 1, 1))
                end
            end
    
            function Card:SetDescription(Text: string)
                Card.Description = tostring(Text)
                DescriptionLabel.Text = Card.Description
            end
    
            function Card:SetButtonText(Text: string)
                Info.ButtonText = tostring(Text)
                ActionLabel.Text = Info.ButtonText
            end
    
            function Card:SetStatus(Status: string)
                Card.Status = Status
                local Color = GetStatusColor(Status)
                StatusDot.BackgroundColor3 = Color
                StatusPulse.BackgroundColor3 = Color
                UpdatePulse()
            end
    
            function Card:SetBanner(Value: any)
                if Value == nil or Value == "" then
                    Value = "none"
                end
                local FileName = "discord_" .. SafeFileName(Card.Code or Card.Title or "card") .. "_" .. SafeFileName(tostring(Value)) .. "_banner.png"
                local Icon = ResolveCardImage(Value, FileName)
    
                if Icon then
                    Library:ApplyLucideIcon(Banner, Icon)
                    Banner.BackgroundTransparency = 1
                    BannerGradient.Enabled = false
                else
                    Banner.Image = ""
                    Banner.BackgroundTransparency = 0
                    BannerGradient.Enabled = true
                end
            end
    
            function Card:SetAvatar(Value: any)
                if Value == nil or Value == "" then
                    Value = "none"
                end
                local FileName = "discord_" .. SafeFileName(Card.Code or Card.Title or "card") .. "_" .. SafeFileName(tostring(Value)) .. "_avatar.png"
                local Icon = ResolveCardImage(Value, FileName)
    
                if Icon then
                    Library:ApplyLucideIcon(Avatar, Icon)
                    if Value == "none" and Library.CorvusTint then
                        Library.Registry[Avatar] = Library.Registry[Avatar] or {}
                        Library.Registry[Avatar].ImageColor3 = Library.CorvusTint
                        Avatar.ImageColor3 = Library.CorvusTint()
                    elseif Library.Registry[Avatar] then
                        Library.Registry[Avatar].ImageColor3 = nil
                        Avatar.ImageColor3 = Color3.new(1, 1, 1)
                    end
                    Avatar.BackgroundTransparency = 1
                    AvatarInitial.Text = ""
                else
                    Avatar.Image = ""
                    Avatar.BackgroundTransparency = 0
                    AvatarInitial.Text = string.upper(string.sub(Card.Title or "", 1, 1))
                end
            end
    
            function Card:SetCounts(Online: number?, Members: number?)
                Card.Online = tonumber(Online)
                Card.Members = tonumber(Members)
    
                local Parts = {}
                if Card.Online then
                    table.insert(Parts, string.format('<font color="#23a55a">\u{25CF}</font> %s Online', FormatThousands(Card.Online)))
                end
                if Card.Members then
                    table.insert(Parts, string.format('<font color="#80848e">\u{25CF}</font> %s Members', FormatThousands(Card.Members)))
                end
    
                StatsLabel.Text = table.concat(Parts, "    ")
                StatsLabel.Visible = Info.ShowCounts ~= false and #Parts > 0
                Card:Layout()
            end
    
            function Card:SetInvite(Invite: string)
                Card.Invite, Card.Code = ParseDiscordInvite(Invite)
            end
    
            function Card:Refresh(): boolean
                if not Card.Code or Card.Destroyed then
                    return false
                end
    
                local Data = HttpRequestJSON(string.format("https://discord.com/api/v10/invites/%s?with_counts=true", Card.Code))
                if typeof(Data) ~= "table" or Card.Destroyed or Library.Unloaded then
                    return false
                end
    
                local Guild = typeof(Data.guild) == "table" and Data.guild or nil
                if Info.AutoFetch ~= false and Guild then
                    if not HasCustomTitle and typeof(Guild.name) == "string" then
                        Card:SetTitle(Guild.name)
                    end
    
                    if not HasCustomDescription and typeof(Guild.description) == "string" and Guild.description ~= "" then
                        Card:SetDescription(Guild.description)
                    end
    
                    if Info.Avatar == nil and Guild.id and Guild.icon then
                        Card:SetAvatar(string.format("https://cdn.discordapp.com/icons/%s/%s.png?size=128", tostring(Guild.id), tostring(Guild.icon)))
                    end
    
                    if Info.Banner == nil and Guild.id then
                        if Guild.banner then
                            Card:SetBanner(string.format("https://cdn.discordapp.com/banners/%s/%s.png?size=512", tostring(Guild.id), tostring(Guild.banner)))
                        elseif Guild.splash then
                            Card:SetBanner(string.format("https://cdn.discordapp.com/splashes/%s/%s.png?size=512", tostring(Guild.id), tostring(Guild.splash)))
                        end
                    end
                end
    
                if Info.ShowCounts ~= false then
                    Card:SetCounts(Data.approximate_presence_count, Data.approximate_member_count)
                end
    
                return true
            end
    
            local CopyToken = 0
            table.insert(Card.Connections, ActionButton.MouseEnter:Connect(function()
                TweenService:Create(ActionButton, Library.TweenInfo, {
                    BackgroundColor3 = Library:GetLighterColor(ButtonColor),
                }):Play()
                TweenService:Create(AvatarScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Scale = 1.06,
                }):Play()
            end))
            table.insert(Card.Connections, ActionButton.MouseLeave:Connect(function()
                TweenService:Create(ActionButton, Library.TweenInfo, {
                    BackgroundColor3 = ButtonColor,
                }):Play()
                TweenService:Create(ActionScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Scale = 1,
                }):Play()
                TweenService:Create(AvatarScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Scale = 1,
                }):Play()
            end))
            table.insert(Card.Connections, ActionButton.MouseButton1Down:Connect(function()
                if Library.IconAnimations == false then
                    return
                end
    
                TweenService:Create(ActionScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Scale = 0.97,
                }):Play()
            end))
            table.insert(Card.Connections, ActionButton.MouseButton1Up:Connect(function()
                TweenService:Create(ActionScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Scale = 1,
                }):Play()
            end))
            table.insert(Card.Connections, ActionButton.MouseButton1Click:Connect(function()
                if Card.Code and Info.OpenDiscord ~= false then
                    task.spawn(Library.OpenDiscordInvite, Library, Card.Code)
                end
    
                if Card.Invite then
                    local Copied = Library:CopyToClipboard(Card.Invite, Info.NotifyText)
                    if Copied then
                        CopyToken += 1
                        local Token = CopyToken
    
                        ActionLabel.Text = Info.CopiedText
                        if CheckIcon then
                            Library:ApplyLucideIcon(ActionIcon, CheckIcon)
                        end
                        TweenService:Create(ActionButton, Library.TweenInfo, {
                            BackgroundColor3 = Color3.fromRGB(35, 165, 90),
                        }):Play()
    
                        task.delay(1.6, function()
                            if Token ~= CopyToken or Card.Destroyed or Library.Unloaded then
                                return
                            end
    
                            ActionLabel.Text = Info.ButtonText
                            if CopyIcon then
                                Library:ApplyLucideIcon(ActionIcon, CopyIcon)
                            end
                            TweenService:Create(ActionButton, Library.TweenInfo, {
                                BackgroundColor3 = ButtonColor,
                            }):Play()
                        end)
                    end
                end
    
                Library:SafeCallback(Info.Callback, Card)
            end))
    
            function Card:SetVisible(Visible: boolean)
                Card.Visible = Visible
    
                Holder.Visible = Card.Visible
                Groupbox:Resize()
            end
    
            function Card:Destroy()
                Card.Destroyed = true
    
                if PulseTween then
                    PulseTween:Cancel()
                    PulseTween = nil
                end
    
                for _, Connection in Card.Connections do
                    Connection:Disconnect()
                end
                table.clear(Card.Connections)
    
                if Holder then
                    Holder:Destroy()
                end
    
                local ElemIdx = table.find(Groupbox.Elements, Card)
                if ElemIdx then
                    table.remove(Groupbox.Elements, ElemIdx)
                end
    
                Groupbox:Resize()
                if Idx then
                    Options[Idx] = nil
                end
            end
    
            Card:SetBanner(Info.Banner)
            Card:SetAvatar(Info.Avatar)
            UpdatePulse()
            Card:Layout()
    
            Card.Holder = Holder
            table.insert(Groupbox.Elements, Card)
    
            if Idx then
                Options[Idx] = Card
            end
    
            if Card.Code and (Info.ShowCounts ~= false or Info.AutoFetch ~= false) then
                task.spawn(function()
                    Card:Refresh()
                end)
            end
    
            return Card
        end
    
        BaseGroupbox.__index = Funcs
        BaseGroupbox.__namecall = function(_, Key, ...)
            return Funcs[Key](...)
        end
    end
    
    function Library:SetFont(FontFace)
        if typeof(FontFace) == "EnumItem" then
            FontFace = Font.fromEnum(FontFace :: any)
        end
    
        Library.Scheme.Font = FontFace
        Library:UpdateColorsUsingRegistry()
    end
    
    function Library:SetBackgroundImage(Image: string | number)
        assert(typeof(Image) == "string" or typeof(Image) == "number", "Expected string/number got " .. typeof(Image))
    
        Library.Scheme.BackgroundImage = Image
        if Library.Window then
            Library.Window:SetBackgroundImage(Image)
        end
    
        Library:UpdateColorsUsingRegistry()
    end
    
    function Library:UpdateNotificationPositions(Snap: boolean?)
        local IsLeft = Library.NotifySide:lower() == "left"
        local XScale = IsLeft and 0 or 1
        local RunningY = 0
    
        for _, FakeBackground in NotifyOrder do
            local Data = Library.Notifications[FakeBackground]
            if not (Data and FakeBackground.Parent) then continue end
    
            local Target = UDim2.new(XScale, 0, 0, RunningY)
            if Snap or not Data.PositionInitialized then
                FakeBackground.Position = Target
                Data.PositionInitialized = true
    
            elseif FakeBackground.Position ~= Target then
                TweenService:Create(FakeBackground, Library.NotifyTweenInfo, {
                    Position = Target,
                }):Play()
            end
    
            RunningY = RunningY + FakeBackground.AbsoluteSize.Y / Library.DPIScale + 8
        end
    end
    
    function Library:SetNotifySide(Side: string)
        Library.NotifySide = Side
    
        local IsLeft = Side:lower() == "left"
        if IsLeft then
            NotificationArea.AnchorPoint = Vector2.new(0, 0)
            NotificationArea.Position = UDim2.fromOffset(6, 6)
        else
            NotificationArea.AnchorPoint = Vector2.new(1, 0)
            NotificationArea.Position = UDim2.new(1, -6, 0, 6)
        end
    
        for FakeBackground in Library.Notifications do
            if not (FakeBackground and FakeBackground.Parent) then continue end
            FakeBackground.AnchorPoint = if IsLeft then Vector2.new(0, 0) else Vector2.new(1, 0)
        end
    
        if Library.UpdateNotificationPositions then
            Library:UpdateNotificationPositions(true)
        end
    end
    
    function Library:CopyToClipboard(Text: string, NotifyTitle: (string | boolean)?): boolean
        Text = tostring(Text)
    
        local Setter = setclipboard or toclipboard or (Clipboard and Clipboard.set)
        if typeof(Setter) ~= "function" then
            Library:Notify({
                Title = "Clipboard unavailable",
                Description = "Your executor does not support copying",
                Time = 6,
            })
            return false
        end
    
        local Success = pcall(Setter, Text)
        if Success and NotifyTitle ~= false then
            local _, LineCount = string.gsub(Text, "\n", "")
            LineCount += 1
            local Summary
            if LineCount > 1 or #Text > 64 then
                Summary = if LineCount > 1
                    then string.format("%d lines ready to paste", LineCount)
                    else string.format("%d characters ready to paste", #Text)
            else
                Summary = Text
            end
            Library:Notify({
                Title = typeof(NotifyTitle) == "string" and NotifyTitle or "Copied to clipboard",
                Description = Summary,
                Time = 3,
            })
        end
    
        return Success
    end
    
    function Library:RecordNotification(Data)
        local Entry = {
            Title = Data.Title,
            Description = Data.Description,
            Time = os.time(),
        }
    
        table.insert(Library.NotificationHistory, 1, Entry)
        while #Library.NotificationHistory > (Library.MaxNotificationHistory or 50) do
            table.remove(Library.NotificationHistory)
        end
    
        local Center = Library.NotificationCenter
        if not (Center and Center.Open) then
            Library.UnreadNotifications += 1
        end
    
        if Center then
            Center:Refresh()
        end
    
        return Entry
    end
    
    function Library:ClearNotifications()
        table.clear(Library.NotificationHistory)
        Library.UnreadNotifications = 0
    
        if Library.NotificationCenter then
            Library.NotificationCenter:Refresh()
        end
    end
    
    function Library:SetNotificationsMuted(Muted: boolean)
        Library.NotificationsMuted = Muted == true
    
        if Library.NotificationCenter then
            Library.NotificationCenter:UpdateBadge()
        end
    end
    
    function Library:Notify(...)
        if Library.IntroPlaying and not Library.Unloaded then
            local Arguments = table.pack(...)
            task.spawn(function()
                repeat
                    task.wait(0.1)
                until not Library.IntroPlaying or Library.Unloaded
                if not Library.Unloaded then
                    Library:Notify(table.unpack(Arguments, 1, Arguments.n))
                end
            end)
            return nil
        end
        local Data = {}
        local Info = select(1, ...)
    
        if typeof(Info) == "table" then
            Data.Title = if Info.Title ~= nil then tostring(Info.Title) else nil
            Data.TitleColor = Info.TitleColor
    
            Data.Description = if Info.Description ~= nil then tostring(Info.Description) else nil
            Data.DescriptionColor = Info.DescriptionColor
    
            Data.Time = Info.Time or 5
            Data.SoundId = Info.SoundId
            Data.Steps = Info.Steps
            Data.Persist = Info.Persist
    
            Data.Callback = typeof(Info.Callback) == "function" and Info.Callback or nil
            Data.Closable = Info.Closable == true
    
            Data.Icon = Info.Icon
            Data.BigIcon = Info.BigIcon
            Data.IconColor = Info.IconColor
    
            Data.Volume = tonumber(Info.Volume) or 3
        else
            Data.Description = tostring(Info)
            Data.Time = select(2, ...) or 5
            Data.SoundId = select(3, ...)
            Data.Volume = select(4, ...) or 3
        end
        Data.Destroyed = false
    
        Library:RecordNotification(Data)
        if Library.NotificationsMuted and Data.Persist ~= true then
            local Stub = {
                Destroyed = false,
                Muted = true,
                Title = Data.Title,
                Description = Data.Description,
            }
    
            function Stub:Resize() end
            function Stub:ChangeStep() end
    
            function Stub:ChangeTitle(Text)
                Stub.Title = tostring(Text)
            end
    
            function Stub:ChangeDescription(Text)
                Stub.Description = tostring(Text)
            end
    
            function Stub:Destroy(Reason)
                if Stub.Destroyed then
                    return
                end
    
                Stub.Destroyed = true
                if Data.Callback then
                    pcall(Data.Callback, Reason or "muted")
                end
            end
    
            return Stub
        end
    
        local DeletedInstance = false
        local DeleteConnection = nil
        if typeof(Data.Time) == "Instance" then
            DeleteConnection = Data.Time.Destroying:Connect(function()
                DeletedInstance = true
    
                DeleteConnection:Disconnect()
                DeleteConnection = nil
            end)
        end
    
        local FakeBackground = New("Frame", {
            AnchorPoint = Library.NotifySide:lower() == "left" and Vector2.new(0, 0) or Vector2.new(1, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(0, 0),
            Visible = false,
            Parent = NotificationArea,
        })
    
        local Holder = New("Frame", {
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = "MainColor",
            Position = Library.NotifySide:lower() == "left" and UDim2.new(-1, -8, 0, 0) or UDim2.new(1, 8, 0, 0),
            Size = UDim2.new(1, 0, 0, 0),
            ZIndex = 5,
            Parent = FakeBackground,
        })
        table.insert(
            Library.Corners,
            New("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius),
                Parent = Holder,
            })
        )
        Library:AddOutline(Holder)
    
        local ContentHolder = New("Frame", {
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 0),
            Parent = Holder,
        })
        New("UIListLayout", {
            Padding = UDim.new(0, 4),
            Parent = ContentHolder,
        })
        New("UIPadding", {
            PaddingBottom = UDim.new(0, 8),
            PaddingLeft = UDim.new(0, 8),
            PaddingRight = UDim.new(0, 8),
            PaddingTop = UDim.new(0, 8),
            Parent = ContentHolder,
        })
    
        local CloseButton
        if Data.Closable then
            CloseButton = New("ImageButton", {
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Image = CloseIcon and CloseIcon.Url or "",
                ImageColor3 = "FontColor",
                ImageRectOffset = CloseIcon and CloseIcon.ImageRectOffset or Vector2.zero,
                ImageRectSize = CloseIcon and CloseIcon.ImageRectSize or Vector2.zero,
                ImageTransparency = 0.5,
                Position = UDim2.new(1, -8, 0, 8),
                Size = UDim2.fromOffset(14, 14),
                ZIndex = 6,
                Parent = Holder,
            })
            if CloseIcon and CloseIcon.Pending then
                Library:ApplyLucideIcon(CloseButton, CloseIcon)
            end

            CloseButton.MouseEnter:Connect(function()
                TweenService:Create(CloseButton, Library.TweenInfo, {
                    ImageTransparency = 0,
                }):Play()
            end)
            CloseButton.MouseLeave:Connect(function()
                TweenService:Create(CloseButton, Library.TweenInfo, {
                    ImageTransparency = 0.5,
                }):Play()
            end)
            CloseButton.MouseButton1Click:Connect(function()
                Data:Destroy("user")
            end)
        end
    
        local ContentContainer = New("Frame", {
            BackgroundTransparency = 1,
            AutomaticSize = Enum.AutomaticSize.XY,
            Size = UDim2.fromOffset(0, 0),
            Parent = ContentHolder,
        })
    
        if Data.BigIcon then
            New("UIListLayout", {
                Padding = UDim.new(0, 8),
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Parent = ContentContainer,
            })
        end
    
        local BigIconLabel
        if Data.BigIcon then
            local ParsedIcon = Library:GetCustomIcon(Data.BigIcon)
            if ParsedIcon then
                BigIconLabel = New("ImageLabel", {
                    BackgroundTransparency = 1,
                    Size = UDim2.fromOffset(24, 24),
                    ImageColor3 = Data.IconColor or "AccentColor",
                    Parent = ContentContainer,
                })
                Library:ApplyLucideIcon(BigIconLabel, ParsedIcon)
            end
        end
    
        local TextContainer = New("Frame", {
            BackgroundTransparency = 1,
            AutomaticSize = Enum.AutomaticSize.XY,
            Size = UDim2.fromOffset(0, 0),
            Parent = ContentContainer,
        })
        New("UIListLayout", {
            Padding = UDim.new(0, 4),
            Parent = TextContainer,
        })
    
        local TitleContainer
        if Data.Title then
            TitleContainer = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(0, 0),
                Parent = TextContainer,
            })
        end
    
        local IconLabel
        if Data.Icon and TitleContainer then
            local ParsedIcon = Library:GetCustomIcon(Data.Icon)
            if ParsedIcon then
                IconLabel = New("ImageLabel", {
                    BackgroundTransparency = 1,
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 0, 0.5, 1),
                    Size = UDim2.fromOffset(15, 15),
                    ImageColor3 = Data.IconColor or "FontColor",
                    Parent = TitleContainer,
                })
                Library:ApplyLucideIcon(IconLabel, ParsedIcon)
            end
        end
    
        local Title
        local Desc
        local TitleX = 0
        local DescX = 0
    
        local TimerFill
    
        if Data.Title then
            Title = New("TextLabel", {
                AutomaticSize = Enum.AutomaticSize.None,
                BackgroundTransparency = 1,
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, (IconLabel and 21 or 0), 0.5, 0),
                Size = UDim2.fromScale(0, 0),
                Text = Data.Title,
                TextColor3 = Data.TitleColor or "FontColor",
                TextSize = 15,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                TextWrapped = true,
                Parent = TitleContainer,
            })
        end
    
        if Data.Description then
            Desc = New("TextLabel", {
                AutomaticSize = Enum.AutomaticSize.None,
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(0, 0),
                Text = Data.Description,
                TextColor3 = Data.DescriptionColor or "FontColor",
                TextSize = 14,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextWrapped = true,
                Parent = TextContainer,
            })
        end
    
        function Data:Resize()
            local ExtraWidth = BigIconLabel and 32 or 0
            local IconWidth = IconLabel and 21 or 0
            local CloseWidth = Data.Closable and 20 or 0
            local MaxTextWidth = math.max(
                40,
                (NotificationArea.AbsoluteSize.X / Library.DPIScale) - 24 - ExtraWidth - CloseWidth
            )
    
            if Title then
                local X, Y = Library:GetTextBounds(Title.Text, Title.FontFace, Title.TextSize, MaxTextWidth - IconWidth)
                Title.Size = UDim2.fromOffset(X, Y)
                TitleX = X + IconWidth
                TitleContainer.Size = UDim2.fromOffset(TitleX, math.max(Y, IconLabel and 16 or 0))
            end
    
            if Desc then
                local X, Y = Library:GetTextBounds(Desc.Text, Desc.FontFace, Desc.TextSize, MaxTextWidth)
                Desc.Size = UDim2.fromOffset(X, Y)
                DescX = X
            end
    
            FakeBackground.Size = UDim2.fromOffset(math.max(TitleX, DescX) + 24 + ExtraWidth + CloseWidth, 0)
    
            if Library.Notifications[FakeBackground] then
                task.defer(function()
                    if Data.Destroyed or not FakeBackground.Parent then
                        return
                    end
    
                    if FakeBackground.AbsoluteSize.Y <= 0 then
                        task.defer(function()
                            if Data.Destroyed or not FakeBackground.Parent then
                                return
                            end
    
                            Library:UpdateNotificationPositions(true)
                        end)
                        return
                    end
    
                    Library:UpdateNotificationPositions(true)
                end)
            end
        end
    
        function Data:ChangeTitle(Text)
            if Title then
                Data.Title = tostring(Text)
                Title.Text = Data.Title
                Data:Resize()
            end
        end
    
        function Data:ChangeDescription(Text)
            if Desc then
                Data.Description = tostring(Text)
                Desc.Text = Data.Description
                Data:Resize()
            end
        end
    
        function Data:ChangeStep(NewStep)
            if TimerFill and Data.Steps then
                NewStep = math.clamp(NewStep or 0, 0, Data.Steps)
                TimerFill.Size = UDim2.fromScale(NewStep / Data.Steps, 1)
            end
        end
    
        function Data:Destroy(Reason)
            if Data.Destroyed then
                return
            end
    
            Reason = Reason or "script"
            Data.Destroyed = true
    
            if Data.Callback then
                pcall(Data.Callback, Reason)
            end
    
            if typeof(Data.Time) == "Instance" then
                pcall(Data.Time.Destroy, Data.Time)
            end
    
            if DeleteConnection then
                DeleteConnection:Disconnect()
            end
    
            if FakeBackground then
                local Idx = table.find(NotifyOrder, FakeBackground)
                if Idx then
                    table.remove(NotifyOrder, Idx)
                end
            end
    
            Library:UpdateNotificationPositions()
    
            TweenService
                :Create(Holder, Library.NotifyTweenInfo, {
                    Position = Library.NotifySide:lower() == "left" and UDim2.new(-1, -8, 0, -2) or UDim2.new(1, 8, 0, -2),
                })
                :Play()
    
            task.delay(Library.NotifyTweenInfo.Time, function()
                Library.Notifications[FakeBackground] = nil
                FakeBackground:Destroy()
            end)
        end
    
        local TimerHolder = New("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 7),
            Visible = (Data.Persist ~= true and typeof(Data.Time) ~= "Instance") or typeof(Data.Steps) == "number",
            Parent = ContentHolder,
        })
        local TimerBar = New("Frame", {
            BackgroundColor3 = "BackgroundColor",
            BorderColor3 = "OutlineColor",
            BorderSizePixel = 1,
            Position = UDim2.fromOffset(0, 3),
            Size = UDim2.new(1, 0, 0, 2),
            Parent = TimerHolder,
        })
        TimerFill = New("Frame", {
            BackgroundColor3 = "AccentColor",
            Size = UDim2.fromScale(1, 1),
            Parent = TimerBar,
        })
    
        if typeof(Data.Time) == "Instance" then
            TimerFill.Size = UDim2.fromScale(0, 1)
        end
        if Data.SoundId then
            local SoundId = Data.SoundId
            if typeof(SoundId) == "number" then
                SoundId = string.format("rbxassetid://%d", SoundId)
            end
    
            New("Sound", {
                SoundId = SoundId,
                Volume = tonumber(Data.Volume) or 3,
                PlayOnRemove = true,
                Parent = SoundService,
            }):Destroy()
        end
    
        Data.Holder = Holder
    
        table.insert(NotifyOrder, FakeBackground)
        Library.Notifications[FakeBackground] = Data
    
        Data:Resize()
    
        FakeBackground.Visible = true
        TweenService:Create(Holder, Library.NotifyTweenInfo, {
            Position = UDim2.fromOffset(0, 0),
        }):Play()
    
        task.defer(function()
            if not Data.Destroyed then
                Library:UpdateNotificationPositions(true)
            end
        end)
    
        task.delay(Library.NotifyTweenInfo.Time, function()
            if Data.Persist then
                return
            elseif typeof(Data.Time) == "Instance" then
                repeat
                    task.wait()
                until DeletedInstance or Data.Destroyed
            else
                TweenService
                    :Create(TimerFill, TweenInfo.new(Data.Time, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut), {
                        Size = UDim2.fromScale(0, 1),
                    })
                    :Play()
                task.wait(Data.Time)
            end
    
            Data:Destroy("timer")
        end)
    
        return Data
    end
    
    function Library:OpenPicker(Dropdown)
        if not Dropdown or Dropdown.Destroyed or Dropdown.Type ~= "Dropdown" then
            return nil
        end
    
        if Library.ActivePicker then
            Library.ActivePicker:Close(true)
        end
    
        local Host = (Library.Window and Library.Window.MainFrame) or ScreenGui
        local IsMulti = Dropdown.Multi == true
        local Picker = {
            Dropdown = Dropdown,
            Closed = false,
            Connections = {},
            Rows = {},
        }
    
        local Backdrop = New("TextButton", {
            BackgroundColor3 = "DarkColor",
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Text = "",
            ZIndex = 80,
            Parent = Host,
        })
        table.insert(
            Library.Corners,
            New("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius),
                Parent = Backdrop,
            })
        )
    
        local Panel = New("TextButton", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = "BackgroundColor",
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromScale(0.62, 0.74),
            Text = "",
            ZIndex = 81,
            Parent = Backdrop,
        })
        New("UISizeConstraint", {
            MaxSize = Vector2.new(420, 460),
            MinSize = Vector2.new(240, 200),
            Parent = Panel,
        })
        table.insert(
            Library.Corners,
            New("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius),
                Parent = Panel,
            })
        )
        Library:AddOutline(Panel)
        local PanelScale = New("UIScale", {
            Scale = 0.9,
            Parent = Panel,
        })
    
        New("TextLabel", {
            BackgroundTransparency = 1,
            FontFace = GetBoldFont,
            Position = UDim2.fromOffset(12, 0),
            Size = UDim2.new(1, -110, 0, 40),
            Text = Dropdown.Text or "Select",
            TextSize = 15,
            TextTruncate = Enum.TextTruncate.AtEnd,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = Panel,
        })
    
        local CountLabel = New("TextLabel", {
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            Position = UDim2.new(1, -36, 0, 0),
            Size = UDim2.new(0, 70, 0, 40),
            Text = "",
            TextSize = 13,
            TextTransparency = 0.5,
            TextXAlignment = Enum.TextXAlignment.Right,
            Parent = Panel,
        })
    
        local CloseButton = New("ImageButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            BackgroundTransparency = 1,
            ImageColor3 = "FontColor",
            ImageTransparency = 0.4,
            Position = UDim2.new(1, -12, 0, 20),
            Size = UDim2.fromOffset(16, 16),
            Parent = Panel,
        })
        if CloseIcon then
            Library:ApplyLucideIcon(CloseButton, CloseIcon)
        end
        Library:AddIconHover(CloseButton, CloseButton, { Scale = 1.15, Tilt = 90, Transparency = 0, RestTransparency = 0.4 })
    
        local SearchHolder = New("Frame", {
            BackgroundColor3 = "MainColor",
            Position = UDim2.fromOffset(10, 40),
            Size = UDim2.new(1, -20, 0, 28),
            Parent = Panel,
        })
        table.insert(
            Library.Corners,
            New("UICorner", {
                CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                Parent = SearchHolder,
            })
        )
        local SearchStroke = New("UIStroke", {
            Color = "OutlineColor",
            Parent = SearchHolder,
        })
    
        local SearchImage = New("ImageLabel", {
            AnchorPoint = Vector2.new(0, 0.5),
            ImageColor3 = "FontColor",
            ImageTransparency = 0.5,
            Position = UDim2.new(0, 8, 0.5, 0),
            Size = UDim2.fromOffset(14, 14),
            Parent = SearchHolder,
        })
        local SearchLucide = Library:GetIcon("search")
        if SearchLucide then
            Library:ApplyLucideIcon(SearchImage, SearchLucide)
        end
    
        local SearchInput = New("TextBox", {
            BackgroundTransparency = 1,
            ClearTextOnFocus = false,
            PlaceholderText = "Search...",
            Position = UDim2.fromOffset(28, 0),
            Size = UDim2.new(1, -36, 1, 0),
            Text = "",
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = SearchHolder,
        })
    
        table.insert(Picker.Connections, SearchInput.Focused:Connect(function()
            Library:SetSchemeProperty(SearchStroke, "Color", "AccentColor", true)
        end))
        table.insert(Picker.Connections, SearchInput.FocusLost:Connect(function()
            Library:SetSchemeProperty(SearchStroke, "Color", "OutlineColor", true)
        end))
    
        local List = New("ScrollingFrame", {
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            CanvasSize = UDim2.fromScale(0, 0),
            Position = UDim2.fromOffset(10, 76),
            ScrollBarImageColor3 = "AccentColor",
            ScrollBarThickness = 2,
            Size = UDim2.new(1, -20, 1, if IsMulti then -120 else -86),
            Parent = Panel,
        })
        New("UIListLayout", {
            Padding = UDim.new(0, 2),
            Parent = List,
        })
    
        local EmptyLabel = New("TextLabel", {
            BackgroundTransparency = 1,
            LayoutOrder = 1e6,
            Size = UDim2.new(1, 0, 0, 36),
            Text = "No results",
            TextSize = 14,
            TextTransparency = 0.5,
            Visible = false,
            Parent = List,
        })
    
        local function IsSelected(Value)
            if IsMulti then
                return typeof(Dropdown.Value) == "table" and Dropdown.Value[Value] == true
            end
            return Dropdown.Value == Value
        end
    
        local function UpdateCount()
            local Total = 0
            local Selected = 0
            for _, Row in Picker.Rows do
                Total += 1
                if IsSelected(Row.Value) then
                    Selected += 1
                end
            end
            CountLabel.Text = if IsMulti then string.format("%d / %d", Selected, Total) else string.format("%d items", Total)
        end
    
        local function PaintRow(Row, Animate)
            local Selected = IsSelected(Row.Value)
            Row.Selected = Selected
    
            Library:SetSchemeProperty(Row.Label, "TextColor3", if Selected then "AccentColor" else "FontColor", Animate)
            Row.Label.TextTransparency = if Row.Disabled then 0.8 elseif Selected then 0 else 0.3
            Row.Button.BackgroundTransparency = if Selected or Row.Hovering then 0 else 1
            Row.Check.Visible = Selected
    
            if Selected and Animate and Library.IconAnimations ~= false then
                Row.CheckScale.Scale = 0.4
                TweenService:Create(Row.CheckScale, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Scale = 1,
                }):Play()
            end
        end
    
        local function RepaintAll(Animate)
            for _, Row in Picker.Rows do
                PaintRow(Row, Animate)
            end
            UpdateCount()
        end
    
        local function Select(Row)
            if Row.Disabled or Picker.Closed then
                return
            end
    
            if IsMulti then
                local NewValue = {}
                for Key, Active in Dropdown.Value or {} do
                    if Active then
                        NewValue[Key] = true
                    end
                end
                NewValue[Row.Value] = if NewValue[Row.Value] then nil else true
                Dropdown:SetValue(NewValue)
                RepaintAll(true)
                return
            end
    
            if Dropdown.Value == Row.Value and Dropdown.AllowNull then
                Dropdown:SetValue(nil)
            else
                Dropdown:SetValue(Row.Value)
            end
    
            RepaintAll(true)
            task.delay(0.12, function()
                Picker:Close()
            end)
        end
    
        local Values = Dropdown.Values or {}
        local IsDictionary = not IsSequentialArray(Values)
        local DisabledValues = Dropdown.DisabledValues or {}
        local Entries = {}
    
        for Key, RawValue in Values do
            local Value = if IsDictionary then Key else RawValue
            local Display = RawValue
            if Dropdown.FormatListValue then
                local Success, Formatted = pcall(Dropdown.FormatListValue, RawValue)
                if Success and Formatted ~= nil then
                    Display = Formatted
                end
            end
    
            table.insert(Entries, {
                Value = Value,
                Display = tostring(Display),
                SortKey = Key,
                Disabled = table.find(DisabledValues, Value) ~= nil or (RawValue ~= Value and table.find(DisabledValues, RawValue) ~= nil),
            })
        end
    
        if not IsDictionary then
            table.sort(Entries, function(A, B)
                return A.SortKey < B.SortKey
            end)
        end
    
        for Index, Entry in Entries do
            local Button = New("TextButton", {
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                LayoutOrder = Index,
                Size = UDim2.new(1, 0, 0, 28),
                Text = "",
                Parent = List,
            })
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                    Parent = Button,
                })
            )
    
            local Label = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(10, 0),
                Size = UDim2.new(1, -40, 1, 0),
                Text = Entry.Display,
                TextSize = 14,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                Parent = Button,
            })
    
            local Check = New("ImageLabel", {
                AnchorPoint = Vector2.new(1, 0.5),
                ImageColor3 = "AccentColor",
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(14, 14),
                Visible = false,
                Parent = Button,
            })
            if CheckIcon then
                Library:ApplyLucideIcon(Check, CheckIcon)
            end
            local CheckScale = New("UIScale", {
                Parent = Check,
            })
    
            local Row = {
                Value = Entry.Value,
                Search = string.lower(Entry.Display),
                Disabled = Entry.Disabled,
                Button = Button,
                Label = Label,
                Check = Check,
                CheckScale = CheckScale,
                Hovering = false,
                Selected = false,
            }
            table.insert(Picker.Rows, Row)
    
            table.insert(Picker.Connections, Button.MouseEnter:Connect(function()
                Row.Hovering = true
                if not Row.Disabled then
                    TweenService:Create(Button, Library.TweenInfo, { BackgroundTransparency = 0 }):Play()
                end
            end))
            table.insert(Picker.Connections, Button.MouseLeave:Connect(function()
                Row.Hovering = false
                TweenService:Create(Button, Library.TweenInfo, {
                    BackgroundTransparency = if Row.Selected then 0 else 1,
                }):Play()
            end))
            table.insert(Picker.Connections, Button.MouseButton1Click:Connect(function()
                Select(Row)
            end))
        end
    
        if IsMulti then
            local Footer = New("Frame", {
                AnchorPoint = Vector2.new(0, 1),
                BackgroundTransparency = 1,
                Position = UDim2.new(0, 10, 1, -10),
                Size = UDim2.new(1, -20, 0, 26),
                Parent = Panel,
            })
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalFlex = Enum.UIFlexAlignment.Fill,
                Padding = UDim.new(0, 8),
                Parent = Footer,
            })
    
            local function FooterButton(Text, Callback)
                local Button = New("TextButton", {
                    BackgroundColor3 = "MainColor",
                    Size = UDim2.fromScale(1, 1),
                    Text = Text,
                    TextSize = 14,
                    TextTransparency = 0.4,
                    Parent = Footer,
                })
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Button,
                    })
                )
                table.insert(Picker.Connections, Button.MouseEnter:Connect(function()
                    TweenService:Create(Button, Library.TweenInfo, { TextTransparency = 0 }):Play()
                end))
                table.insert(Picker.Connections, Button.MouseLeave:Connect(function()
                    TweenService:Create(Button, Library.TweenInfo, { TextTransparency = 0.4 }):Play()
                end))
                table.insert(Picker.Connections, Button.MouseButton1Click:Connect(Callback))
                return Button
            end
    
            FooterButton("Select all", function()
                local NewValue = {}
                for _, Row in Picker.Rows do
                    if (Row.Button.Visible and not Row.Disabled) or IsSelected(Row.Value) then
                        NewValue[Row.Value] = true
                    end
                end
                Dropdown:SetValue(NewValue)
                RepaintAll(true)
            end)
    
            FooterButton("Clear", function()
                local NewValue = {}
                for _, Row in Picker.Rows do
                    if Row.Disabled and IsSelected(Row.Value) then
                        NewValue[Row.Value] = true
                    end
                end
                Dropdown:SetValue(NewValue)
                RepaintAll(true)
            end)
        end
    
        table.insert(Picker.Connections, SearchInput:GetPropertyChangedSignal("Text"):Connect(function()
            local Query = string.lower(Trim(SearchInput.Text))
            local AnyVisible = false
    
            for _, Row in Picker.Rows do
                local Visible = Query == "" or string.find(Row.Search, Query, 1, true) ~= nil
                if not Visible and Query ~= "" then
                    Visible = FuzzyScore(Row.Search, NormalizeSearch(Query))
                end
    
                Row.Button.Visible = Visible
                AnyVisible = AnyVisible or Visible
            end
    
            EmptyLabel.Visible = not AnyVisible
            List.CanvasPosition = Vector2.zero
        end))
    
        function Picker:Close(Instant: boolean?)
            if Picker.Closed then
                return
            end
            Picker.Closed = true
    
            if Library.ActivePicker == Picker then
                Library.ActivePicker = nil
            end
    
            for _, Connection in Picker.Connections do
                Connection:Disconnect()
            end
            table.clear(Picker.Connections)
    
            if Instant or Library.IconAnimations == false then
                Backdrop:Destroy()
                return
            end
    
            TweenService:Create(Backdrop, Library.TweenInfo, { BackgroundTransparency = 1 }):Play()
            TweenService:Create(PanelScale, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                Scale = 0.9,
            }):Play()
            task.delay(0.15, function()
                Backdrop:Destroy()
            end)
        end
    
        table.insert(Picker.Connections, Backdrop.MouseButton1Click:Connect(function()
            Picker:Close()
        end))
        table.insert(Picker.Connections, CloseButton.MouseButton1Click:Connect(function()
            Picker:Close()
        end))
        table.insert(Picker.Connections, UserInputService.InputBegan:Connect(function(Input: InputObject)
            if Input.KeyCode == Enum.KeyCode.Escape then
                Picker:Close()
            end
        end))
    
        RepaintAll(false)
        Library.ActivePicker = Picker
    
        if Library.IconAnimations ~= false then
            TweenService:Create(Backdrop, Library.TweenInfo, { BackgroundTransparency = 0.45 }):Play()
            TweenService:Create(PanelScale, TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                Scale = 1,
            }):Play()
        else
            Backdrop.BackgroundTransparency = 0.45
            PanelScale.Scale = 1
        end
    
        return Picker
    end
    
    function Library:GetGuiArea()
        local Camera = workspace.CurrentCamera
        local Viewport = if Camera then Camera.ViewportSize else Vector2.new(1920, 1080)
        local Top = 0
        pcall(function()
            local Inset = GuiService:GetGuiInset()
            Top = Inset.Y
        end)
        return Vector2.new(Viewport.X, math.max(120, Viewport.Y - Top))
    end
    
    function Library:MobileFit(Percent)
        Percent = tonumber(Percent) or 100
        if not Library.IsMobile then
            return Percent
        end
        local Size = Library.MobileWindowSize
        if typeof(Size) ~= "Vector2" or Size.X <= 0 or Size.Y <= 0 then
            return math.min(Percent, 100)
        end
        local Area = Library:GetGuiArea()
        local Fit = math.min((Area.X - 16) / Size.X, (Area.Y - 10) / Size.Y)
        return math.clamp(math.floor(Fit * 100), 50, math.max(50, Percent))
    end
    
    function Library:CenterMobileWindow()
        if not Library.IsMobile then
            return
        end
        local Main = Library.ScreenGui and Library.ScreenGui:FindFirstChild("Main")
        local Size = Library.MobileWindowSize
        if not (Main and typeof(Size) == "Vector2") then
            return
        end
        local Window = Library.Window
        if Window and Window.IsMinimized and Window:IsMinimized() then
            return
        end
        local Scale = Library.DPIScale
        Main.Position = UDim2.new(0.5, -math.floor(Size.X * Scale / 2), 0.5, -math.floor(Size.Y * Scale / 2))
    end
    
    function Library:CreateWindow(WindowInfo)
        WindowInfo = Library:Validate(WindowInfo, Templates.Window)
        Library.Title = WindowInfo.Title
        WindowInfo.Starfield = Library:GetSetting("Starfield", WindowInfo.Starfield ~= false) ~= false
        Library.IconAnimations = Library:GetSetting("Animations", Library.IconAnimations ~= false) ~= false
        Library.Glass = Library:GetSetting("Glass", WindowInfo.Glass ~= false) ~= false
        Library.CometTransitions = Library:GetSetting("Comets", WindowInfo.CometTransitions ~= false) ~= false
        Library.CursorLight = Library:GetSetting("CursorLight", true) ~= false
        Library.Stardust = Library:GetSetting("Stardust", true) ~= false
        do
            local StartTheme = Library:GetSetting("Theme", WindowInfo.Theme)
            if typeof(StartTheme) == "string" and Library.CorvusThemes[StartTheme] then
                Library:SetTheme(StartTheme)
            end
            local StartAccent = Library:GetSetting("Accent", nil)
            if typeof(StartAccent) == "string" then
                local Success, Color = pcall(Color3.fromHex, StartAccent)
                if Success then
                    Library.Scheme.AccentColor = Color
                end
            end
            Library.DefaultThemeName = if typeof(WindowInfo.Theme) == "string" and Library.CorvusThemes[WindowInfo.Theme] then WindowInfo.Theme else "Corvus Night"
        end
        if Library:GetSetting("StatsHUD", false) == true then
            task.defer(Library.SetStatsHUD, Library, true)
        end
        local ViewportSize: Vector2 = workspace.CurrentCamera.ViewportSize
        if RunService:IsStudio() and ViewportSize.X <= 5 and ViewportSize.Y <= 5 then
            repeat
                ViewportSize = workspace.CurrentCamera.ViewportSize
                task.wait()
            until ViewportSize.X > 5 and ViewportSize.Y > 5
        end
    
        local MaxX = ViewportSize.X - 64
        local MaxY = ViewportSize.Y - 64
        if Library.IsMobile then
            local Area = Library:GetGuiArea()
            MaxX = math.min(MaxX, Area.X - 24)
            MaxY = math.min(MaxY, Area.Y - 14)
        end
    
        Library.OriginalMinSize =
            Vector2.new(math.min(Library.OriginalMinSize.X, MaxX), math.min(Library.OriginalMinSize.Y, MaxY))
        Library.MinSize = Vector2.new(math.min(WindowInfo.MinContainerWidth, MaxX), Library.OriginalMinSize.Y)
    
        WindowInfo.Size = UDim2.fromOffset(
            math.clamp(WindowInfo.Size.X.Offset, Library.MinSize.X, math.max(Library.MinSize.X, MaxX)),
            math.clamp(WindowInfo.Size.Y.Offset, Library.MinSize.Y, math.max(Library.MinSize.Y, MaxY))
        )
        Library.MobileWindowSize = Vector2.new(WindowInfo.Size.X.Offset, WindowInfo.Size.Y.Offset)
        if typeof(WindowInfo.Font) == "EnumItem" then
            WindowInfo.Font = Font.fromEnum(WindowInfo.Font :: any)
        end
        WindowInfo.CornerRadius = math.min(WindowInfo.CornerRadius, 20)
    
        local TabButtonsStyle = WindowInfo.TabButtonsStyle
    
        if WindowInfo.Compact ~= nil then
            WindowInfo.SidebarCompacted = WindowInfo.Compact
        end
        if WindowInfo.SidebarMinWidth ~= nil then
            WindowInfo.MinSidebarWidth = WindowInfo.SidebarMinWidth
        end
        WindowInfo.MinSidebarWidth = math.max(64 + TabButtonsStyle.Padding * 2, WindowInfo.MinSidebarWidth)
        WindowInfo.SidebarCompactWidth = math.max(40 + TabButtonsStyle.Padding * 2, WindowInfo.SidebarCompactWidth)
        WindowInfo.SidebarCollapseThreshold = math.clamp(WindowInfo.SidebarCollapseThreshold, 0.1, 0.9)
        WindowInfo.CompactWidthActivation = math.max(40 + TabButtonsStyle.Padding * 2, WindowInfo.CompactWidthActivation)
        WindowInfo.SnapDistance = math.max(0, WindowInfo.SnapDistance)
        WindowInfo.SnapMargin = math.max(0, WindowInfo.SnapMargin)
    
        Library.CornerRadius = WindowInfo.CornerRadius
        Library:SetNotifySide(WindowInfo.NotifySide)
        Library.ShowCustomCursor = WindowInfo.ShowCustomCursor
        Library.Scheme.Font = WindowInfo.Font
        Library.ToggleKeybind = WindowInfo.ToggleKeybind
        Library.GlobalSearch = WindowInfo.GlobalSearch
    
        Library.Animations = WindowInfo.Animations
        Library.TabTransitionInfo = TweenInfo.new(
            math.max(0, WindowInfo.TabTransitionTime or 0.22),
            Enum.EasingStyle.Quad,
            Enum.EasingDirection.Out
        )
        Library.TabSwipeOffset = math.max(1, WindowInfo.TabSwipeOffset or 26)
        Library.TabSwipeFrom = WindowInfo.TabSwipeFrom or "right"
    
        local IsDefaultSearchbarSize = WindowInfo.SearchbarSize == UDim2.fromScale(1, 1)
        local TopbarButtonCount = (WindowInfo.MinimizeButton ~= false and 1 or 0) + (WindowInfo.NotificationCenter ~= false and 1 or 0) + (WindowInfo.Console ~= false and 1 or 0)
        local ConsoleButton
        local ConsoleImage
        local TopbarRightInset = if TopbarButtonCount > 0 then 51 + 28 * TopbarButtonCount else 49
        local BottomBar
        local BottomLine
        local TopLine
        local HideTabTooltipSafe = function() end
        local FooterLinkButton
        local FooterCopyButton
        local MinimizeButton
        local MinimizeImage
        local BellButton
        local BellImage
        local BellBadge
        local BellBadgeLabel
        local WindowStarfield
        local WindowAurora
        local MainFrame
        local DividerLine
        local TitleHolder
        local WindowTitle
        local WindowIcon
        local RightWrapper
        local SearchBox
        local CurrentTabInfo
        local CurrentTabLabel
        local CurrentTabDescription
        local ResizeButton
        local Tabs
        local Container
        local BackgroundImage
        local HasBackgroundImage = false
        local BottomBackground
        local FooterLabel
        local TopBar
        local WindowSnapConfig = {
            Enabled = WindowInfo.Snapping,
            Distance = WindowInfo.SnapDistance,
            Margin = WindowInfo.SnapMargin,
            AvoidCoreGui = WindowInfo.SnapAvoidCoreGui,
        }
    
        local InitialLeftWidth = math.ceil(WindowInfo.Size.X.Offset * 0.3)
        local IsCompact = WindowInfo.SidebarCompacted
        local LastExpandedWidth = InitialLeftWidth
    
        do
            Library.KeybindFrame, Library.KeybindContainer = Library:AddDraggableMenu("Keybinds")
            Library.KeybindFrame.AnchorPoint = Vector2.new(0, 0.5)
            Library.KeybindFrame.Position = UDim2.new(0, 6, 0.5, 0)
            Library.KeybindFrame.Visible = false
    
            MainFrame = New("TextButton", {
                BackgroundColor3 = function()
                    return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
                end,
                Name = "Main",
                Text = "",
                Position = WindowInfo.Position,
                Size = WindowInfo.Size,
                Visible = false,
                Parent = ScreenGui,
            })
            table.insert(
                Library.Corners,
                New("UICorner", {
                    CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                    Parent = MainFrame,
                })
            )
            table.insert(
                Library.Scales,
                New("UIScale", {
                    Parent = MainFrame,
                })
            )
            Library:AddOutline(MainFrame)
            WindowStarfield = Library:CreateStarfield(MainFrame, {
                Count = 72,
                Sparkles = 4,
                BrightStars = 12,
                Constellation = WindowInfo.Constellation ~= false,
                Seed = 11,
                ZIndex = 0,
            })
            WindowStarfield.Enabled = WindowInfo.Starfield
            WindowStarfield:SetActive(false)
    
            do
                local function ShineSequence(Peak: number, Floor: number)
                    return NumberSequence.new({
                        NumberSequenceKeypoint.new(0, Peak),
                        NumberSequenceKeypoint.new(0.07, Floor + (1 - Floor) * 0.35),
                        NumberSequenceKeypoint.new(0.2, Floor),
                        NumberSequenceKeypoint.new(0.43, Floor),
                        NumberSequenceKeypoint.new(0.5, Peak),
                        NumberSequenceKeypoint.new(0.57, Floor + (1 - Floor) * 0.35),
                        NumberSequenceKeypoint.new(0.7, Floor),
                        NumberSequenceKeypoint.new(0.93, Floor),
                        NumberSequenceKeypoint.new(1, Peak),
                    })
                end
                local AuroraStroke = New("UIStroke", {
                    Color = "WhiteColor",
                    Thickness = 1.6,
                    ZIndex = 3,
                    Parent = MainFrame,
                })
