                    Stroke = AuroraStroke,
                    Glow = GlowStroke,
                    Gradient = AuroraGradient,
                    Enabled = Library:GetSetting("Aurora", true) ~= false,
                    Connection = nil,
                }
    
                function WindowAurora:Refresh(Running: boolean)
                    AuroraStroke.Enabled = WindowAurora.Enabled
                    GlowStroke.Enabled = WindowAurora.Enabled
                    if WindowAurora.Connection then
                        WindowAurora.Connection:Disconnect()
                        WindowAurora.Connection = nil
                    end
                    if WindowAurora.Enabled and Running and Library.IconAnimations ~= false then
                        WindowAurora.Connection = RunService.RenderStepped:Connect(function(Delta)
                            local Rotation = (AuroraGradient.Rotation + Delta * 60) % 360
                            AuroraGradient.Rotation = Rotation
                            GlowGradient.Rotation = Rotation
                        end)
                        table.insert(Library.Signals, WindowAurora.Connection)
                    end
                end
                WindowAurora:Refresh(false)
