        local Window = {}
        local Fading = false
    
        local function SetUICorner(UICorner, Corner, HalfValue)
            local Current = UICorner[Corner]
            if Current.Offset == 0 and Current.Scale == 0 then
                return
            end
    
            UICorner[Corner] = HalfValue
        end
    
        function Window:ChangeTitle(title)
            assert(typeof(title) == "string", "Expected string for title got: " .. typeof(title))
    
            WindowTitle.Text = title
            WindowInfo.Title = title
        end
    
        function Window:SetBackgroundImage(Image: string)
            local ValidIcon = false
    
            if typeof(Image) == "string" then
                local BackgroundIcon = Library:GetCustomIcon(Image)
    
                if BackgroundIcon then
                    ValidIcon = true
    
                    Library:ApplyLucideIcon(BackgroundImage, BackgroundIcon)
                elseif Image:match("http://") or Image:match("https://") then
                    local RawFileName = Image:match("(.+)%..+$")
                    local _, Domain = Image:match("^(https?://)([^/]+)");
    
                    if RawFileName and Domain then
                        local Extention = string.sub(Image, #RawFileName + 1, #Image)
                        local FileNamePos = RawFileName:gsub("\\", "/"):find("/[^/]*$")
                        local FileName = FileNamePos and Image:sub(FileNamePos + 1) or nil
    
                        if FileName then
                            ValidIcon = true
    
                            local AssetName = Domain .. FileName
                            if #AssetName > 255 then
                                local NewLength = 255 - #Domain - #Extention
                                if NewLength < 0 then
                                    AssetName = Domain .. Extention
                                else
                                    AssetName = Domain .. string.sub(FileName:sub(1, #FileName - #Extention), 1, NewLength) .. Extention
                                end
                            end
    
                            if CustomImageManagerAssets[FileName] == nil then
                                CustomImageManager.AddAsset(FileName, 0, Image)
                            else
                                CustomImageManager.DownloadAsset(FileName, true)
                            end
    
                            BackgroundImage.Image = CustomImageManager.GetAsset(FileName)
                            BackgroundImage.ImageRectOffset = Vector2.zero
                            BackgroundImage.ImageRectSize = Vector2.zero
                        end
                    end
                end
            end
    
            if not ValidIcon then
                BackgroundImage.Image = ""
                BackgroundImage.ImageRectOffset = Vector2.zero
                BackgroundImage.ImageRectSize = Vector2.zero
            end
    
            HasBackgroundImage = ValidIcon
            WindowInfo.BackgroundImage = Image
        end
    
        local FooterCopyToken = 0
        local function EscapeRichText(Text: string): string
            return (tostring(Text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
        end
    
        local function RefreshFooter()
            local Link = WindowInfo.FooterLink
            local HasLink = typeof(Link) == "string" and Link ~= ""
            local FooterText = typeof(WindowInfo.Footer) == "string" and WindowInfo.Footer or ""
    
            FooterLinkButton.Visible = HasLink
            FooterCopyButton.Visible = HasLink
            FooterLinkButton.Text = HasLink and EscapeRichText(Link) or ""
    
            if HasLink and FooterText ~= "" then
                FooterText = "|  " .. FooterText
            end
    
            FooterLabel.Text = FooterText
            FooterLabel.Visible = FooterText ~= ""
        end
    
        local function CopyFooterLink()
            local Link = WindowInfo.FooterLink
            if typeof(Link) ~= "string" or Link == "" then
                return
            end
    
            if not Library:CopyToClipboard(Link) then
                return
            end
    
            FooterCopyToken += 1
            local Token = FooterCopyToken
            if CheckIcon then
                Library:ApplyLucideIcon(FooterCopyButton, CheckIcon)
            end
    
            task.delay(1.5, function()
                if Token ~= FooterCopyToken or Library.Unloaded then
                    return
                end
    
                if CopyIcon then
                    Library:ApplyLucideIcon(FooterCopyButton, CopyIcon)
                end
            end)
        end
    
        FooterLinkButton.MouseEnter:Connect(function()
            local Link = WindowInfo.FooterLink
            if typeof(Link) == "string" and Link ~= "" then
                FooterLinkButton.Text = "<u>" .. EscapeRichText(Link) .. "</u>"
            end
        end)
        FooterLinkButton.MouseLeave:Connect(function()
            local Link = WindowInfo.FooterLink
            if typeof(Link) == "string" and Link ~= "" then
                FooterLinkButton.Text = EscapeRichText(Link)
            end
        end)
        FooterLinkButton.MouseButton1Click:Connect(CopyFooterLink)
        FooterCopyButton.MouseButton1Click:Connect(CopyFooterLink)
        RefreshFooter()
    
        function Window:SetFooter(Footer: string)
            assert(typeof(Footer) == "string", "Expected string for footer got: " .. typeof(Footer))
    
            WindowInfo.Footer = Footer
            RefreshFooter()
        end
    
        function Window:SetFooterLink(Link: string?)
            assert(Link == nil or typeof(Link) == "string", "Expected string or nil for footer link got: " .. typeof(Link))
    
            WindowInfo.FooterLink = Link
            RefreshFooter()
        end
    
