        local function RefreshMini()
            if not MiniCard then
                return
            end
    
            MiniSubtitle.Text = if Library.ActiveTab then tostring(Library.ActiveTab.Name or "") else ""
    
            local Footer = typeof(WindowInfo.Footer) == "string" and WindowInfo.Footer or ""
            local Link = WindowInfo.FooterLink
            if typeof(Link) == "string" and Link ~= "" then
                MiniFooter.Text = if Footer ~= "" then Link .. "  |  " .. Footer else Link
