            function Center:Place()
                local Desired = Center.DesiredHeight or Panel.Size.Y.Offset
                local Scale = math.max(Library.DPIScale, 0.01)
                if Minimized then
                    local Area = if Library.GetGuiArea then Library:GetGuiArea() else Vector2.new(1920, 1080)
                    local Top = MainFrame.AbsolutePosition.Y
                    local BelowSpace = (Area.Y - (Top + MainFrame.AbsoluteSize.Y + 10) - 8) / Scale
                    local AboveSpace = (Top - 18) / Scale
                    local Below = BelowSpace >= Desired or BelowSpace >= AboveSpace
                    local Height = math.floor(math.max(90, math.min(Desired, if Below then BelowSpace else AboveSpace)))
                    Panel.Size = UDim2.fromOffset(Panel.Size.X.Offset, Height)
                    Panel.AnchorPoint = if Below then Vector2.new(1, 0) else Vector2.new(1, 1)
                    Panel.Position = if Below then UDim2.new(1, 0, 1, 10) else UDim2.new(1, 0, 0, -10)
                else
                    local Height = math.floor(math.max(90, math.min(Desired, MainFrame.Size.Y.Offset - 62)))
                    Panel.Size = UDim2.fromOffset(Panel.Size.X.Offset, Height)
                    Panel.AnchorPoint = Vector2.new(1, 0)
                    Panel.Position = UDim2.new(1, -8, 0, 54)
                end
            end
    
