        function Window:SetSnapping(Enabled: boolean, Distance: number?, Margin: number?, AvoidCoreGui: boolean?)
            WindowInfo.Snapping = Enabled == true
            WindowSnapConfig.Enabled = WindowInfo.Snapping
    
            if Distance then
                WindowInfo.SnapDistance = math.max(0, Distance)
                WindowSnapConfig.Distance = WindowInfo.SnapDistance
            end
    
            if Margin then
                WindowInfo.SnapMargin = math.max(0, Margin)
                WindowSnapConfig.Margin = WindowInfo.SnapMargin
            end
    
            if AvoidCoreGui ~= nil then
                WindowInfo.SnapAvoidCoreGui = AvoidCoreGui == true
                WindowSnapConfig.AvoidCoreGui = WindowInfo.SnapAvoidCoreGui
            end
        end
    
        function Window:SetCornerRadius(Radius: number)
            assert(typeof(Radius) == "number", "Expected number for Radius got: " .. typeof(Radius))
            Radius = math.min(Radius, 20)
    
            local RadiusHalf = UDim.new(0, Radius / 2)
            local RadiusUDim = UDim.new(0, Radius)
            local HalfCurrent = Library.CornerRadius / 2
    
            for _, UICorner in Library.Corners do
                if math.abs(UICorner.CornerRadius.Offset - HalfCurrent) < 0.001 then
                    UICorner.CornerRadius = RadiusHalf
                else
                    UICorner.CornerRadius = RadiusUDim
                end
            end
    
            for _, UICorner in Library.SpecificCorners do
                SetUICorner(UICorner, "TopRightRadius", RadiusHalf)
                SetUICorner(UICorner, "TopLeftRadius", RadiusHalf)
                SetUICorner(UICorner, "BottomRightRadius", RadiusHalf)
                SetUICorner(UICorner, "BottomLeftRadius", RadiusHalf)
            end
    
            Library.CornerRadius = Radius
            WindowInfo.CornerRadius = Radius
    
            ResizeButton.Position = UDim2.new(1, -Radius / 4, 0, 0)
            BottomBackground.Size = UDim2.new(1, 0, 0, 20 + Radius)
    
            for _, Menu in Library.ContextMenus do
                if Menu.Destroyed then
                    continue
                end
    
                if typeof(Menu.ActiveCallback) ~= "function" then
                    continue
                end
    
                if not Menu.Active then
                    local HolderActive = false
                    for _, Other in Library.ContextMenus do
                        if Other == Menu then
                            continue
                        end
    
                        if Other.Active and Other.Holder == Menu.Holder then
                            HolderActive = true
                            break
                        end
                    end
    
                    if HolderActive then
                        continue
                    end
    
                    Menu.ActiveCallback(false)
                    continue
                end
    
                Menu.ActiveCallback(true)
            end
    
            for _, Option in Options do
                if Option.Type == "Dropdown" and Option.RefreshPool then
                    Option:RefreshPool()
                end
            end
    
            for _, Tab in Library.Tabs do
                if Tab.IsKeyTab then
                    continue
                end
    
                for _, Tabbox in Tab.Tabboxes do
                    Tabbox:UpdateCorners()
                end
            end
        end
    
        function Window:SetAnimations(Animations: { [string]: boolean }?, TabTransitionTime: number?, TabSwipeOffset: number?, TabSwipeFrom: ("left" | "right" | "top" | "bottom" | string)?)
            if typeof(Animations) == "table" then
                WindowInfo.Animations = Animations
                Library.Animations = Animations
            end
    
            if typeof(TabTransitionTime) == "number" then
                local TweenInfo = TweenInfo.new(
                    math.max(0, TabTransitionTime or 0.22),
                    Enum.EasingStyle.Quad,
                    Enum.EasingDirection.Out
                )
    
                WindowInfo.TabTransitionInfo = TweenInfo
                Library.TabTransitionInfo = TweenInfo
            end
    
            if typeof(TabSwipeOffset) == "number" then
                TabSwipeOffset = math.max(1, TabSwipeOffset)
    
                WindowInfo.TabSwipeOffset = TabSwipeOffset
                Library.TabSwipeOffset = TabSwipeOffset
            end
    
            if typeof(TabSwipeFrom) == "string" then
                TabSwipeFrom = string.lower(TabSwipeFrom)
    
                WindowInfo.TabSwipeFrom = TabSwipeFrom
                Library.TabSwipeFrom = TabSwipeFrom
            end
        end
    
        local function ApplyCompact()
            IsCompact = Window:GetSidebarWidth() == WindowInfo.SidebarCompactWidth
            if WindowInfo.DisableCompactingSnap then
                IsCompact = Window:GetSidebarWidth() <= WindowInfo.CompactWidthActivation
            end
    
            WindowTitle.Visible = false
            if not WindowInfo.Icon then
                WindowIcon.Visible = IsCompact
            end
    
            for _, Button in Library.TabButtons do
                if Button.Tile then
                    Button.Tile.Size = if IsCompact
                        then UDim2.fromOffset(WindowInfo.TabTileSize or 30, WindowInfo.TabTileSize or 30)
                        else UDim2.fromScale(1, 1)
                end
                if Button.Plate then
                    Button.Plate.Size = if IsCompact
                        then UDim2.fromOffset(WindowInfo.TabTileSize or 30, WindowInfo.TabTileSize or 30)
                        else UDim2.fromScale(1, 1)
                end
    
                if not Button.Icon then
                    continue
                end
    
                Button.Label.Visible = not IsCompact
                Button.Padding.PaddingBottom = UDim.new(0, 11)
                Button.Padding.PaddingLeft = UDim.new(0, IsCompact and 11 or 12)
                Button.Padding.PaddingRight = UDim.new(0, IsCompact and 11 or 12)
                Button.Padding.PaddingTop = UDim.new(0, 11)
                Button.Icon.SizeConstraint = IsCompact and Enum.SizeConstraint.RelativeXY or Enum.SizeConstraint.RelativeYY
            end
        end
    
        function Window:IsSidebarCompacted()
            return IsCompact
        end
    
        function Window:SetCompact(State)
            Window:SetSidebarWidth(State and WindowInfo.SidebarCompactWidth or LastExpandedWidth)
        end
    
        function Window:GetSidebarWidth()
            return Tabs.Size.X.Offset
        end
    
        function Window:SetSidebarWidth(Width)
            Width = math.clamp(Width, 48, math.max(48, MainFrame.Size.X.Offset - WindowInfo.MinContainerWidth - 1))
    
            DividerLine.Position = UDim2.fromOffset(Width, 0)
    
            TitleHolder.Size = UDim2.new(0, Width, 1, 0)
            RightWrapper.Size = UDim2.new(1, -Width - TopbarRightInset - 8 - 1, 1, -16)
            Tabs.Size = UDim2.new(0, Width, 1, -70)
            Container.Size = UDim2.new(1, -Width - 1, 1, -70)
    
            if WindowInfo.EnableCompacting then
                ApplyCompact()
            end
            if not IsCompact then
                LastExpandedWidth = Width
            end
        end
    
        function Window:ShowTabInfo(Name, Description)
            CurrentTabLabel.Text = Name
            CurrentTabDescription.Text = Description or ""
            CurrentTabDescription.Visible = typeof(Description) == "string" and Description ~= ""
            CurrentTabLabel.Position = if CurrentTabDescription.Visible then UDim2.new(0, 0, 0.5, -16) else UDim2.new(0, 0, 0.5, -8)
    
            if IsDefaultSearchbarSize then
                SearchBox.Size = if WindowInfo.ShowTabTitle ~= false
                    then UDim2.new(0, WindowInfo.SearchbarWidth or 200, 1, 0)
                    else UDim2.fromScale(0.5, 1)
            end
            CurrentTabInfo.Visible = true
        end
    
        function Window:HideTabInfo()
            CurrentTabInfo.Visible = false
            if IsDefaultSearchbarSize then
                SearchBox.Size = UDim2.fromScale(1, 1)
            end
        end
    
        local TabTooltip
        local TabTooltipLabel
        local TabTooltipDesc
        local TabTooltipStroke
        local TabTooltipArrow
        local TabTooltipKey
        local TabTooltipKeyStroke
        local TabTooltipKeyLabel
        local TabTooltipToken = 0
    
        local function EnsureTabTooltip()
            if TabTooltip then
                return
            end
    
            TabTooltip = New("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(120, 30),
                Visible = false,
                ZIndex = 70,
                Parent = MainFrame,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 6),
                Parent = TabTooltip,
            })
            TabTooltipStroke = New("UIStroke", {
                Color = "OutlineColor",
                Transparency = 1,
                Parent = TabTooltip,
            })
            TabTooltipArrow = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Position = UDim2.new(0, 0, 0.5, 0),
                Rotation = 45,
                Size = UDim2.fromOffset(8, 8),
                Parent = TabTooltip,
            })
            TabTooltipLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetMediumFont,
                Position = UDim2.fromOffset(11, 7),
                Size = UDim2.fromOffset(60, 16),
                Text = "",
                TextSize = 14,
                TextTransparency = 1,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                Parent = TabTooltip,
            })
            TabTooltipKey = New("Frame", {
                BackgroundColor3 = "BackgroundColor",
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(80, 8),
                Size = UDim2.fromOffset(38, 15),
                Parent = TabTooltip,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 4),
                Parent = TabTooltipKey,
            })
            TabTooltipKeyStroke = New("UIStroke", {
                Color = "OutlineColor",
                Transparency = 1,
                Parent = TabTooltipKey,
            })
            TabTooltipKeyLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetMediumFont,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextSize = 11,
                TextTransparency = 1,
                Parent = TabTooltipKey,
            })
            TabTooltipDesc = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(11, 24),
                Size = UDim2.fromOffset(60, 14),
                Text = "",
                TextSize = 12,
                TextTransparency = 1,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                Visible = false,
                Parent = TabTooltip,
            })
        end
    
        local function ShowTabTooltip(Entry)
            if WindowInfo.TabTooltips == false or not IsCompact or Window:IsMinimized() then
                return
            end
    
            EnsureTabTooltip()
            TabTooltipToken += 1
    
            local Description = Entry.Description
            local HotkeyIndex = if WindowInfo.TabHotkeys ~= false and Window.GetTabHotkeyIndex then Window.GetTabHotkeyIndex(Entry) else nil
            local SafeName = tostring(Entry.Name or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
            local HasDescription = typeof(Description) == "string" and Description ~= ""
            TabTooltipLabel.RichText = false
            TabTooltipLabel.Text = tostring(Entry.Name or "")
            TabTooltipDesc.Text = if HasDescription then Description else ""
            TabTooltipDesc.Visible = HasDescription
            TabTooltipKey.Visible = HotkeyIndex ~= nil
            TabTooltipKeyLabel.Text = if HotkeyIndex then "Ctrl " .. HotkeyIndex else ""
    
            local MediumFont = GetMediumFont()
            local NameWidth = Library:GetTextBounds(TabTooltipLabel.Text, MediumFont, 14, 1000)
            local KeyWidth = if HotkeyIndex then Library:GetTextBounds(TabTooltipKeyLabel.Text, MediumFont, 11, 1000) + 12 else 0
            local DescWidth = if HasDescription then Library:GetTextBounds(Description, Library.Scheme.Font, 12, 1000) else 0
            local HeaderWidth = NameWidth + (if HotkeyIndex then KeyWidth + 8 else 0)
            local Width = math.ceil(math.max(HeaderWidth, DescWidth) + 24)
            TabTooltipLabel.Size = UDim2.fromOffset(NameWidth + 4, 16)
            TabTooltipKey.Position = UDim2.fromOffset(11 + NameWidth + 8, 7)
            TabTooltipKey.Size = UDim2.fromOffset(KeyWidth, 16)
            TabTooltipDesc.Size = UDim2.fromOffset(DescWidth + 4, 14)
            TabTooltip.Size = UDim2.fromOffset(Width, if HasDescription then 45 else 30)
    
            local Scale = math.max(Library.DPIScale, 0.01)
            local Y = (Entry.Button.AbsolutePosition.Y - MainFrame.AbsolutePosition.Y + Entry.Button.AbsoluteSize.Y / 2) / Scale
            local X = Window:GetSidebarWidth() + 12
    
            TabTooltip.Position = UDim2.fromOffset(X - 6, Y)
            TabTooltip.Visible = true
    
            local Info = TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            TweenService:Create(TabTooltip, Info, { BackgroundTransparency = 0, Position = UDim2.fromOffset(X, Y) }):Play()
            TweenService:Create(TabTooltipArrow, Info, { BackgroundTransparency = 0 }):Play()
            TweenService:Create(TabTooltipStroke, Info, { Transparency = 0 }):Play()
            TweenService:Create(TabTooltipLabel, Info, { TextTransparency = 0 }):Play()
            TweenService:Create(TabTooltipDesc, Info, { TextTransparency = 0.45 }):Play()
            TweenService:Create(TabTooltipKey, Info, { BackgroundTransparency = 0.2 }):Play()
            TweenService:Create(TabTooltipKeyStroke, Info, { Transparency = 0 }):Play()
            TweenService:Create(TabTooltipKeyLabel, Info, { TextTransparency = 0.35 }):Play()
        end
    
        local function HideTabTooltip()
            if not TabTooltip then
                return
            end
    
            TabTooltipToken += 1
            local Token = TabTooltipToken
            local Info = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            TweenService:Create(TabTooltip, Info, { BackgroundTransparency = 1 }):Play()
            TweenService:Create(TabTooltipArrow, Info, { BackgroundTransparency = 1 }):Play()
            TweenService:Create(TabTooltipStroke, Info, { Transparency = 1 }):Play()
            TweenService:Create(TabTooltipLabel, Info, { TextTransparency = 1 }):Play()
            TweenService:Create(TabTooltipDesc, Info, { TextTransparency = 1 }):Play()
            TweenService:Create(TabTooltipKey, Info, { BackgroundTransparency = 1 }):Play()
            TweenService:Create(TabTooltipKeyStroke, Info, { Transparency = 1 }):Play()
            TweenService:Create(TabTooltipKeyLabel, Info, { TextTransparency = 1 }):Play()
    
            task.delay(0.13, function()
                if Token == TabTooltipToken and TabTooltip then
                    TabTooltip.Visible = false
                end
            end)
        end
    
        HideTabTooltipSafe = HideTabTooltip
    
        local function CreateTabButton(Name, Icon, Order)
            local TabButton = New("TextButton", {
                BackgroundColor3 = "MainColor",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 40),
                Text = "",
                LayoutOrder = Order,
                Parent = Tabs,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, TabButtonsStyle.CornerRadius),
                Parent = TabButton,
            })
    
            local TabIndicator
            if TabButtonsStyle.Indicator then
                TabIndicator = New("Frame", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundColor3 = "AccentColor",
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, -2, 0.5, 0),
                    Size = UDim2.fromOffset(TabButtonsStyle.IndicatorWidth, TabButtonsStyle.IndicatorHeight),
                    Parent = TabButton,
                })
    
                New("UICorner", {
                    CornerRadius = UDim.new(1, 0),
                    Parent = TabIndicator,
                })
            end
    
            local TileSize = WindowInfo.TabTileSize or 30
            local TileRadius = math.max(TabButtonsStyle.CornerRadius, 7)
    
            local HoverPlate = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = function()
                    return Library:GetBetterColor(Library.Scheme.MainColor, 9)
                end,
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = if IsCompact then UDim2.fromOffset(TileSize, TileSize) else UDim2.fromScale(1, 1),
                Parent = TabButton,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, TileRadius),
                Parent = HoverPlate,
            })
            local HoverStroke = New("UIStroke", {
                Color = "AccentColor",
                Transparency = 1,
                Parent = HoverPlate,
            })
    
            local TabTile = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                BackgroundTransparency = 1,
                ClipsDescendants = true,
                Position = UDim2.fromScale(0.5, 0.5),
                Size = if IsCompact then UDim2.fromOffset(TileSize, TileSize) else UDim2.fromScale(1, 1),
                Parent = TabButton,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, TileRadius),
                Parent = TabTile,
            })
            local TileGradient = New("UIGradient", {
                Color = GetNebulaSequence,
                Rotation = 45,
                Parent = TabTile,
            })
            local TileScale = New("UIScale", {
                Parent = TabTile,
            })
    
            local Shine = New("Frame", {
                BackgroundColor3 = "WhiteColor",
                Size = UDim2.fromScale(1, 1),
                Visible = false,
                Parent = TabTile,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, TileRadius),
                Parent = Shine,
            })
            local ShineGradient = New("UIGradient", {
                Offset = Vector2.new(-1, 0),
                Rotation = 20,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.38, 1),
                    NumberSequenceKeypoint.new(0.5, 0.45),
                    NumberSequenceKeypoint.new(0.62, 1),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = Shine,
            })
    
            local Pill = New("Frame", {
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.new(0, -TabButtonsStyle.Padding, 0.5, 0),
                Size = UDim2.fromOffset(4, 0),
                Parent = TabButton,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 2),
                Parent = Pill,
            })
            New("UIGradient", {
                Color = GetNebulaSequence,
                Rotation = 90,
                Parent = Pill,
            })
    
            local Badge = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = GetBadgeColor,
                Position = UDim2.new(0.5, TileSize / 2 - 1, 0.5, -TileSize / 2 + 1),
                Size = UDim2.fromOffset(9, 9),
                Visible = false,
                ZIndex = TabButton.ZIndex + 3,
                Parent = TabButton,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Badge,
            })
            New("UIStroke", {
                Color = function()
                    return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
                end,
                Thickness = 2,
                Parent = Badge,
            })
            local BadgeLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Size = UDim2.fromScale(1, 1),
                Text = "",
                TextColor3 = "WhiteColor",
                TextSize = 10,
                Parent = Badge,
            })
    
            local ButtonHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                ZIndex = TabButton.ZIndex + 1,
                Parent = TabButton,
            })
            local ButtonPadding = New("UIPadding", {
                PaddingBottom = UDim.new(0, 11),
                PaddingLeft = UDim.new(0, IsCompact and 11 or 12),
                PaddingRight = UDim.new(0, IsCompact and 11 or 12),
                PaddingTop = UDim.new(0, 11),
                Parent = ButtonHolder,
            })
    
            local TabLabel = New("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(30, 0),
                Size = UDim2.new(1, -30, 1, 0),
                Text = Name,
                TextSize = 16,
                TextTransparency = 0.5,
                TextXAlignment = Enum.TextXAlignment.Left,
                Visible = not IsCompact,
                Parent = ButtonHolder,
            })
    
            local TabIcon
            local Hover
            if Icon then
                TabIcon = New("ImageLabel", {
                    ImageColor3 = Icon.Custom and "WhiteColor" or "AccentColor",
                    ImageTransparency = 0.5,
                    ScaleType = Enum.ScaleType.Fit,
                    Size = UDim2.fromScale(1, 1),
                    SizeConstraint = IsCompact and Enum.SizeConstraint.RelativeXY or Enum.SizeConstraint.RelativeYY,
                    Parent = ButtonHolder,
                })
                Library:ApplyLucideIcon(TabIcon, Icon)
            end
            local IconScale = TabIcon and New("UIScale", {
                Parent = TabIcon,
            })
    
            local Entry = {
                Name = Name,
                Button = TabButton,
                Label = TabLabel,
                Padding = ButtonPadding,
                Icon = TabIcon,
                Tile = TabTile,
                Plate = HoverPlate,
                PlateStroke = HoverStroke,
                Pill = Pill,
                Shine = Shine,
                ShineGradient = ShineGradient,
                TileGradient = TileGradient,
                TileScale = TileScale,
                IconScale = IconScale,
                Indicator = TabIndicator,
                CustomIcon = Icon ~= nil and Icon.Custom == true,
                Hover = Hover,
                Badge = Badge,
                Active = false,
                Hovering = false,
            }
            table.insert(Library.TabButtons, Entry)
    
            function Entry.SetBadge(Value)
                if Value == nil or Value == false or Value == 0 then
                    Badge.Visible = false
                    return
                end
    
                Badge.Visible = true
                if typeof(Value) == "number" or typeof(Value) == "string" then
                    local Text = if typeof(Value) == "number" and Value > 99 then "99+" else tostring(Value)
                    BadgeLabel.Text = Text
                    Badge.Size = UDim2.fromOffset(math.max(16, 8 + #Text * 6), 16)
                else
                    BadgeLabel.Text = ""
                    Badge.Size = UDim2.fromOffset(9, 9)
                end
    
                if Library.IconAnimations ~= false then
                    local BadgeScale = Badge:FindFirstChildOfClass("UIScale") or New("UIScale", { Parent = Badge })
                    BadgeScale.Scale = 0.4
                    TweenService:Create(BadgeScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                        Scale = 1,
                    }):Play()
                end
            end
    
            local function PaintHover()
                local Info = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
                local Hovering = Entry.Hovering and not Entry.Active
    
                TweenService:Create(HoverPlate, Info, {
                    BackgroundTransparency = if Hovering then 0.2 else 1,
                }):Play()
                TweenService:Create(HoverStroke, Info, {
                    Transparency = if Hovering then 0.55 elseif Entry.Active and Entry.Hovering then 0.35 else 1,
                }):Play()
                TweenService:Create(Pill, TweenInfo.new(0.24, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Size = UDim2.fromOffset(4, if Entry.Active then 22 elseif Entry.Hovering then 10 else 0),
                }):Play()
    
                if TabLabel.Visible then
                    TweenService:Create(TabLabel, Info, {
                        Position = UDim2.fromOffset(if Entry.Hovering and not Entry.Active then 33 else 30, 0),
                    }):Play()
                end
            end
            Entry.PaintHover = PaintHover
    
            local function Release()
                local Info = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                TweenService:Create(TileScale, Info, { Scale = 1 }):Play()
                if IconScale then
                    TweenService:Create(IconScale, Info, { Scale = 1 }):Play()
                end
            end
    
            TabButton.MouseEnter:Connect(function()
                Entry.Hovering = true
                PaintHover()
                ShowTabTooltip(Entry)
            end)
            TabButton.MouseLeave:Connect(function()
                Entry.Hovering = false
                PaintHover()
                Release()
                HideTabTooltip()
            end)
            TabButton.MouseButton1Down:Connect(function()
                if Library.IconAnimations == false then
                    return
                end
    
                local Info = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                TweenService:Create(TileScale, Info, { Scale = 0.88 }):Play()
                if IconScale then
                    TweenService:Create(IconScale, Info, { Scale = 0.86 }):Play()
                end
            end)
            TabButton.MouseButton1Up:Connect(Release)
            TabButton.MouseButton1Click:Connect(function()
                HideTabTooltip()
            end)
    
            return TabButton, TabIndicator, TabLabel, TabIcon, Entry
        end
    
        local function PaintTabEntry(Entry, Active)
            if not Entry then
                return
            end
    
            local WasActive = Entry.Active
            Entry.Active = Active
    
            if Entry.Tile then
                TweenService:Create(Entry.Tile, Library.TweenInfo, {
                    BackgroundTransparency = Active and 0 or 1,
                }):Play()
            end
    
            if Entry.SpinTween then
                Entry.SpinTween:Cancel()
                Entry.SpinTween = nil
            end
            if Entry.TileGradient then
                Entry.TileGradient.Rotation = 45
                if Active and Library.IconAnimations ~= false then
                    Entry.SpinTween = TweenService:Create(Entry.TileGradient, TweenInfo.new(7, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {
                        Rotation = 405,
                    })
                    Entry.SpinTween:Play()
                end
            end
    
            if Active and not WasActive and Entry.Shine and Library.IconAnimations ~= false then
                Entry.Shine.Visible = true
                Entry.ShineGradient.Offset = Vector2.new(-1, 0)
                local Sweep = TweenService:Create(Entry.ShineGradient, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Offset = Vector2.new(1, 0),
                })
                Sweep.Completed:Once(function()
                    if Entry.Shine then
                        Entry.Shine.Visible = false
                    end
                end)
                Sweep:Play()
            end
    
            if Entry.PaintHover then
                Entry.PaintHover()
            end
    
            if Entry.Label then
                Library:SetSchemeProperty(Entry.Label, "TextColor3", Active and "BackgroundColor" or "FontColor", true)
            end
    
            if Entry.Icon and not Entry.CustomIcon then
                Library:SetSchemeProperty(Entry.Icon, "ImageColor3", Active and "BackgroundColor" or "AccentColor", true)
            end
        end
    
        function Window:AddTab(...)
            local Name = nil
            local Icon = nil
            local Description = nil
            local Tooltip = nil
            local Order = nil
    
            if select("#", ...) == 1 and typeof(...) == "table" then
                local Info = select(1, ...)
                Name = Info.Name or "Tab"
                Icon = Info.Icon
                Description = Info.Description
                Tooltip = Info.Tooltip
                Order = Info.Order
            else
                Name = select(1, ...)
                Icon = select(2, ...)
                Description = select(3, ...)
                Order = select(4, ...)
            end
    
            if not tonumber(Order) then
                Order = #Tabs:GetChildren()
            end
    
            local TabButton: TextButton
            local TabIndicator
            local TabLabel
            local TabIcon
            local TabEntry
    
            local TabContainer
            local TabLeft
            local TabRight
    
            Icon = Library:GetCustomIcon(Icon)
            do
                TabButton, TabIndicator, TabLabel, TabIcon, TabEntry = CreateTabButton(Name, Icon, Order)
                TabEntry.Description = Description
    
                TabContainer = New("Frame", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0, 0),
                    Size = UDim2.fromScale(1, 1),
                    Visible = false,
                    Parent = Container,
                })
    
                TabLeft = New("ScrollingFrame", {
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    CanvasSize = UDim2.fromScale(0, 0),
                    ScrollBarImageTransparency = 1,
                    ScrollBarThickness = 0,
                    Size = UDim2.new(0.5, -3, 1, 0),
                    Parent = TabContainer,
                })
                New("UIListLayout", {
                    Padding = UDim.new(0, 2),
                    Parent = TabLeft,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 2),
                    PaddingLeft = UDim.new(0, 2),
                    PaddingRight = UDim.new(0, 2),
                    PaddingTop = UDim.new(0, 2),
                    Parent = TabLeft,
                })
                do
                    New("Frame", {
                        BackgroundTransparency = 1,
                        LayoutOrder = -1,
                        Parent = TabLeft,
                    })
                    New("Frame", {
                        BackgroundTransparency = 1,
                        LayoutOrder = 1,
                        Parent = TabLeft,
                    })
                end
    
                TabRight = New("ScrollingFrame", {
                    AnchorPoint = Vector2.new(1, 0),
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    CanvasSize = UDim2.fromScale(0, 0),
                    Position = UDim2.fromScale(1, 0),
                    ScrollBarImageTransparency = 1,
                    ScrollBarThickness = 0,
                    Size = UDim2.new(0.5, -3, 1, 0),
                    Parent = TabContainer,
                })
                New("UIListLayout", {
                    Padding = UDim.new(0, 2),
                    Parent = TabRight,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 2),
                    PaddingLeft = UDim.new(0, 2),
                    PaddingRight = UDim.new(0, 2),
                    PaddingTop = UDim.new(0, 2),
                    Parent = TabRight,
                })
                do
                    New("Frame", {
                        BackgroundTransparency = 1,
                        LayoutOrder = -1,
                        Parent = TabRight,
                    })
                    New("Frame", {
                        BackgroundTransparency = 1,
                        LayoutOrder = 1,
                        Parent = TabRight,
                    })
                end
            end
    
            local Tab = {
                Name = Name,
                Description = Description,
    
                Tooltip = Tooltip,
                TooltipTable = nil,
    
                Connections = {},
                Destroyed = false,
    
                Window = Window,
                Button = TabButton,
                Container = TabContainer,
                Sides = {
                    TabLeft,
                    TabRight,
                },
                WarningBox = {
                    IsNormal = false,
                    LockSize = false,
                    Visible = false,
                    Title = "WARNING",
                    Text = "",
                },
    
                Groupboxes = {},
                Tabboxes = {},
                DependencyGroupboxes = {},
            }
    
            local WarningBoxHolder = New("Frame", {
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(0, 7),
                Size = UDim2.fromScale(1, 0),
                Visible = false,
                Parent = TabContainer,
            })
    
            local WarningBox
            local WarningBoxOutline
            local WarningBoxShadowOutline
            local WarningBoxScrollingFrame
            local WarningTitle
            local WarningStroke
            local WarningText
            do
                WarningBox = New("Frame", {
                    BackgroundColor3 = Color3.fromRGB(127, 0, 0),
                    Position = UDim2.fromOffset(2, 0),
                    Size = UDim2.new(1, -5, 0, 0),
                    Parent = WarningBoxHolder,
                })
                Library:AddToRegistry(WarningBox, {
                    BackgroundColor3 = function()
                        return Tab.WarningBox.IsNormal == true and Library.Scheme.BackgroundColor or Color3.fromRGB(127, 0, 0)
                    end
                })
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                        Parent = WarningBox,
                    })
                )
                WarningBoxOutline, WarningBoxShadowOutline = Library:AddOutline(WarningBox)
                Library:AddToRegistry(WarningBoxOutline, {
                    Color = function()
                        return Tab.WarningBox.IsNormal == true and Library.Scheme.OutlineColor or Color3.fromRGB(255, 50, 50)
                    end
                })
                Library:AddToRegistry(WarningBoxShadowOutline, {
                    Color = function()
                        return Tab.WarningBox.IsNormal == true and Library.Scheme.DarkColor or Color3.fromRGB(85, 0, 0)
                    end
                })
    
                WarningBoxScrollingFrame = New("ScrollingFrame", {
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Size = UDim2.fromScale(1, 1),
                    CanvasSize = UDim2.new(0, 0, 0, 0),
                    ScrollBarThickness = 3,
                    ScrollingDirection = Enum.ScrollingDirection.Y,
                    Parent = WarningBox,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 4),
                    PaddingLeft = UDim.new(0, 6),
                    PaddingRight = UDim.new(0, 6),
                    PaddingTop = UDim.new(0, 4),
                    Parent = WarningBoxScrollingFrame,
                })
    
                WarningTitle = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, -4, 0, 14),
                    Text = "",
                    TextColor3 = Color3.fromRGB(255, 50, 50),
                    TextSize = 14,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Parent = WarningBoxScrollingFrame,
                })
                Library:AddToRegistry(WarningTitle, {
                    TextColor3 = function()
                        return Tab.WarningBox.IsNormal == true and Library.Scheme.FontColor or Color3.fromRGB(255, 50, 50)
                    end
                })
    
                WarningStroke = New("UIStroke", {
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                    Color = Color3.fromRGB(169, 0, 0),
                    LineJoinMode = Enum.LineJoinMode.Miter,
                    Parent = WarningTitle,
                })
                Library:AddToRegistry(WarningStroke, {
                    Color = function()
                        return Tab.WarningBox.IsNormal == true and Library.Scheme.OutlineColor or Color3.fromRGB(169, 0, 0)
                    end
                })
    
                WarningText = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(0, 16),
                    Size = UDim2.new(1, -4, 0, 0),
                    Text = "",
                    TextSize = 14,
                    TextWrapped = true,
                    Parent = WarningBoxScrollingFrame,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Top,
                })
    
                New("UIStroke", {
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                    Color = "DarkColor",
                    LineJoinMode = Enum.LineJoinMode.Miter,
                    Parent = WarningText,
                })
            end
    
            function Tab:UpdateWarningBox(Info)
                if typeof(Info.IsNormal) == "boolean" then
                    Tab.WarningBox.IsNormal = Info.IsNormal
                end
                if typeof(Info.LockSize) == "boolean" then
                    Tab.WarningBox.LockSize = Info.LockSize
                end
                if typeof(Info.Visible) == "boolean" then
                    Tab.WarningBox.Visible = Info.Visible
                end
                if typeof(Info.Title) == "string" then
                    Tab.WarningBox.Title = Info.Title
                end
                if typeof(Info.Text) == "string" then
                    Tab.WarningBox.Text = Info.Text
                end
    
                WarningBoxHolder.Visible = Tab.WarningBox.Visible
                WarningTitle.Text = Tab.WarningBox.Title
                WarningText.Text = Tab.WarningBox.Text
                Tab:Resize(true)
    
                WarningBox.BackgroundColor3 = Library.Registry[WarningBox].BackgroundColor3()
                WarningBoxShadowOutline.Color = Library.Registry[WarningBoxShadowOutline].Color()
                WarningBoxOutline.Color = Library.Registry[WarningBoxOutline].Color()
                WarningTitle.TextColor3 = Library.Registry[WarningTitle].TextColor3()
                WarningStroke.Color = Library.Registry[WarningStroke].Color()
            end
    
            function Tab:RefreshSides()
                local Offset = WarningBoxHolder.Visible and WarningBox.Size.Y.Offset + 8 or 0
                for _, Side in Tab.Sides do
                    Side.Position = UDim2.new(Side.Position.X.Scale, 0, 0, Offset)
                    Side.Size = UDim2.new(0.5, -3, 1, -Offset)
                end
            end
    
            function Tab:Resize(ResizeWarningBox: boolean?)
                if ResizeWarningBox then
                    local MaximumSize = math.floor((TabContainer.AbsoluteSize.Y / Library.DPIScale) / 3.25)
                    local _, YText = Library:GetTextBounds(
                        WarningText.Text,
                        Library.Scheme.Font,
                        WarningText.TextSize,
                        WarningText.AbsoluteSize.X / Library.DPIScale
                    )
    
                    local YBox = 24 + YText
                    if Tab.WarningBox.LockSize == true and YBox >= MaximumSize then
                        WarningBoxScrollingFrame.CanvasSize = UDim2.fromOffset(0, YBox)
                        YBox = MaximumSize
                    else
                        WarningBoxScrollingFrame.CanvasSize = UDim2.fromOffset(0, 0)
                    end
    
                    WarningText.Size = UDim2.new(1, -4, 0, YText)
                    WarningBox.Size = UDim2.new(1, -5, 0, YBox + 4)
                end
    
                Tab:RefreshSides()
            end
    
            local function AddTabbox(self, Info)
                Info = Library:Validate(Info, Templates.Tabbox)
                local ParentObj = self
    
                if typeof(Info.Side) == "string" then
                    local lowerSide = string.lower(Info.Side)
                    if not SideIndex[lowerSide] then
                        error(string.format("Invalid side: %s", Info.Side))
                    end
    
                    Info.Side = SideIndex[lowerSide]
                end
    
                local BoxHolder = New("Frame", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 0),
                    Parent = if ParentObj.Type == "Groupbox" then ParentObj.Container else (Info.Side == 1 and TabLeft or TabRight),
                })
                New("UIListLayout", {
                    Padding = UDim.new(0, 6),
                    Parent = BoxHolder,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 4),
                    PaddingTop = UDim.new(0, 4),
                    Parent = BoxHolder,
                })
    
                local TabboxHolder
                local TabboxButtons
    
                do
                    TabboxHolder = New("Frame", {
                        BackgroundColor3 = "BackgroundColor",
                        Size = UDim2.fromScale(1, 0),
                        Parent = BoxHolder,
                    })
                    MakeGlass(TabboxHolder)
                    table.insert(
                        Library.Corners,
                        New("UICorner", {
                            CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                            Parent = TabboxHolder,
                        })
                    )
                    Library:AddOutline(TabboxHolder)
    
                    TabboxButtons = New("Frame", {
                        BackgroundTransparency = 1,
                        Size = UDim2.new(1, 0, 0, 34),
                        Parent = TabboxHolder,
                    })
                    New("UIListLayout", {
                        FillDirection = Enum.FillDirection.Horizontal,
                        HorizontalFlex = Enum.UIFlexAlignment.Fill,
                        Parent = TabboxButtons,
                    })
                end
    
                local TotalTabs = 0
                local FirstTab
                local LastTab
    
                local Tabbox: any = {
                    Type = "Tabbox",
    
                    Connections = {},
                    Destroyed = false,
    
                    Visible = true,
                    ActiveTab = nil,
    
                    BoxHolder = BoxHolder,
                    Holder = TabboxHolder,
                    Tabs = {},
    
                    ParentBox = if ParentObj.Type == "Groupbox" then ParentObj else nil,
                }
    
                function Tabbox:UpdateCorners()
                    for _, Tab in Tabbox.Tabs do
                        Tab:UpdateCorners()
                    end
                end
    
                function Tabbox:Resize()
                    if Tabbox.ActiveTab then
                        Tabbox.ActiveTab:Resize()
                    end
                end
    
                function Tabbox:AddTab(Name, IconName)
                    TotalTabs = TotalTabs + 1
                    local TabIndex = TotalTabs
    
                    LastTab = TabIndex
                    if not FirstTab then
                        FirstTab = TabIndex
                    end
    
                    local IsNameEmpty = Name == nil or Trim(tostring(Name)) == ""
                    local TabStoringIndex = IsNameEmpty and tostring(TabIndex) or Name
    
                    local Button = New("TextButton", {
                        BackgroundColor3 = "MainColor",
                        BackgroundTransparency = 0,
                        Size = UDim2.fromOffset(0, 34),
                        Text = "",
                        Parent = TabboxButtons,
                    })
    
                    local ButtonCorner = New("UICorner", {
                        TopLeftRadius = UDim.new(0, WindowInfo.CornerRadius),
                        TopRightRadius = UDim.new(0, WindowInfo.CornerRadius),
                        BottomRightRadius = UDim.new(0, 0),
                        BottomLeftRadius = UDim.new(0, 0),
                        Parent = Button,
                    }); table.insert(Library.SpecificCorners, ButtonCorner)
    
                    local ButtonContent = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        AutomaticSize = Enum.AutomaticSize.X,
                        BackgroundTransparency = 1,
                        Position = UDim2.fromScale(0.5, 0.5),
                        Size = UDim2.fromOffset(0, 16),
                        Parent = Button,
                    })
                    New("UIListLayout", {
                        FillDirection = Enum.FillDirection.Horizontal,
                        HorizontalAlignment = Enum.HorizontalAlignment.Center,
                        VerticalAlignment = Enum.VerticalAlignment.Center,
                        Padding = UDim.new(0, 8),
                        Parent = ButtonContent,
                    })
    
                    local ButtonIcon
                    local BoxIcon = Library:GetCustomIcon(IconName)
                    if BoxIcon then
                        ButtonIcon = New("ImageLabel", {
                            ImageColor3 = BoxIcon.Custom and "WhiteColor" or "AccentColor",
                            ImageTransparency = 0.5,
                            Size = IsNameEmpty and UDim2.fromOffset(16, 16) or UDim2.fromOffset(18, 18),
                            Parent = ButtonContent,
                        })
                        Library:ApplyLucideIcon(ButtonIcon, BoxIcon)
                    end
    
                    local ButtonLabel
                    if not IsNameEmpty then
                        ButtonLabel = New("TextLabel", {
                            AutomaticSize = Enum.AutomaticSize.X,
                            BackgroundTransparency = 1,
                            Size = UDim2.fromOffset(0, 16),
                            Text = Name,
                            TextSize = 15,
                            TextTransparency = 0.5,
                            Parent = ButtonContent,
                        })
                    end
    
                    local Line = Library:MakeLine(Button, {
                        AnchorPoint = Vector2.new(0, 1),
                        Position = UDim2.new(0, 0, 1, 1),
                        Size = UDim2.new(1, 0, 0, 1),
                    })
    
                    local Container = New("ScrollingFrame", {
                        AutomaticCanvasSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        BorderSizePixel = 0,
                        CanvasSize = UDim2.fromScale(0, 0),
                        Position = UDim2.fromOffset(0, 35),
                        ScrollBarThickness = 0,
                        Size = UDim2.new(1, 0, 1, -35),
                        Visible = false,
                        Parent = TabboxHolder,
                    })
                    local List = New("UIListLayout", {
                        Padding = UDim.new(0, 8),
                        Parent = Container,
                    })
                    New("UIPadding", {
                        PaddingBottom = UDim.new(0, 7),
                        PaddingLeft = UDim.new(0, 7),
                        PaddingRight = UDim.new(0, 7),
                        PaddingTop = UDim.new(0, 7),
                        Parent = Container,
                    })
    
                    local Tab = {
                        Name = Name,
    
                        Connections = {},
                        Destroyed = false,
    
                        ButtonHolder = Button,
                        Container = Container,
                        ButtonCorner = ButtonCorner,
    
                        Tab = Tab,
                        Tabbox = Tabbox,
    
                        Elements = {},
                        DependencyBoxes = {},
                    }
    
                    function Tab:Show()
                        if Tabbox.ActiveTab then
                            Tabbox.ActiveTab:Hide()
                        end
    
                        Button.BackgroundTransparency = 1
    
                        if ButtonLabel then
                            ButtonLabel.TextTransparency = 0
                        end
                        if ButtonIcon then
                            ButtonIcon.ImageTransparency = 0
                        end
    
                        Line.Visible = false
    
                        Container.Visible = true
    
                        Tabbox.ActiveTab = Tab
                        Tab:Resize()
                        Tabbox:RefreshPopOutPlaceholder()
                    end
    
                    function Tab:Hide()
                        Button.BackgroundTransparency = 0
    
                        if ButtonLabel then
                            ButtonLabel.TextTransparency = 0.5
                        end
                        if ButtonIcon then
                            ButtonIcon.ImageTransparency = 0.5
                        end
                        Line.Visible = true
                        Container.Visible = false
    
                        Tabbox.ActiveTab = nil
                    end
    
                    function Tab:Resize()
                        if Tabbox.ActiveTab ~= Tab then
                            return
                        end
    
                        local ContentSize = (List.AbsoluteContentSize.Y / Library.DPIScale) + 14
                        if Tabbox.PoppedOut then
                            ContentSize = math.min(ContentSize, GetPopOutBodyMaxHeight(Tabbox, 35))
                        end
    
                        TabboxHolder.Size = UDim2.new(1, 0, 0, ContentSize + 35)
                        if ParentObj.Type == "Groupbox" then
                            ParentObj:Resize()
                        end
                    end
    
                    function Tab:UpdateCorners()
                        local Radius = WindowInfo.CornerRadius
    
                        ButtonCorner.TopLeftRadius = UDim.new(0, TabIndex == FirstTab and Radius or 0)
                        ButtonCorner.TopRightRadius = UDim.new(0, TabIndex == LastTab and Radius or 0)
                    end
    
                    function Tab:Destroy()
                        Tab.Destroyed = true
    
                        if Tab.Connections then
                            for _, Connection in Tab.Connections do
                                Connection:Disconnect()
                            end
                        end
    
                        for _, Element in Tab.Elements do
                            if Element.Destroy then
                                Element:Destroy()
                            end
                        end
    
                        for _, SubDepbox in Tab.DependencyBoxes do
                            if SubDepbox.Destroy then
                                SubDepbox:Destroy()
                            end
                        end
    
                        if Container then
                            Container:Destroy()
                        end
    
                        if Button then
                            Button:Destroy()
                        end
                    end
    
                    if not Tabbox.ActiveTab then
                        Tab:Show()
                    end
    
                    Button.MouseButton1Click:Connect(Tab.Show)
    
                    setmetatable(Tab, BaseGroupbox)
    
                    Tabbox.Tabs[TabStoringIndex] = Tab
                    Tabbox:UpdateCorners()
    
                    return Tab, TabStoringIndex
                end
    
                Library:MakeBoxPopOut(Tabbox, {
                    Enabled = Info.PopOut ~= false,
                    MaxPopOutHeight = Info.MaxPopOutHeight,
                    PopOutWidth = Info.PopOutWidth,
    
                    Header = TabboxButtons,
                    Children = function()
                        return { TabboxHolder }
                    end,
    
                    After = function()
                        if Tabbox.ActiveTab then
                            Tabbox.ActiveTab:Resize()
                        end
                        if ParentObj.Type == "Groupbox" then
                            ParentObj:Resize()
                        end
                    end,
                })
    
                function Tabbox:Destroy()
                    if Tabbox.PoppedOut then
                        Tabbox:SetPoppedOut(false)
                    end
    
                    Tabbox.Destroyed = true
    
                    if Tabbox.Connections then
                        for _, Connection in Tabbox.Connections do
                            Connection:Disconnect()
                        end
                    end
    
                    for _, Tab in Tabbox.Tabs do
                        if Tab.Destroy then
                            Tab:Destroy()
                        end
                    end
    
                    if TabboxHolder then
                        TabboxHolder:Destroy()
                    end
    
                    if BoxHolder then
                        BoxHolder:Destroy()
                    end
                end
    
                if Info.Name then
                    Tab.Tabboxes[Info.Name] = Tabbox
                else
                    table.insert(Tab.Tabboxes, Tabbox)
                end
    
                return Tabbox
            end
    
            Tab.AddTabbox = AddTabbox
    
            function Tab:AddLeftTabbox(Name)
                return Tab:AddTabbox({ Side = 1, Name = Name })
            end
    
            function Tab:AddRightTabbox(Name)
                return Tab:AddTabbox({ Side = 2, Name = Name })
            end
    
            function Tab:AddGroupbox(Info)
                Info = Library:Validate(Info, Templates.Groupbox)
    
                if typeof(Info.Side) == "string" then
                    local lowerSide = string.lower(Info.Side)
                    if not SideIndex[lowerSide] then
                        error(string.format("Invalid side: %s", Info.Side))
                    end
    
                    Info.Side = SideIndex[lowerSide]
                end
    
                local BoxHolder = New("Frame", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 0),
                    Parent = (Info.Side == 1) and TabLeft or TabRight,
                })
                New("UIListLayout", {
                    Padding = UDim.new(0, 6),
                    Parent = BoxHolder,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 4),
                    PaddingTop = UDim.new(0, 4),
                    Parent = BoxHolder,
                })
    
                local GroupboxHolder
    
                local GroupboxTop
                local GroupboxLabel
                local GroupboxDescription
    
                local GroupboxContainer
                local GroupboxList
    
                local GroupboxCollapseArrow
                local GroupboxLine
    
                do
                    GroupboxHolder = New("Frame", {
                        BackgroundColor3 = "BackgroundColor",
                        Size = UDim2.fromScale(1, 0),
                        Parent = BoxHolder,
                    })
                    MakeGlass(GroupboxHolder)
                    table.insert(
                        Library.Corners,
                        New("UICorner", {
                            CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                            Parent = GroupboxHolder,
                        })
                    )
                    New("UIListLayout", {
                        Parent = GroupboxHolder,
                    })
                    Library:AddOutline(GroupboxHolder)
    
                    GroupboxTop = New("Frame", {
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        Size = UDim2.fromScale(1, 0),
                        Parent = GroupboxHolder,
                    })
                    New("UIPadding", {
                        PaddingBottom = UDim.new(0, 6),
                        PaddingLeft = UDim.new(0, 6),
                        PaddingRight = UDim.new(0, 6),
                        PaddingTop = UDim.new(0, 6),
                        Parent = GroupboxTop,
                    })
    
                    local BoxIcon = Library:GetCustomIcon(Info.IconName)
                    if BoxIcon then
                        local GroupboxHeaderIcon = New("ImageLabel", {
                            AnchorPoint = Vector2.new(0, 0.5),
                            ImageColor3 = BoxIcon.Custom and "WhiteColor" or "AccentColor",
                            Position = UDim2.fromScale(0, 0.5),
                            Size = UDim2.fromOffset(22, 22),
                            Parent = GroupboxTop,
                        })
                        Library:ApplyLucideIcon(GroupboxHeaderIcon, BoxIcon)
                        Library:AddIconHover(GroupboxTop, GroupboxHeaderIcon, { Scale = 1.15, Tilt = -10, Press = false })
                    end
    
                    local RightInset = if Info.DisableCollapsing ~= true then 22 else 0
                    local TextsFrame = New("Frame", {
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(BoxIcon and 24 or 0, 0),
                        Size = UDim2.new(1, -RightInset - (BoxIcon and 24 or 0), 0, 0),
                        Parent = GroupboxTop,
                    })
                    New("UIListLayout", {
                        Parent = TextsFrame,
                    })
                    New("UIPadding", {
                        PaddingBottom = UDim.new(0, 3),
                        PaddingLeft = UDim.new(0, 6),
                        PaddingRight = UDim.new(0, 6),
                        PaddingTop = UDim.new(0, 3),
                        Parent = TextsFrame,
                    })
    
                    GroupboxLabel = New("TextLabel", {
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        Size = UDim2.fromScale(1, 0),
                        Text = Info.Name,
                        TextSize = 15,
                        TextWrapped = true,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        Parent = TextsFrame,
                    })
                    New("UIPadding", {
                        PaddingBottom = UDim.new(0, 1),
                        Parent = GroupboxLabel,
                    })
    
                    GroupboxDescription = New("TextLabel", {
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        Size = UDim2.fromScale(1, 0),
                        Text = Info.Description or "",
                        TextSize = 14,
                        TextTransparency = 0.5,
                        TextWrapped = true,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        Visible = (Info.Description ~= nil),
                        Parent = TextsFrame,
                    })
    
                    GroupboxCollapseArrow = New("ImageButton", {
                        Visible = Info.DisableCollapsing ~= true,
                        AnchorPoint = Vector2.new(1, 0.5),
                        BackgroundTransparency = 1,
                        ImageColor3 = "WhiteColor",
                        Position = UDim2.fromScale(1, 0.5),
                        Size = UDim2.fromOffset(22, 22),
                        Parent = GroupboxTop,
                    })
                    if ArrowIcon then
                        Library:ApplyLucideIcon(GroupboxCollapseArrow, ArrowIcon, 180)
                    end
                    Library:AddIconHover(GroupboxCollapseArrow, GroupboxCollapseArrow, { Scale = 1.15 })
    
                    GroupboxLine = Library:MakeLine(GroupboxHolder, {
                        LayoutOrder = 1,
                        Size = UDim2.new(1, 0, 0, 1),
                    })
    
                    GroupboxContainer = New("ScrollingFrame", {
                        AutomaticCanvasSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        BorderSizePixel = 0,
                        CanvasSize = UDim2.fromScale(0, 0),
                        LayoutOrder = 2,
                        ScrollBarThickness = 0,
                        Size = UDim2.fromScale(1, 0),
                        Parent = GroupboxHolder,
                    })
    
                    GroupboxList = New("UIListLayout", {
                        Padding = UDim.new(0, 8),
                        Parent = GroupboxContainer,
                    })
                    New("UIPadding", {
                        PaddingBottom = UDim.new(0, 7),
                        PaddingLeft = UDim.new(0, 7),
                        PaddingRight = UDim.new(0, 7),
                        PaddingTop = UDim.new(0, 7),
                        Parent = GroupboxContainer,
                    })
                end
    
                local Groupbox: any = {
                    Type = "Groupbox",
    
                    Name = Info.Name,
                    Description = Info.Description,
    
                    Connections = {},
                    Destroyed = false,
    
                    Visible = true,
                    Collapsed = false,
    
                    BoxHolder = BoxHolder,
                    Holder = GroupboxHolder,
                    Container = GroupboxContainer,
    
                    Tab = Tab,
                    DependencyBoxes = {},
                    Elements = {}
                }
    
                local ResizeTween
                local ResizeTarget
                local CollapseArrowTween

                function Groupbox:Resize()
                    local TopSize = (GroupboxTop.AbsoluteSize.Y / Library.DPIScale)
                    local ContainerSize = (GroupboxList.AbsoluteContentSize.Y / Library.DPIScale) + 14
                    if Groupbox.PoppedOut then
                        ContainerSize = math.min(ContainerSize, GetPopOutBodyMaxHeight(Groupbox, TopSize + 1))
                    end
    
                    local TargetSize = UDim2.new(1, 0, 0, if Groupbox.Collapsed then TopSize else (TopSize + 1 + ContainerSize))
                    GroupboxContainer.Size = UDim2.new(1, 0, 0, ContainerSize)
                    GroupboxLine.Visible = not Groupbox.Collapsed

                    -- live labels fire AbsoluteContentSize often: keep a running tween to the same size, skip a resize to the current size
                    if ResizeTween then
                        if ResizeTarget == TargetSize then
                            return
                        end
                        StopTween(ResizeTween, true)
                        ResizeTween = nil
                    elseif GroupboxHolder.Size == TargetSize then
                        return
                    end
                    ResizeTarget = TargetSize

                    if Library.Animations and Library.Animations.Groupbox then
                        local TweenInfo = Library.GroupboxTweenInfo or TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                        local Tween = TweenService:Create(GroupboxHolder, TweenInfo, { Size = TargetSize })
                        ResizeTween = Tween
    
                        local Connection; Connection = Library:GiveSignal(Tween.Completed:Once(function()
                            if Connection then
                                Connection:Disconnect()
                            end
    
                            if ResizeTween == Tween then
                                StopTween(ResizeTween, true)
                                ResizeTween = nil
                            end
                        end))
    
                        Tween:Play()
                    else
                        GroupboxHolder.Size = TargetSize
                    end
                end
    
                table.insert(Groupbox.Connections, GroupboxList:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                    if Groupbox.Visible == false or Groupbox.Destroyed then
                        return
                    end
    
                    Groupbox:Resize()
                end))
    
                function Groupbox:SetDescription(Description: string | nil)
                    GroupboxDescription.Text = Description or ""
                    GroupboxDescription.Visible = (Description ~= nil)
    
                    Groupbox:Resize()
                end
    
                function Groupbox:SetCollapsed(Collapsed: boolean)
                    if Info.DisableCollapsing == true then return end
                    Groupbox.Collapsed = Collapsed
    
                    if CollapseArrowTween then
                        StopTween(CollapseArrowTween, true)
                        CollapseArrowTween = nil
                    end
    
                    local TargetRotation = if Collapsed then 0 else 180
    
                    GroupboxContainer.Visible = not Collapsed
                    if Library.Animations and Library.Animations.Groupbox then
                        local TweenInfo = Library.GroupboxTweenInfo or TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                        local Tween = TweenService:Create(GroupboxCollapseArrow, TweenInfo, { Rotation = TargetRotation })
                        CollapseArrowTween = Tween
    
                        local Connection; Connection = Library:GiveSignal(Tween.Completed:Connect(function()
                            if Connection then
                                Connection:Disconnect()
                            end
    
                            if CollapseArrowTween == Tween then
                                StopTween(CollapseArrowTween, true)
                                CollapseArrowTween = nil
                            end
                        end))
    
                        Tween:Play()
                    else
                        GroupboxCollapseArrow.Rotation = TargetRotation
                    end
    
                    Groupbox:Resize()
                end
    
                function Groupbox:ToggleCollapsed()
                    if Info.DisableCollapsing == true then return end
                    Groupbox:SetCollapsed(not Groupbox.Collapsed)
                end
    
                Library:MakeBoxPopOut(Groupbox, {
                    Enabled = Info.PopOut ~= false,
                    MaxPopOutHeight = Info.MaxPopOutHeight,
                    PopOutWidth = Info.PopOutWidth,
    
                    Header = GroupboxTop,
                    Children = function()
                        local Children = {}
                        for _, Child in BoxHolder:GetChildren() do
                            if Child:IsA("GuiObject") and Child ~= Groupbox.PopOutPlaceholder then
                                table.insert(Children, Child)
                            end
                        end
                        return Children
                    end,
    
                    Before = function()
                        GroupboxCollapseArrow.Visible = false
                    end,
                    After = function()
                        GroupboxCollapseArrow.Visible = Info.DisableCollapsing ~= true
                        Groupbox:Resize()
                    end
                })
    
                function Groupbox:Destroy()
                    if Groupbox.PoppedOut then
                        Groupbox:SetPoppedOut(false)
                    end
    
                    Groupbox.Destroyed = true
    
                    if ResizeTween then
                        StopTween(ResizeTween, true)
                        ResizeTween = nil
                    end
    
                    if CollapseArrowTween then
                        StopTween(CollapseArrowTween, true)
                        CollapseArrowTween = nil
                    end
    
                    if Groupbox.Connections then
                        for _, Connection in Groupbox.Connections do
                            Connection:Disconnect()
                        end
                    end
    
                    for _, Element in Groupbox.Elements do
                        if Element.Destroy then
                            Element:Destroy()
                        end
                    end
                    table.clear(Groupbox.Elements)
    
                    for _, SubDepbox in Groupbox.DependencyBoxes do
                        if SubDepbox.Destroy then
                            SubDepbox:Destroy()
                        end
                    end
                    table.clear(Groupbox.DependencyBoxes)
    
                    if GroupboxHolder then
                        GroupboxHolder:Destroy()
                    end
    
                    if BoxHolder then
                        BoxHolder:Destroy()
                    end
                end
    
                function Groupbox:SetVisible(Visible: boolean)
                    Groupbox.Visible = Visible
                    BoxHolder.Visible = Visible
                    SyncPopOutVisibility(Groupbox)
    
                    if Visible == true and Library.Searching then
                        Library:UpdateSearch(Library.SearchText)
                    end
                end
    
                function Groupbox:Show()
                    Groupbox:SetVisible(true)
                end
    
                function Groupbox:Hide()
                    Groupbox:SetVisible(false)
                end
    
                if Info.DisableCollapsing ~= true then
                    GroupboxCollapseArrow.MouseButton1Click:Connect(function()
                        Groupbox:ToggleCollapsed()
                    end)
                end
    
                Groupbox.AddTabbox = AddTabbox
                setmetatable(Groupbox, BaseGroupbox)
    
                Groupbox:Resize()
                Tab.Groupboxes[Info.Name] = Groupbox
    
                if Info.Visible == false then
                    Groupbox:Hide()
                end
    
                if Info.DisableCollapsing ~= true and Info.Collapsed == true then
                    Groupbox:SetCollapsed(true)
                end
    
                return Groupbox
            end
    
            function Tab:AddLeftGroupbox(Name, IconName, Visible, Collapsed, DisableCollapsing)
                return Tab:AddGroupbox({ Side = 1, Name = Name, IconName = IconName, Visible = Visible, Collapsed = Collapsed, DisableCollapsing = DisableCollapsing })
            end
    
            function Tab:AddRightGroupbox(Name, IconName, Visible, Collapsed, DisableCollapsing)
                return Tab:AddGroupbox({ Side = 2, Name = Name, IconName = IconName, Visible = Visible, Collapsed = Collapsed, DisableCollapsing = DisableCollapsing })
            end
    
            function Tab:Hover(Hovering)
                if Library.ActiveTab == Tab then
                    return
                end
    
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = Hovering and 0.25 or 0.5,
                }):Play()
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = Hovering and 0.25 or 0.5,
                    }):Play()
                end
            end
    
            function Tab:Show()
                if Library.ActiveTab == Tab then
                    return
                end
    
                if Library.ActiveTab then
                    Library.ActiveTab:Hide()
                end
    
                PaintTabEntry(TabEntry, true)
                if TabIndicator then
                    TweenService:Create(TabIndicator, Library.TweenInfo, {
                        BackgroundTransparency = 0,
                    }):Play()
                end
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = 0,
                }):Play()
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = 0,
                    }):Play()
                end
    
                if Description or WindowInfo.ShowTabTitle ~= false then
                    Window:ShowTabInfo(Name, Description)
                end
    
                Library:PlayTabAnimation(Tab, true)
                Tab:RefreshSides()
    
                Library.ActiveTab = Tab
    
                if Library.Searching then
                    Library:UpdateSearch(Library.SearchText)
                end
            end
    
            function Tab:Hide()
                PaintTabEntry(TabEntry, false)
    
                if TabIndicator then
                    TweenService:Create(TabIndicator, Library.TweenInfo, {
                        BackgroundTransparency = 1,
                    }):Play()
                end
    
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = 0.5,
                }):Play()
    
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = 0.5,
                    }):Play()
                end
    
                Library:PlayTabAnimation(Tab, false)
                Window:HideTabInfo()
    
                Library.PreviousTab = Tab
                Library.ActiveTab = nil
            end
    
            function Tab:SetVisible(Visible: boolean)
                TabButton.Visible = Visible
    
                if not Visible and Library.ActiveTab == Tab then
                    Tab:Hide()
                end
            end
    
            function Tab:SetBadge(Value: any)
                Tab.BadgeValue = Value
                if TabEntry and TabEntry.SetBadge then
                    TabEntry.SetBadge(Value)
                end
            end
    
            function Tab:SetOrder(NewOrder: number)
                Order = NewOrder
                TabButton.LayoutOrder = Order
            end
    
            function Tab:SetTooltip(Text: string?)
                Tab.Tooltip = Text
    
                if Tab.TooltipTable then
                    Tab.TooltipTable:Destroy()
                    Tab.TooltipTable = nil
                end
    
                if typeof(Text) == "string" then
                    Tab.TooltipTable = Library:AddTooltip(Text, nil, TabButton)
                end
            end
    
            function Tab:Destroy()
                Tab.Destroyed = true
    
                if Tab.Connections then
                    for _, Connection in Tab.Connections do
                        Connection:Disconnect()
                    end
                end
    
                if Tab.TooltipTable then
                    Tab.TooltipTable:Destroy()
                    Tab.TooltipTable = nil
                end
    
                for _, Groupbox in Tab.Groupboxes do
                    if Groupbox.Destroy then
                        Groupbox:Destroy()
                    end
                end
                table.clear(Tab.Groupboxes)
    
                for _, Tabbox in Tab.Tabboxes do
                    if Tabbox.Destroy then
                        Tabbox:Destroy()
                    end
                end
                table.clear(Tab.Tabboxes)
    
                for _, DepGroupbox in Tab.DependencyGroupboxes do
                    if DepGroupbox.Destroy then
                        DepGroupbox:Destroy()
                    end
                end
    
                if TabContainer then
                    TabContainer:Destroy()
                end
    
                if TabButton then
                    for Index, Entry in Library.TabButtons do
                        if typeof(Entry) == "table" and Entry.Button == TabButton then
                            if Entry.Hover then
                                Entry.Hover:Destroy()
                            end
                            table.remove(Library.TabButtons, Index)
                            break
                        end
                    end
    
                    TabButton:Destroy()
                end
    
                Library.Tabs[Name] = nil
            end
    
            if typeof(Tooltip) == "string" then
                Tab.TooltipTable = Library:AddTooltip(Tooltip, nil, TabButton)
            end
    
            if not Library.ActiveTab then
                Tab:Show()
            end
    
            TabButton.MouseEnter:Connect(function()
                Tab:Hover(true)
            end)
            TabButton.MouseLeave:Connect(function()
                Tab:Hover(false)
            end)
            TabButton.MouseButton1Click:Connect(Tab.Show)
    
            Library.Tabs[Name] = Tab
    
            return Tab
        end
    
        function Window:AddKeyTab(...)
            local Name = nil
            local Icon = nil
            local Description = nil
            local Tooltip = nil
            local Order = nil
    
            if select("#", ...) == 1 and typeof(...) == "table" then
                local Info = select(1, ...)
                Name = Info.Name or "Tab"
                Icon = Info.Icon
                Description = Info.Description
                Tooltip = Info.Tooltip
                Order = Info.Order
            else
                Name = select(1, ...) or "Tab"
                Icon = select(2, ...)
                Description = select(3, ...)
                Order = select(4, ...)
            end
    
            if not tonumber(Order) then
                Order = #Tabs:GetChildren()
            end
    
            Icon = Icon or "key"
    
            local TabButton: TextButton
            local TabIndicator
            local TabLabel
            local TabIcon
            local TabEntry
    
            local TabContainer
    
            Icon = if Icon == "key" then KeyIcon else Library:GetCustomIcon(Icon)
            do
                TabButton, TabIndicator, TabLabel, TabIcon, TabEntry = CreateTabButton(Name, Icon, Order)
                TabEntry.Description = Description
    
                TabContainer = New("ScrollingFrame", {
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    CanvasSize = UDim2.fromScale(0, 0),
                    ScrollBarThickness = 0,
                    Position = UDim2.fromScale(0, 0),
                    Size = UDim2.fromScale(1, 1),
                    Visible = false,
                    Parent = Container,
                })
                New("UIListLayout", {
                    HorizontalAlignment = Enum.HorizontalAlignment.Center,
                    Padding = UDim.new(0, 8),
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Parent = TabContainer,
                })
                New("UIPadding", {
                    PaddingLeft = UDim.new(0, 1),
                    PaddingRight = UDim.new(0, 1),
                    Parent = TabContainer,
                })
            end
    
            local Tab = {
                Description = Description,
                IsKeyTab = true,
    
                Tooltip = Tooltip,
                TooltipTable = nil,
    
                Elements = {},
    
                Window = Window,
                Button = TabButton,
                Container = TabContainer
            }
    
            function Tab:AddKeyBox(Callback)
                assert(typeof(Callback) == "function", "Callback must be a function")
    
                local Holder = New("Frame", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(0.75, 0, 0, 21),
                    Parent = TabContainer,
                })
    
                local Box = New("TextBox", {
                    BackgroundColor3 = "MainColor",
                    PlaceholderText = "Key",
                    Size = UDim2.new(1, -71, 1, 0),
                    TextSize = 14,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Parent = Holder,
                })
                New("UIPadding", {
                    PaddingLeft = UDim.new(0, 8),
                    PaddingRight = UDim.new(0, 8),
                    Parent = Box,
                })
                local BoxStroke = New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = Box,
                })
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Box,
                    })
                )
    
                Box.Focused:Connect(function()
                    Library.Registry[BoxStroke].Color = "AccentColor"
                    TweenService:Create(BoxStroke, Library.TweenInfo, {
                        Color = Library.Scheme.AccentColor,
                    }):Play()
                end)
    
                Box.FocusLost:Connect(function()
                    Library.Registry[BoxStroke].Color = "OutlineColor"
                    TweenService:Create(BoxStroke, Library.TweenInfo, {
                        Color = Library.Scheme.OutlineColor,
                    }):Play()
                end)
    
                local Button = New("TextButton", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundColor3 = "MainColor",
                    Position = UDim2.fromScale(1, 0),
                    Size = UDim2.new(0, 63, 1, 0),
                    Text = "Execute",
                    TextSize = 14,
                    TextTransparency = 0.4,
                    Parent = Holder,
                })
                New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = Button,
                })
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius / 2),
                        Parent = Button,
                    })
                )
    
                Button.MouseEnter:Connect(function()
                    TweenService:Create(Button, Library.TweenInfo, {
                        TextTransparency = 0,
                    }):Play()
                end)
    
                Button.MouseLeave:Connect(function()
                    TweenService:Create(Button, Library.TweenInfo, {
                        TextTransparency = 0.4,
                    }):Play()
                end)
    
                Button.InputBegan:Connect(function(Input)
                    if not IsClickInput(Input) then
                        return
                    end
    
                    if not Library:MouseIsOverFrame(Button, Input.Position) then
                        return
                    end
    
                    Callback(Box.Text)
                end)
            end
    
            function Tab:Destroy()
                if TabContainer then
                    TabContainer:Destroy()
                end
    
                if TabButton then
                    for Index, Entry in Library.TabButtons do
                        if typeof(Entry) == "table" and Entry.Button == TabButton then
                            if Entry.Hover then
                                Entry.Hover:Destroy()
                            end
                            table.remove(Library.TabButtons, Index)
                            break
                        end
                    end
    
                    TabButton:Destroy()
                end
    
                Library.Tabs[Name] = nil
            end
    
            function Tab:SetBadge(Value: any)
                Tab.BadgeValue = Value
                if TabEntry and TabEntry.SetBadge then
                    TabEntry.SetBadge(Value)
                end
            end
    
            function Tab:SetOrder(NewOrder: number)
                Order = NewOrder
                TabButton.LayoutOrder = Order
            end
    
            function Tab:RefreshSides() end
            function Tab:Resize() end
            function Tab:UpdateCorners() end
    
            function Tab:Hover(Hovering)
                if Library.ActiveTab == Tab then
                    return
                end
    
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = Hovering and 0.25 or 0.5,
                }):Play()
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = Hovering and 0.25 or 0.5,
                    }):Play()
                end
            end
    
            function Tab:Show()
                if Library.ActiveTab == Tab then
                    return
                end
    
                if Library.ActiveTab then
                    Library.ActiveTab:Hide()
                end
    
                PaintTabEntry(TabEntry, true)
    
                if TabIndicator then
                    TweenService:Create(TabIndicator, Library.TweenInfo, {
                        BackgroundTransparency = 0,
                    }):Play()
                end
    
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = 0,
                }):Play()
    
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = 0,
                    }):Play()
                end
    
                Library:PlayTabAnimation(Tab, true)
    
                if Description or WindowInfo.ShowTabTitle ~= false then
                    Window:ShowTabInfo(Name, Description)
                end
    
                Tab:RefreshSides()
    
                Library.ActiveTab = Tab
    
                if Library.Searching then
                    Library:UpdateSearch(Library.SearchText)
                end
            end
    
            function Tab:Hide()
                PaintTabEntry(TabEntry, false)
    
                if TabIndicator then
                    TweenService:Create(TabIndicator, Library.TweenInfo, {
                        BackgroundTransparency = 1,
                    }):Play()
                end
    
                TweenService:Create(TabLabel, Library.TweenInfo, {
                    TextTransparency = 0.5,
                }):Play()
    
                if TabIcon then
                    TweenService:Create(TabIcon, Library.TweenInfo, {
                        ImageTransparency = 0.5,
                    }):Play()
                end
    
                Library:PlayTabAnimation(Tab, false)
                Window:HideTabInfo()
    
                Library.PreviousTab = Tab
                Library.ActiveTab = nil
            end
    
            function Tab:SetVisible(Visible: boolean)
                TabButton.Visible = Visible
    
                if not Visible and Library.ActiveTab == Tab then
                    Tab:Hide()
                end
            end
    
            function Tab:SetTooltip(Text: string?)
                Tab.Tooltip = Text
    
                if Tab.TooltipTable then
                    Tab.TooltipTable:Destroy()
                    Tab.TooltipTable = nil
                end
    
                if typeof(Text) == "string" then
                    Tab.TooltipTable = Library:AddTooltip(Text, nil, TabButton)
                end
            end
    
            if typeof(Tooltip) == "string" then
                Tab.TooltipTable = Library:AddTooltip(Tooltip, nil, TabButton)
            end
    
            if not Library.ActiveTab then
                Tab:Show()
            end
    
            TabButton.MouseEnter:Connect(function()
                Tab:Hover(true)
            end)
            TabButton.MouseLeave:Connect(function()
                Tab:Hover(false)
            end)
            TabButton.MouseButton1Click:Connect(Tab.Show)
    
            Tab.Container = TabContainer
            setmetatable(Tab, BaseGroupbox)
    
            Library.Tabs[Name] = Tab
    
            return Tab
        end
    
