                Parent = InnerContainer,
            })
            local _DialogContainerLayout = New("UIListLayout", {
                Padding = UDim.new(0, 8),
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = DialogContainer,
            })
            New("UIPadding", {
                PaddingBottom = UDim.new(0, 5),
                Parent = DialogContainer,
            })
    
            local _Sep2 = New("Frame", {
                BackgroundColor3 = "OutlineColor",
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, 1),
                LayoutOrder = 5,
                ZIndex = 2,
                Parent = InnerContainer,
            })
    
            ButtonsHolder = New("Frame", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = 6,
                ZIndex = 2,
                Parent = InnerContainer,
            })
            New("UIListLayout", {
                Padding = UDim.new(0, 8),
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                Wraps = true,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = ButtonsHolder,
            })
            New("UIPadding", {
                PaddingTop = UDim.new(0, 5),
                Parent = ButtonsHolder,
            })
    
            local Dialog = {
                Destroyed = false,
                Elements = {},
                Container = DialogContainer,
                OutsideClickDismiss = Info.OutsideClickDismiss,
            }
    
            function Dialog:Resize()
                local MaxWidth = (MainFrame.AbsoluteSize.X / Library.DPIScale) * 0.75
                local MinWidth = 400
    
                local TotalButtonWidth = 0
                local ButtonCount = 0
                local HasButtons = false
    
                for _, BtnWrap in FooterButtonsList do
                    HasButtons = true
                    ButtonCount = ButtonCount + 1
                    TotalButtonWidth = TotalButtonWidth + BtnWrap.Container.Size.X.Offset
                end
    
                local TargetWidth = MinWidth
                if HasButtons then
                    local RequiredWidth = TotalButtonWidth + ((ButtonCount - 1) * 8) + 30
                    TargetWidth = math.max(MinWidth, math.min(RequiredWidth, MaxWidth))
                end
    
                DialogFrame.Size = UDim2.fromOffset(TargetWidth, 0)
    
                local _DescX, DescY = Library:GetTextBounds(DescriptionLabel.Text, Library.Scheme.Font, 14, TargetWidth - 30)
                DescriptionLabel.Size = UDim2.new(1, 0, 0, DescY)
    
                local HasElements = false
                for _, v in DialogContainer:GetChildren() do
                    if not v:IsA("UIListLayout") and not v:IsA("UIPadding") then
                        HasElements = true
                        break
                    end
                end
                DialogContainer.Visible = HasElements
    
                ButtonsHolder.Visible = HasButtons
                _Sep2.Visible = HasButtons
            end
    
            function Dialog:SetTitle(Title)
                TitleLabel.Text = Title
                Dialog:Resize()
            end
    
            function Dialog:SetDescription(Description)
                DescriptionLabel.Text = Description
                Dialog:Resize()
            end
    
            function Dialog:Dismiss()
                if Dialog.Destroyed then
                    return
                end
    
                Dialog.Destroyed = true
    
                if Library.ActiveDialog == Dialog then
                    Library.ActiveDialog = nil
                end
    
                for Index = #Dialog.Elements, 1, -1 do
                    local Element = Dialog.Elements[Index]
                    if Element and Element.Destroy then
                        Element:Destroy()
                    end
                end
                table.clear(Dialog.Elements)
    
                local CloseTween = TweenService:Create(DialogScale, Library.TweenInfo, { Scale = 0.95 })
                TweenService:Create(DialogOverlay, Library.TweenInfo, { BackgroundTransparency = 1 }):Play()
                CloseTween:Play()
    
                task.delay(Library.TweenInfo.Time, function()
                    DialogOverlay:Destroy()
                end)
                Library.Dialogues[Idx] = nil
            end
    
            DialogOverlay.MouseButton1Click:Connect(function()
                if Info.OutsideClickDismiss then
                    Dialog:Dismiss()
                end
            end)
    
            function Dialog:RemoveFooterButton(ButtonIdx)
                if FooterButtonsList[ButtonIdx] then
                    FooterButtonsList[ButtonIdx].Container:Destroy()
                    FooterButtonsList[ButtonIdx] = nil
                end
            end
    
            function Dialog:SetButtonDisabled(ButtonIdx, Disabled)
                if FooterButtonsList[ButtonIdx] and type(FooterButtonsList[ButtonIdx].SetDisabled) == "function" then
                    FooterButtonsList[ButtonIdx]:SetDisabled(Disabled)
                end
            end
    
            function Dialog:SetButtonOrder(ButtonIdx, Order)
                if FooterButtonsList[ButtonIdx] and FooterButtonsList[ButtonIdx].Container then
                    FooterButtonsList[ButtonIdx].Container.LayoutOrder = Order
                end
            end
    
            function Dialog:AddFooterButton(ButtonIdx, ButtonInfo)
                Dialog:RemoveFooterButton(ButtonIdx)
    
                local WaitTime = ButtonInfo.WaitTime or 0
    
                local ButtonContainer = New("Frame", {
                    BackgroundTransparency = 1,
                    Size = UDim2.fromOffset(0, 26),
                    LayoutOrder = ButtonInfo.Order or 0,
                    ZIndex = 2,
                    Parent = ButtonsHolder,
                })
    
                local BtnColor = "MainColor"
                local BtnOutline = "OutlineColor"
                local Variant = ButtonInfo.Variant or "Primary"
    
                if Variant == "Primary" then
                    BtnColor = "FontColor"
                    BtnOutline = "FontColor"
                elseif Variant == "Secondary" then
                    BtnColor = "MainColor"
                    BtnOutline = "OutlineColor"
                elseif Variant == "Destructive" then
                    BtnColor = "DestructiveColor"
                    BtnOutline = "DestructiveColor"
                elseif Variant == "Ghost" then
                    BtnColor = "BackgroundColor"
                    BtnOutline = "BackgroundColor"
                end
    
                local TextBtn = New("TextButton", {
                    BackgroundColor3 = BtnColor,
                    BorderColor3 = BtnOutline,
                    BackgroundTransparency = WaitTime > 0 and 0.5 or 0,
                    Size = UDim2.fromOffset(0, 26),
                    Text = "",
                    AutoButtonColor = false,
                    ZIndex = 2,
                    Parent = ButtonContainer,
                })
                Library:AddOutline(TextBtn)
                table.insert(
                    Library.Corners,
                    New("UICorner", {
                        CornerRadius = UDim.new(0, Library.CornerRadius),
                        Parent = TextBtn
                    })
                )
    
                local _BtnPadding = New("UIPadding", {
                    PaddingLeft = UDim.new(0, 15),
                    PaddingRight = UDim.new(0, 15),
                    Parent = TextBtn,
                })
    
                local TextColor = Library.Scheme.FontColor
                if Variant == "Primary" then
                    TextColor = Library.Scheme.BackgroundColor
                elseif Variant == "Destructive" then
                    TextColor = Color3.new(1, 1, 1)
                end
    
                local BtnLabel = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 1),
                    Text = ButtonInfo.Title or ButtonIdx,
                    TextColor3 = TextColor,
                    TextTransparency = WaitTime > 0 and 0.5 or 0,
                    TextSize = 14,
                    ZIndex = 2,
                    Parent = TextBtn,
                })
    
                local LabelX, _ = Library:GetTextBounds(BtnLabel.Text, Library.Scheme.Font, 14, 250)
                ButtonContainer.Size = UDim2.fromOffset(LabelX + 30, 26)
                TextBtn.Size = UDim2.fromOffset(LabelX + 30, 26)
    
                local ProgressBar
                if WaitTime > 0 then
                    ProgressBar = New("Frame", {
                        BackgroundColor3 = "AccentColor",
                        BorderSizePixel = 0,
                        Position = UDim2.new(0, 0, 1, -2),
                        Size = UDim2.new(0, 0, 0, 2),
                        ZIndex = 2,
                        Parent = TextBtn,
                    })
                    table.insert(
                        Library.Corners,
                        New("UICorner", {
                            CornerRadius = UDim.new(0, Library.CornerRadius),
                            Parent = ProgressBar
                        })
                    )
                end
    
                local IsActive = WaitTime <= 0
    
                local ButtonWrap = {
                    Container = ButtonContainer,
                    SetDisabled = function(self, Disabled)
                        IsActive = not Disabled
                        if Disabled then
                            TweenService:Create(TextBtn, Library.TweenInfo, { BackgroundTransparency = 0.5 }):Play()
                            TweenService:Create(BtnLabel, Library.TweenInfo, { TextTransparency = 0.5 }):Play()
                        else
                            TweenService:Create(TextBtn, Library.TweenInfo, { BackgroundTransparency = 0 }):Play()
                            TweenService:Create(BtnLabel, Library.TweenInfo, { TextTransparency = 0 }):Play()
                        end
                    end
                }
    
                local ActiveColor = typeof(BtnColor) == "Color3" and BtnColor or Library.Scheme[BtnColor]
                local HoverColor = Variant == "Ghost" and Library.Scheme.MainColor or Library:GetBetterColor(ActiveColor, 10)
    
                TextBtn.MouseEnter:Connect(function()
                    if not IsActive then return end
                    TweenService:Create(TextBtn, Library.TweenInfo, {
                        BackgroundColor3 = HoverColor
                    }):Play()
                end)
                TextBtn.MouseLeave:Connect(function()
                    if not IsActive then return end
                    TweenService:Create(TextBtn, Library.TweenInfo, {
                        BackgroundColor3 = ActiveColor
                    }):Play()
                end)
    
                TextBtn.MouseButton1Click:Connect(function()
                    if not IsActive then return end
                    if ButtonInfo.Callback then
                        ButtonInfo.Callback(Dialog)
                    end
                    if Info.AutoDismiss then
                        Dialog:Dismiss()
                    end
                end)
    
                if WaitTime > 0 then
                    TweenService:Create(ProgressBar, TweenInfo.new(WaitTime, Enum.EasingStyle.Linear), {
                        Size = UDim2.new(1, 0, 0, 2)
                    }):Play()
    
                    task.delay(WaitTime, function()
                        ButtonWrap:SetDisabled(false)
                        if ProgressBar then
                            TweenService:Create(ProgressBar, Library.TweenInfo, {
                                BackgroundTransparency = 1
                            }):Play()
                        end
                    end)
                end
    
                FooterButtonsList[ButtonIdx] = ButtonWrap
            end
    
            for BIdx, BInfo in Info.FooterButtons do
                if type(BIdx) == "number" and BInfo.Id then BIdx = BInfo.Id end
                Dialog:AddFooterButton(BIdx, BInfo)
            end
    
            setmetatable(Dialog, BaseGroupbox)
            Library.Dialogues[Idx] = Dialog
    
            Dialog:Resize()
    
            Library.ActiveDialog = Dialog
            return Dialog
        end
    
        local GuiProperties = { "BackgroundTransparency" }
        local ImageProperties = { "BackgroundTransparency", "ImageTransparency" }
        local TextProperties = { "BackgroundTransparency", "TextTransparency" }
        local StrokeProperties = { "Transparency" }
    
        local function FadeInstance(Desc, Properties)
            local Cache = TransparencyCache[Desc]
            if not Cache then
                Cache = {}
                TransparencyCache[Desc] = Cache
            end
    
            for _, Prop in Properties do
                if not Library.Toggled then
                    Cache[Prop] = Desc[Prop]
                end
    
                if Cache[Prop] ~= nil and Cache[Prop] ~= 1 then
                    TweenService:Create(Desc, Library.WindowAnimationInfo, {
                        [Prop] = Library.Toggled and Cache[Prop] or 1,
                    }):Play()
                end
            end
        end
    
        function Window:Toggle(Value: boolean?)
            if Fading then
                return
            end
    
            if Library.ActiveLoading then
                if Value == true then
                    return
                end
    
                if not Library.Toggled then
                    return
                end
            end
    
            if typeof(Value) == "boolean" then
                Library.Toggled = Value
            else
                Library.Toggled = not Library.Toggled
            end
    
            if WindowStarfield then
                if Library.Toggled then
                    local Delay = if Library.Animations and Library.Animations.ToggleWindow == true then Library.WindowAnimationInfo.Time * 0.5 else 0
                    task.delay(Delay, function()
                        if Library.Toggled and WindowStarfield then
                            WindowStarfield:SetActive(true)
                        end
                    end)
                else
                    WindowStarfield:SetActive(false)
                end
            end
            if WindowAurora then
                WindowAurora:Refresh(Library.Toggled)
            end
    
            if Library.Animations and Library.Animations.ToggleWindow == true and Library.CometTransitions ~= false and Window.PlayComet then
                Fading = true
                if Library.Toggled then
                    TooltipLabel.Visible = false
                end
                local Finished = false
                local function Finish()
                    if Finished then
                        return
                    end
                    Finished = true
                    Fading = false
                end
                local Success = pcall(Window.PlayComet, Library.Toggled, Finish)
                if not Success then
                    pcall(Window.ResetWarp)
                    MainFrame.Visible = Library.Toggled
                    Finish()
                end
                task.delay(2.4, function()
                    if not Finished then
                        pcall(Window.ResetWarp)
                        MainFrame.Visible = Library.Toggled
                        Finish()
                    end
                end)
            elseif Library.Animations and Library.Animations.ToggleWindow == true then
                local FadeTime = Library.WindowAnimationInfo.Time
                Fading = true
    
                if Library.Toggled then
                    MainFrame.Visible = true
                end
    
                if Library.Toggled then
                    FadeInstance(MainFrame, { "BackgroundTransparency" })
                    task.wait(FadeTime / 2)
                else
                    task.delay(FadeTime / 2, FadeInstance, MainFrame, { "BackgroundTransparency" })
                end
    
                for _, Instance in MainFrame:GetDescendants() do
                    if Instance == TopBar then
                        continue
                    end
                    if WindowStarfield and (Instance == WindowStarfield.Frame or Instance:IsDescendantOf(WindowStarfield.Frame)) then
                        continue
                    end
                    if Instance:IsA("ViewportFrame") then
                        FadeInstance(Instance, ImageProperties)
                        continue
                    end
    
                    if Instance:IsA("GuiObject") then
                        local ClassName = Instance.ClassName
                        if ClassName == "ImageLabel" or ClassName == "ImageButton" then
                            FadeInstance(Instance, ImageProperties)
                        elseif ClassName == "TextLabel" or ClassName == "TextBox" or ClassName == "TextButton" then
                            FadeInstance(Instance, TextProperties)
                        else
                            FadeInstance(Instance, GuiProperties)
                        end
                    elseif Instance.ClassName == "UIStroke" then
                        FadeInstance(Instance, StrokeProperties)
                    end
                end
    
                task.delay(FadeTime, function()
                    MainFrame.Visible = Library.Toggled
                    Fading = false
                end)
            else
                MainFrame.Visible = Library.Toggled
            end
    
            if WindowInfo.UnlockMouseWhileOpen then
                ModalElement.Modal = Library.Toggled
            end
    
            if Library.Toggled and not Library.IsMobile then
                local ShowCursorBinding = Library.ShowCursorBinding
                Library.OriginalMouseIconEnabled = UserInputService.MouseIconEnabled
    
                pcall(function() RunService:UnbindFromRenderStep(ShowCursorBinding) end)
                RunService:BindToRenderStep(ShowCursorBinding, Enum.RenderPriority.Last.Value, function()
                    UserInputService.MouseIconEnabled = not Library.ShowCustomCursor
    
                    Cursor.Position = UDim2.fromOffset(Mouse.X, Mouse.Y)
                    Cursor.Visible = Library.ShowCustomCursor
    
                    if Library.Unloaded == true or not (Library.Toggled and ScreenGui and ScreenGui.Parent) then
                        RestoreMouseIcon()
                    end
                end)
            elseif not Library.Toggled then
                RestoreMouseIcon()
                TooltipLabel.Visible = false
    
                for _, Option in Library.Options do
                    if Option.Type == "ColorPicker" then
                        Option.ColorMenu:Close()
                        Option.ContextMenu:Close()
                    elseif Option.Type == "Dropdown" or Option.Type == "KeyPicker" then
                        Option.Menu:Close()
                    end
                end
            end
        end
    
        function Library:Toggle(Value: boolean?)
            return Window:Toggle(Value)
        end
    
        if WindowInfo.EnableSidebarResize then
            local Threshold = (WindowInfo.MinSidebarWidth + WindowInfo.SidebarCompactWidth) * WindowInfo.SidebarCollapseThreshold
            local StartPos, StartWidth
            local Dragging = false
            local Changed
    
            local SidebarGrabber = New("TextButton", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Position = UDim2.fromScale(0.5, 0),
                Size = UDim2.new(0, 8, 1, 0),
                Text = "",
                Parent = DividerLine,
            })
            SidebarGrabber.MouseEnter:Connect(function()
                TweenService:Create(DividerLine, Library.TweenInfo, {
                    BackgroundColor3 = Library:GetLighterColor(Library.Scheme.OutlineColor),
                }):Play()
            end)
            SidebarGrabber.MouseLeave:Connect(function()
                if Dragging then
                    return
                end
                TweenService:Create(DividerLine, Library.TweenInfo, {
                    BackgroundColor3 = Library.Scheme.OutlineColor,
                }):Play()
            end)
    
            SidebarGrabber.InputBegan:Connect(function(Input: InputObject)
                if not IsClickInput(Input) then
                    return
                end
    
                Library.CantDragForced = true
    
                StartPos = Input.Position
                StartWidth = Window:GetSidebarWidth()
                Dragging = true
    
                Changed = Input.Changed:Connect(function()
                    if Input.UserInputState ~= Enum.UserInputState.End then
                        return
                    end
    
                    Library.CantDragForced = false
                    TweenService:Create(DividerLine, Library.TweenInfo, {
                        BackgroundColor3 = Library.Scheme.OutlineColor,
                    }):Play()
    
                    Dragging = false
                    if Changed and Changed.Connected then
                        Changed:Disconnect()
                        Changed = nil
                    end
                end)
            end)
    
            Library:GiveSignal(UserInputService.InputChanged:Connect(function(Input: InputObject)
                if not Library.Toggled or not (ScreenGui and ScreenGui.Parent) then
                    Dragging = false
                    if Changed and Changed.Connected then
                        Changed:Disconnect()
                        Changed = nil
                    end
    
                    return
                end
    
                if Dragging and IsHoverInput(Input) then
                    local Delta = Input.Position - StartPos
                    local Width = StartWidth + Delta.X
    
                    if WindowInfo.DisableCompactingSnap then
                        Window:SetSidebarWidth(Width)
                        return
                    end
    
                    if Width > Threshold then
                        Window:SetSidebarWidth(math.max(Width, WindowInfo.MinSidebarWidth))
                    else
                        Window:SetSidebarWidth(WindowInfo.SidebarCompactWidth)
                    end
                end
            end))
        end
    
        function Window:SetStarfield(Enabled: boolean)
            Enabled = Enabled ~= false
            WindowInfo.Starfield = Enabled
    
            if WindowStarfield then
                WindowStarfield:SetEnabled(Enabled)
            end
    
            local Transparency = if Enabled then 1 else 0
            for _, Gui in { Tabs, Container } do
                Gui.BackgroundTransparency = Transparency
                local Cache = TransparencyCache[Gui]
                if Cache and Cache.BackgroundTransparency ~= nil then
                    Cache.BackgroundTransparency = Transparency
                end
            end
        end
    
        function Library:SetStarfield(Enabled: boolean)
            return Window:SetStarfield(Enabled)
        end
    
        local function PlayTween(Object: Instance, Time: number, Properties: { [string]: any }, Style: Enum.EasingStyle?, Direction: Enum.EasingDirection?)
            local Tween = TweenService:Create(Object, TweenInfo.new(Time, Style or Enum.EasingStyle.Quad, Direction or Enum.EasingDirection.Out), Properties)
            Tween:Play()
            return Tween
        end
    
        Window.PlaySheen = function() end
    
        local function Particle(At: Vector2, Velocity: Vector2, Size: number, Life: number, Color: any, ZIndex: number?)
            local Dot = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = Color or "WhiteColor",
                Position = UDim2.fromOffset(At.X, At.Y),
                Size = UDim2.fromOffset(Size, Size),
                ZIndex = ZIndex or 948,
                Parent = ScreenGui,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Dot,
            })
            local Target = At + Velocity * Life
            PlayTween(Dot, Life, {
                Position = UDim2.fromOffset(Target.X, Target.Y),
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(math.max(Size * 0.3, 1), math.max(Size * 0.3, 1)),
            }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            task.delay(Life + 0.05, function()
                Dot:Destroy()
            end)
        end
    
        local function SpawnBurst(At: Vector2, Count: number, Speed: number, Life: number?)
            for Index = 1, Count do
                local Angle = (Index / Count) * math.pi * 2 + math.random() * 0.6
                local Velocity = Vector2.new(math.cos(Angle), math.sin(Angle)) * Speed * (0.55 + math.random() * 0.7)
                Particle(At, Velocity, if Index % 3 == 0 then 4 else 3, (Life or 0.5) * (0.7 + math.random() * 0.5), if Index % 2 == 0 then "AccentColor" else "WhiteColor")
            end
        end
        Window.SpawnBurst = SpawnBurst
    
        local NovaGlow = Library:GetEmbeddedAsset("corvus-glow")
        local RayFade = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.42, 0.55),
            NumberSequenceKeypoint.new(0.5, 0),
            NumberSequenceKeypoint.new(0.58, 0.55),
            NumberSequenceKeypoint.new(1, 1),
        })
    
        local function SpawnFlare(At: Vector2, Size: number, Life: number, Grow: number?)
            local Holder = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Name = "NovaFlare",
                Position = UDim2.fromOffset(At.X, At.Y),
                Rotation = 45,
                Size = UDim2.fromOffset(Size, Size),
                ZIndex = 962,
                Parent = ScreenGui,
            })
            local Scale = New("UIScale", {
                Scale = 0.05,
                Parent = Holder,
            })
            local Parts = {}
            if NovaGlow then
                table.insert(Parts, New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Image = NovaGlow,
                    ImageColor3 = "AccentColor",
                    ImageTransparency = 0.15,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromScale(0.75, 0.75),
                    ZIndex = 962,
                    Parent = Holder,
                }))
            end
            for _, Vertical in { false, true } do
                local Ray = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = "WhiteColor",
                    BorderSizePixel = 0,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = if Vertical then UDim2.new(0, 2, 0.7, 0) else UDim2.new(1, 0, 0, 2),
                    ZIndex = 963,
                    Parent = Holder,
                })
                New("UIGradient", {
                    Rotation = if Vertical then 90 else 0,
                    Transparency = RayFade,
                    Parent = Ray,
                })
                table.insert(Parts, Ray)
            end
            local Core = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(7, 7),
                ZIndex = 964,
                Parent = Holder,
            })
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Core,
            })
            table.insert(Parts, Core)
    
            local Peak = Grow or 1
            PlayTween(Scale, Life * 0.3, { Scale = Peak }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
            PlayTween(Holder, Life, { Rotation = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            task.delay(Life * 0.35, function()
                if not Holder.Parent then
                    return
                end
                PlayTween(Scale, Life * 0.65, { Scale = 0.02 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                for _, Part in Parts do
                    if Part:IsA("ImageLabel") then
                        PlayTween(Part, Life * 0.65, { ImageTransparency = 1 })
                    else
                        PlayTween(Part, Life * 0.65, { BackgroundTransparency = 1 })
                    end
                end
            end)
            task.delay(Life + 0.05, function()
                Holder:Destroy()
            end)
            return Holder
        end
        Window.SpawnFlare = SpawnFlare
    
        local ActiveGhosts = {}
    
        local function MakeGhost(Center: Vector2, Width: number, Height: number)
            local Ghost = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "BackgroundColor",
                Name = "NovaGhost",
                Position = UDim2.fromOffset(Center.X, Center.Y),
                Size = UDim2.fromOffset(Width, Height),
                ZIndex = 960,
                Parent = ScreenGui,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                Parent = Ghost,
            })
            local Stroke = New("UIStroke", {
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Color = "AccentColor",
                Thickness = 1.5,
                Transparency = 0.25,
                Parent = Ghost,
            })
            local Tint = New("Frame", {
                BackgroundColor3 = "WhiteColor",
                BackgroundTransparency = 1,
                Size = UDim2.fromScale(1, 1),
                ZIndex = 961,
                Parent = Ghost,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, WindowInfo.CornerRadius),
                Parent = Tint,
            })
            New("UIGradient", {
                Color = GetNebulaSequence,
                Rotation = 90,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.7),
                    NumberSequenceKeypoint.new(0.5, 0.05),
                    NumberSequenceKeypoint.new(1, 0.7),
                }),
                Parent = Tint,
            })
            local Beam
            if NovaGlow then
                Beam = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Image = NovaGlow,
                    ImageColor3 = "AccentColor",
                    ImageTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.new(1, 80, 0, 110),
                    ZIndex = 959,
                    Parent = Ghost,
                })
            end
            local Entry = { Ghost = Ghost, Stroke = Stroke, Tint = Tint, Beam = Beam }
            ActiveGhosts[Ghost] = true
            return Entry
        end
    
        local function DropGhost(Entry)
            if Entry and Entry.Ghost then
                ActiveGhosts[Entry.Ghost] = nil
                Entry.Ghost:Destroy()
            end
        end
    
        local NovaToken = 0
    
        function Window.ResetWarp()
            NovaToken += 1
            local Scale = MainFrame:FindFirstChildOfClass("UIScale")
            if Scale then
                Scale.Scale = Library.DPIScale - (tonumber(Library.ScalesOffset[Scale]) or 0)
            end
            for Ghost in ActiveGhosts do
                pcall(Ghost.Destroy, Ghost)
            end
            table.clear(ActiveGhosts)
        end
    
        function Window.PlayComet(Showing: boolean, Done: () -> ())
            Window.ResetWarp()
            local Token = NovaToken
            local Position, Size = MainFrame.AbsolutePosition, MainFrame.AbsoluteSize
            if Size.X < 20 or Size.Y < 20 then
                MainFrame.Visible = Showing
                Done()
                return
            end
            local Center = Position + Size / 2
            local function Alive()
                return Token == NovaToken and not Library.Unloaded
            end
    
            if Showing then
                SpawnFlare(Center, 170, 0.62, 1.15)
                task.delay(0.16, function()
                    if not Alive() then
                        return
                    end
                    local Entry = MakeGhost(Center, 0, 2)
                    Entry.Tint.BackgroundTransparency = 0.1
                    Entry.Stroke.Transparency = 0
                    if Entry.Beam then
                        Entry.Beam.ImageTransparency = 0.35
                    end
                    PlayTween(Entry.Ghost, 0.2, { Size = UDim2.fromOffset(Size.X, 2) }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
                    task.delay(0.2, function()
                        if not Alive() then
                            DropGhost(Entry)
                            return
                        end
                        PlayTween(Entry.Ghost, 0.3, { Size = UDim2.fromOffset(Size.X, Size.Y) }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                        if Entry.Beam then
                            PlayTween(Entry.Beam, 0.26, { ImageTransparency = 1 })
                        end
                        PlayTween(Entry.Tint, 0.3, { BackgroundTransparency = 0.55 })
                        task.delay(0.3, function()
                            if not Alive() then
                                DropGhost(Entry)
                                return
                            end
                            MainFrame.Visible = true
                            PlayTween(Entry.Ghost, 0.24, { BackgroundTransparency = 1 })
                            PlayTween(Entry.Tint, 0.24, { BackgroundTransparency = 1 })
                            PlayTween(Entry.Stroke, 0.3, { Transparency = 1 })
                            task.delay(0.3, function()
                                DropGhost(Entry)
                                if Token == NovaToken then
                                    Done()
                                end
                            end)
                        end)
                    end)
                end)
            else
                local Entry = MakeGhost(Center, Size.X, Size.Y)
                MainFrame.Visible = false
                Entry.Ghost.BackgroundTransparency = 0.05
                PlayTween(Entry.Tint, 0.12, { BackgroundTransparency = 0.12 })
                PlayTween(Entry.Stroke, 0.12, { Transparency = 0 })
                task.delay(0.08, function()
                    if not Alive() then
                        DropGhost(Entry)
                        return
                    end
                    PlayTween(Entry.Ghost, 0.22, { Size = UDim2.fromOffset(Size.X * 0.94, 2) }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
                    if Entry.Beam then
                        PlayTween(Entry.Beam, 0.2, { ImageTransparency = 0.3 })
                    end
                    task.delay(0.22, function()
                        if not Alive() then
                            DropGhost(Entry)
                            return
                        end
                        PlayTween(Entry.Ghost, 0.15, { Size = UDim2.fromOffset(0, 2) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                        task.delay(0.13, function()
                            DropGhost(Entry)
                            if not Alive() then
                                return
                            end
                            SpawnFlare(Center, 190, 0.6, 1.2)
                            SpawnBurst(Center, 8, 170, 0.5)
                            MainFrame.Visible = Library.Toggled
                            task.delay(0.12, function()
                                if Token == NovaToken then
                                    Done()
                                end
                            end)
                        end)
                    end)
                end)
            end
        end
    
        function Window.PlayMinimizeComet(Minimizing: boolean)
            if Library.CometTransitions == false or Library.IconAnimations == false or not MainFrame.Visible then
                return
            end
            local Position, Size = MainFrame.AbsolutePosition, MainFrame.AbsoluteSize
            local Scale = math.max(Library.DPIScale, 0.01)
            local MiniWidth = 300 * Scale
            local From = if Minimizing then Size.X else MiniWidth
            local To = if Minimizing then MiniWidth else math.max(Size.X, (Library.MinSize and Library.MinSize.X or 480))
            local Line = New("Frame", {
                BackgroundColor3 = "WhiteColor",
                BorderSizePixel = 0,
                Name = "NovaLine",
                Position = UDim2.fromOffset(Position.X, Position.Y),
                Size = UDim2.fromOffset(From, 2),
                ZIndex = 962,
                Parent = ScreenGui,
            })
            New("UIGradient", {
                Color = GetNebulaSequence,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.2, 0.15),
                    NumberSequenceKeypoint.new(0.8, 0.15),
                    NumberSequenceKeypoint.new(1, 1),
                }),
                Parent = Line,
            })
            PlayTween(Line, 0.32, { Size = UDim2.fromOffset(To, 2) }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
            task.delay(0.22, function()
                PlayTween(Line, 0.25, { BackgroundTransparency = 1 })
            end)
            task.delay(0.5, function()
                Line:Destroy()
            end)
            local Star = if Minimizing then Position + Vector2.new(30 * Scale, 39 * Scale) else Position + Vector2.new(To / 2, 2)
            task.delay(if Minimizing then 0.24 else 0.05, function()
                SpawnFlare(Star, if Minimizing then 90 else 140, 0.5, 1)
            end)
        end
    
        do
            local GlowImage = Library:GetEmbeddedAsset("corvus-glow")
            if GlowImage then
                local CursorGlow = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Image = GlowImage,
                    ImageColor3 = "AccentColor",
                    ImageTransparency = 1,
                    Name = "CursorGlow",
                    Size = UDim2.fromOffset(240, 240),
                    ZIndex = 0,
                    Parent = MainFrame,
                })
                local GlowPosition = nil
                local GlowAlpha = 0
                table.insert(Library.Signals, RunService.RenderStepped:Connect(function(Delta)
                    if Library.Unloaded then
                        return
                    end
                    local Active = not Library.IsMobile and Library.CursorLight ~= false and Library.Toggled and MainFrame.Visible and not Window:IsMinimized()
                    local Scale = math.max(Library.DPIScale, 0.01)
                    local Mouse2 = Vector2.new(Mouse.X, Mouse.Y)
                    local Inside = Active and Library:MouseIsOverFrame(MainFrame, Mouse2)
                    local Target = if Inside then 1 else 0
                    GlowAlpha += (Target - GlowAlpha) * math.clamp(Delta * 6, 0, 1)
                    if GlowAlpha < 0.01 and not Inside then
                        if CursorGlow.ImageTransparency ~= 1 then
                            CursorGlow.ImageTransparency = 1
                        end
                        GlowPosition = nil
                        return
                    end
                    local Local = (Mouse2 - MainFrame.AbsolutePosition) / Scale
                    GlowPosition = if GlowPosition then GlowPosition:Lerp(Local, math.clamp(Delta * 10, 0, 1)) else Local
                    CursorGlow.Position = UDim2.fromOffset(GlowPosition.X, GlowPosition.Y)
                    CursorGlow.ImageTransparency = 1 - GlowAlpha * 0.2
                end))
            end
    
            Library:GiveSignal(UserInputService.InputBegan:Connect(function(Input: InputObject)
                if Library.Unloaded or Library.Stardust == false or Library.IconAnimations == false then
                    return
                end
                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
                    return
                end
                if not (Library.Toggled and MainFrame.Visible) then
                    return
                end
                local At = Vector2.new(Input.Position.X, Input.Position.Y)
                if not Library:MouseIsOverFrame(MainFrame, At) then
                    return
                end
                SpawnBurst(At, 7, 70, 0.4)
            end))
        end
    
        do
            local StartScale = Library:GetSetting("Scale", nil)
            local Number = if typeof(StartScale) == "string" then tonumber((string.gsub(StartScale, "%%", ""))) else tonumber(WindowInfo.Scale or (if Library.IsMobile then 100 else 110))
            Number = Library:MobileFit(Number)
            if Number and math.abs(Library.DPIScale * 100 - Number) > 0.5 then
                Library:SetDPIScale(Number)
            end
            Library:CenterMobileWindow()
        end
    
        if WindowInfo.FooterGame then
            task.spawn(function()
                local Name = Library:GetGameName()
                if Name and not Library.Unloaded then
                    Window:SetFooter(Name)
                end
            end)
        end
    
        function Window:SetGlass(Enabled: boolean)
            Library.Glass = Enabled ~= false
            local Value = if Library.Glass then Library.GlassTransparency else 0
            for Panel in Library.GlassPanels do
                if Panel.Parent then
                    Panel.BackgroundTransparency = Value
                    local Cache = TransparencyCache[Panel]
                    if Cache and Cache.BackgroundTransparency ~= nil then
                        Cache.BackgroundTransparency = Value
                    end
                end
            end
        end
    
        function Window:SetAurora(Enabled: boolean)
            if not WindowAurora then
                return
            end
            WindowAurora.Enabled = Enabled ~= false
            WindowAurora:Refresh(Library.Toggled)
        end
    
        Window:SetStarfield(WindowInfo.Starfield)
    
