                Size = UDim2.new(1, -60, 0, 22),
                Text = SpacedTitle,
                TextScaled = true,
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(TitleLabel, "TextTransparency", 0)
            New("UITextSizeConstraint", {
                MaxTextSize = 20,
                MinTextSize = 9,
                Parent = TitleLabel,
            })
            New("UIGradient", {
                Color = function()
                    return ColorSequence.new(Color3.new(1, 1, 1), Library.Scheme.AccentColor:Lerp(Color3.new(1, 1, 1), 0.3))
                end,
                Parent = TitleLabel,
            })
    
            local Status = New("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 0, 138),
                Size = UDim2.new(1, -60, 0, 16),
                Text = "Launching",
                TextSize = 13,
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(Status, "TextTransparency", 0.3)
    
            local Steps = {
                { Name = "Preparing workspace", Min = 3, Countdown = true },
                { Name = "Building interface", Min = 0.9 },
                { Name = "Loading icons and assets", Min = 0.8 },
                { Name = "Loading commands", Min = 0.9, Max = 12 },
                { Name = "Syncing game data", Min = 0.9 },
                { Name = "Restoring settings", Min = 0.7 },
            }
    
            local LastCount, LastChange = -1, 0
            local function CountInterface()
                local Count = 0
                for _ in Library.Options do
                    Count += 1
                end
                for _ in Library.Toggles do
                    Count += 1
                end
                for _ in Library.Tabs do
                    Count += 1
                end
                return Count
            end
            Steps[2].Ready = function(Now)
                local Count = CountInterface()
                if Count ~= LastCount then
                    LastCount, LastChange = Count, Now
                end
                return Count > 0 and Now - LastChange >= 0.45
            end
            Steps[3].Ready = function()
                return Library:IconsReady()
            end
            Steps[4].Ready = function()
                return InfiniteYield.Loaded or not InfiniteYield.Loading
            end
    
            local IconPending = Library:GetIcon("circle")
            local IconActive = Library:GetIcon("loader-circle")
            local IconDone = Library:GetIcon("circle-check")
    
            local List = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 0, 166),
                Size = UDim2.fromOffset(352, #Steps * 17),
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            for Index, Step in Steps do
                local Row = New("Frame", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(0, (Index - 1) * 17),
                    Size = UDim2.new(1, 0, 0, 17),
                    ZIndex = Holder.ZIndex + 2,
                    Parent = List,
                })
                Step.Icon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    ImageColor3 = "FontColor",
                    Position = UDim2.fromScale(0, 0.5),
                    Size = UDim2.fromOffset(12, 12),
                    ZIndex = Holder.ZIndex + 2,
                    Parent = Row,
                })
                if IconPending then
                    Library:ApplyLucideIcon(Step.Icon, IconPending)
                end
                Fade(Step.Icon, "ImageTransparency", 0.75)
                Step.Label = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(20, 0),
                    Size = UDim2.new(1, -80, 1, 0),
                    Text = Step.Name,
                    TextSize = 13,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Holder.ZIndex + 2,
                    Parent = Row,
                })
                Fade(Step.Label, "TextTransparency", 0.65)
                Step.Time = New("TextLabel", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(1, 0),
                    Size = UDim2.fromOffset(60, 17),
                    Text = "",
                    TextSize = 12,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    ZIndex = Holder.ZIndex + 2,
                    Parent = Row,
                })
                Fade(Step.Time, "TextTransparency", 0.5)
            end
    
            local Track = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0),
                BackgroundColor3 = "OutlineColor",
                Position = UDim2.new(0.5, 0, 0, 276),
                Size = UDim2.fromOffset(352, 4),
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(Track, "BackgroundTransparency", 0)
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Track,
            })
            local Fill = New("Frame", {
                BackgroundColor3 = "WhiteColor",
                Size = UDim2.fromScale(0, 1),
                ZIndex = Holder.ZIndex + 3,
                Parent = Track,
            })
            Fade(Fill, "BackgroundTransparency", 0)
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Fill,
            })
            New("UIGradient", {
                Color = GetNebulaSequence,
                Parent = Fill,
            })
            local Tip = New("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = "WhiteColor",
                Position = UDim2.fromScale(1, 0.5),
                Size = UDim2.fromOffset(7, 7),
                ZIndex = Holder.ZIndex + 4,
                Parent = Fill,
            })
            Fade(Tip, "BackgroundTransparency", 0)
            New("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = Tip,
            })
            local TipGlow = New("UIStroke", {
                Color = "AccentColor",
                Thickness = 3,
                Parent = Tip,
            })
            Fade(TipGlow, "Transparency", 0.5)
    
            local Percent = New("TextLabel", {
                BackgroundTransparency = 1,
                FontFace = GetBoldFont,
                Position = UDim2.fromOffset(44, 287),
                Size = UDim2.fromOffset(80, 14),
                Text = "0%",
                TextColor3 = "AccentColor",
                TextSize = 13,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(Percent, "TextTransparency", 0)
            local Timing = New("TextLabel", {
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Position = UDim2.new(1, -44, 0, 287),
                Size = UDim2.fromOffset(220, 14),
                Text = "",
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Right,
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(Timing, "TextTransparency", 0.45)
            local Hint = New("TextLabel", {
                AnchorPoint = Vector2.new(0.5, 1),
                BackgroundTransparency = 1,
                Position = UDim2.new(0.5, 0, 1, -6),
                Size = UDim2.fromOffset(200, 12),
                Text = "click to skip",
                TextSize = 10,
                ZIndex = Holder.ZIndex + 2,
                Parent = Holder,
            })
            Fade(Hint, "TextTransparency", 0.8)
    
            local function Play(Object: Instance, Time: number, Properties: { [string]: any }, Style: Enum.EasingStyle?)
                local Tween = TweenService:Create(Object, TweenInfo.new(Time, Style or Enum.EasingStyle.Quint, Enum.EasingDirection.Out), Properties)
                Tween:Play()
                return Tween
            end
    
            local function Skip()
                Finished = true
            end
            Holder.MouseButton1Click:Connect(Skip)
            Shade.MouseButton1Click:Connect(Skip)
    
            for _, Fader in Faders do
                Play(Fader[1], 0.45, { [Fader[2]] = Fader[3] })
            end
            if Blur then
                Play(Blur, 0.6, { Size = 14 }, Enum.EasingStyle.Quad)
            end
            Play(HolderScale, 0.6, { Scale = Library.DPIScale }, Enum.EasingStyle.Back)
            Play(LogoScale, 0.7, { Scale = 1 }, Enum.EasingStyle.Back)
            task.delay(0.2, function()
                if not Finished and not Library.Unloaded then
                    Field:SetActive(true)
                end
            end)
    
            local TotalMin = 0
            for _, Step in Steps do
                TotalMin += Step.Min
            end
    
            local function SetStepState(Step, State: string, Elapsed: number?)
                if Step.State == State then
                    return
                end
                Step.State = State
                if State == "active" then
                    if IconActive then
                        Library:ApplyLucideIcon(Step.Icon, IconActive)
                    end
                    Library:SetSchemeProperty(Step.Icon, "ImageColor3", "AccentColor")
                    Play(Step.Icon, 0.25, { ImageTransparency = 0 })
                    Play(Step.Label, 0.25, { TextTransparency = 0 })
                elseif State == "done" then
                    Step.Icon.Rotation = 0
                    if IconDone then
                        Library:ApplyLucideIcon(Step.Icon, IconDone)
                    end
                    Library:SetSchemeProperty(Step.Icon, "ImageColor3", "AccentColor")
                    Play(Step.Icon, 0.25, { ImageTransparency = 0 })
                    Play(Step.Label, 0.25, { TextTransparency = 0.3 })
                    Step.Time.Text = string.format("%.1fs", Elapsed or 0)
                    local Pop = New("UIScale", {
                        Scale = 1.5,
                        Parent = Step.Icon,
                    })
                    Play(Pop, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)
                end
            end
    
            local Clock = 0
            local Display = 0
            local Current = 1
            local StepStart = 0
            local CompletedMin = 0
    
            while not Library.Unloaded do
                local Delta = task.wait() or 0.016
                Clock += Delta
                StrokeGradient.Rotation = (StrokeGradient.Rotation + Delta * 40) % 360
                RingGradient.Rotation = (RingGradient.Rotation + Delta * 320) % 360
    
                if Finished then
                    for Index = Current, #Steps do
                        SetStepState(Steps[Index], "done", if Index == Current then Clock - StepStart else 0)
                    end
                    Current = #Steps + 1
                end
    
                local Step = Steps[Current]
                local Fraction = 0
                if Step then
                    SetStepState(Step, "active")
                    local InStep = Clock - StepStart
                    Step.Icon.Rotation = (Step.Icon.Rotation + Delta * 300) % 360
                    Fraction = math.min(InStep / Step.Min, 1) * 0.96
    
                    if Step.Countdown then
                        Status.Text = string.format("Launching in %d", math.max(1, math.ceil(Step.Min - InStep)))
                    else
                        Status.Text = Step.Name .. "..."
                    end
    
                    local Ready = InStep >= Step.Min and (Step.Ready == nil or Step.Ready(Clock) or InStep >= (Step.Max or 6))
                    if Ready then
                        SetStepState(Step, "done", InStep)
                        CompletedMin += Step.Min
                        Current += 1
                        StepStart = Clock
                        Fraction = 0
                    end
                end
    
                local Target = if Current > #Steps then 1 else (CompletedMin + Fraction * (if Step then Step.Min else 0)) / TotalMin
                Display += (Target - Display) * math.clamp(Delta * 7, 0, 1)
                if Current > #Steps and Target - Display < 0.004 then
                    Display = 1
                end
                Fill.Size = UDim2.fromScale(Display, 1)
                Percent.Text = string.format("%d%%", math.floor(Display * 100 + 0.5))
    
                local Remaining = 0
                for Index = Current, #Steps do
                    if Index == Current then
                        Remaining += math.max(Steps[Index].Min - (Clock - StepStart), 0)
                    else
                        Remaining += Steps[Index].Min
                    end
                end
                Timing.Text = if Current > #Steps
                    then string.format("Loaded in %.1fs", Clock)
                    else string.format("%.1fs  \u{00B7}  ~%ds left", Clock, math.max(1, math.ceil(Remaining)))
    
                if Current > #Steps and Display >= 1 then
                    break
                end
            end
    
            if not Library.Unloaded then
                Status.Text = "Ready"
                Library:SetSchemeProperty(Status, "TextColor3", "AccentColor")
                local Pulse = New("UIScale", {
                    Parent = LogoFrame,
                })
                Play(Pulse, 0.18, { Scale = 1.12 }, Enum.EasingStyle.Quad)
                task.delay(0.18, function()
                    Play(Pulse, 0.3, { Scale = 1 }, Enum.EasingStyle.Back)
                end)
                local Waited = 0
                repeat
                    Waited += (task.wait() or 0.016)
                until Waited >= (if Finished then 0.15 else 0.55) or Library.Unloaded
            end
            Finished = true
    
            Field:SetActive(false)
            for _, Fader in Faders do
                Play(Fader[1], 0.32, { [Fader[2]] = 1 }, Enum.EasingStyle.Quad)
            end
            if Blur then
                Play(Blur, 0.4, { Size = 0 }, Enum.EasingStyle.Quad)
            end
            Play(HolderScale, 0.35, { Scale = Library.DPIScale * 1.06 }, Enum.EasingStyle.Quad)
    
            task.wait(0.14)
            Library.IntroPlaying = false
            if not Library.Unloaded and not Library.Toggled then
                task.spawn(Library.Toggle, Library, true)
            end
    
            task.wait(0.3)
            Field:Destroy()
            Holder:Destroy()
            Shade:Destroy()
            if Blur then
                Blur:Destroy()
            end
        end
    
        do
            local NumberKeys = {
                Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three,
                Enum.KeyCode.Four, Enum.KeyCode.Five, Enum.KeyCode.Six,
                Enum.KeyCode.Seven, Enum.KeyCode.Eight, Enum.KeyCode.Nine,
            }
    
            local function GetOrderedTabs()
                local List = {}
                for _, Tab in Library.Tabs do
                    if typeof(Tab) == "table" and not Tab.Destroyed and Tab.Button and Tab.Button.Visible ~= false then
                        table.insert(List, Tab)
                    end
                end
    
                table.sort(List, function(A, B)
                    local OrderA, OrderB = A.Button.LayoutOrder, B.Button.LayoutOrder
                    if OrderA == OrderB then
                        return tostring(A.Name) < tostring(B.Name)
                    end
                    return OrderA < OrderB
                end)
    
                return List
            end
            Window.GetOrderedTabs = GetOrderedTabs
    
            function Window.GetTabHotkeyIndex(Entry)
                for Index, Tab in GetOrderedTabs() do
                    if Tab.Button == Entry.Button then
                        return if Index <= 9 then Index else nil
                    end
                end
                return nil
            end
    
            Library:GiveSignal(UserInputService.InputBegan:Connect(function(Input: InputObject, Processed: boolean)
                if Library.Unloaded or Processed then
                    return
                end
    
                local Ctrl = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
                if WindowInfo.TabHotkeys ~= false and Ctrl and Library.Toggled and not Window:IsMinimized() then
                    local Index = table.find(NumberKeys, Input.KeyCode)
                    if Index then
                        local Tab = GetOrderedTabs()[Index]
                        if Tab then
                            Tab:Show()
                        end
                    end
                end
            end))
        end
    
        local SessionStarted = os.clock()
    
        local function InfoRow(Groupbox, Label: string, Value: string)
            return Groupbox:AddLabel({
                Text = string.format('<font transparency="0.5">%s</font>   %s', Label, Value),
                DoesWrap = false,
            })
        end
    
        local function SetInfoRow(Row, Label: string, Value: string)
            if Row and Row.SetText then
                Row:SetText(string.format('<font transparency="0.5">%s</font>   %s', Label, Value))
            end
        end
    
        local function GetExecutorName(): string
            local Success, Name, Version = pcall(function()
                if identifyexecutor then
                    return identifyexecutor()
                elseif getexecutorname then
                    return getexecutorname()
                end
                return nil
            end)
    
            if Success and typeof(Name) == "string" and Name ~= "" then
                return if typeof(Version) == "string" and Version ~= "" then Name .. " " .. Version else Name
            end
            return "Unknown"
        end
    
        local function GetDeviceName(): string
            if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
                return "Mobile"
            elseif UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
                return "Console"
            end
            return "PC"
        end
    
        function Window:Rejoin()
            local TeleportService = game:GetService("TeleportService")
            Library:Notify({ Title = "Rejoin", Description = "Rejoining this server...", Time = 3 })
    
            local Success = pcall(function()
                if #Players:GetPlayers() <= 1 then
                    TeleportService:Teleport(game.PlaceId, LocalPlayer)
                else
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
                end
            end)
            if not Success then
                Library:Notify({ Title = "Rejoin", Description = "Teleport failed, try again in a moment.", Time = 4 })
            end
        end
    
        function Window:ServerHop()
            local TeleportService = game:GetService("TeleportService")
            Library:Notify({ Title = "Server Hop", Description = "Looking for another server...", Time = 3 })
    
            local Data = HttpRequestJSON(string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100&excludeFullGames=true", game.PlaceId))
            local Candidates = {}
            if typeof(Data) == "table" and typeof(Data.data) == "table" then
                for _, Server in Data.data do
                    local Playing, Maximum = tonumber(Server.playing), tonumber(Server.maxPlayers)
                    if typeof(Server) == "table" and Server.id ~= game.JobId and Playing and Maximum and Playing < Maximum then
                        table.insert(Candidates, Server.id)
                    end
                end
            end
    
            if #Candidates == 0 then
                Library:Notify({ Title = "Server Hop", Description = "No other public servers were found.", Time = 4 })
                return
            end
    
            local Success = pcall(function()
                TeleportService:TeleportToPlaceInstance(game.PlaceId, Candidates[math.random(1, #Candidates)], LocalPlayer)
            end)
            if not Success then
                Library:Notify({ Title = "Server Hop", Description = "Teleport failed, try again in a moment.", Time = 4 })
            end
        end
    
