            end)
    
            local function UpdateSession(Fps: number?, Ping: number?)
                if Library.Unloaded then
                    return
                end
    
                local CurrentFps, CurrentPing = Library:GetPerformance()
                Fps, Ping = Fps or CurrentFps, Ping or CurrentPing
    
                SetInfoRow(PlayersRow, "Players", string.format("%d / %d", #Players:GetPlayers(), tonumber(Players.MaxPlayers) or #Players:GetPlayers()))
                SetInfoRow(ServerRow, "Server age", Library:FormatDuration(workspace.DistributedGameTime))
                SetInfoRow(SessionRow, "Session", Library:FormatDuration(os.clock() - SessionStarted))
                SetInfoRow(PerformanceRow, "Performance", string.format("%d fps  \u{00B7}  %d ms", tonumber(Fps) or 0, tonumber(Ping) or 0))
            end
            UpdateSession()
            Library:OnPerformance(function(Fps, Ping)
                if Library.ActiveTab == Tab and Library.Toggled then
                    UpdateSession(Fps, Ping)
                end
            end)
    
            local Invite = Info.Discord or Info.Invite
