        function Window:AddMiscTab(Info)
            Info = Info or {}
    
            local Tab = Window:AddTab({
                Name = Info.Name or "Misc",
                Icon = Info.Icon or "gauge",
                Description = Info.Description or "Performance, AFK and connection",
            })
            Window.MiscTab = Tab
            if typeof(Info.RejoinScript) == "string" then
                Library.RejoinScript = Info.RejoinScript
            end

            local function Humanoid()
                local Character = LocalPlayer.Character
                return Character and Character:FindFirstChildOfClass("Humanoid")
            end
    
            local Afk = {
                Enabled = Library:GetSetting("AntiAFK", true) ~= false,
                Count = 0,
                LastPulse = os.clock(),
                NextPulse = os.clock() + 45,
                Jump = false,
                JumpEvery = 30,
                LastJump = os.clock(),
                Move = false,
                LastMove = os.clock(),
            }
    
            local AfkBox = Tab:AddLeftGroupbox("Anti AFK", "coffee")
            AfkBox:AddToggle("CorvusAntiAFK", {
                Text = "Anti AFK",
                Description = "Never get kicked for being idle",
                Tooltip = "A harmless key press after a minute without input, a tiny step now and then while you stand still, and a rejoin if Roblox still kicks you",
                Default = Afk.Enabled,
                Callback = function(Value)
                    Afk.Enabled = Value
                    if Library.SetAntiAfk then
                        Library:SetAntiAfk(Value)
                    else
                        Library:SetSetting("AntiAFK", Value)
                    end
                end,
            })
            AfkBox:AddToggle("CorvusAutoJump", {
                Text = "Auto jump",
                Description = "Jumps every few seconds",
                Default = false,
                Callback = function(Value)
                    Afk.Jump = Value
                    Afk.LastJump = os.clock()
                end,
            })
            AfkBox:AddSlider("CorvusJumpEvery", {
                Text = "Jump every",
                Min = 5,
                Max = 120,
                Default = 30,
                Rounding = 0,
                Suffix = "s",
                HideMax = true,
                Callback = function(Value)
                    Afk.JumpEvery = math.max(5, tonumber(Value) or 30)
                end,
            })
            AfkBox:AddToggle("CorvusMicroMove", {
                Text = "Micro movement",
                Description = "A tiny step and turn now and then",
                Default = false,
                Callback = function(Value)
                    Afk.Move = Value
                    Afk.LastMove = os.clock()
                end,
            })
            local AfkStat = AfkBox:AddStat({ Icon = "shield-check", Text = "AFK inputs sent", Value = "0", Size = 22 })
            local PulseStat = AfkBox:AddStat({ Icon = "activity", Text = "Last activity", Value = "just now", Size = 22, ValueColor = "FontColor" })
    
            task.spawn(function()
                while not Library.Unloaded do
                    task.wait(1)
                    local Now = os.clock()
                    local Engine = Library.AntiAfk
                    if typeof(Engine) == "table" then
                        Afk.Count = Engine.Count or Afk.Count
                        Afk.LastPulse = math.max(Afk.LastPulse, Engine.LastPulse or 0)
                    end
                    if Afk.Jump and Now - Afk.LastJump >= Afk.JumpEvery then
                        Afk.LastJump = Now
                        local Hum = Humanoid()
                        if Hum and Hum.FloorMaterial ~= Enum.Material.Air then
                            pcall(function()
                                Hum:ChangeState(Enum.HumanoidStateType.Jumping)
                            end)
                            Afk.LastPulse = Now
                        end
                    end
                    if Afk.Move and Now - Afk.LastMove >= 25 + math.random() * 20 then
                        Afk.LastMove = Now
                        local Hum = Humanoid()
                        local Root = Hum and Hum.RootPart
                        if Hum and Root then
                            task.spawn(function()
                                pcall(function()
                                    local Turn = math.rad(math.random(-12, 12))
                                    Root.CFrame = Root.CFrame * CFrame.Angles(0, Turn, 0)
                                    Hum:Move(Vector3.new(0, 0, -1), true)
                                    task.wait(0.12)
                                    Hum:Move(Vector3.new(0, 0, 1), true)
                                    task.wait(0.12)
                                    Hum:Move(Vector3.zero, true)
                                end)
                            end)
                            Afk.LastPulse = Now
                        end
                    end
                    pcall(AfkStat.SetValue, AfkStat, tostring(Afk.Count))
                    local Ago = math.floor(Now - Afk.LastPulse)
                    pcall(PulseStat.SetValue, PulseStat, if Ago < 5 then "just now" else Library:FormatDuration(Ago) .. " ago")
                end
            end)
    
            local ConnectionBox = Tab:AddLeftGroupbox("Connection", "wifi")
            local Reconnect = { Enabled = false, Pending = false, Attempts = 0, Status = "Off" }
            local ReconnectStat
    
            local function StartReconnect()
                if not Reconnect.Enabled or Reconnect.Pending then
                    return
                end
                Reconnect.Pending = true
                Reconnect.Status = "Reconnecting"
                task.spawn(function()
                    task.wait(2)
                    while Reconnect.Enabled do
                        Reconnect.Attempts += 1
                        Reconnect.Status = "Attempt " .. Reconnect.Attempts
                        if typeof(Info.RejoinScript) == "string" and typeof(queue_on_teleport) == "function" then
                            pcall(queue_on_teleport, Info.RejoinScript)
                        end
                        pcall(function()
                            if Reconnect.Attempts <= 3 and game.JobId ~= "" then
                                game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
                            else
                                game:GetService("TeleportService"):Teleport(game.PlaceId, LocalPlayer)
                            end
                        end)
                        task.wait(8)
                    end
                    Reconnect.Pending = false
                end)
            end
    
            ConnectionBox:AddToggle("CorvusAutoReconnect", {
                Text = "Auto reconnect",
                Description = "Rejoins by itself after a kick or disconnect",
                Tooltip = "Tries the same server first, so all your accounts end up together again. If that server is gone, it joins a new one.",
                Default = false,
                Callback = function(Value)
                    Reconnect.Enabled = Value
                    Library.AutoReconnectOn = Value == true
                    Reconnect.Status = if Value then "Watching" else "Off"
                    if not Value then
                        Reconnect.Pending = false
                    end
                end,
            })
            ConnectionBox:AddToggle("CorvusNoPausePopup", {
                Text = "Hide paused popup",
                Description = "Removes the gameplay paused overlay",
                Default = false,
                Callback = function(Value)
                    pcall(function()
                        GuiService:SetGameplayPausedNotificationEnabled(not Value)
                    end)
                end,
            })
            ReconnectStat = ConnectionBox:AddStat({ Icon = "refresh-cw", Text = "Reconnect", Value = "Off", Size = 22, ValueColor = "FontColor" })
            ConnectionBox:AddButton({
                Text = "Rejoin now",
                DoubleClick = true,
                Func = function()
                    if typeof(Info.RejoinScript) == "string" and typeof(queue_on_teleport) == "function" then
                        pcall(queue_on_teleport, Info.RejoinScript)
                    end
                    pcall(function()
                        game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
                    end)
                end,
            })
    
            pcall(function()
                Library:GiveSignal(GuiService.ErrorMessageChanged:Connect(function()
                    local Message = ""
                    pcall(function()
                        Message = GuiService:GetErrorMessage()
                    end)
                    if Message ~= "" then
                        StartReconnect()
                    end
                end))
            end)
            task.spawn(function()
                local Prompt
                pcall(function()
                    Prompt = game:GetService("CoreGui"):WaitForChild("RobloxPromptGui", 10)
                    Prompt = Prompt and Prompt:WaitForChild("promptOverlay", 10)
                end)
                if Prompt then
                    Library:GiveSignal(Prompt.ChildAdded:Connect(function(Child)
                        if Child.Name == "ErrorPrompt" then
                            StartReconnect()
                        end
                    end))
                end
            end)
            task.spawn(function()
                while not Library.Unloaded do
                    task.wait(1)
                    pcall(ReconnectStat.SetValue, ReconnectStat, Reconnect.Status)
                end
            end)
    
            local Perf = Tab:AddRightGroupbox("Performance", "zap")
            local AntiLag = {
                Enabled = false,
                Level = 2,
                Saved = setmetatable({}, { __mode = "k" }),
                Count = 0,
                Queue = {},
                Token = 0,
                Globals = {},
            }
            local Levels = { Light = 1, Balanced = 2, Ultra = 3 }
    
            local function Remember(Target: Instance, Property: string, Value: any)
                local Entry = AntiLag.Saved[Target]
                if not Entry then
                    Entry = {}
                    AntiLag.Saved[Target] = Entry
                end
                local Ok, Current = pcall(function()
                    return Target[Property]
                end)
                if not Ok or Current == Value then
                    return
                end
                if Entry[Property] == nil then
                    Entry[Property] = { Current }
                end
                pcall(function()
                    Target[Property] = Value
                end)
            end
    
            local function Protected(Target: Instance)
                local Map = workspace:FindFirstChild("Map")
                local Eggs = Map and Map:FindFirstChild("Eggs")
                if Eggs and Target:IsDescendantOf(Eggs) then
                    return true
                end
                local Character = LocalPlayer.Character
                return Character ~= nil and Target:IsDescendantOf(Character)
            end
    
            local function Optimize(Target: Instance)
                local Level = AntiLag.Level
                if Target:IsA("ParticleEmitter") or Target:IsA("Trail") or Target:IsA("Beam") or Target:IsA("Smoke") or Target:IsA("Fire") or Target:IsA("Sparkles") then
                    Remember(Target, "Enabled", false)
                    AntiLag.Count += 1
                elseif Target:IsA("Explosion") then
                    Remember(Target, "Visible", false)
                elseif Target:IsA("BasePart") then
                    Remember(Target, "CastShadow", false)
                    if Level >= 2 then
                        Remember(Target, "Reflectance", 0)
                        if not Protected(Target) then
                            Remember(Target, "Material", Enum.Material.SmoothPlastic)
                        end
                    end
                    if Level >= 3 and Target:IsA("MeshPart") and not Protected(Target) then
                        Remember(Target, "TextureID", "")
                    end
                    AntiLag.Count += 1
                elseif Level >= 2 and (Target:IsA("Decal") or Target:IsA("Texture")) and not Protected(Target) then
                    Remember(Target, "Transparency", 1)
                    AntiLag.Count += 1
                elseif Level >= 2 and Target:IsA("Light") then
                    Remember(Target, "Enabled", false)
                    AntiLag.Count += 1
                end
            end
    
            local function ApplyGlobals()
                local Lighting = game:GetService("Lighting")
                Remember(Lighting, "GlobalShadows", false)
                if AntiLag.Level >= 2 then
                    Remember(Lighting, "FogEnd", 1e9)
                    for _, Child in Lighting:GetChildren() do
                        if Child:IsA("PostEffect") then
                            Remember(Child, "Enabled", false)
                        elseif Child:IsA("Atmosphere") then
                            Remember(Child, "Density", 0)
                            Remember(Child, "Haze", 0)
                            Remember(Child, "Glare", 0)
                        elseif Child:IsA("Clouds") then
                            Remember(Child, "Enabled", false)
                        end
                    end
                end
                local Terrain = workspace:FindFirstChildOfClass("Terrain")
                if Terrain then
                    Remember(Terrain, "WaterWaveSize", 0)
                    Remember(Terrain, "WaterWaveSpeed", 0)
                    Remember(Terrain, "WaterReflectance", 0)
                    if AntiLag.Level >= 3 and typeof(sethiddenproperty) == "function" then
                        pcall(sethiddenproperty, Terrain, "Decoration", false)
                    end
                end
                pcall(function()
                    if AntiLag.Globals.Quality == nil then
                        AntiLag.Globals.Quality = settings().Rendering.QualityLevel
                    end
                    settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
                end)
            end
    
            local function Restore()
                AntiLag.Token += 1
                for Target, Entry in AntiLag.Saved do
                    for Property, Box in Entry do
                        pcall(function()
                            Target[Property] = Box[1]
                        end)
                    end
                end
                table.clear(AntiLag.Saved)
                table.clear(AntiLag.Queue)
                if AntiLag.Globals.Quality ~= nil then
                    pcall(function()
                        settings().Rendering.QualityLevel = AntiLag.Globals.Quality
                    end)
                    AntiLag.Globals.Quality = nil
                end
                AntiLag.Count = 0
            end
    
            local function Apply()
                AntiLag.Token += 1
                local Token = AntiLag.Token
                ApplyGlobals()
                task.spawn(function()
                    local List = workspace:GetDescendants()
                    for Index, Target in List do
                        if Token ~= AntiLag.Token then
                            return
                        end
                        pcall(Optimize, Target)
                        if Index % 1500 == 0 then
                            task.wait()
                        end
                    end
                end)
            end
    
            Library:GiveSignal(workspace.DescendantAdded:Connect(function(Target)
                if AntiLag.Enabled then
                    table.insert(AntiLag.Queue, Target)
                end
            end))
            Library:GiveSignal(RunService.Heartbeat:Connect(function()
                if not AntiLag.Enabled or #AntiLag.Queue == 0 then
                    return
                end
                for _ = 1, math.min(#AntiLag.Queue, 300) do
                    local Target = table.remove(AntiLag.Queue)
                    if Target and Target.Parent then
                        pcall(Optimize, Target)
                    end
                end
            end))
    
            Perf:AddToggle("CorvusAntiLag", {
                Text = "Anti lag",
                Description = "Strips effects, shadows and heavy textures",
                Tooltip = "Light: effects and shadows. Balanced: plus materials, decals and lights. Ultra: plus mesh textures and terrain decoration. Turning it off restores everything.",
                Default = false,
                Callback = function(Value)
                    AntiLag.Enabled = Value
                    if Value then
                        Apply()
                    else
                        Restore()
                    end
                end,
            })
            Perf:AddDropdown("CorvusAntiLagLevel", {
                Text = "Level",
                Values = { "Light", "Balanced", "Ultra" },
                Default = "Balanced",
                Callback = function(Value)
                    AntiLag.Level = Levels[Value] or 2
                    if AntiLag.Enabled then
                        Restore()
                        Apply()
                    end
                end,
            })
            local LagStat = Perf:AddStat({ Icon = "zap", Text = "Objects optimized", Value = "0", Size = 22 })
    
            local FpsMeter = { Frames = 0, Elapsed = 0 }
            Library:GiveSignal(RunService.Heartbeat:Connect(function(Delta)
                FpsMeter.Frames += 1
                FpsMeter.Elapsed += tonumber(Delta) or 0
            end))
    
            local FpsStat = Perf:AddStat({ Icon = "gauge", Text = "FPS", Value = "-", Size = 22, ValueColor = "FontColor" })
            task.spawn(function()
                while not Library.Unloaded do
                    task.wait(1)
                    if FpsMeter.Elapsed > 0.2 then
                        local Fps = FpsMeter.Frames / FpsMeter.Elapsed
                        FpsMeter.Frames, FpsMeter.Elapsed = 0, 0
                        local Color = if Fps >= 50 then "#60d696" elseif Fps >= 30 then "#ffb84d" else "#ff6e8a"
                        pcall(FpsStat.SetValue, FpsStat, string.format('<font color="%s">%d</font>', Color, math.floor(Fps + 0.5)))
                    end
                end
            end)
    
            local Overlay = nil
            local function BuildOverlay()
                if Overlay then
                    return Overlay
                end
                local Holder = New("Frame", {
                    BackgroundColor3 = Color3.fromRGB(4, 4, 7),
                    Name = "CorvusRenderOverlay",
                    Size = UDim2.fromScale(1, 1),
                    Visible = false,
                    ZIndex = -20,
                    Parent = Library.ScreenGui,
                })
                New("UIGradient", {
                    Color = ColorSequence.new(Color3.fromRGB(10, 10, 16), Color3.fromRGB(2, 2, 4)),
                    Rotation = 90,
                    Parent = Holder,
                })
                local Field = Library:CreateStarfield(Holder, {
                    Count = 150,
                    Sparkles = 10,
                    BrightStars = 8,
                    Seed = 41,
                    ZIndex = -19,
                })
                local Card = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(460, 260),
                    ZIndex = -18,
                    Parent = Holder,
                })
                local Logo = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0),
                    Size = UDim2.fromOffset(72, 72),
                    ZIndex = -17,
                    Parent = Card,
                })
                local LogoData = Library:GetCustomIcon(WindowInfo.Icon or "corvus")
                if LogoData then
                    Library:ApplyLucideIcon(Logo, LogoData)
                end
                New("TextLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.new(0.5, 0, 0, 84),
                    Size = UDim2.new(1, 0, 0, 34),
                    Text = "C O R V U S",
                    TextColor3 = "FontColor",
                    TextSize = 30,
                    ZIndex = -17,
                    Parent = Card,
                })
                New("TextLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0, 122),
                    Size = UDim2.new(1, 0, 0, 20),
                    Text = "3D rendering is off. Your farm keeps running.",
                    TextColor3 = "FontColor",
                    TextSize = 15,
                    TextTransparency = 0.3,
                    ZIndex = -17,
                    Parent = Card,
                })
                local InfoLine = New("TextLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0, 146),
                    RichText = true,
                    Size = UDim2.new(1, 0, 0, 20),
                    Text = "",
                    TextColor3 = "AccentColor",
                    TextSize = 14,
                    ZIndex = -17,
                    Parent = Card,
                })
                local Resume = New("TextButton", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    AutoButtonColor = false,
                    BackgroundColor3 = "MainColor",
                    FontFace = GetBoldFont,
                    Position = UDim2.new(0.5, 0, 0, 184),
                    Size = UDim2.fromOffset(200, 38),
                    Text = "Resume rendering",
                    TextColor3 = "FontColor",
                    TextSize = 15,
                    ZIndex = -17,
                    Parent = Card,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 10),
                    Parent = Resume,
                })
                New("UIStroke", {
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                    Color = "AccentColor",
                    Transparency = 0.35,
                    Parent = Resume,
                })
                local KeyHint = New("TextLabel", {
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0, 230),
                    Size = UDim2.new(1, 0, 0, 18),
                    Text = "",
                    TextColor3 = "FontColor",
                    TextSize = 13,
                    TextTransparency = 0.5,
                    ZIndex = -17,
                    Parent = Card,
                })
                Overlay = {
                    Holder = Holder,
                    Field = Field,
                    InfoLine = InfoLine,
                    KeyHint = KeyHint,
                    Resume = Resume,
                }
                Resume.MouseButton1Click:Connect(function()
                    local Toggle = Library.Toggles.CorvusNoRender
                    if Toggle then
                        Toggle:SetValue(false)
                    end
                end)
                task.spawn(function()
                    local Started = os.clock()
                    while Holder.Parent and not Library.Unloaded do
                        if Holder.Visible then
                            local Line = "Paused for " .. Library:FormatDuration(os.clock() - Started)
                            if typeof(Library.RenderOverlayInfo) == "function" then
                                local Ok, Extra = pcall(Library.RenderOverlayInfo)
                                if Ok and typeof(Extra) == "string" and Extra ~= "" then
                                    Line = Line .. "  \u{00B7}  " .. Extra
                                end
                            end
                            InfoLine.Text = Line
                            local Key = "Z"
                            pcall(function()
                                local Picker = Library.Options.MenuKeybind
                                if Picker and Picker.Value then
                                    Key = tostring(Picker.Value)
                                end
                            end)
                            KeyHint.Text = if Library.IsMobile then "Tap the Corvus button to show or hide the hub" else "Press " .. Key .. " to show or hide the hub"
                        else
                            Started = os.clock()
                        end
                        task.wait(1)
                    end
                end)
                return Overlay
            end
    
            Perf:AddToggle("CorvusNoRender", {
                Text = "Disable 3D rendering",
                Description = "Saves GPU, shows the Corvus sky instead",
                Default = false,
                Callback = function(Value)
                    pcall(function()
                        RunService:Set3dRenderingEnabled(not Value)
                    end)
                    local Built = BuildOverlay()
                    Built.Holder.Visible = Value
                    pcall(Built.Field.SetActive, Built.Field, Value)
                end,
            })
    
            if typeof(setfpscap) == "function" then
                Perf:AddDropdown("CorvusFPSCap", {
                    Text = "FPS cap",
                    Values = { "Unlimited", "240", "144", "120", "60", "30", "15" },
                    Default = "Unlimited",
                    Callback = function(Value)
                        pcall(setfpscap, tonumber(Value) or 999)
                    end,
                })
            end
    
            task.spawn(function()
                while not Library.Unloaded do
                    task.wait(1)
                    pcall(LagStat.SetValue, LagStat, if AntiLag.Enabled then tostring(AntiLag.Count) else "off")
                end
            end)
    
            Library:OnUnload(function()
                if AntiLag.Enabled then
                    pcall(Restore)
                end
                pcall(function()
                    RunService:Set3dRenderingEnabled(true)
                end)
            end)
    
            return Tab
        end
    
        function Window:AddSettingsTab(Info)
            Info = Info or {}
    
            local Tab = Window:AddTab({
                Name = Info.Name or "Settings",
                Icon = Info.Icon or "settings",
                Description = Info.Description or "Appearance, behaviour and configs",
            })
    
            local ThemeManager, SaveManager = Info.ThemeManager, Info.SaveManager
            local Folder = Info.Folder or tostring(WindowInfo.Title or Library.Name)
    
            local Appearance = Tab:AddLeftGroupbox("Appearance", "palette")
            local SavedTheme = Library:GetSetting("Theme", nil)
            if typeof(SavedTheme) ~= "string" or not Library.CorvusThemes[SavedTheme] then
                SavedTheme = Library.DefaultThemeName or "Corvus Night"
            end
            local SavedAccent = Library:GetSetting("Accent", nil)
    
            local AccentLabel
            local Gallery = Appearance:AddThemeGallery({
                Default = SavedTheme,
                Callback = function(Name)
                    Library:SetTheme(Name)
                    Library:SetSetting("Theme", Name)
                    Library:SetSetting("Accent", nil)
                    local Picker = Library.Options.CorvusAccent
                    if Picker and Picker.SetValueRGB then
                        Picker:SetValueRGB(Library.Scheme.AccentColor)
                    end
                end,
            })
            Library.ThemeGallery = Gallery
            Library:SetTheme(SavedTheme)
            if typeof(SavedAccent) == "string" then
                local Success, Color = pcall(Color3.fromHex, SavedAccent)
                if Success then
                    Library.Scheme.AccentColor = Color
                    Library:UpdateColorsUsingRegistry()
                end
            end
    
            Appearance:AddDivider({ Text = "Customize", MarginTop = 4 })
            AccentLabel = Appearance:AddLabel("Accent color")
            AccentLabel:AddColorPicker("CorvusAccent", {
                Default = Library.Scheme.AccentColor,
                Title = "Accent color",
                Callback = function(Color)
                    if Library.Scheme.AccentColor == Color then
                        return
                    end
                    Library.Scheme.AccentColor = Color
                    Library:UpdateColorsUsingRegistry()
                    Library:SetSetting("Accent", Color:ToHex())
                end,
            })
    
            local Fonts = { "BuilderSans", "Gotham", "Montserrat", "Nunito", "Ubuntu", "Arial" }
            local SavedFont = Library:GetSetting("Font", "BuilderSans")
            if not table.find(Fonts, SavedFont) then
                SavedFont = "BuilderSans"
            end
            Appearance:AddDropdown("CorvusFont", {
                Text = "Font",
                Values = Fonts,
                Default = SavedFont,
                Callback = function(Value)
                    local Success, FontEnum = pcall(function()
                        return Enum.Font[Value]
                    end)
                    if Success and FontEnum then
                        pcall(Library.SetFont, Library, Font.fromEnum(FontEnum))
                        Library:SetSetting("Font", Value)
                    end
                end,
            })
            if SavedFont ~= "BuilderSans" then
                pcall(function()
                    Library:SetFont(Font.fromEnum(Enum.Font[SavedFont]))
                end)
            end
    
            local SavedScale = Library:GetSetting("Scale", nil)
            if typeof(SavedScale) ~= "string" then
                SavedScale = tostring(WindowInfo.Scale or (if Library.IsMobile then 100 else 110)) .. "%"
            end
            Appearance:AddDropdown("CorvusScale", {
                Text = "Interface scale",
                Values = { "75%", "90%", "100%", "110%", "125%", "150%" },
                Default = SavedScale,
                Callback = function(Value)
                    local Number = tonumber((string.gsub(tostring(Value), "%%", "")))
                    if Number then
                        Library:SetDPIScale(Library:MobileFit(Number))
                        Library:CenterMobileWindow()
                        Library:SetSetting("Scale", Value)
                    end
                end,
            })
            do
                local Number = Library:MobileFit(tonumber((string.gsub(SavedScale, "%%", ""))))
                if Number and math.abs(Library.DPIScale * 100 - Number) > 0.5 then
                    Library:SetDPIScale(Number)
                    Library:CenterMobileWindow()
                end
            end
    
            if Library.IsMobile and Library.MobileButtons then
                local MobileBox = Tab:AddLeftGroupbox("Mobile", "smartphone")
                MobileBox:AddDropdown("CorvusMobileButtonSize", {
                    Text = "Button size",
                    Values = { "Small", "Normal", "Large" },
                    Default = Library:GetSetting("MobileButtonSize", "Normal"),
                    Callback = function(Value)
                        if Library.SetMobileButtonSize then
                            Library:SetMobileButtonSize(Value)
                        end
                    end,
                })
                MobileBox:AddToggle("CorvusMobileLock", {
                    Text = "Lock button",
                    Description = "Stops the hub from being dragged by accident",
                    Default = Library:GetSetting("MobileLockButton", true) ~= false,
                    Callback = function(Value)
                        Library:SetSetting("MobileLockButton", Value)
                        local Lock = Library.MobileButtons and Library.MobileButtons.Lock
                        if Lock and Lock.Button then
                            Lock.Button.Visible = Value
                        end
                    end,
                })
                MobileBox:AddToggle("CorvusQuickBar", {
                    Text = "Quick bar",
                    Description = "Shortcut buttons next to the Corvus button",
                    Default = Library:GetSetting("QuickBar", true) ~= false,
                    Callback = function(Value)
                        Library:SetSetting("QuickBar", Value)
                    end,
                })
                local QuickList = Library.QuickBarItems or {}
                if #QuickList > 0 then
                    local Labels, ById, Defaults = {}, {}, {}
                    local Chosen = Library:GetSetting("QuickBarItems", nil)
                    for _, Item in QuickList do
                        local Label = tostring(Item.Label or Item.Toggle)
                        table.insert(Labels, Label)
                        ById[Label] = Item.Toggle
                        local On = if typeof(Chosen) == "table" then table.find(Chosen, Item.Toggle) ~= nil else Item.Default ~= false
                        if On then
                            table.insert(Defaults, Label)
                        end
                    end
                    MobileBox:AddDropdown("CorvusQuickBarItems", {
                        Text = "Quick bar buttons",
                        Values = Labels,
                        Default = Defaults,
                        Multi = true,
                        Callback = function(Value)
                            local List = {}
                            for _, Label in Labels do
                                if typeof(Value) == "table" and Value[Label] and #List < 6 then
                                    table.insert(List, ById[Label])
                                end
                            end
                            Library:SetSetting("QuickBarItems", List)
                            if Library.BuildQuickBar then
                                Library:BuildQuickBar()
                            end
                        end,
                    })
                end
                MobileBox:AddButton({
                    Text = "Reset button position",
                    Func = function()
                        if Library.ResetMobileButtons then
                            Library:ResetMobileButtons()
                        end
                    end,
                })
            end
    
            local Effects = Tab:AddLeftGroupbox("Effects", "sparkles")
            Effects:AddToggle("CorvusStarfield", {
                Text = "Night sky",
                Description = "Animated stars and constellation",
                Default = WindowInfo.Starfield ~= false,
                Callback = function(Value)
                    Window:SetStarfield(Value)
                    Library:SetSetting("Starfield", Value)
                end,
            })
            Effects:AddToggle("CorvusGlass", {
                Text = "Glass panels",
                Description = "Let the sky shine through panels",
                Default = Library.Glass ~= false,
                Callback = function(Value)
                    Window:SetGlass(Value)
                    Library:SetSetting("Glass", Value)
                end,
            })
            Effects:AddToggle("CorvusAurora", {
                Text = "Shining border",
                Description = "Light that orbits the window",
                Default = WindowAurora == nil or WindowAurora.Enabled,
                Callback = function(Value)
                    Window:SetAurora(Value)
                    Library:SetSetting("Aurora", Value)
                end,
            })
            Effects:AddToggle("CorvusComets", {
                Text = "Nova transitions",
                Description = "The hub collapses into a star and back",
                Default = Library.CometTransitions ~= false,
                Callback = function(Value)
                    Library.CometTransitions = Value
                    Library:SetSetting("Comets", Value)
                end,
            })
            Effects:AddToggle("CorvusCursorLight", {
                Text = "Cursor light",
                Description = "Soft glow that follows your mouse",
                Default = Library.CursorLight ~= false,
                Callback = function(Value)
                    Library.CursorLight = Value
                    Library:SetSetting("CursorLight", Value)
                end,
            })
            Effects:AddToggle("CorvusStardust", {
                Text = "Stardust clicks",
                Description = "Tiny stars burst where you click",
                Default = Library.Stardust ~= false,
                Callback = function(Value)
                    Library.Stardust = Value
                    Library:SetSetting("Stardust", Value)
                end,
            })
            Effects:AddToggle("CorvusAnimations", {
                Text = "Motion",
                Description = "Hover, press and icon animations",
                Default = Library.IconAnimations ~= false,
                Callback = function(Value)
                    Library.IconAnimations = Value
                    Library:SetSetting("Animations", Value)
                    if WindowStarfield then
                        WindowStarfield:Refresh()
                    end
                    if WindowAurora then
                        WindowAurora:Refresh(Library.Toggled)
                    end
                end,
            })
    
            local General = Tab:AddRightGroupbox("General", "sliders-horizontal")
            local KeybindLabel = General:AddLabel("Menu keybind")
            KeybindLabel:AddKeyPicker("MenuKeybind", {
                Default = Library:GetSetting("MenuKeybind", Info.MenuKeybind or "RightShift"),
                NoUI = true,
                Text = "Menu keybind",
            })
            Library.ToggleKeybind = Library.Options.MenuKeybind
            Library.Options.MenuKeybind:OnChanged(function()
                local Key = Library.Options.MenuKeybind.Value
                if typeof(Key) == "string" and Key ~= "Unknown" and Key ~= "None" then
                    Library:SetSetting("MenuKeybind", Key)
                end
            end)
            if Library.IsMobile then
                pcall(KeybindLabel.SetVisible, KeybindLabel, false)
                task.defer(function()
                    for _, Id in { "CorvusKeybindList", "CorvusCustomCursor" } do
                        local Element = Library.Toggles[Id]
                        if Element and Element.SetVisible then
                            pcall(Element.SetVisible, Element, false)
                        end
                    end
                end)
            end
            General:AddDropdown("CorvusNotifySide", {
                Text = "Notifications",
                Values = { "Right", "Left" },
                Default = if string.lower(tostring(Library.NotifySide)) == "left" then "Left" else "Right",
                Callback = function(Value)
                    Library:SetNotifySide(Value)
                end,
            })
            General:AddToggle("CorvusHideOnStart", {
                Text = "Start hidden",
                Description = if Library.IsMobile then "Load silently, open with the Corvus button" else "Load silently, open with the keybind",
                Default = Library:GetSetting("HideOnStart", false) == true,
                Callback = function(Value)
                    Library:SetSetting("HideOnStart", Value)
                end,
            })
            General:AddToggle("CorvusStatsHUD", {
                Text = "Performance overlay",
                Description = "FPS and ping in the corner",
                Default = Library.StatsHUDEnabled == true or Library:GetSetting("StatsHUD", false) == true,
                Callback = function(Value)
                    Library:SetStatsHUD(Value)
                    Library:SetSetting("StatsHUD", Value)
                end,
            })
            General:AddToggle("CorvusKeybindList", {
                Text = "Keybind list",
                Description = "Floating list of active keybinds",
                Default = Library.KeybindFrame ~= nil and Library.KeybindFrame.Visible,
                Callback = function(Value)
                    if Library.KeybindFrame then
                        Library.KeybindFrame.Visible = Value
                    end
                end,
            })
            General:AddToggle("CorvusCustomCursor", {
                Text = "Custom cursor",
                Description = "Use the hub cursor while it is open",
                Default = Library.ShowCustomCursor == true,
                Callback = function(Value)
                    Library.ShowCustomCursor = Value
                end,
            })
    
            General:AddToggle("CorvusBlockRobux", {
                Text = "Block Robux Prompts",
                Description = "Hides every Robux purchase pop-up while the hub runs",
                Default = Library.BlockRobuxPrompts ~= false,
                Callback = function(Value)
                    Library:SetBlockRobuxPrompts(Value)
                end,
            })

            local DiagBox = Tab:AddRightGroupbox("Diagnostics", "activity")
            DiagBox:AddToggle("CorvusDiagnostics", {
            	Text = "Send anonymous diagnostics",
            	Description = "Helps fix bugs. Sends only the hub's own status lines, no nickname or account data.",
            	Default = Library:GetSetting("Diagnostics", true) ~= false,
            	Callback = function(Value)
            		if Library.SetDiagnostics then
            			Library:SetDiagnostics(Value)
            		else
            			Library:SetSetting("Diagnostics", Value)
            		end
            	end,
            })
            Library.DiagnosticsLabel = DiagBox:AddLabel({ Text = Library.DiagnosticsStatus or "On", DoesWrap = true })

