                local function ConfigNotify(Title: string, Text: string?)
                    Library:Notify({ Title = Title, Description = Text, Time = 3 })
                end
    
                local function RefreshConfigs(Select: string?)
                    local Names = {}
                    pcall(function()
                        Names = SaveManager:RefreshConfigList()
