                })
                Configs:AddButton({
                    Text = "Save config",
                    Func = function()
                        local Name = Library.Options.CorvusConfigName.Value
                        if typeof(Name) ~= "string" or string.match(Name, "^%s*$") then
                            Name = ConfigList.Value
                        end
                        if typeof(Name) ~= "string" or Name == "" then
                            ConfigNotify("Configs", "Type a name first")
                            return
                        end
                        local Success, Error = SaveManager:Save(Name)
                        if Success then
                            ConfigNotify("Config saved", Name)
                            RefreshConfigs(Name)
                        else
                            ConfigNotify("Config not saved", tostring(Error))
                        end
                    end,
                })
    
                ConfigList = Configs:AddDropdown("CorvusConfigList", {
