                            ConfigNotify("Configs", "Pick a config first")
                            return
                        end
                        local Success, Error = SaveManager:Save(Name)
                        ConfigNotify(if Success then "Config overwritten" else "Config not saved", if Success then Name else tostring(Error))
                    end,
                }):AddButton({
                    Text = "Refresh",
                    Func = function()
                        RefreshConfigs(ConfigList.Value)
                    end,
                })
    
                Configs:AddButton({
                    Text = "Load",
                    Func = function()
                        local Name = ConfigList.Value
                        if typeof(Name) ~= "string" then
                            ConfigNotify("Configs", "Pick a config first")
                            return
                        end
                        local Success, Error = SaveManager:Load(Name)
                        ConfigNotify(if Success then "Config loaded" else "Config not loaded", if Success then Name else tostring(Error))
                    end,
                }):AddButton({
                    Text = "Delete",
                    DoubleClick = true,
                    Func = function()
                        local Name = ConfigList.Value
                        if typeof(Name) ~= "string" then
                            return
