                        local Success, Error = SaveManager:Delete(Name)
                        ConfigNotify(if Success then "Config deleted" else "Config not deleted", if Success then Name else tostring(Error))
                        RefreshConfigs()
                    end,
                })
    
                Configs:AddButton({
                    Text = "Autoload this",
                    Func = function()
                        local Name = ConfigList.Value
                        if typeof(Name) ~= "string" then
                            ConfigNotify("Configs", "Pick a config first")
                            return
                        end
                        local Success, Error = SaveManager:SaveAutoloadConfig(Name)
                        ConfigNotify(if Success then "Autoload set" else "Autoload not set", if Success then Name else tostring(Error))
                        RefreshConfigs(Name)
                    end,
                }):AddButton({
                    Text = "Clear autoload",
                    Func = function()
                        pcall(SaveManager.DeleteAutoLoadConfig, SaveManager)
                        ConfigNotify("Autoload cleared")
                        RefreshConfigs()
                    end,
                })
    
                AutoloadLabel = Configs:AddLabel('<font transparency="0.5">Autoload</font>   none')
                RefreshConfigs()
    
                local AutoSaveFile = tostring(SaveManager.Folder or Folder) .. "/corvus_autosave.txt"
                local AutoSaveOn = true
                pcall(function()
                    if isfile(AutoSaveFile) then
                        AutoSaveOn = readfile(AutoSaveFile) ~= "off"
                    end
                end)
                local function AutoSaveNow()
                    if not AutoSaveOn then
                        return
                    end
                    local Target = "none"
                    pcall(function()
                        Target = SaveManager:GetAutoloadConfig()
                    end)
                    if Library.ConfigLoadFailed and Target == Library.ConfigLoadFailed then
                        -- the autoload config did not load this session: never overwrite the player's file with defaults
                        if not Library.ConfigAutoSavePaused then
                            Library.ConfigAutoSavePaused = true
                            Library:CorvusLog("CONFIG auto save paused, " .. tostring(Target) .. " did not load and is kept as it is")
                        end
                        return
                    end
                    if typeof(Target) ~= "string" or Target == "" or Target == "none" then
                        Target = "Auto Save"
                        pcall(SaveManager.SaveAutoloadConfig, SaveManager, Target)
                        pcall(RefreshConfigs, ConfigList.Value)
                    end
                    pcall(SaveManager.Save, SaveManager, Target)
                end
                Configs:AddToggle("CorvusAutoSave", {
                    Text = "Auto save config",
                    Description = "Your settings load again next time",
                    Tooltip = "Saves your settings every 30 seconds and when the hub closes. It saves into your autoload config, or makes one called Auto Save, so the same setup loads when you come back.",
                    Default = AutoSaveOn,
                    Callback = function(Value)
                        AutoSaveOn = Value == true
                        pcall(writefile, AutoSaveFile, if AutoSaveOn then "on" else "off")
                    end,
                })
                task.spawn(function()
                    task.wait(15)
                    while not Library.Unloaded do
                        AutoSaveNow()
                        task.wait(30)
                    end
                end)
                Library:OnUnload(AutoSaveNow)
    
                Configs:AddDivider()
                Configs:AddInput("CorvusShareCode", {
                    Text = "Share code",
                    Placeholder = "Paste a code from a friend",
                    Default = "",
                })
                Configs:AddButton({
                    Text = "Copy my code",
                    Tooltip = "Makes a short code with everything you changed. Webhook links and other private text are never included.",
                    Func = function()
                        local Code, Count = Library:ExportShareCode(SaveManager.Ignore)
                        if not Code then
                            ConfigNotify("Share code", tostring(Count))
                            return
                        end
                        local Copied = typeof(setclipboard) == "function" and pcall(setclipboard, Code)
                        pcall(Library.Options.CorvusShareCode.SetValue, Library.Options.CorvusShareCode, Code)
                        ConfigNotify(if Copied then "Code copied" else "Code ready", string.format("%d changed settings%s", Count, if Copied then ", paste it anywhere" else ", copy it from the box"))
                    end,
                }):AddButton({
                    Text = "Apply code",
                    DoubleClick = true,
                    Tooltip = "Loads the pasted code. Settings not in the code go back to their defaults.",
                    Func = function()
                        local Ok, Result = Library:ImportShareCode(Library.Options.CorvusShareCode.Value, SaveManager.Ignore)
                        ConfigNotify(if Ok then "Code applied" else "Code not applied", if Ok then string.format("%d settings loaded", Result) else tostring(Result))
                    end,
                })
    
                if Info.AutoLoad ~= false then
                    task.defer(function()
                        pcall(SaveManager.LoadAutoloadConfig, SaveManager)
                        Library:FireAutoload()
                    end)
                end
            end
    
            if not Library.IsMobile then
                local Binds = Tab:AddRightGroupbox("Quick Binds", "keyboard")
                Binds:AddLabel({ Text = '<font transparency="0.45">Right click any toggle or button, then press a key. Backspace removes it. In the console: bind B black runs any command with one key.</font>', DoesWrap = true })
                local BindList = Binds:AddLabel({ Text = "", DoesWrap = true })
                local function RefreshBinds()
                    local Lines = {}
                    for KeyName, Entry in Library:GetQuickBinds() do
                        if typeof(Entry) == "table" then
                            table.insert(Lines, string.format('<b>%s</b>  <font transparency="0.45">%s</font>', KeyName, tostring(Entry.Label or Entry.Target)))
                        end
                    end
                    table.sort(Lines)
                    BindList:SetText(if #Lines > 0 then table.concat(Lines, "\n") else '<font transparency="0.45">No binds yet</font>')
                end
                Library.QuickBindSignals = Library.QuickBindSignals or {}
                table.insert(Library.QuickBindSignals, RefreshBinds)
                RefreshBinds()
                Binds:AddButton({
                    Text = "Clear all binds",
                    DoubleClick = true,
                    Func = function()
                        for KeyName in Library:GetQuickBinds() do
                            Library:SetQuickBind(KeyName, nil)
                        end
                        RefreshBinds()
                    end,
                })
            end
    
            local Hub = Tab:AddRightGroupbox("Hub", "power")
            Hub:AddButton({
                Text = "Unload hub",
                DoubleClick = true,
                Risky = true,
                Func = function()
                    Library:Unload()
                end,
            })
    
            return Tab
        end
    
        do
            local Console = {
                Open = false,
                Built = false,
                History = {},
                HistoryIndex = 0,
                Filtered = {},
                Rows = {},
                Suggestion = nil,
            }
            Window.Console = Console
    
            local Panel, Input, Ghost, InputStroke, ListFrame, OutputFrame, StatusLabel, CountLabel, LoadButton, EmptyLabel
            local RowHeight, PoolSize = 40, 18
            local MonoFont = Font.fromEnum(Enum.Font.RobotoMono)
            local KindColors = {
                system = function()
                    return Library.Scheme.AccentColor
                end,
                input = function()
                    return Library.Scheme.FontColor
                end,
                success = function()
                    return Color3.fromRGB(96, 214, 150)
                end,
                error = function()
                    return Library.Scheme.RedColor
                end,
                iy = function()
                    return GetSecondaryAccent()
                end,
            }
    
            local function EscapeRich(Text: string): string
                return (tostring(Text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
            end
    
            local function CommandMatches(Command, Word: string): number?
                if Word == "" then
                    return 1
                end
    
                local Best = nil
                for Index, Name in { Command.Name, table.unpack(Command.Aliases) } do
                    local Score = nil
                    if Name == Word then
                        Score = 300
                    elseif string.sub(Name, 1, #Word) == Word then
                        Score = 220 - #Name
                    elseif string.find(Name, Word, 1, true) then
                        Score = 120 - #Name
                    end
                    if Score and Index > 1 then
                        Score -= 5
                    end
                    if Score and (not Best or Score > Best) then
                        Best = Score
                    end
                end
    
                if not Best and #Word >= 3 and string.find(string.lower(Command.Description), Word, 1, true) then
                    Best = 20
                end
                return Best
            end
    
            local function FilterCommands(Query: string)
                local Word = string.lower(string.match(Query, "^%s*(%S*)") or "")
                local Scored = {}
                for Order, Command in Library:GetCommands() do
                    local Score = if Command.Source == "Pack" then CommandMatches(Command, Word) else nil
                    if Score then
                        table.insert(Scored, { Command = Command, Score = Score, Order = Order })
                    end
                end
                if Word ~= "" then
                    table.sort(Scored, function(A, B)
                        if A.Score == B.Score then
                            return A.Order < B.Order
                        end
                        return A.Score > B.Score
                    end)
                end
    
                local Result = {}
                for _, Item in Scored do
                    table.insert(Result, Item.Command)
                end
                return Result, Word
            end
            Console.FilterCommands = FilterCommands
    
            local function PaintStatus()
                if not Console.Built then
                    return
                end
    
                if InfiniteYield.Loaded then
                    StatusLabel.Text = string.format("%d commands", #InfiniteYield.Commands)
                    LoadButton.Visible = false
                elseif InfiniteYield.Loading then
                    StatusLabel.Text = "Loading commands\u{2026}"
                    LoadButton.Visible = false
                else
                    StatusLabel.Text = "Commands not loaded"
                    LoadButton.Visible = true
                end
            end
    
            local function RenderRows()
                if not Console.Built then
                    return
                end
    
                local Scale = math.max(Library.DPIScale, 0.01)
                local First = math.max(0, math.floor(ListFrame.CanvasPosition.Y / Scale / RowHeight) - 1)
                for Index, Row in Console.Rows do
                    local DataIndex = First + Index
                    local Command = Console.Filtered[DataIndex]
                    Row.Button.Visible = Command ~= nil
                    Row.Command = Command
    
                    if Command then
                        Row.Button.Position = UDim2.fromOffset(4, (DataIndex - 1) * RowHeight + 4)
    
                        local Accent = Library.Scheme.AccentColor:ToHex()
                        local Head = string.format('<font color="#%s">%s</font>', Accent, EscapeRich(Command.Name))
                        if Command.Args ~= "" then
                            Head ..= string.format(' <font transparency="0.45">%s</font>', EscapeRich(Command.Args))
                        end
                        if #Command.Aliases > 0 then
                            Head ..= string.format('  <font transparency="0.6">%s</font>', EscapeRich(table.concat(Command.Aliases, ", ")))
                        end
                        Row.Head.Text = Head
                        Row.Desc.Text = if Command.Description ~= "" then EscapeRich(Command.Description) else "No description"
                        Row.Source.Text = ""
                    end
                end
            end
    
            local function RefreshList()
                if not Console.Built then
                    return
                end
    
                local Filtered = FilterCommands(Input.Text)
                Console.Filtered = Filtered
                ListFrame.CanvasSize = UDim2.fromOffset(0, #Filtered * RowHeight + 8)
                CountLabel.Text = string.format("%d", #Filtered)
                EmptyLabel.Visible = #Filtered == 0
                RenderRows()
                PaintStatus()
            end
    
            local function UpdateGhost()
                if not Console.Built then
                    return
                end
    
                local Text = Input.Text
                Console.Suggestion = nil
                Ghost.Text = ""
    
                if Text == "" or string.find(Text, "%s") then
                    return
                end
    
                local Word = string.lower(Text)
                for _, Command in Console.Filtered do
                    for _, Name in { Command.Name, table.unpack(Command.Aliases) } do
                        if string.sub(Name, 1, #Word) == Word and #Name > #Word then
                            Console.Suggestion = Name
                            Ghost.Text = Text .. string.sub(Name, #Word + 1)
                            return
                        end
                    end
                end
            end
    
            local function AddLine(Entry)
                if not Console.Built then
                    return
                end
                Console.NextLine = (Console.NextLine or 0) + 1
    
                if Entry == nil then
                    for _, Child in OutputFrame:GetChildren() do
                        if Child:IsA("TextLabel") then
                            Child:Destroy()
                        end
                    end
                    return
                end
    
                local Body = EscapeRich(Entry.Text)
                if Entry.Kind == "input" then
                    Body = string.format('<font color="#%s">\u{203A}</font> %s', Library.Scheme.AccentColor:ToHex(), Body)
                elseif KindColors[Entry.Kind] then
                    Body = string.format('<font color="#%s">%s</font>', KindColors[Entry.Kind]():ToHex(), Body)
                else
                    Body = string.format('<font transparency="0.2">%s</font>', Body)
                end
    
                New("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    FontFace = MonoFont,
                    LayoutOrder = Console.NextLine,
                    Size = UDim2.new(1, 0, 0, 14),
                    Text = string.format('<font transparency="0.6">%s</font>  %s', Entry.Time, Body),
                    TextSize = 12,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = Panel.ZIndex + 3,
                    Parent = OutputFrame,
                })
    
                local Labels = {}
                for _, Child in OutputFrame:GetChildren() do
                    if Child:IsA("TextLabel") then
                        table.insert(Labels, Child)
                    end
                end
                for Index = 1, #Labels - 150 do
                    Labels[Index]:Destroy()
                end
    
                task.defer(function()
                    if OutputFrame then
                        local Window = OutputFrame.AbsoluteWindowSize or OutputFrame.AbsoluteSize
                        OutputFrame.CanvasPosition = Vector2.new(0, math.max(0, OutputFrame.AbsoluteCanvasSize.Y - Window.Y))
                    end
                end)
            end
    
            local function HeaderButton(Parent: Instance, Text: string, IconName: string?, Order: number)
                local Button = New("TextButton", {
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundColor3 = "MainColor",
                    LayoutOrder = Order,
                    Size = UDim2.fromOffset(0, 24),
                    Text = "",
                    ZIndex = Parent.ZIndex + 1,
                    Parent = Parent,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 6),
                    Parent = Button,
                })
                local Stroke = New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = Button,
                })
                Library:AddHoverStroke(Button, Stroke)
                New("UIPadding", {
                    PaddingLeft = UDim.new(0, if Text ~= "" then 8 else 5),
                    PaddingRight = UDim.new(0, if Text ~= "" then 9 else 5),
                    Parent = Button,
                })
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Padding = UDim.new(0, 5),
                    Parent = Button,
                })
    
                if IconName then
                    local Icon = New("ImageLabel", {
                        ImageColor3 = "FontColor",
                        ImageTransparency = 0.25,
                        LayoutOrder = 1,
                        Size = UDim2.fromOffset(14, 14),
                        ZIndex = Button.ZIndex + 1,
                        Parent = Button,
                    })
                    local IconData = Library:GetIcon(IconName)
                    if IconData then
                        Library:ApplyLucideIcon(Icon, IconData)
                    end
                    Library:AddIconHover(Button, Icon, { Scale = 1.15, Transparency = 0, RestTransparency = 0.25 })
                end
    
                if Text ~= "" then
                    New("TextLabel", {
                        AutomaticSize = Enum.AutomaticSize.X,
                        BackgroundTransparency = 1,
                        FontFace = GetMediumFont,
                        LayoutOrder = 2,
                        Size = UDim2.fromOffset(0, 24),
                        Text = Text,
                        TextSize = 12,
                        ZIndex = Button.ZIndex + 1,
                        Parent = Button,
                    })
                end
    
                return Button
            end
    
            local function Build(Host: GuiObject)
                if Console.Built then
                    return
                end
                Console.Built = true
    
                Panel = New("Frame", {
                    BackgroundTransparency = 1,
                    Name = "CorvusConsole",
