                    ZIndex = 40,
                    Parent = Host,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 8),
                    PaddingLeft = UDim.new(0, 2),
                    PaddingRight = UDim.new(0, 2),
                    PaddingTop = UDim.new(0, 8),
                    Parent = Panel,
                })
    
                local Header = New("Frame", {
                    BackgroundTransparency = 1,
                    Size = UDim2.new(1, 0, 0, 26),
                    ZIndex = 41,
                    Parent = Panel,
                })
                local HeaderIcon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    ImageColor3 = "AccentColor",
                    Position = UDim2.new(0, 0, 0.5, 0),
                    Size = UDim2.fromOffset(18, 18),
                    ZIndex = 42,
                    Parent = Header,
                })
                local TerminalIcon = Library:GetIcon("square-terminal")
                if TerminalIcon then
                    Library:ApplyLucideIcon(HeaderIcon, TerminalIcon)
                end
                New("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    FontFace = GetBoldFont,
                    Position = UDim2.fromOffset(26, 0),
                    Size = UDim2.fromOffset(0, 26),
                    Text = "Console",
                    TextSize = 16,
                    ZIndex = 42,
                    Parent = Header,
                })
                StatusLabel = New("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(94, 0),
                    Size = UDim2.new(1, -330, 0, 26),
                    Text = "",
                    TextSize = 12,
                    TextTransparency = 0.45,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 42,
                    Parent = Header,
                })
    
                local Actions = New("Frame", {
                    AnchorPoint = Vector2.new(1, 0),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(1, 0),
                    Size = UDim2.new(0, 320, 1, 0),
                    ZIndex = 42,
                    Parent = Header,
                })
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalAlignment = Enum.HorizontalAlignment.Right,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Padding = UDim.new(0, 6),
                    Parent = Actions,
                })
    
                LoadButton = HeaderButton(Actions, "Load commands", "zap", 1)
                local SpyButton = HeaderButton(Actions, "Remote Spy", "radar", 2)
                local ClearButton = HeaderButton(Actions, "", "trash-2", 3)
    
                local InputHolder = New("Frame", {
                    BackgroundColor3 = "MainColor",
                    Position = UDim2.fromOffset(0, 34),
                    Size = UDim2.new(1, 0, 0, 34),
                    ZIndex = 41,
                    Parent = Panel,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 7),
                    Parent = InputHolder,
                })
                InputStroke = New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = InputHolder,
                })
                New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = MonoFont,
                    Position = UDim2.fromOffset(10, 0),
                    Size = UDim2.fromOffset(14, 34),
                    Text = "\u{203A}",
                    TextColor3 = "AccentColor",
                    TextSize = 18,
                    ZIndex = 42,
                    Parent = InputHolder,
                })
                Ghost = New("TextLabel", {
                    BackgroundTransparency = 1,
                    FontFace = MonoFont,
                    Position = UDim2.fromOffset(30, 0),
                    Size = UDim2.new(1, -40, 1, 0),
                    Text = "",
                    TextSize = 14,
                    TextTransparency = 0.65,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    ZIndex = 42,
                    Parent = InputHolder,
