            local function EscapeRich(Text: string): string
                return (tostring(Text):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
            end
    
            local function PillButton(Parent: Instance, Text: string, IconName: string?, Order: number, Accent: boolean?)
                local Button = New("TextButton", {
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundColor3 = if Accent then "AccentColor" else "MainColor",
                    LayoutOrder = Order,
                    Size = UDim2.fromOffset(0, 24),
                    Text = "",
                    ZIndex = Parent.ZIndex + 1,
                    Parent = Parent,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 6),
                    Parent = Button,
                })
                local Stroke = New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = Button,
                })
                Library:AddHoverStroke(Button, Stroke)
                New("UIPadding", {
                    PaddingLeft = UDim.new(0, if Text ~= "" then 8 else 5),
                    PaddingRight = UDim.new(0, if Text ~= "" then 9 else 5),
                    Parent = Button,
                })
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Padding = UDim.new(0, 5),
                    Parent = Button,
                })
    
                local Icon
                if IconName then
                    Icon = New("ImageLabel", {
                        ImageColor3 = if Accent then "BackgroundColor" else "FontColor",
                        ImageTransparency = if Accent then 0 else 0.25,
                        LayoutOrder = 1,
                        Size = UDim2.fromOffset(14, 14),
                        ZIndex = Button.ZIndex + 1,
                        Parent = Button,
                    })
                    local IconData = Library:GetIcon(IconName)
                    if IconData then
                        Library:ApplyLucideIcon(Icon, IconData)
                    end
                end
    
                local Label
                if Text ~= "" then
                    Label = New("TextLabel", {
                        AutomaticSize = Enum.AutomaticSize.X,
                        BackgroundTransparency = 1,
                        FontFace = GetMediumFont,
                        LayoutOrder = 2,
                        Size = UDim2.fromOffset(0, 24),
                        Text = Text,
                        TextColor3 = if Accent then "BackgroundColor" else "FontColor",
                        TextSize = 12,
                        ZIndex = Button.ZIndex + 1,
                        Parent = Button,
                    })
                end
    
                return Button, Label, Icon
            end
    
