                })
                for Order, Data in { { "LogOutgoing", "Outgoing", "arrow-up-right" }, { "LogIncoming", "Incoming", "arrow-down-left" }, { "LogExecutor", "Executor", "code" } } do
                    local Button, Label = PillButton(ChipHolder, Data[2], nil, Order)
                    Chips[Data[1]] = { Button = Button, Label = Label }
                    Button.MouseButton1Click:Connect(function()
                        if Data[1] == "LogIncoming" then
                            RemoteSpy:SetIncoming(not RemoteSpy.LogIncoming)
