                            Spy.SelectedCall = Row.Index
                            Spy.CodeMode = "Code"
                            RenderCalls()
                        end
                    end)
                end
    
                local CodeBox = New("Frame", {
                    AnchorPoint = Vector2.new(0, 1),
                    BackgroundColor3 = "BackgroundColor",
                    Position = UDim2.new(0, 6, 1, -6),
