                    ZIndex = 42,
                    Parent = CallBox,
                })
                New("UICorner", {
                    CornerRadius = UDim.new(0, 6),
                    Parent = CodeBox,
                })
                New("UIStroke", {
                    Color = "OutlineColor",
                    Parent = CodeBox,
                })
                CodeFrame = New("ScrollingFrame", {
                    AutomaticCanvasSize = Enum.AutomaticSize.XY,
                    BackgroundTransparency = 1,
                    CanvasSize = UDim2.fromOffset(0, 0),
                    ScrollBarImageColor3 = "AccentColor",
                    ScrollBarImageTransparency = 0.4,
                    ScrollBarThickness = 2,
                    Size = UDim2.fromScale(1, 1),
                    ZIndex = 43,
                    Parent = CodeBox,
                })
                New("UIPadding", {
                    PaddingBottom = UDim.new(0, 8),
                    PaddingLeft = UDim.new(0, 9),
                    PaddingRight = UDim.new(0, 9),
                    PaddingTop = UDim.new(0, 8),
                    Parent = CodeFrame,
                })
                CodeLabel = New("TextLabel", {
                    AutomaticSize = Enum.AutomaticSize.XY,
                    BackgroundTransparency = 1,
                    FontFace = MonoFont,
                    Size = UDim2.fromOffset(0, 0),
                    Text = "",
                    TextSize = 12,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Top,
                    ZIndex = 44,
                    Parent = CodeFrame,
                })
    
                RemoteList:GetPropertyChangedSignal("CanvasPosition"):Connect(RenderRemotes)
                CallList:GetPropertyChangedSignal("CanvasPosition"):Connect(RenderCalls)
    
                StartButton.MouseButton1Click:Connect(function()
                    if RemoteSpy.Enabled then
                        RemoteSpy:Stop()
                        Library:ConsoleLog("Remote spy stopped.", "system")
                    else
                        local Success, Error = RemoteSpy:Start()
                        if not Success then
                            Library:Notify({
                                Title = "Remote Spy",
                                Description = tostring(Error),
                                Time = 5,
                            })
                        else
                            Library:ConsoleLog("Remote spy started.", "system")
                        end
                    end
                    Render()
                end)
                PauseButton.MouseButton1Click:Connect(function()
                    RemoteSpy:SetPaused(not RemoteSpy.Paused)
                    Render()
                end)
                ClearButton.MouseButton1Click:Connect(function()
                    Spy.Selected = nil
                    RemoteSpy:Clear()
                    Render()
                end)
                CopyButton.MouseButton1Click:Connect(function()
                    local Record = Spy.Selected
                    local Call = Record and Record.Calls[Spy.SelectedCall]
                    if Call then
                        Library:CopyToClipboard(if Spy.CodeMode == "Decompiled" and Spy.DecompiledFor == Call then Spy.DecompiledText else RemoteSpy.GetCode(Record, Call), "Code copied")
                    end
                end)
                RepeatButton.MouseButton1Click:Connect(function()
                    local Record = Spy.Selected
                    local Call = Record and Record.Calls[Spy.SelectedCall]
                    if not Call then
                        return
                    end
                    local Success, Error = RemoteSpy:Repeat(Record, Call)
                    Library:Notify({
                        Title = "Remote Spy",
                        Description = if Success then "Sent " .. Record.Name .. " again" else tostring(Error),
                        Time = 3,
                    })
                end)
                DecompileButton.MouseButton1Click:Connect(function()
                    local Record = Spy.Selected
                    local Call = Record and Record.Calls[Spy.SelectedCall]
                    if not Call then
                        return
                    end
                    if Spy.CodeMode == "Decompiled" and Spy.DecompiledFor == Call then
                        Spy.CodeMode = "Code"
                        RenderCode()
                        return
                    end
    
                    CodeLabel.Text = "Decompiling\u{2026}"
                    task.spawn(function()
                        local Success, Result = RemoteSpy:Decompile(Call)
                        if not Success then
                            Library:Notify({ Title = "Remote Spy", Description = Result, Time = 4 })
                            RenderCode()
                            return
                        end
                        Spy.CodeMode = "Decompiled"
                        Spy.DecompiledFor = Call
                        Spy.DecompiledText = Result
                        Library:CopyToClipboard(Result, "Decompiled script copied")
                        RenderCode()
                    end)
                end)
                PathButton.MouseButton1Click:Connect(function()
                    if Spy.Selected then
                        Library:CopyToClipboard(Spy.Selected.Path, "Path copied")
                    end
                end)
                IgnoreButton.MouseButton1Click:Connect(function()
                    if Spy.Selected then
                        Spy.Selected.Ignored = not Spy.Selected.Ignored
                        Render()
                    end
                end)
                BlockButton.MouseButton1Click:Connect(function()
                    if Spy.Selected then
                        Spy.Selected.Blocked = not Spy.Selected.Blocked
                        Render()
                    end
                end)
    
                RemoteSpy:OnChanged(function()
                    Spy.Dirty = true
                    if Spy.Tab and Library.ActiveTab == Spy.Tab and Library.Toggled then
                        Render()
                    end
                end)
    
                Render()
            end
    
            function Window:AddRemoteSpyTab(Info)
                if Spy.Tab then
                    return Spy.Tab
                end
                Info = Info or {}
    
                local Tab = Window:AddTab({
                    Name = Info.Name or "Remote Spy",
                    Icon = Info.Icon or "radar",
                    Description = Info.Description or "Watch remote calls live",
                })
                for _, Side in Tab.Sides do
                    Side.Visible = false
                end
    
                Spy.Tab = Tab
                Window.RemoteSpyTab = Tab
                BuildSpy(Tab.Container)
    
                local OriginalShow = Tab.Show
                function Tab:Show(...)
                    OriginalShow(Tab, ...)
                    if Spy.Dirty then
                        Render()
                    end
                end
    
                if Info.AutoStart == true then
                    RemoteSpy:Start()
                    Render()
                end
    
                return Tab
            end
    
            Library:AddCommand({
                Name = "spy",
                Aliases = { "remotes", "rspy", "remotespy" },
                Description = "Opens the Corvus remote spy tab",
                Callback = function()
                    if not Window.RemoteSpyTab then
                        Window:AddRemoteSpyTab()
                    end
                    Window.RemoteSpyTab:Show()
                end,
            })
        end
    
        Window:SetAlwaysOnTop(WindowInfo.AlwaysOnTop)
        if WindowInfo.EnableCompacting and WindowInfo.SidebarCompacted then
            Window:SetSidebarWidth(WindowInfo.SidebarCompactWidth)
        end
        if WindowInfo.AutoShow and not Library.ActiveLoading then
            if Library:GetSetting("HideOnStart", false) == true then
                task.delay(0.8, function()
                    if Library.Unloaded or Library.Toggled then
                        return
                    end
    
                    local Bind = Library.ToggleKeybind
                    local KeyName = "your menu key"
                    if typeof(Bind) == "table" and Bind.Value ~= nil then
                        KeyName = tostring(Bind.Value)
                    elseif typeof(Bind) == "EnumItem" then
                        KeyName = Bind.Name
                    end
    
                    Library:Notify({
                        Title = WindowInfo.Title,
                        Description = if Library.IsMobile then "Loaded in the background. Tap the Corvus button to open." else string.format("Loaded in the background. Press %s to open.", KeyName),
                        Time = 6,
                    })
                end)
            elseif WindowInfo.Intro ~= false then
                task.spawn(function()
                    local Success = pcall(Window.PlayIntro)
                    if Success then
                        return
                    end
                    Library.IntroPlaying = false
                    for _, Name in { "CorvusIntro", "CorvusLoadingShade" } do
                        local Leftover = ScreenGui:FindFirstChild(Name)
                        if Leftover then
                            Leftover:Destroy()
                        end
                    end
                    pcall(function()
                        local Leftover = game:GetService("Lighting"):FindFirstChild("CorvusLoadingBlur")
                        if Leftover then
                            Leftover:Destroy()
                        end
                    end)
                    if not Library.Unloaded and not Library.Toggled then
                        Library:Toggle(true)
                    end
                end)
            else
                task.spawn(Library.Toggle)
            end
        end
    
        if Library.IsMobile then
            local ToggleButton = Library:AddDraggableButton("Toggle", function()
                Library:Toggle()
            end, true, true)
    
            local LockButton = Library:AddDraggableButton("Lock", function(self)
                Library.CantDragForced = not Library.CantDragForced
                if self.SetLocked then
                    self:SetLocked(Library.CantDragForced)
                end
            end, true, true)
    
            local OrbSizes = { Small = 42, Normal = 50, Large = 60 }
            local Diameter = OrbSizes[Library:GetSetting("MobileButtonSize", "Normal")] or 50
    
            local function MakeOrb(Draggable, Size, IconName)
                local Button = Draggable.Button
                Button.Text = ""
                Button.AutoButtonColor = false
                Button.Size = UDim2.fromOffset(Size, Size)
                Button.ZIndex = 50
                for _, Child in Button:GetChildren() do
                    if Child:IsA("UICorner") then
                        local Index = table.find(Library.Corners, Child)
                        if Index then
                            table.remove(Library.Corners, Index)
                        end
                        Child.CornerRadius = UDim.new(1, 0)
                    end
                end
                Draggable.Ring = New("UIStroke", {
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                    Color = "AccentColor",
                    Thickness = 1.6,
                    Transparency = 0.3,
                    Parent = Button,
                })
                Draggable.Icon = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 1,
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromScale(0.6, 0.6),
                    ZIndex = 51,
                    Parent = Button,
                })
                local Data = Library:GetCustomIcon(IconName)
                if Data then
                    Library:ApplyLucideIcon(Draggable.Icon, Data)
                    if Data.IconName then
                        Library:SetSchemeProperty(Draggable.Icon, "ImageColor3", "FontColor")
                    end
                end
                function Draggable:SetText() end
            end
    
            MakeOrb(ToggleButton, Diameter, WindowInfo.Icon or "corvus")
            MakeOrb(LockButton, math.floor(Diameter * 0.72), "lock-open")
    
            function LockButton:SetLocked(Locked)
                local Data = Library:GetCustomIcon(if Locked then "lock" else "lock-open")
                if Data and LockButton.Icon then
                    Library:ApplyLucideIcon(LockButton.Icon, Data)
                end
                if LockButton.Ring then
                    LockButton.Ring.Transparency = if Locked then 0 else 0.3
                end
            end
    
            local function PlaceDefault()
                local Right = WindowInfo.MobileButtonsSide == "Right"
                local Size = ToggleButton.Button.Size.X.Offset
                local Small = LockButton.Button.Size.X.Offset
                ToggleButton.Button.AnchorPoint = Vector2.new(if Right then 1 else 0, 0)
                LockButton.Button.AnchorPoint = Vector2.new(if Right then 1 else 0, 0)
                ToggleButton.Button.Position = UDim2.new(if Right then 1 else 0, if Right then -10 else 10, 0.28, 0)
                local Shift = math.floor((Size - Small) / 2)
                LockButton.Button.Position = UDim2.new(if Right then 1 else 0, if Right then -10 - Shift else 10 + Shift, 0.28, Size + 8)
            end
    
            local SavedSpot = Library:GetSetting("MobileButtons", nil)
            if typeof(SavedSpot) == "table" and tonumber(SavedSpot[1]) and tonumber(SavedSpot[2]) then
                ToggleButton.Button.AnchorPoint = Vector2.zero
                ToggleButton.Button.Position = UDim2.fromOffset(tonumber(SavedSpot[1]), tonumber(SavedSpot[2]))
                if tonumber(SavedSpot[3]) and tonumber(SavedSpot[4]) then
                    LockButton.Button.AnchorPoint = Vector2.zero
                    LockButton.Button.Position = UDim2.fromOffset(tonumber(SavedSpot[3]), tonumber(SavedSpot[4]))
                end
                pcall(PositionDraggable, ToggleButton.Button, ToggleButton.Button.Position)
                pcall(PositionDraggable, LockButton.Button, LockButton.Button.Position)
            else
                PlaceDefault()
            end
    
            function Library:SetMobileButtonSize(Name)
                local Size = OrbSizes[Name] or 50
                ToggleButton.Button.Size = UDim2.fromOffset(Size, Size)
                LockButton.Button.Size = UDim2.fromOffset(math.floor(Size * 0.72), math.floor(Size * 0.72))
                Library:SetSetting("MobileButtonSize", Name)
            end
    
            function Library:ResetMobileButtons()
                Library:SetSetting("MobileButtons", false)
                PlaceDefault()
            end
    
            Library.MobileButtons = { Toggle = ToggleButton, Lock = LockButton }
    
            local Dock = New("Frame", {
                BackgroundColor3 = "BackgroundColor",
                BackgroundTransparency = 0.06,
                Size = UDim2.fromOffset(0, 52),
                Visible = false,
                ZIndex = 48,
                Parent = ToggleButton.Button.Parent,
            })
            New("UICorner", {
                CornerRadius = UDim.new(0, 14),
                Parent = Dock,
            })
            New("UIStroke", {
                Color = "OutlineColor",
                Transparency = 0.1,
                Parent = Dock,
            })
            local DockButtons = {}
            Library.QuickBar = { Frame = Dock, Buttons = DockButtons }
    
            local function QuickItems()
                local Chosen = Library:GetSetting("QuickBarItems", nil)
                local List = {}
                for _, Item in Library.QuickBarItems or {} do
                    local Allowed
                    if typeof(Chosen) == "table" then
                        Allowed = table.find(Chosen, Item.Toggle) ~= nil
                    else
                        Allowed = Item.Default ~= false
                    end
                    if Allowed and Library.Toggles[Item.Toggle] and #List < 6 then
                        table.insert(List, Item)
                    end
                end
                return List
            end
    
            function Library:BuildQuickBar()
                for _, Entry in DockButtons do
                    Entry.Button:Destroy()
                end
                table.clear(DockButtons)
                local Items = QuickItems()
                for Index, Item in Items do
                    local Button = New("TextButton", {
                        BackgroundColor3 = "AccentColor",
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(4 + (Index - 1) * 48, 4),
                        Size = UDim2.fromOffset(44, 44),
                        Text = "",
                        ZIndex = 49,
                        Parent = Dock,
                    })
                    New("UICorner", {
                        CornerRadius = UDim.new(0, 11),
                        Parent = Button,
                    })
                    local Stroke = New("UIStroke", {
                        Color = "AccentColor",
                        Transparency = 1,
                        Parent = Button,
                    })
                    local Icon = New("ImageLabel", {
                        AnchorPoint = Vector2.new(0.5, 0),
                        BackgroundTransparency = 1,
                        Position = UDim2.new(0.5, 0, 0, 6),
                        Size = UDim2.fromOffset(20, 20),
                        ZIndex = 50,
                        Parent = Button,
                    })
                    local Data = Library:GetCustomIcon(Item.Icon or "circle")
                    if Data then
                        Library:ApplyLucideIcon(Icon, Data)
                        if Data.IconName then
                            Library:SetSchemeProperty(Icon, "ImageColor3", "FontColor")
                        end
                    end
                    local Label = New("TextLabel", {
                        AnchorPoint = Vector2.new(0.5, 1),
                        BackgroundTransparency = 1,
                        Position = UDim2.new(0.5, 0, 1, -3),
                        Size = UDim2.new(1, 0, 0, 11),
                        Text = tostring(Item.Label or Item.Toggle),
                        TextSize = 10,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        ZIndex = 50,
                        Parent = Button,
                    })
                    local Entry = { Button = Button, Stroke = Stroke, Icon = Icon, Label = Label, Item = Item, State = nil }
                    Button.MouseButton1Click:Connect(function()
                        local Toggle = Library.Toggles[Item.Toggle]
                        if Toggle and not Toggle.Disabled then
                            Toggle:SetValue(not Toggle.Value)
                            if typeof(Item.Toggle) == "string" and Library.OnUserToggle then
                            	pcall(Library.OnUserToggle, Item.Toggle, Toggle.Value)
                            end
                        end
                    end)
                    table.insert(DockButtons, Entry)
                end
                Dock.Size = UDim2.fromOffset(#Items * 48 + 4, 52)
            end
    
            function Library:SetQuickBar(Items)
                Library.QuickBarItems = Items
                Library:BuildQuickBar()
            end
    
            task.spawn(function()
                while not Library.Unloaded and Dock.Parent do
                    task.wait(0.15)
                    local Enabled = Library:GetSetting("QuickBar", true) ~= false
                    local Show = Enabled and not Library.Toggled and ToggleButton.Button.Visible and #DockButtons > 0
                    if Dock.Visible ~= Show then
                        Dock.Visible = Show
                    end
                    if Show then
                        local OrbPos = ToggleButton.Button.AbsolutePosition
                        local OrbSize = ToggleButton.Button.AbsoluteSize
                        local Area = Library:GetGuiArea()
                        local Width = Dock.Size.X.Offset
                        local X = OrbPos.X + OrbSize.X + 8
                        if X + Width > Area.X - 6 then
                            X = OrbPos.X - Width - 8
                        end
                        local Y = OrbPos.Y + OrbSize.Y / 2 - 26
                        Dock.Position = UDim2.fromOffset(math.floor(math.clamp(X, 6, math.max(6, Area.X - Width - 6))), math.floor(math.clamp(Y, 6, math.max(6, Area.Y - 58))))
                        for _, Entry in DockButtons do
                            local Toggle = Library.Toggles[Entry.Item.Toggle]
                            local On = Toggle ~= nil and Toggle.Value == true
                            if Entry.State ~= On then
                                Entry.State = On
                                Entry.Button.BackgroundTransparency = if On then 0.78 else 1
                                Entry.Stroke.Transparency = if On then 0.35 else 1
                                Entry.Icon.ImageTransparency = if On then 0 else 0.45
                                Entry.Label.TextTransparency = if On then 0 else 0.45
                            end
                        end
                    end
                end
            end)
    
            if WindowInfo.ShowMobileButtons == false then
                ToggleButton.Button.Visible = false
                LockButton.Button.Visible = false
            elseif Library:GetSetting("MobileLockButton", true) == false then
                LockButton.Button.Visible = false
            end
    
            task.spawn(function()
                local LastSpot = nil
                while not Library.Unloaded and ToggleButton.Button.Parent do
                    task.wait(1)
                    if ToggleButton.Ring then
                        ToggleButton.Ring.Transparency = if Library.Toggled then 0.1 else 0.55
                    end
                    local A = ToggleButton.Button.AbsolutePosition
                    local B = LockButton.Button.AbsolutePosition
                    local Spot = string.format("%d,%d,%d,%d", A.X, A.Y, B.X, B.Y)
                    if LastSpot == nil then
                        LastSpot = Spot
                    elseif Spot ~= LastSpot then
                        LastSpot = Spot
                        Library:SetSetting("MobileButtons", { math.floor(A.X), math.floor(A.Y), math.floor(B.X), math.floor(B.Y) })
                    end
                end
            end)
    
            local Camera = workspace.CurrentCamera
            if Camera then
                Library:GiveSignal(Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                    task.defer(function()
                        if Library.Unloaded then
                            return
                        end
                        local Saved = tostring(Library:GetSetting("Scale", "100%"))
                        local Number = tonumber((string.gsub(Saved, "%%", ""))) or 100
                        Library:SetDPIScale(Library:MobileFit(Number))
                        Library:CenterMobileWindow()
                    end)
                end))
            end
    
            if Library:GetSetting("MobileHintShown", false) ~= true then
                task.delay(3, function()
                    if Library.Unloaded then
                        return
                    end
                    Library:SetSetting("MobileHintShown", true)
                    Library:Notify({
                        Title = WindowInfo.Title or "Corvus",
                        Description = "Tap the round Corvus button to show or hide the hub. Drag it anywhere you like.",
                        Time = 7,
                    })
                end)
            end
        end
    
        Library:GiveSignal(SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
            Library:UpdateSearch(SearchBox.Text)
        end))
    
        Library:GiveSignal(UserInputService.InputBegan:Connect(function(Input: InputObject)
            if Library.Unloaded then
                return
            end
    
            if Input.KeyCode == Enum.KeyCode.Escape then
                local FocusedBox = UserInputService:GetFocusedTextBox()
                if FocusedBox then
                    FocusedBox:ReleaseFocus()
                    return
                end
    
                if Library.ActiveDialog and Library.ActiveDialog.OutsideClickDismiss ~= false then
                    Library.ActiveDialog:Dismiss()
                    return
                end
    
                if CurrentMenu then
                    CurrentMenu:Close()
                    return
                end
    
                return
            end
    
            if UserInputService:GetFocusedTextBox() then
                return
            end
    
            if Input.KeyCode == Library.ToggleKeybind then
                Library:Toggle()
            end
        end))
    
        Library:GiveSignal(UserInputService.WindowFocused:Connect(function()
            Library.IsRobloxFocused = true
        end))
        Library:GiveSignal(UserInputService.WindowFocusReleased:Connect(function()
            Library.IsRobloxFocused = false
        end))
    
        Window.MainFrame = MainFrame
        Window.TopBar = TopBar
        Window.SearchBox = SearchBox
        Window.BellButton = BellButton
        Window.MinimizeButton = MinimizeButton
        Window.FooterLinkButton = FooterLinkButton
        Window.FooterCopyButton = FooterCopyButton
        Window.FooterLabel = FooterLabel
        Library.Window = Window
    
        return Window
    end
    
    function Library:CreateLoading(LoadingInfo)
        if Library.ActiveLoading then
            warn("Loading GUI already exists, you cannot create multiple Loading GUIs.")
            return Library.ActiveLoading
        end
    
        LoadingInfo = Library:Validate(LoadingInfo, Templates.Loading)
    
        local Loading = {
            CurrentStep = LoadingInfo.CurrentStep,
            TotalSteps = LoadingInfo.TotalSteps,
    
            ShowSidebar = LoadingInfo.ShowSidebar,
            AutoResizeHeight = LoadingInfo.AutoResizeHeight,
            AlwaysOnTop = LoadingInfo.AlwaysOnTop,
    
            IsError = false,
            Destroyed = false,
    
            WindowWidth = LoadingInfo.WindowWidth,
            WindowHeight = LoadingInfo.WindowHeight,
            BaseWindowHeight = LoadingInfo.WindowHeight,
            WindowErrorHeight = LoadingInfo.WindowHeight,
    
            ContentWidth = LoadingInfo.ContentWidth,
            SidebarWidth = LoadingInfo.SidebarWidth,
        }
    
        local ScreenGui = New("ScreenGui", {
            Name = "CorvusLoading",
            DisplayOrder = 999,
            ResetOnSpawn = false
        })
        ParentUI(ScreenGui)
        Loading.ScreenGui = ScreenGui
        SetAlwaysOnTop(ScreenGui, LoadingInfo.AlwaysOnTop)
    
        ScreenGui.DescendantRemoving:Connect(function(Instance)
            task.defer(function()
                if Instance.Parent and Instance:IsDescendantOf(ScreenGui) then
                    return
                end
    
                Library:RemoveFromRegistry(Instance)
            end)
        end)
    
        local MainFrame = New("TextButton", {
            Name = "Main",
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = function()
                return Library:GetBetterColor(Library.Scheme.BackgroundColor, -1)
            end,
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(Loading.ShowSidebar and (Loading.ContentWidth + Loading.SidebarWidth) or Loading.WindowWidth, Loading.WindowHeight),
            ClipsDescendants = true,
            Text = "",
            AutoButtonColor = false,
            Parent = ScreenGui,
        })
        Library:AddOutline(MainFrame)
        table.insert(Library.Corners, New("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius), Parent = MainFrame }))
    
        local MainScale = New("UIScale", {
            Scale = Library.IsMobile and 0.8 or 1,
            Parent = MainFrame
        })
        table.insert(Library.Scales, MainScale)
        Library.ScalesOffset[MainScale] = Library.IsMobile and 0.2 or 0
    
        local Container = New("Frame", {
            Name = "Content",
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(0, Loading.ContentWidth, 1, 0),
            Parent = MainFrame,
        })
    
        local SideBar = New("Frame", {
            Name = "SideBar",
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(Loading.ContentWidth, 0),
            Size = UDim2.new(0, Loading.ShowSidebar and Loading.SidebarWidth or 0, 1, 0),
            ClipsDescendants = true,
            Visible = Loading.ShowSidebar,
            Parent = MainFrame,
        })
        local SidebarCorner = New("UICorner", { CornerRadius = UDim.new(0, Library.CornerRadius), Parent = SideBar })
        table.insert(Library.Corners, SidebarCorner)
    
        Library:AddOutline(SideBar)
    
        local SidebarDivider = New("Frame", {
            BackgroundColor3 = "OutlineColor",
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(0, 1, 1, 0),
            Visible = Loading.ShowSidebar,
            Parent = SideBar,
        })
    
        local TopBar = New("Frame", {
            Name = "TopBar",
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 48),
            ZIndex = 2,
            Parent = Container,
        })
        Library:MakeDraggable(MainFrame, TopBar, true, true)
    
        local TitleHolder = New("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 1, 0),
            Parent = TopBar,
        })
        New("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            HorizontalAlignment = Enum.HorizontalAlignment.Left,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 6),
            Parent = TitleHolder,
        })
        New("UIPadding", {
            PaddingLeft = UDim.new(0, 12),
            Parent = TitleHolder,
        })
    
        if LoadingInfo.Icon then
            local Icon = Library:GetCustomIcon(LoadingInfo.Icon)
            local _WindowIcon = New("ImageLabel", {
                Size = LoadingInfo.IconSize,
                Parent = TitleHolder,
            })
            if Icon then
                Library:ApplyLucideIcon(_WindowIcon, Icon)
            end
        else
            local _WindowIcon = New("TextLabel", {
                BackgroundTransparency = 1,
                Size = LoadingInfo.IconSize,
                Text = LoadingInfo.Title:sub(1, 1),
                TextScaled = true,
                Visible = false,
                Parent = TitleHolder,
            })
        end
    
        local TitleX = Library:GetTextBounds(
            LoadingInfo.Title,
            Library.Scheme.Font,
            20,
            (TitleHolder.AbsoluteSize.X / Library.DPIScale) - (LoadingInfo.Icon and (LoadingInfo.IconSize.X.Offset + 6) or 0) - 12
        )
        local _WindowTitle = New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(0, TitleX, 1, 0),
            Text = LoadingInfo.Title,
            TextSize = 20,
            Parent = TitleHolder,
        })
    
        Library:MakeLine(Container, {
            Position = UDim2.fromOffset(0, 48),
            Size = UDim2.new(1, 0, 0, 1),
        })
    
        local InnerContent = New("Frame", {
            Name = "InnerContent",
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(0, 49),
            Size = UDim2.new(1, 0, 1, -49),
            Parent = Container,
        })
    
        New("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Padding = UDim.new(0, 12),
            Parent = InnerContent,
        })
    
        local IconHolder = New("Frame", {
            Name = "IconHolder",
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(64, 64),
            Parent = InnerContent,
        })
    
        local LoaderIcon = Library:GetCustomIcon(LoadingInfo.LoadingIcon)
        local LoadingIcon = New("ImageLabel", {
            Name = "LoaderIcon",
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromScale(1, 1),
            ImageColor3 = LoadingInfo.LoadingIconColor or ((LoadingInfo.LoadingIcon == Templates.Loading.LoadingIcon) and "AccentColor" or "WhiteColor"),
            Parent = IconHolder,
        })
        if LoaderIcon then
            Library:ApplyLucideIcon(LoadingIcon, LoaderIcon)
        end
    
        local RotationTween
        if LoadingInfo.LoadingIconTweenTime > 0 then
            RotationTween = TweenService:Create(
                LoadingIcon,
                TweenInfo.new(LoadingInfo.LoadingIconTweenTime, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1),
                { Rotation = 360 }
            )
            RotationTween:Play()
        end
    
        local MessageLabel = New("TextLabel", {
            BackgroundTransparency = 1,
            AutomaticSize = Loading.AutoResizeHeight and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
            Size = Loading.AutoResizeHeight and UDim2.new(1, -60, 0, 0) or UDim2.fromOffset(0, 0),
            Text = "",
            TextSize = 18,
            TextWrapped = Loading.AutoResizeHeight,
            Parent = InnerContent,
        })
    
        local DescriptionLabel = New("TextLabel", {
            BackgroundTransparency = 1,
            AutomaticSize = Loading.AutoResizeHeight and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
            Size = Loading.AutoResizeHeight and UDim2.new(1, -60, 0, 0) or UDim2.fromOffset(0, 0),
            Text = "",
            TextSize = 14,
            TextTransparency = 0.5,
            TextWrapped = Loading.AutoResizeHeight,
            Parent = InnerContent,
        })
    
