	--       AFK watchdog no input for <N> min -> nudge (max once per 5 min), AFK defused game idle handlers n=<n>, AFK kicked "<msg>" -> rejoin.
	do
		local Afk = {
			Enabled = Library:GetSetting("AntiAFK", true) ~= false,
			LastInput = os.clock(),
			LastHuman = os.clock(),
			OwnAt = -1e9,
			LastPulse = os.clock(),
			LastNudge = os.clock(),
			NextNudge = 180 + math.random() * 60,
			Every = 60 + math.random() * 20,
			Count = 0,
			LastVia = nil,
			LastLog = -1e9,
			LastWatchLog = -1e9,
			LastDefuse = -1e9,
