		function Library:SetAntiAfk(Value: boolean)
			local Was = Afk.Enabled
			Afk.Enabled = Value == true
			Library:SetSetting("AntiAFK", Value == true)
			if Was ~= Afk.Enabled then
				Library:CorvusLog("AFK guard " .. (if Afk.Enabled then "on" else "off"))
			end
		end
		local AfkKey = Enum.KeyCode.F13
		local function AfkNote(Via: string)
			Afk.Count += 1
			Afk.LastPulse = os.clock()
			local Now = os.clock()
			if Via ~= Afk.LastVia or Now - Afk.LastLog >= 300 then
				Afk.LastVia = Via
