			end
			if AfkVirtualUser() then
				Afk.LastInput = os.clock()
				AfkNote("vu")
			end
		end
		local function AfkStep(Hum: Humanoid, Target: Vector3): ()
			local Done = false
			local Conn = Hum.MoveToFinished:Connect(function()
				Done = true
			end)
			Hum:MoveTo(Target)
			local Deadline = os.clock() + 0.8
			while not Done and os.clock() < Deadline do
				task.wait(0.05)
			end
			Conn:Disconnect()
		end
		local function AfkNudge(): boolean
			local Busy = Library.AntiAfkBusy
			if typeof(Busy) == "function" then
				local Ok, IsBusy = pcall(Busy)
				if Ok and IsBusy then
					return false
				end
			end
			local Char = LocalPlayer.Character
			local Hum = Char and Char:FindFirstChildOfClass("Humanoid")
			local Root = Hum and Hum.RootPart
			if not (Hum and Root) or Hum.Health <= 0 or Hum.Sit or Hum.PlatformStand or Root.Anchored then
				return false
			end
			if Hum.FloorMaterial == Enum.Material.Air or Hum.MoveDirection.Magnitude > 0.05 or Root.AssemblyLinearVelocity.Magnitude > 1 then
				return false
			end
			local Origin = Root.Position
			local Look = Root.CFrame.LookVector
			local Dir = Vector3.new(Look.X, 0, Look.Z)
			Dir = if Dir.Magnitude > 0.1 then Dir.Unit else Vector3.new(0, 0, -1)
			local Ok = pcall(function()
				AfkStep(Hum, Origin + Dir * 0.5)
				AfkStep(Hum, Vector3.new(Origin.X, Root.Position.Y, Origin.Z))
			end)
			return Ok
		end
		local function AfkIdled()
			if not Afk.Enabled or Library.Unloaded then
				return
			end
			if AfkVirtualUser() then
				Afk.LastInput = os.clock()
				AfkNote("idled")
			end
		end
		pcall(function()
			Library:GiveSignal(LocalPlayer.Idled:Connect(AfkIdled))
		end)
		local function AfkReleaseIdled()
			for Conn in Afk.Disabled do
				Afk.Disabled[Conn] = nil
				pcall(function()
					Conn:Enable()
				end)
			end
		end
		table.insert(Library.UnloadSignals, AfkReleaseIdled)
		local function AfkDefuse()
			if typeof(getconnections) ~= "function" then
				return
			end
			local Ok, List = pcall(getconnections, LocalPlayer.Idled)
			if not Ok or typeof(List) ~= "table" then
				return
			end
			local Fresh = 0
			for _, Conn in List do
				local Fn = nil
				pcall(function()
					Fn = Conn.Function
				end)
				if typeof(Fn) == "function" and Fn ~= AfkIdled and not Afk.Disabled[Conn] then
					local Source = ""
					pcall(function()
						Source = tostring(debug.info(Fn, "s"))
					end)
					local Core = string.find(Source, "CoreGui", 1, true) or string.find(Source, "CorePackages", 1, true) or string.find(Source, "RobloxGui", 1, true)
					if not Core and pcall(function()
						Conn:Disable()
					end) then
