			end
		end
		local function AfkKicked(Message: string)
			if not Afk.Enabled or Afk.Rejoining or Library.Unloaded or Library.AutoReconnectOn then
				return
			end
			local Low = string.lower(tostring(Message or ""))
			if not (string.find(Low, "idle", 1, true) or string.find(Low, "afk", 1, true) or string.find(Low, "278", 1, true)) then
				return
			end
			Afk.Rejoining = true
			Library:CorvusLog(string.format('AFK kicked "%s" -> rejoin same server', string.sub(tostring(Message), 1, 120)))
			task.spawn(function()
				local Script = Library.RejoinScript
				if typeof(Script) ~= "string" then
					Script = 'loadstring(game:HttpGet("https://raw.githubusercontent.com/vaensigma/Corvus/refs/heads/main/Loader"))()'
				end
				pcall(function()
					local Queue = queue_on_teleport or queueonteleport or (typeof(syn) == "table" and syn.queue_on_teleport)
					if typeof(Queue) == "function" then
						Queue("if not game:IsLoaded() then game.Loaded:Wait() end\n" .. Script)
					end
				end)
				local TeleportService = game:GetService("TeleportService")
				for Attempt = 1, 30 do
					pcall(function()
						if Attempt <= 3 and game.JobId ~= "" then
							TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
						else
							TeleportService:Teleport(game.PlaceId, LocalPlayer)
						end
					end)
					task.wait(8)
				end
			end)
		end
		pcall(function()
			Library:GiveSignal(GuiService.ErrorMessageChanged:Connect(function()
				local Message = ""
				pcall(function()
					Message = GuiService:GetErrorMessage()
				end)
				AfkKicked(Message)
			end))
		end)
