			if Library.Unloaded then
				return
			end
			local HasVIM = pcall(function()
				return game:GetService("VirtualInputManager")
			end)
			Library:CorvusLog(string.format(
				"AFK guard %s layers=key%s,vu,idled,nudge,rejoin%s",
				if Afk.Enabled then "on" else "off",
				if HasVIM then "" else "(no VIM)",
				if typeof(getconnections) == "function" then ",defuse" else ""
			))
		end)
