			while not Library.Unloaded do
				task.wait(1)
				if Afk.Enabled then
					local Now = os.clock()
					local Idle = Now - Afk.LastInput
					if Idle >= Afk.Every then
						Afk.Every = 60 + math.random() * 20
						Afk.LastInput = Now
						if Now - Afk.LastWatchLog >= 300 then
							Afk.LastWatchLog = Now
							Library:CorvusLog(string.format("AFK watchdog no input for %.1f min -> nudge", Idle / 60))
						end
