		TrailShopRequest = { "AutoTrail" },
		UpgradePlotRequest = { "AutoPlotUpgrade" },
		UnlockTreadmillRequest = { "AutoTreadmill", "AutoPlotUpgrade" },
		UpgradeTreadmillRequest = { "AutoTreadmill" },
