	local Suffixes = { "", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No", "Dc" }
	function formatNumber(n)
		n = tonumber(n) or 0
		if n ~= n or n == math.huge then
			return "?"
		end
		local negative = n < 0
		n = math.abs(n)
		local text
		if n < 1000 then
			text = if n % 1 == 0 or n >= 100 then tostring(math.floor(n)) else (string.format("%.1f", n):gsub("%.0$", ""))
		else
			local i = 1
			while n >= 1000 and i < #Suffixes do
				n /= 1000
				i += 1
			end
			text = string.format("%.2f", n):gsub("%.?0+$", "") .. Suffixes[i]
		end
		return (if negative then "-" else "") .. text
	end
	function clockText(seconds)
		seconds = math.max(0, math.floor(tonumber(seconds) or 0))
		if seconds >= 3600 then
			return string.format("%d:%02d:%02d", seconds // 3600, (seconds % 3600) // 60, seconds % 60)
		end
		return string.format("%d:%02d", seconds // 60, seconds % 60)
	end
	function N.longTime(seconds)
		seconds = math.max(0, math.floor(tonumber(seconds) or 0))
		if seconds >= 3600 then
			return string.format("%dh %dm", seconds // 3600, (seconds % 3600) // 60)
		elseif seconds >= 60 then
			return string.format("%dm", math.ceil(seconds / 60))
		end
		return string.format("%ds", seconds)
	end
	function character()
		return LocalPlayer.Character
	end
	function rootPart()
		local c = character()
		return c and c:FindFirstChild("HumanoidRootPart")
	end
	function humanoid()
		local c = character()
		return c and c:FindFirstChildOfClass("Humanoid")
