	function allows(option, value)
		local v = option and option.Value
		if v == nil then
			return true
		end
		if type(v) == "table" then
			if next(v) == nil then
				return true
			end
			return v[value] == true
		end
		return v == value
	end
	function selected(option, value)
		local v = option and option.Value
		if type(v) == "table" then
			return v[value] == true
		end
		return v == value
	end
	function picked(option)
		local list = {}
