	function N.parseMoney(text)
		local num, suffix = string.match(string.lower(tostring(text or "")), "^%s*([%d%.]+)%s*([a-z]*)%s*$")
		local value, power = tonumber(num), MoneyPow[suffix or ""]
		if not value or not power then
