N.Hell = { joinAt = -1e9, swings = 0, essenceHits = 0, status = "-", nextSwing = 0, enteredAt = nil, logAt = -1e9, tokensAt = nil, fights = 0, probe = { swings = 0, drops = 0, said = false, pending = {} }, bossSeenAt = nil, retreatUntil = 0 }
