			})
			HookBox:AddToggle("WebhookHuge", { Text = "HUGE and TITANIC animals", Default = true })
			HookBox:AddToggle("WebhookUpgrades", { Text = "Upgrades bought", Default = true })
			HookBox:AddToggle("WebhookZones", { Text = "New zones", Default = true })
