					end
					Options.MoveMode:SetValue(pick)
					return "Mode set to " .. pick
				end,
			})
			Library:AddCommand({
				Name = "status",
				Description = "Shows what Corvus is doing",
				Source = GameName,
				Callback = function()
					return string.format(
						"%s  |  $%s  |  speed %s  |  %d eggs, %d animals home",
						Status,
						formatNumber(N.cash()),
						formatNumber(N.power()),
						Session.eggs,
						Session.banked
					)
				end,
			})
			Library:AddCommand({
				Name = "perf",
				Aliases = { "fps", "lag" },
				Description = "Shows how smooth the game runs and how much time Corvus takes",
				Source = GameName,
				Callback = Debug.perfText,
			})
		end)
	end
